# One row of the "Select probabilities" dim_1/dim_2/dim_3 pickers on the
# Plot Polytope(s) tab — the three call sites were identical except for the
# id suffix and default selection.
dim_picker_row <- function(id, selected) {
  fluidRow(column(
    12,
    offset = 0,
    pickerInput(paste0("dim_", id), paste0(c("x", "y", "z")[as.integer(id)], " axis: probability"),
      list(1, 2, 3),
      selected = selected
    )
  ))
}

ui <- shinyUI(fluidPage(
  lang = "en",
  tags$head(
    tags$style(HTML(
      "

      :root {
        --fairy-bg: #f4f6fa;
        --fairy-panel: #ffffff;
        --fairy-border: #e2e6ee;
        --fairy-primary: #593196;
        --fairy-wing-a: #593196; --fairy-wing-b: #7a4fc4; --fairy-wing-s: #4a2a7a;   /* wings of the fairy: purple by day */
        --fairy-primary-dark: #4a2a7a;
        /* Background for any element with WHITE/light text sitting
           directly on it (active toggle buttons, primary filled
           buttons, the active navbar tab, …) — separate from
           --fairy-primary, which
           is also used as a plain TEXT/icon color on light backgrounds
           (its own contrast requirement runs the other direction). In
           light mode --fairy-primary itself already passes WCAG AA
           (4.5:1) for white text, so this is identical to it here. */
        --fairy-primary-contrast-bg: #593196;
        --fairy-primary-contrast-bg-hover: #4a2a7a;
        --fairy-accent: #16a37a;
        --fairy-text: #1f2430;
        --fairy-text-muted: #667085;
        --fairy-navbar: #1b2130;
        --ct-border: #dde3f0;
        --ct-default: #f7f8fb;
        --ct-diag: #eef2fe;
        --ct-nodim: #f5f5f5;
        --ct-info-bg: #f9fafd;
      }

      body.dark-mode {
        --fairy-bg: #0e1117;
        --fairy-panel: #161b27;
        --fairy-border: #2d3347;
        --fairy-primary: #6089f8;
        --fairy-primary-dark: #4a73e0;
        /* Dark mode's own --fairy-primary (#6089f8) is lighter than
           light mode's, chosen for its own text/icon-on-dark-background
           contrast — but that SAME shade under white text only reaches
           ~3.3:1, well under WCAG AA's 4.5:1 (confirmed directly:
           computed via the WCAG relative-luminance formula). A dedicated,
           darker shade for backgrounds carrying white text instead —
           #4c6dc6 measures ~4.9:1 with white text, comfortably clearing
           AA, while --fairy-primary itself stays unchanged for its own
           (already-passing) text-color uses. --fairy-primary-dark is
           NOT reused for this even though it's already a darker shade —
           it's independently tuned for ITS OWN role as a plain text
           color (link/icon hover), and darkening it further to also
           satisfy white-on-it would have broken that (confirmed
           directly: a candidate dark enough for white text dropped its
           own text-on-background contrast under AA). */
        --fairy-primary-contrast-bg: #2a5bd7;
        --fairy-wing-a: #2a5bd7; --fairy-wing-b: #4f7be8; --fairy-wing-s: #2350bd;   /* ... blue at night */
        --fairy-primary-contrast-bg-hover: #2350bd;
        --fairy-accent: #1fcc9a;
        --fairy-text: #dde1ea;
        --fairy-text-muted: #8892aa;
        --fairy-navbar: #0b0f1a;
        --ct-border: #2d3950;
        --ct-default: #1a1f2c;
        --ct-diag: #192240;
        --ct-nodim: #1e2028;
        --ct-info-bg: #192030;
      }

      /* Accessibility: respects the OS-level reduce-motion setting
         (vestibular disorders / motion sensitivity) — the app has quite
         a few animations (the corner mascot, the intro-pulse glow on
         newly-appeared buttons, the stale-results ring on Go, several
         flash/blink cues) and NONE of them previously checked this at
         all. The universal override below (every animation/transition
         collapsed to near-zero duration, one iteration) is the standard
         pattern for this — catches every current AND future animation
         in the app automatically, with no need to hunt down and edit
         each @keyframes/animation declaration individually, and without
         changing layout (only timing). */
      @media (prefers-reduced-motion: reduce) {
        *, *::before, *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 0.01ms !important;
          scroll-behavior: auto !important;
        }
      }

      /* Dark mode: panels, wells, tables, inputs */
      body.dark-mode .well,
      body.dark-mode .panel.panel-default > .panel-body {
        background-color: var(--fairy-panel) !important;
        border-color: var(--fairy-border) !important;
        color: var(--fairy-text) !important;
      }
      body.dark-mode .panel.panel-default > .panel-heading {
        background-color: var(--fairy-panel) !important;
        border-color: var(--fairy-border) !important;
        color: var(--fairy-text) !important;
      }
      body.dark-mode textarea,
      body.dark-mode input[type='text'],
      body.dark-mode input[type='number'],
      body.dark-mode .selectize-input {
        background-color: var(--fairy-panel) !important;
        color: var(--fairy-text) !important;
      }
      /* the dropdown boxes and switch knobs keep a Bootstrap white gradient/fill without these */
      body.dark-mode .selectize-input, body.dark-mode .selectize-input.full, body.dark-mode .selectize-input.input-active, body.dark-mode .selectize-input.dropdown-active {
        background-color: var(--fairy-panel) !important; background-image: none !important; color: var(--fairy-text) !important; box-shadow: none !important; border-color: var(--fairy-border) !important; }
      body.dark-mode .selectize-input .item, body.dark-mode .selectize-input > input { color: var(--fairy-text) !important; background: transparent !important; }
      /* plain download buttons (PDF, CSV, ...) were dark text on dark in night mode */
      body.dark-mode a.btn.btn-default.shiny-download-link, body.dark-mode .btn-default.btn-sm {
        background-color: transparent !important; background-image: none !important; color: var(--fairy-primary) !important; border-color: var(--fairy-primary) !important; }
      body.dark-mode a.btn.btn-default.shiny-download-link:hover, body.dark-mode .btn-default.btn-sm:hover { background-color: color-mix(in srgb, var(--fairy-primary) 16%, transparent) !important; }
      body.dark-mode .material-switch > label::after { background: #8b93a7 !important; box-shadow: none !important; }
      /* switches (shinyWidgets materialSwitch): knob and track in the theme colour when on */
      .material-switch > input[type=checkbox]:checked + label.label-primary::before, .material-switch > input[type=checkbox]:checked + label::before { background-color: var(--fairy-primary-contrast-bg) !important; opacity: .5; }
      .material-switch > input[type=checkbox]:checked + label.label-primary::after, .material-switch > input[type=checkbox]:checked + label::after { background-color: var(--fairy-primary-contrast-bg) !important; }
      body.dark-mode select, body.dark-mode .form-control { background-color: var(--fairy-panel) !important; background-image: none; color: var(--fairy-text) !important; border-color: var(--fairy-border) !important; }
      html:has(body.dark-mode) { background-color: #0e1117 !important; }
      /* shinyWidgets pickers (bootstrap-select) */
      body.dark-mode .bootstrap-select > .dropdown-toggle, body.dark-mode .bootstrap-select > .dropdown-toggle.btn-default, body.dark-mode .bootstrap-select .btn-default {
        background-color: var(--fairy-panel) !important; background-image: none !important; color: var(--fairy-text) !important; border-color: var(--fairy-border) !important; box-shadow: none !important; }
      body.dark-mode .bootstrap-select .dropdown-menu { background-color: var(--fairy-panel) !important; border-color: var(--fairy-border) !important; }
      body.dark-mode .bootstrap-select .dropdown-menu li a { color: var(--fairy-text) !important; }
      body.dark-mode .bootstrap-select .dropdown-menu li a:hover, body.dark-mode .bootstrap-select .dropdown-menu li.selected a { background-color: var(--ct-diag) !important; }
      body.dark-mode .bootstrap-select .filter-option, body.dark-mode .bootstrap-select .filter-option-inner-inner { color: var(--fairy-text) !important; }
      body.dark-mode .selectize-dropdown { background: var(--fairy-panel) !important; color: var(--fairy-text) !important; border-color: var(--fairy-border) !important; }
      body.dark-mode .selectize-dropdown .option:hover,
      body.dark-mode .selectize-dropdown .option.active { background: var(--ct-diag) !important; }
      body.dark-mode table.dataTable,
      body.dark-mode .dataTables_wrapper { color: var(--fairy-text) !important; }
      body.dark-mode table.dataTable thead th,
      body.dark-mode table.dataTable thead td {
        background: var(--fairy-panel) !important;
