            R('H-representation', 'Data for multinomineq', 'Your data for multinomineq: n and frequencies. They go into the files and the script of the multinomineq download and are used by Run analysis.', function() { return [inPane('#mn_data_open')]; }),
            R('H-representation', 'multinomineq download', 'Files, analysis script and data file for the multinomineq R package. Run the script on your own computer for large analyses.', function() { return [inPane('#d_h_multinomineq')]; }),
            R('H-representation', 'Run analysis', 'Runs the multinomineq analysis here, for small analyses, with the numbers and settings saved under Data. Results come as tables, a web page and a PDF.', function() { return [inPane('#mn_run_open')]; }),
            R('H-representation', 'LaTeX download', 'Downloads the H-representation as a LaTeX file.', function() { return [inPane('#d_latex')]; }),
            R('H-representation', 'Order of the probabilities (unpacked models)', 'With unpacked models an extra button appears in the Export part. It chooses which probability of an unpacked model is called p1, p2, ... in the QTEST and multinomineq downloads and in the R script.', function() { return [byTip(/Choose which probability of an unpacked model/)]; }),
            R('H-representation', 'Items (unpacked models)', 'With unpacked models the toolbar has a fourth group, Items. It marks the items with coloured bars, and single items can be deselected like parameters.', function() { return [inPane('#h_items_toggle_group')]; }),
            R('V-representation', 'V-representation', 'The vertices (corner points) of each model, one card per model. Click a column header to sort.', function() { var p = pane(); var e = p ? p.querySelector('.model-card') : null; return [shown(e) ? e : null]; }),
            R('V-representation', 'Vertices in words', 'Shows the vertices in words (all, none, fractions) instead of numbers.', function() { return [paneLabel(/Show vertices in words/)]; }),
            R('V-representation', 'Compare models', 'With two or more models: the link button marks the vertices that other models share (vertices only this model has are tinted), and the filter button shows only the vertices that no other model has.', function() { return [inPane('#v_shared_btn'), inPane('#v_unique_btn')]; }),
            R('V-representation', 'Downloads', 'The V-representation for QTEST, or as a LaTeX table.', function() { return [inPane('#d_v'), inPane('#d_v_latex')]; }),
            R('Plot Edge Cases', 'Choose a model', 'The model whose vertices are plotted.', function() { var p = pane(); var h = p ? p.querySelector('h5') : null; return [shown(h) ? h.parentElement : null]; }),
            R('Plot Edge Cases', 'Edge cases', 'Every vertex of the model is one case. The plot shows the value of every probability at that vertex. Play steps through the vertices. The toolbar at the top right of the plot zooms, pans, resets the axes and saves a PNG.', function() { return [inPane('#plot_example')]; }),
            R('Plot Edge Cases', 'Save as PDF', 'Saves the plot as a PDF.', function() { return [inPane('#plot_example_pdf')]; }),
            R('Plot Polytope(s)', 'Models to plot', 'Choose which models are drawn. Several models can be drawn together in different colours.', function() { var l = paneLabel(/Models to plot/); return [l ? l.parentElement : null]; }),
            R('Plot Polytope(s)', 'Auto-rotate', 'Turns the plot slowly all the time.', function() { return [paneLabel(/Auto-rotate/)]; }),
            R('Plot Polytope(s)', 'Axes', 'Choose which three probabilities are the x, y and z axes.', function() { var h = inPane('#dim_pick_heading'); var z = inPane('#dim_3'); return [h, z ? z.closest('.form-group') : null]; }),
            R('Plot Polytope(s)', 'The polytope', 'Drag to rotate and scroll to zoom. Click a model in the legend to hide or show it. The toolbar at the top right of the plot offers more views and saves a PNG.', function() { return [inPane('#plot')]; }),
            R('Plot Polytope(s)', 'PDF and full size', 'Saves the plot as a vector PDF, sharp at any size. The arrows enlarge the plot.', function() { return [inPane('#download_polytope_pdf'), inPane('#polytope_plot_expand')]; }),
            R('Model Properties', 'Parsimony', 'Computes the volume of every model: the share of the parameter space that fits the model. A smaller volume means a more restrictive model.', function() { return [inPane('#go_inline_pars')]; }),
            R('Model Properties', 'Exact volume', 'Calculates the volume from the corner points of the model (up to 5 minutes in total; you can skip it). Where it works, no algorithm is needed.', function() { return [byTip(/Calculates the volume from the corner points/)]; }),
            R('Model Properties', 'Algorithms', 'Estimates the volume with algorithms for every model. Off: Cooling Bodies only runs for models whose exact volume was skipped or did not finish.', function() { return [byTip(/Estimate the volume with algorithms/)]; }),
            R('Model Properties', 'Algorithm settings', 'Opens the settings of the algorithms that estimate the volume. Choose them before you start.', function() { return [inPane('#show')]; }),
            S('The settings window', 'One tab per algorithm (Cooling Bodies, Cooling Gaussian, Sequence of Balls). Each has the approximation error, the random walk method, walk length, sliding window length, H-polytopes in MMC and the random seed. The fields are pre-filled with each algorithm own default, and Save keeps your values.', function() { return [modQ('.modal-body')]; }, { pre: function() { closeModal(); return cclick(document.getElementById('show')); }, wait: 1400 }),
            R('Model Properties', 'Volume by model', 'One bar per model and method. PDF saves the chart, and the arrows enlarge it.', function() { return [inPane('#parsimony_plot_ui')]; }, { pre: function() { closeModal(); goTab('Model Properties'); setTimeout(function() { if (!document.getElementById('parsimony_plot_ui') || !shown(document.getElementById('parsimony_bar_plot'))) clickEl(document.getElementById('go_inline_pars')); }, 800); }, until: function() { return shown(document.getElementById('parsimony_bar_plot')); }, wait: 1500, maxwait: 30000 }),
            R('Model Properties', 'Detailed results', 'Volume (exact ones as fractions), the dimensionality, and Max BF, the largest Bayes factor the model can reach (1 divided by the volume). CSV saves the table, and the heading above explains the columns.', function() { return [inPane('#parsimony_spinner_table')]; }),
            R('Model Properties', 'What do the columns mean?', 'Volume is the share of the parameter space that fits the model. Exact is calculated from the corner points, the algorithms estimate it by sampling and differ from run to run. Max BF is 1 divided by the volume: a smaller volume means a more restrictive model. The text also names the R packages behind the numbers.', function() { return [inPane('details')]; }, { pre: function() { goTab('Model Properties'); setTimeout(function() { var d = inPane('details'); if (d) d.open = true; }, 600); }, wait: 1300 }),
            S('That is it', 'Every tab has the same pattern: controls on the left, the result in the middle, downloads for your own work.', function() { return []; }, { last: true, noexample: true, pre: function() { goTab('Input'); }, wait: 400 })
          ];
        }
        function runSteps() {
          function rw(sel) { return function() { var e = document.querySelector(sel); return [shown(e) ? e : null]; }; }
          return [
            S('The run window', 'This window opens when a calculation takes a moment: here the H-representations and vertices, and also Parsimony and the multinomineq analysis. It shows how many steps are done, how long the current step has been running, and its time limit. (The tour shows an example, nothing is calculated.)', function() { var c = document.getElementById('fairy-run-title'), d = document.getElementById('fairy-run-sub'); return [shown(c) ? c : null, shown(d) ? d : null]; }, { pre: function() { closeModal(); goTab('Input'); demoOn = true; Shiny.setInputValue('fairy_run_demo', Date.now(), { priority: 'event' }); }, until: function() { return !!document.querySelector('.fairy-run-stopready') && shown(document.getElementById('fairy-run-card')); }, wait: 1500, maxwait: 9000, quiet: true }),
            S('One row per model', 'The columns are the steps. A cell shows whether a step is waiting, running, done, skipped or failed.', rw('.fairy-run-table')),
            S('Skip one model', 'After a few seconds, Skip appears at the model that is running. Skip it and the others go on. A skipped model can be retried with Retry.', function() { var e = document.querySelector('.fairy-run-rowbtn:not(.fairy-run-rowundo)'); return [shown(e) ? e : null]; }),
            S('Skip all', 'Skips everything that is still running. Skipping is optional: without it the calculation keeps going until it is finished or the time limit is reached.', rw('#fairy-run-cancel')),
            S('When it is done', 'If everything went well the window closes by itself. If something needs your attention, for example a warning, it stays open until you close it.', function() { return []; }, { last: true, noexample: true })
          ];
        }
        function mnSteps() {
          function mf(sel) { return function() { var e = modQ(sel); return [e ? (e.closest('.form-group') || e) : null]; }; }
          return [
            S('Data for multinomineq', 'The multinomineq analysis needs your data: how many observations (n) and how often the outcome happened (frequency) for each probability.', function() { return [inPane('#mn_data_open')]; }, {
              pre: function() { closeModal(); if (!tabShown('H-representation')) runGo(); },
              until: function() { if (tabShown('H-representation')) { if (!shown(document.getElementById('mn_data_open'))) goTab('H-representation'); } return shown(document.getElementById('mn_data_open')); }, wait: 1500, maxwait: 60000 }),
            S('n and frequency', 'One row per probability. The numbers are examples until you save your own. The badge shows which model they belong to.', function() { return [modQ('.modal-body')]; }, { pre: function() { closeModal(); return cclick(document.getElementById('mn_data_open')); }, wait: 1400 }),
            S('Same n for every row', 'Optional: one n for all rows at once.', mf('#mn_nall_1')),
            S('Reset or save', 'Reset puts the example numbers back. Save keeps your numbers for the next download and for Run analysis.', function() { var a = modQ('#mn_data_reset'), b2 = modQ('#mn_data_save'); return [a, b2]; }),
            S('Samples', 'How many draws the analysis uses for the Bayes factors and the posterior. More draws are more precise and take longer.', function() { var l = modQ('#mn_samples-label'); return [l ? l.parentElement : null]; }, { pre: function() { closeModal(); return cclick(document.getElementById('mn_run_open')); }, wait: 1400 }),
            S('Advanced', 'Burn-in is the number of draws thrown away at the start. The prior is a Beta(a, b) distribution on every probability, and Beta(1, 1) is flat. The random seed makes a run repeatable.', function() { return [modQ('details')]; }, { pre: function() { var d = modQ('details'); if (d) d.open = true; }, wait: 500 }),
            S('Shared server', 'The analysis runs on a shared server, so keep it small. For larger analyses download the files and run the script on your own computer.', function() { var st = modText('strong', /Shared server/); return [st ? st.parentElement : null]; }),
            S('Run analysis here', 'Starts the analysis with these settings. The next steps start it now to show the results window.', function() { return [modQ('#mn_run')]; }),
            S('The results window', 'Computed with multinomineq on the shared server. The line below tells date, prior, number of samples and package version.', function() { var m = modalOpen(); var l = m ? [].filter.call(m.querySelectorAll('p'), shown) : []; return l.slice(0, 2); }, { pre: function() { clickEl(document.getElementById('mn_run')); }, until: function() { var h = document.getElementById('mn_results_host'); return shown(h); }, wait: 2500, maxwait: 120000 }),
            S('Overview and models', 'The Overview tab compares all models. There is one tab for every model with its details.', function() { var a = shLabel(/^Overview$/), l = shRoot() ? [].filter.call(shRoot().querySelectorAll('label'), shown) : []; return l; }, { pre: function() { var o = shLabel(/^Overview$/); if (o) o.click(); }, wait: 500 }),
            S('Bayes factors of all models', 'A value above 1 favours the model. Model vs. unconstrained: how much better the data fit the model than a model without restrictions. Model vs. complement: the model against everything it forbids. The colours show the strength of evidence.', function() { var h = shQ('h2'), t2 = shQ('table'); return [h, t2]; }),
            S('Estimates of one model', 'The posterior of every probability: mean, SD and 95% interval. The dot is the mean and the bar the interval.', function() { var r = shRoot(), l = r ? [].filter.call(r.querySelectorAll('h3'), function(x) { return /Probabilities/.test(x.textContent) && shown(x); }) : []; var t2 = r ? [].filter.call(r.querySelectorAll('table'), shown)[1] : null; return [l[0], t2]; }, { pre: function() { var m1 = null, r = shRoot(), l = r ? r.querySelectorAll('label') : [], i; for (i = 0; i !== l.length; i++) { if (l[i].textContent.trim() !== 'Overview' && !m1) m1 = l[i]; } if (m1) m1.click(); }, wait: 800 }),
            S('Is the sample reliable?', 'Diagnostics of the posterior sample: trace and density plots, effective sample size and Geweke z. Green means fine.', function() { var r = shRoot(), l = r ? [].filter.call(r.querySelectorAll('h3'), function(x) { return /Diagnostics/.test(x.textContent) && shown(x); }) : []; return [l[0]]; }),
            S('Analyse again', 'Runs the analysis again, for example with more samples.', function() { return [modQ('#mn_results_again')]; }),
            S('Download', 'The PDF report (with a link back to your input) or everything in one file: PDF, web page, tables, the files and the R script.', function() { var d = modQ('.dropdown-toggle'); return [d]; }),
            S('That is it', 'Close the window with Close. Everything stays available under Download.', function() { return []; }, { last: true, noexample: true })
          ];
        }
        // ---- interactive tutorial: the cringe study of the paper (the pointer enters everything) ----
        async function waitFor(cond, ms) { var t0 = Date.now(); while (!cond() && Date.now() - t0 < ms) { await sleep(300); } return cond(); }
        function specTd(k) { var e = document.getElementById('textin_relations_' + k); var r = e ? (e.closest('.fairy-model-row') || e.closest('td')) : null; return shown(r) ? r : null; }
        function probCount() { var e = document.getElementById('set_prob_count'); return e ? parseInt(e.value, 10) : 0; }
        async function ensureProbs(n, tk) { var g = 0; while (probCount() !== n && g !== 12 && tk === token) { clickEl(null); await cclick(document.getElementById(probCount() > n ? 'rm_prob' : 'add_prob')); await sleep(500); g++; } }
        async function ensureModelRows(n, tk) { var g = 0; while (!document.getElementById('textin_relations_' + n) && g !== 14 && tk === token) { await cclick(document.getElementById('add_ie')); await sleep(900); g++; } await sleep(500); }
        function R2(tab, title, text, f, extra) { var o = { pre: function() { return tabC(tab); }, wait: 600 }; if (extra) { for (var k in extra) { o[k] = extra[k]; } } return S(title, text, f, o); }
        async function interDemo(ids, tk) {
          await sleep(300); var b0 = document.getElementById('add_intersection_model'); if (!b0) { await ensureRowsFast(2); await sleep(800); b0 = document.getElementById('add_intersection_model'); }
          var rows0 = document.querySelectorAll('[id^=textin_relations_name]').length;
          await cclick(document.getElementById('add_intersection_model')); await sleep(900); place();
          var i, m = modalOpen();
          for (i = 0; i !== ids.length; i++) { var cb = null, ins = m ? m.querySelectorAll('#intersection_model_picker input') : [], q; for (q = 0; q !== ins.length; q++) { if (ins[q].value === String(ids[i])) cb = ins[q]; } if (cb) { await cclick(cb.closest('label') || cb); } }
          await sleep(500); await cclick(document.getElementById('submit_intersection_model')); await sleep(1200); place();
        }
        async function ensureRowsFast(n) { var g = 0; while (!document.getElementById('textin_relations_' + n) && g !== 20) { clickEl(document.getElementById('add_ie')); await sleep(800); g++; } await sleep(300); }
        function tutorialSteps() {
          function model(k, title, text, spec, extra) {
            return S(title, text, function() { return [specTd(k)]; }, { pre: function() { return ensureRowsFast(k); }, wait: 200, demo: async function(tk) { await typeInto(document.getElementById('textin_relations_' + k), spec, tk); } });
          }
          var A = [
            S('The cringe study', 'A fictitious joke study: children, teens and adults hear jokes, and we record who cringes. A theory predicts that children cringe most and adults least. This tutorial enters everything for you, so you see how it is done. It replaces your current input, so save it first if you want to keep it (Share or save).', function() { return []; }, { pre: function() { closeModal(); goTab('Input'); } }),
            S('Three probabilities', 'p1 is the probability that a child cringes, p2 that a teen cringes, and p3 that an adult cringes. Here the names are typed in.', function() { return [q1('.def-col--pnames')]; }, { demo: async function(tk) { await ensureProbs(3, tk); var names = ['p_{C}', 'p_{T}', 'p_{A}'], i; for (i = 0; i !== 3; i++) { await typeInto(document.getElementById('textin_name_' + (i + 1)), names[i], tk); } } }),
            S('The theory', 'The theory says: children cringe at least as much as teens, who cringe at least as much as adults. In the app you type p1 > p2 > p3. The app takes > for easier input and means at least as much.', function() { return [specTd(1)]; }, { demo: async function(tk) { await typeInto(document.getElementById('textin_relations_1'), 'p1 > p2 > p3', tk); } }),
            S('Vertices on', 'The vertices of the model (V-representation) are optional because they can take long for large models. Here the switch is turned on.', function() { return [q1('#vrep_toggle_btn_1')]; }, { demo: async function(tk) { if (!tabShown('V-representation')) await cclick(document.getElementById('vrep_toggle_btn_1')); } }),
            S('Go', 'Go builds the H-representation of the model, and the vertices.', function() { return [q1('#go_inline')]; }, { demo: async function(tk) { await cclick(document.getElementById('go_inline')); await waitFor(function() { return tabShown('V-representation') && tabShown('Plot Edge Cases'); }, 60000); } }),
            R2('H-representation', 'The H-representation', 'The fairy describes the model with inequalities. Line 1: p_T is at most p_C. Line 2: p_A is at most p_T. Line 3: p_C is at most 1, and line 4: p_A is at least 0, because probabilities lie between 0 and 1. On the left you can download the files for QTEST and a LaTeX file.', function() { var p = pane(); var l = p ? p.querySelectorAll('.model-card') : []; return [].filter.call(l, shown); }),
            R2('Plot Polytope(s)', 'The polytope', 'Each axis is one probability (p_C, p_T, p_A) from 0 to 1, so the cube holds all possible triples. The coloured figure marks the triples that fit your model. This figure is a polytope. Drag to rotate it.', function() { return [inPane('#plot')]; }),
            R2('V-representation', 'The vertices', 'The corner points of the polytope, written as (p_C, p_T, p_A): (1, 1, 1), (1, 1, 0), (1, 0, 0) and (0, 0, 0). Each row is one vertex and each column one probability. Vertices are the edge cases of your model.', function() { var p = pane(); var e = p ? p.querySelector('.model-card') : null; return [shown(e) ? e : null]; }),
            R2('Plot Edge Cases', 'The edge cases', 'Step through the four vertices: the plot shows the value of each probability at every vertex.', function() { return [inPane('#plot_example')]; }),
            R2('Model Properties', 'Parsimony: the volume', 'The smaller the polytope, the more parsimonious the model. Go computes its volume, the share of the cube that fits the model.', function() { return [inPane('#go_inline_pars')]; }, { demo: async function(tk) { await cclick(document.getElementById('go_inline_pars')); await waitFor(function() { return shown(document.getElementById('parsimony_bar_plot')); }, 60000); } }),
            S('1 / volume = the largest Bayes factor', 'The model fills 1/6 of the cube (about 17 percent). The reciprocal of the volume is the largest Bayes factor the model can reach against an unconstrained model: here 6. If this is too low for your purposes, look for stimuli where your theory predicts more.', function() { return [inPane('#parsimony_spinner_table')]; }),
            S('Now the full study', 'The paper crosses three age groups with two joke types: illogical jokes (i) and puns (p). That makes a 2 x 3 design with six probabilities: p1 children, p2 teens and p3 adults for illogical jokes, and p4, p5 and p6 for puns. Nine cringe theories predict how they relate.', function() { return []; }, { pre: function() { closeModal(); return tabC('Input'); } }),
            S('Six probabilities', 'Three probabilities are added and all six are named: C, T and A for children, teens and adults, with i for illogical jokes and p for puns.', function() { return [q1('.def-col--pnames')]; }, { demo: async function(tk) { await ensureProbs(6, tk); var names = ['p_{C,i}', 'p_{T,i}', 'p_{A,i}', 'p_{C,p}', 'p_{T,p}', 'p_{A,p}'], i; for (i = 0; i !== 6; i++) { await typeInto(document.getElementById('textin_name_' + (i + 1)), names[i], tk); } } }),
            S('Nine models', 'One row per theory: eight more rows are added.', function() { return [q1('.def-col--models-card')]; }, { demo: async function(tk) { await ensureModelRows(9, tk); } }),
            model(1, 'm1: cringyness increases with age', 'The first theory: cringyness increases with age, averaged over both joke types.', '1/2 * p1 + 1/2 * p4 < 1/2 * p2 + 1/2 * p5 < 1/2 * p3 + 1/2 * p6'),
            model(2, 'm2: ... irrespective of the joke type', 'Cringyness increases with age for both joke types separately. Two chains, separated by a semicolon.', 'p1 < p2 < p3; p4 < p5 < p6'),
            model(3, 'm3: opposite trends, puns cringier', 'Illogical jokes decrease with age, puns increase, and on average illogical jokes are less cringy than puns. Sums with weights are typed as 1/3 * p1.', 'p1 > p2 > p3; p4 < p5 < p6; 1/3 * p1 + 1/3 * p2 + 1/3 * p3 < 1/3 * p4 + 1/3 * p5 + 1/3 * p6'),
            model(4, 'm4: ... in every age group', 'Like m3, but puns are cringier than illogical jokes in every single age group.', 'p1 > p2 > p3; p4 < p5 < p6; p1 < p4; p2 < p5; p3 < p6'),
            model(5, 'm5: equally cringy', 'Both joke types are exactly equally cringe-worthy in all age groups: all six probabilities are equal.', 'p1 = p2 = p3 = p4 = p5 = p6'),
            model(6, 'm6: the trends balance out', 'Like m3, but the average cringyness of both joke types is exactly equal.', 'p1 > p2 > p3; p4 < p5 < p6; 1/3 * p1 + 1/3 * p2 + 1/3 * p3 = 1/3 * p4 + 1/3 * p5 + 1/3 * p6'),
            S('m7: about equally cringy', 'm7 reads about equally cringy differently: the two averages may differ by .05. The input is the same as for m6; then the equality is switched to approximate with a tolerance of .05.', function() { return [modQ('.modal-body') || specTd(7)]; }, { pre: function() { return ensureRowsFast(7); }, wait: 200, demo: async function(tk) {
              await typeInto(document.getElementById('textin_relations_7'), 'p1 > p2 > p3; p4 < p5 < p6; 1/3 * p1 + 1/3 * p2 + 1/3 * p3 = 1/3 * p4 + 1/3 * p5 + 1/3 * p6', tk);
              await sleep(1200); await cclick(document.getElementById('eq_tol_btn_7')); await sleep(1500); place();
              var sw = modQ('label[for=eq_tol_switch_7_1]'); if (sw) await cclick(sw); await sleep(700);
              await cclick(modQ('#submit_eq_tol_7')); await sleep(900); place(); } }),
            S('m8: wiggle room for all pairs', 'm8 says that all six probabilities are about the same, within .05. The braces are a shortcut: every element on the left is set equal to every element on the right, so this stands for all pairs. The buttons for each term switch all its pairs to approximate at once.', function() { return [modQ('.modal-body') || specTd(8)]; }, { pre: function() { return ensureRowsFast(8); }, wait: 200, demo: async function(tk) {
              await typeInto(document.getElementById('textin_relations_8'), '{p1,p2,p3,p4,p5,p6} = {p1,p2,p3,p4,p5,p6}', tk);
              await sleep(1200); await cclick(document.getElementById('eq_tol_btn_8')); await sleep(1500); place();
              var m = modalOpen(), bs = m ? m.querySelectorAll('#fairy-eq-tol-terms button') : [], i;
              for (i = 0; i !== 5 && i !== bs.length; i++) { await cclick(bs[i]); }
              await sleep(500); await cclick(modQ('#submit_eq_tol_8')); await sleep(900); place(); } }),
            model(9, 'm9: the opposite of m4', 'Illogical jokes increase with age, puns decrease, and illogical jokes are cringier than puns in every age group.', 'p1 < p2 < p3; p4 > p5 > p6; p1 > p4; p2 > p5; p3 > p6'),
            S('Intersections: what two models share', 'Models can make similar predictions: their polytopes overlap. The intersection of two models is the space they share. The Intersection model button adds a model with all constraints of the models you pick. Here m1 and m2.', function() { return [modQ('.modal-body') || q1('#add_intersection_model')]; }, { pre: function() { closeModal(); return tabC('Input'); }, wait: 300, demo: async function(tk) { await interDemo([1, 2], tk); } }),
            S('Another intersection: m1 and m3', 'The same for m1 and m3. Each intersection is a new row of its own.', function() { return [modQ('.modal-body') || q1('#add_intersection_model')]; }, { pre: function() { closeModal(); }, wait: 300, demo: async function(tk) { await interDemo([1, 3], tk); } }),
            S('Go for all models', 'Go builds the H-representation of every model, the nine theories and the two intersections.', function() { return [q1('#go_inline')]; }, { pre: function() { closeModal(); return tabC('Input'); }, wait: 300, demo: async function(tk) { await cclick(document.getElementById('go_inline')); await waitFor(function() { return tabShown('H-representation') && document.querySelectorAll('.tab-pane .model-card').length > 8; }, 90000); } }),
            R2('H-representation', 'One card per model', 'The H-representation of every model. Equalities are counted separately from inequalities in the badge, so m5 shows five equalities.', function() { var p = pane(); var l = p ? p.querySelectorAll('.model-card') : []; return [].filter.call(l, shown).slice(0, 2); }),
            R2('Model Properties', 'Parsimony of all models', 'Now the volumes of all models. The tournament of the paper compares the theories by how much of the space they occupy. This can take a moment for six probabilities.', function() { return [inPane('#go_inline_pars')]; }, { demo: async function(tk) { await cclick(document.getElementById('go_inline_pars')); await waitFor(function() { return shown(document.getElementById('parsimony_bar_plot')) || shown(document.getElementById('parsim_table')); }, 240000); } }),
            S('Volumes and nested models', 'The bars show each model share of the space. The intersection of m1 and m2 has the same volume as m2, so m2 is nested in m1: whenever data fit m2 they also fit m1. Because m2 is smaller, it is preferred by the Bayesian analysis, which rewards parsimony.', function() { return [inPane('#parsimony_plot_ui')]; }, { pre: function() { return tabC('Model Properties'); }, wait: 400 }),
