    (function() {
      var done = false;
      function hide() {
        if (done) return;
        done = true;
        var el = document.getElementById('fairy-loader');
        if (!el) return;
        el.classList.add('fairy-loader-done');
        setTimeout(function() { if (el.parentNode) el.parentNode.removeChild(el); }, 500);
      }
