        ")),
        tags$script(HTML("
          (function() {
            function apply() {
              var d = document.getElementById('fairy_items_diagram'), w = document.getElementById('fairy_items_fade_wrap'), t = document.getElementById('fairy_items_fade_toggle');
              if (!d || !w || !t) return;
              var faded = d.querySelectorAll('[data-implied]');
              w.style.display = faded.length ? 'block' : 'none';
              for (var i = 0; i < faded.length; i++) faded[i].style.display = t.checked ? '' : 'none';
              // the legend line for the meeting point only while one is still drawn
              var hubs = [].filter.call(d.querySelectorAll('circle[r=\"3.2\"]'), function(c) { return c.style.display !== 'none'; });
              var leg = document.getElementById('fairy_items_legend');
              if (leg) [].forEach.call(leg.querySelectorAll('span'), function(sp) { if (sp.textContent.indexOf('lines meet here') >= 0) sp.style.display = hubs.length ? '' : 'none'; });
            }
            document.addEventListener('change', function(e) { if (e.target && e.target.id === 'fairy_items_fade_toggle') apply(); });
            new MutationObserver(function() { apply(); }).observe(document.documentElement, { childList: true, subtree: true });
          })();
        ")),
        tags$script(HTML("
          (function() {
            // the floating parts live inside the dialog itself: the dialog takes the keyboard focus back from anything outside it,
            // which made the name boxes in the panel impossible to type into
            function itemsHost() { return document.querySelector('.modal:has(#submit_items_multi)') || document.body; }
            function moved(node, id) {
              var ph = document.createElement('div'); ph.id = id; node.parentNode.insertBefore(ph, node); itemsHost().appendChild(node); return ph;
            }
            function back(node, id) {
              var ph = document.getElementById(id);
              if (ph) { ph.parentNode.insertBefore(node, ph); ph.parentNode.removeChild(ph); } else if (node.parentNode) { node.parentNode.removeChild(node); }
            }
            function active() { return document.querySelector('.fairy-items-viz.fairy-items-full'); }
            function decorate(box, title) {
              box.classList.add('fairy-items-panel');
              var head = document.createElement('div');
              head.className = 'fairy-plot-panel-head';
              head.innerHTML = '<span class=\"fairy-plot-panel-grip\">\\u2847\\u2847\\u2847</span><span class=\"fairy-plot-panel-title\">' + title + '</span><button type=\"button\" title=\"Shrink / enlarge\">\\u25BE</button>';
              box.insertBefore(head, box.firstChild);
              var btn = head.querySelector('button');
              btn.addEventListener('click', function() {
                var f = box.classList.toggle('fairy-items-folded'); btn.textContent = f ? '\\u25B8' : '\\u25BE';
              });
              var drag = null;
              head.addEventListener('pointerdown', function(e) {
                if (e.target.closest('button')) return;
                var r = box.getBoundingClientRect(); drag = { dx: e.clientX - r.left, dy: e.clientY - r.top }; head.setPointerCapture(e.pointerId);
              });
              head.addEventListener('pointermove', function(e) {
                if (!drag) return;
                box.style.left = Math.max(0, Math.min(window.innerWidth - 80, e.clientX - drag.dx)) + 'px';
                box.style.top = Math.max(0, Math.min(window.innerHeight - 40, e.clientY - drag.dy)) + 'px';
              });
              head.addEventListener('pointerup', function() { drag = null; });
            }
            function expand() {
              var viz = document.querySelector('.fairy-items-viz');
              var opts = document.querySelector('.fairy-items-main > div:first-child');
              if (!viz || !opts || active()) return;
              moved(viz, 'fairy_items_viz_ph'); viz.classList.add('fairy-items-full');
              var setup = document.createElement('div'); setup.id = 'fairy_items_setup_panel'; itemsHost().appendChild(setup);
              ['fairy_items_base_wrap', 'fairy_items_q1', 'fairy_items_count_same', 'fairy_items_two_panel', 'fairy_items_quick_eps_wrap'].forEach(function(id) {
                var n = document.getElementById(id);
                if (n) { moved(n, id + '_ph'); n.classList.add('fairy-items-count'); setup.appendChild(n); }
              });
              // one panel like the settings column of the dialog: base model, items, then the options
              moved(opts, 'fairy_items_opts_ph'); setup.appendChild(opts);
              decorate(setup, 'Settings');
              var sub = document.getElementById('submit_items_multi');
              if (sub) {
                var addb = document.createElement('button'); addb.type = 'button'; addb.id = 'fairy_items_add_here'; addb.className = 'btn btn-primary fairy-items-add';
                addb.textContent = sub.textContent.trim() || 'Add';
                addb.addEventListener('click', function() { collapse(); setTimeout(function() { sub.click(); }, 50); });
                var bw = document.createElement('div'); bw.id = 'fairy_items_btns'; itemsHost().appendChild(bw); bw.appendChild(addb);
                var canb = document.createElement('button'); canb.type = 'button'; canb.id = 'fairy_items_cancel_here'; canb.className = 'btn fairy-items-add fairy-items-cancel';
                canb.textContent = 'Cancel';
                canb.addEventListener('click', function() {
                  var cx = document.querySelector('.modal:has(#submit_items_multi) .modal-footer [data-dismiss=modal], .modal:has(#submit_items_multi) .modal-footer [data-bs-dismiss=modal]');
                  collapse(); setTimeout(function() { if (cx) cx.click(); }, 50);
                });
                bw.insertBefore(canb, addb);
              }
            }
            function collapse() {
              var viz = active(), setup = document.getElementById('fairy_items_setup_panel');
              var stm = setup && setup.querySelector('#fairy_items_stmts'), opts = stm ? stm.parentNode : null;
              if (opts) back(opts, 'fairy_items_opts_ph');
              ['fairy_items_base_wrap', 'fairy_items_q1', 'fairy_items_count_same', 'fairy_items_two_panel', 'fairy_items_quick_eps_wrap'].forEach(function(id) {
                var n = document.getElementById(id);
                if (n) { n.classList.remove('fairy-items-count'); back(n, id + '_ph'); }
              });
              if (setup) setup.parentNode.removeChild(setup);
              var btns = document.getElementById('fairy_items_btns'); if (btns) btns.parentNode.removeChild(btns);
              if (viz) { viz.classList.remove('fairy-items-full'); back(viz, 'fairy_items_viz_ph'); }
            }
            document.addEventListener('click', function(e) {
              if (e.target.closest && e.target.closest('#fairy_items_expand')) { if (active()) collapse(); else expand(); }
            });
            document.addEventListener('keydown', function(e) {
              if (e.key === 'Escape' && active()) { e.stopImmediatePropagation(); e.preventDefault(); collapse(); }
            }, true);
            // only when the dialog itself closes: the conditional panels inside it send 'hide' events as well
            if (window.jQuery) jQuery(document).on('hide.bs.modal', function(e) {
              if (e.target && e.target.classList && e.target.classList.contains('modal')) collapse();
            });
          })();
        ")),
        tags$script(HTML(
          "
          (function() {
            var rotateTimer = null;
            var theta = 0, phi = 0;
            function startRotate() {
              if (rotateTimer) return;
              var gd0 = document.getElementById('plot');
              // Keep whatever zoom level is already on screen instead of
              // snapping to a fixed distance — read the current eye vector
              // (falling back to Plotly's own default) and rotate around
              // ITS radius, so toggling auto-rotate never changes the zoom.
              var eye0 = (gd0 && gd0.layout && gd0.layout.scene &&
                gd0.layout.scene.camera && gd0.layout.scene.camera.eye) ||
                {x: 1.25, y: 1.25, z: 1.25};
              var r = Math.sqrt(eye0.x*eye0.x + eye0.y*eye0.y + eye0.z*eye0.z) || 1.8;
              theta = Math.atan2(eye0.y, eye0.x);
              phi   = Math.asin(eye0.z / r);
              rotateTimer = setInterval(function() {
                var gd = document.getElementById('plot');
                if (!gd || !gd.layout) return;
                // theta tumbles the view around the vertical axis, phi
                // drifts (and wraps via sin/cos) up and down through the
                // poles, so the combined path covers all directions
                // instead of spinning flat around a single axis. r is
                // fixed for the whole rotation, so distance never changes.
                theta += 0.020;
                phi   += 0.007;
                var eye = {
                  x: r * Math.cos(theta) * Math.cos(phi),
                  y: r * Math.sin(theta) * Math.cos(phi),
                  z: r * Math.sin(phi)
                };
                Plotly.relayout(gd, {'scene.camera.eye': eye});
              }, 50);
            }
            function stopRotate() {
              if (rotateTimer) { clearInterval(rotateTimer); rotateTimer = null; }
            }
            $(document).on('change', '#auto_rotate_plot', function() {
              if ($(this).is(':checked')) startRotate(); else stopRotate();
            });
          })();
          "
        ))
      )
    ),
    tabPanel(
      HTML("&#9654; Parsimony"),
      value = "Model Properties",
      # No sidebar — this tab's controls (algorithm switches, Compute,
      # settings, download) live entirely in the same always-floating
      # panel Input's Go/Download/Upload use (see FORCE_FLOAT_TABS),
      # rather than duplicating that pattern as yet another dedicated
      # rail. bsTooltip's container="body" means it isn't affected by
      # this button being reparented into the panel later.
      div(
        class = "fairy-primary-controls-src",
        # Icon-only + a plain fairy-tooltip (same pattern as the icon
        # buttons elsewhere) instead of a labeled button — "Compute
        # parsimony" spelled out doesn't fit the compact floating panel
        # nearly as well as Go/Download/Upload's short labels did. The
        # tooltip attribute has to sit on the BUTTON itself, not a
        # wrapping span — updateFab() finds and reparents this element
        # via querySelector('.fairy-primary-action') specifically (not
        # its parent), so a wrapping span's data-tooltip would get left
        # behind, tooltip-less, the moment this button floats.
        # A single data-tooltip, kept in sync with the button's
        # enabled/disabled state by the input$CB|SoB|CG observer below
        # (which toggles the text via runjs) — a separate bsTooltip used
        # to sit here too for the disabled-state message, but shinyBS
        # binds unconditionally on hover regardless of disabled state,
        # so both tooltips ended up showing stacked/overlapping at once.
        # Compute is the ONLY thing always visible while collapsed — see
        # the matching comment on the Input tab's Go button. Stale
        # results blink Compute itself instead of a separate badge.
        # Sideways tooltip (fairy-tooltip-left) — same as every other
        # trigger in this panel (switches, settings, download), NOT the
        # upward/downward treatment Input's Go uses. Input's panel now
        # widens on hover to fit Download/Upload/Go on one row with
        # open space above, so upward works there; this panel is still
        # a TALL stack (3 switches sit directly above this same row),
        # so upward would land right back on "Sequ. of Balls" and
        # downward reads as detached from the card. Sideways is the one
        # direction that's actually clear regardless of stack position.
        actionBttn("go", "Go", style = "jelly", color = "primary", size = "sm",
          class = "fairy-primary-action fairy-tooltip fairy-tooltip-left", `data-tooltip` = "Compute parsimony (⌘/Ctrl+Enter)"),
        div(
          # Vertical stack (one switch per line) — hover-collapsible flow
          # content, same as Input's Download/Upload. Settings/Download
          # share their own row at the bottom of the stack.
          class = "fairy-primary-controls", `data-fab-layout` = "column",
          tags$span(class = "fairy-tooltip fairy-tooltip-left", style = "display:block;",
            `data-tooltip` = paste0("Calculates the volume from the corner points of the model (up to ", EXACT_VOLUME_LIMIT_TXT, " in total; you can skip it); where it works, no algorithm is needed"),
            materialSwitch("EX", "Exact volume", value = TRUE, status = "primary", right = TRUE)
          ),
          tags$span(class = "fairy-tooltip fairy-tooltip-left", style = "display:block;",
            `data-tooltip` = "Estimate the volume with algorithms for every model. Off: Cooling Bodies only runs for models whose exact volume was skipped or did not finish",
            materialSwitch("ALG", "Algorithms", value = FALSE, status = "primary", right = TRUE)
          ),
          # the three algorithms only show while Algorithms is on (kept in step by the small script below, not by a conditionalPanel:
          # this block is moved around in the page and the panel lost its state there)
          div(id = "alg_sub", style = "display:none;",
            div(style = "margin-left:14px;",
              tags$span(class = "fairy-tooltip fairy-tooltip-left", style = "display:block;",
                `data-tooltip` = "General-purpose, recommended",
                materialSwitch("CB", "Cooling Bodies", value = TRUE, status = "primary", right = TRUE)
              ),
              tags$span(class = "fairy-tooltip fairy-tooltip-left", style = "display:block;",
                `data-tooltip` = "Gaussian annealing",
                materialSwitch("CG", "Cooling Gaussian", value = FALSE, status = "primary", right = TRUE)
              ),
              tags$span(class = "fairy-tooltip fairy-tooltip-left", style = "display:block;",
                `data-tooltip` = "Ball-based annealing",
                materialSwitch("SoB", "Sequ. of Balls", value = FALSE, status = "primary", right = TRUE)
              )
            )
          ),
          tags$script(HTML("(function() { function syncAlg() { var a = document.getElementById('ALG'), d = document.getElementById('alg_sub'); if (a && d) d.style.display = a.checked ? '' : 'none'; } document.addEventListener('change', function(e) { if (e.target && e.target.id === 'ALG') syncAlg(); }); setInterval(syncAlg, 300); })();")),
          tags$div(class = "fairy-pars-hint",
            "The exact volume is calculated first. It has a time limit and can be skipped; the algorithm then estimates the volume instead. ",
            "With Algorithms on, the chosen algorithms run for every model as well."),
          div(class = "fairy-fab-action-row",
            tags$span(class = "fairy-tooltip fairy-tooltip-left", `data-tooltip` = "Algorithm settings",
              # Same square fairy-toolbar-iconbtn look Download uses
              # (and Input's Download/Upload both use) — was the round
              # jelly-pill style before, visually inconsistent with the
              # icon next to it.
              actionButton("show", NULL, icon = icon("sliders"), class = "fairy-toolbar-iconbtn")
            )
          )
        )
      ),
      mainPanel(
        width = 12,
        fluidPage(
          div(
            class = "model-def-panel",
            style = "padding: 18px 22px;",
            # a big Go at the top of this page too (the one in the floating panel is easy to miss)
            tags$div(class = "fairy-go-inline fairy-go-inline-stack", style = "margin-top:0;",
              tags$button(id = "go_inline_pars", type = "button", class = "btn fairy-go-inline-btn",
                onclick = "var g = document.getElementById('go'); if (g && !g.disabled) g.click();",
                icon("play"), tags$span("Go"),
                tags$small("compute parsimony"))),
            uiOutput("parsimony_placeholder_ui"),
            div(id = "parsim_out",
              uiOutput("parsimony_stale_note"),
              uiOutput("ex_skipped_note"),
              uiOutput("parsimony_results_header_ui"),
              uiOutput("parsimony_plot_ui"),
              uiOutput("parsimony_spinner_table")
            )
          )
        )
      )
    )
  ),
  navbarPage(
    title = "",
    position = "fixed-bottom",
    fluid = T,
    inverse = F,
    id = "banner"
  )
))

server <- shinyServer(function(input, output, session) {

  `%||%` <- function(a, b) if (!is.null(a)) a else b

  win_cluster <- NULL

  par_lapply <- function(X, FUN, ...) {
    if (isTRUE(isolate(input$use_parallel))) {
      n_cores <- max(1L, parallel::detectCores(logical = FALSE) - 1L)
      if (.Platform$OS.type == "windows") {
        # mclapply forks, which the Windows kernel does not support (it
        # silently runs sequentially there) — a PSOCK cluster of worker
        # processes is the Windows-compatible equivalent. Reuse one cluster
        # for the whole session instead of spinning one up per call, since
        # starting worker processes is comparatively slow.
        if (is.null(win_cluster)) {
          win_cluster <<- parallel::makeCluster(n_cores)
          parallel::clusterEvalQ(win_cluster, library(rcdd))
          session$onSessionEnded(function() {
            tryCatch(parallel::stopCluster(win_cluster), error = function(e) NULL)
          })
        }
        parallel::parLapply(win_cluster, X, FUN, ...)
      } else {
        parallel::mclapply(X, FUN, mc.cores = n_cores, ...)
      }
    } else {
      lapply(X, FUN, ...)
    }
  }

  # ---- One large, persistent run window (replaces the small progress popups) ----
  # A Go click opens it once; every model is a table row with an H and a V
  # column whose state changes in place (wait / run / done / cached / warn /
  # fail). It stays on screen until the user closes it. Rows are created on
  # first use, so intersections, mixtures and items models simply appear when
  # their phase starts.
  fairy_run_begin <- function(title = "Calculating", cols = c("H-representation", "V-representation"), skippable = FALSE) {
    session$sendCustomMessage("fairy_run_begin", list(title = title, cols = as.list(cols), skippable = skippable))
  }
  fairy_run_row <- function(name, kind = NULL, h = NULL, v = NULL) {
    msg <- Filter(Negate(is.null), list(name = as.character(name), kind = kind, h = h, v = v))
    session$sendCustomMessage("fairy_run_row", msg)
  }
  fairy_run_end <- function(note = "") session$sendCustomMessage("fairy_run_end", list(note = note))
  # the columns of the Parsimony run window (exact volume, one column per algorithm) and a state in one of them
  run_cols <- reactiveVal(character(0))
  fairy_run_cell <- function(name, col, state) {
    i <- match(col, isolate(run_cols()))
    if (is.na(i)) {
      run_cols(c(isolate(run_cols()), col)); i <- length(isolate(run_cols()))
      session$sendCustomMessage("fairy_run_addcol", list(name = col))
    }
    if (!is.na(i)) session$sendCustomMessage("fairy_run_row", list(name = as.character(name), col = i - 1L, state = state))
  }
  # last mixture results by name, with a signature of the component models they were built from
  mixture_cache <- new.env()
  # The mixtures are calculated in separate R processes (like the vertices): the window stays alive, a mixture can be skipped.
  # The Go run stops after it has started them and is repeated (without a new window) when they are done; the results wait in
  # mixture_results, keyed by the signature of the mixture (components and their H-representations).
  mixture_results <- new.env()
  mix_job <- reactiveValues(active = FALSE, dir = NULL, names = character(0), sigs = list(), queue = character(0), procs = list(),
                            skipped = character(0), resume = FALSE, parallel = FALSE)
  mix_kill_all <- function() {
    for (p in isolate(mix_job$procs)) try(p$kill_tree(), silent = TRUE)
    mix_job$procs <- list()
  }
  mix_job_script <- c(
    "suppressMessages(library(rcdd))",
    "a <- commandArgs(TRUE); inp <- readRDS(a[1])",
    "res <- tryCatch({",
    "  V_sel <- lapply(inp$sel, function(m) {",
    "    h_comp <- inp$h[[m]]",
    "    if (ncol(h_comp) != ncol(inp$cube)) return(NULL)",
    "    h_full <- rbind(h_comp, inp$cube); attr(h_full, 'representation') <- 'H'",
    "    v_out <- tryCatch(scdd(h_full)$output, error = function(e) NULL)",
    "    if (is.null(v_out)) return(NULL)",
    "    v_out[v_out[, 2] == '1', , drop = FALSE]",
    "  })",
    "  V_sel <- c(V_sel, inp$extra); V_sel <- Filter(function(v) !is.null(v) && nrow(v) > 0, V_sel)",
    "  if (length(V_sel) == 0) list(error = 'its component models have no extreme cases to combine') else {",
    "    V_comb <- do.call(rbind, V_sel); attr(V_comb, 'representation') <- 'V'",
    "    hh <- scdd(V_comb)$output",
    "    if (nrow(hh) > 1) { hh <- redundant(hh)$output; attr(hh, 'representation') <- 'H' }",
    "    colnames(hh) <- inp$h1_cols",
    "    vv <- scdd(hh)",
    "    if (!is.null(inp$v1cols) && length(inp$v1cols) == ncol(vv$output)) colnames(vv$output) <- inp$v1cols else colnames(vv$output) <- inp$h1_cols",
    "    list(h = hh, v = vv)",
    "  }",
    "}, error = function(e) list(error = conditionMessage(e)))",
    "saveRDS(res, a[2])"
  )
  mix_start_jobs <- function(pending) {
    mix_kill_all()
    d <- tempfile("mixrun_"); dir.create(d)
    writeLines(mix_job_script, file.path(d, "job.R"))
    nms <- names(pending)
    for (i in seq_along(nms)) saveRDS(pending[[i]]$input, file.path(d, paste0("in", i, ".rds")))
    mix_job$dir <- d; mix_job$names <- nms; mix_job$sigs <- lapply(pending, function(x) x$sig); mix_job$queue <- nms; mix_job$procs <- list()
    mix_job$parallel <- isTRUE(isolate(input$use_parallel))
    mix_job$active <- TRUE
    session$sendCustomMessage("fairy_run_cancelable", list(on = TRUE, input = "v_cancel", label = "Skip all"))
    for (m in nms) fairy_run_row(m, "mixture", h = "wait", v = "wait")
  }
  observe({
    if (!isTRUE(mix_job$active)) return()
    invalidateLater(400)
    d <- isolate(mix_job$dir); nms <- isolate(mix_job$names); procs <- isolate(mix_job$procs); queue <- isolate(mix_job$queue)
    for (m in names(procs)) {
      if (!procs[[m]]$is_alive()) {
        idx <- match(m, nms)
        res <- tryCatch(readRDS(file.path(d, paste0("out", idx, ".rds"))), error = function(e) list(error = "the calculation did not finish"))
        assign(isolate(mix_job$sigs)[[m]], res, envir = mixture_results)
        fairy_run_row(m, h = if (is.null(res$error)) "done" else "fail", v = if (is.null(res$error)) "done" else "fail")
        procs[[m]] <- NULL
      }
    }
    max_run <- if (isolate(mix_job$parallel)) length(nms) else 1L
    while (length(queue) > 0 && length(procs) < max_run) {
      m <- queue[1]; queue <- queue[-1]; idx <- match(m, nms)
      pr <- tryCatch(processx::process$new(file.path(R.home("bin"), "Rscript"),
        c(file.path(d, "job.R"), file.path(d, paste0("in", idx, ".rds")), file.path(d, paste0("out", idx, ".rds"))), cleanup_tree = TRUE),
        error = function(e) NULL)
      if (is.null(pr)) { assign(isolate(mix_job$sigs)[[m]], list(error = "the calculation could not be started"), envir = mixture_results); fairy_run_row(m, h = "fail", v = "fail") }
      else { procs[[m]] <- pr; fairy_run_row(m, h = "run", v = "run") }
    }
    mix_job$procs <- procs; mix_job$queue <- queue
    if (length(queue) == 0 && length(procs) == 0) {
      mix_job$active <- FALSE
      unlink(d, recursive = TRUE)
      mix_job$resume <- TRUE   # the Go run is repeated: the results are taken from mixture_results
      shinyjs::runjs("var g = document.getElementById('go_v_h'); if (g) g.click();")
    }
  })
  # a mixture is skipped (this run only); any other model in the list: its V-representation is switched off (as everywhere else)
  mix_skip <- function(m) {
    procs <- isolate(mix_job$procs); queue <- isolate(mix_job$queue)
    if (!is.null(procs[[m]]) || m %in% queue) {
      if (!is.null(procs[[m]])) { try(procs[[m]]$kill_tree(), silent = TRUE); procs[[m]] <- NULL; mix_job$procs <- procs }
      mix_job$queue <- setdiff(queue, m)
      mix_job$skipped <- unique(c(isolate(mix_job$skipped), m)); mix_job$stale <- TRUE
      fairy_run_row(m, h = "skip", v = "skip")
    } else {
      set_v_included(m, FALSE); v_skipped_mem(union(isolate(v_skipped_mem()), m)); last_recomputed_snapshot(NULL)
      fairy_run_row(m, v = "skip")
    }
  }
  mix_unskip <- function(m) {
    if (m %in% isolate(mix_job$skipped)) {
      mix_job$skipped <- setdiff(isolate(mix_job$skipped), m)
      mix_job$queue <- c(isolate(mix_job$queue), m)
      fairy_run_row(m, h = "wait", v = "wait")
    } else {
      set_v_included(m, TRUE); v_skipped_mem(setdiff(isolate(v_skipped_mem()), m)); fairy_run_row(m, v = "wait")
    }
  }
  hint_cache <- new.env()   # results of rows built from H-representations of their sources (intersections with mixtures, unpacked models)

  # An unexpected R error inside a big computation block used to end the session (greyed-out
  # app). Report it in the run window / as a notification instead and keep the session alive.
  fairy_report_error <- function(e, where) {
    msg <- conditionMessage(e)
    message("[fairy] error in ", where, ": ", msg)
    if (!is.null(conditionCall(e))) message("[fairy]   call: ", substr(paste(deparse(conditionCall(e)), collapse = " "), 1, 300))
    if (identical(where, "go_v_h")) {
      fairy_run_end(paste0("<b>Error:</b> the calculation stopped (", htmltools::htmlEscape(msg),
        "). Your input is unchanged; please check the models and try again."))
    } else {
      if (identical(where, "go")) fairy_run_hide()
      showNotification(HTML(paste0("Something went wrong. Please check your input and try again.<br><small style='opacity:.75;'>Technical detail: ",
                                   htmltools::htmlEscape(msg), "</small>")),
        type = "error", duration = 12)
    }
  }
  # Cheap pre-check: bounds on a single probability that contradict each other
  # (e.g. "p1 < .3; p1 > .5"). Returns one message per conflicting probability.
  fairy_bound_conflicts <- function(spec) {
    spec <- enc2utf8(spec)
    spec <- gsub("\u2264", "<=", gsub("\u2265", ">=", spec, fixed = TRUE, useBytes = TRUE), fixed = TRUE, useBytes = TRUE)
    num <- function(x) {
      x <- trimws(x)
      if (grepl("^[0-9]*\\.?[0-9]+$", x)) return(as.numeric(x))
      if (grepl("^[0-9.]+/[0-9.]+$", x)) { a <- as.numeric(strsplit(x, "/")[[1]]); return(a[1] / a[2]) }
      NA_real_
    }
    isvar <- function(x) grepl("^p[0-9]+$", trimws(x))
    lo <- list(); hi <- list()   # per probability: list(v = value, strict = TRUE/FALSE)
    upd_lo <- function(k, v, st) { cur <- lo[[k]]; if (is.null(cur) || v > cur$v || (v == cur$v && st)) lo[[k]] <<- list(v = v, strict = st) }
    upd_hi <- function(k, v, st) { cur <- hi[[k]]; if (is.null(cur) || v < cur$v || (v == cur$v && st)) hi[[k]] <<- list(v = v, strict = st) }
    for (cl in strsplit(spec, ";", fixed = TRUE)[[1]]) {
      ops <- regmatches(cl, gregexpr("[<>]=?|=", cl))[[1]]
      opd <- strsplit(cl, "[<>]=?|=")[[1]]
      if (length(ops) == 0 || length(opd) != length(ops) + 1) next
      for (i in seq_along(ops)) {
        op <- ops[i]; a <- opd[i]; b <- opd[i + 1]
        if (op == "=") next
        if (isvar(a) && !is.na(num(b))) { k <- trimws(a); v <- num(b); less <- grepl("^<", op) }
        else if (isvar(b) && !is.na(num(a))) { k <- trimws(b); v <- num(a); less <- grepl("^>", op) }  # 5 < p1 means p1 > 5
        else next
        st <- FALSE   # closed sets: < counts like <=
        if (less) upd_hi(k, v, st) else upd_lo(k, v, st)
      }
    }
    # Comparisons between probabilities (p1 > p2; p2 > p3; p3 > p1 ...) together with the bounds:
    # difference constraints x - y <= w, solved with Floyd-Warshall; a negative cycle (or a zero
    # cycle through a strict step) means no probability vector satisfies everything.
    graph_msg <- character()
    {
      edges <- list()
      add_edge <- function(from, to, w, st) edges[[length(edges) + 1]] <<- list(from, to, w, st)
      vars <- character()
      for (cl in strsplit(spec, ";", fixed = TRUE)[[1]]) {
        ops <- regmatches(cl, gregexpr("[<>]=?|=", cl))[[1]]
        opd <- trimws(strsplit(cl, "[<>]=?|=")[[1]])
        if (length(ops) == 0 || length(opd) != length(ops) + 1) next
        for (i in seq_along(ops)) {
          op <- ops[i]; a <- opd[i]; b <- opd[i + 1]
          if (op == "=") next
          st <- FALSE   # closed sets: < counts like <=
          if (isvar(a) && isvar(b)) {
            vars <- c(vars, a, b)
            if (grepl("^<", op)) add_edge(b, a, 0, st) else add_edge(a, b, 0, st)     # a - b <= 0  /  b - a <= 0
          } else if (isvar(a) && !is.na(num(b))) {
            vars <- c(vars, a)
            if (grepl("^<", op)) add_edge("Z", a, num(b), st) else add_edge(a, "Z", -num(b), st)
          } else if (isvar(b) && !is.na(num(a))) {
            vars <- c(vars, b)
            if (grepl("^<", op)) add_edge(b, "Z", -num(a), st) else add_edge("Z", b, num(a), st)
          }
        }
      }
      vars <- unique(vars)
      if (length(vars) > 0 && length(edges) > 0) {
        for (v in vars) { add_edge(v, "Z", 0, FALSE); add_edge("Z", v, 1, FALSE) }   # 0 <= p <= 1
        nodes <- c("Z", vars); n <- length(nodes)
        D <- matrix(Inf, n, n, dimnames = list(nodes, nodes)); S <- matrix(FALSE, n, n, dimnames = list(nodes, nodes))
        diag(D) <- 0
        for (e in edges) {
          if (e[[3]] < D[e[[1]], e[[2]]] || (e[[3]] == D[e[[1]], e[[2]]] && e[[4]] && !S[e[[1]], e[[2]]])) {
            D[e[[1]], e[[2]]] <- e[[3]]; S[e[[1]], e[[2]]] <- e[[4]]
          }
        }
        for (k in seq_len(n)) for (i in seq_len(n)) for (j in seq_len(n)) {
          nd <- D[i, k] + D[k, j]; ns <- S[i, k] || S[k, j]
          if (nd < D[i, j] - 1e-12 || (abs(nd - D[i, j]) <= 1e-12 && ns && !S[i, j])) { D[i, j] <- nd; S[i, j] <- ns }
        }
        bad <- vars[vapply(vars, function(v) D[v, v] < -1e-12 || (abs(D[v, v]) <= 1e-12 && S[v, v]), logical(1))]
        if (length(bad) > 0) graph_msg <- paste0(paste(bad, collapse = ", "), " cannot satisfy all comparisons at once")
      }
    }
    msgs <- character()
    for (k in union(names(lo), names(hi))) {
      l <- lo[[k]]; h <- hi[[k]]
      if (is.null(l)) l <- list(v = 0, strict = FALSE)
      if (is.null(h)) h <- list(v = 1, strict = FALSE)
      if (l$v > h$v || (l$v == h$v && (l$strict || h$strict))) {
        msgs <- c(msgs, paste0(k, " would have to be ", if (l$strict) "above " else "at least ", format(l$v),
          " and ", if (h$strict) "below " else "at most ", format(h$v), " at the same time"))
      }
    }
    if (length(msgs) == 0) msgs <- graph_msg
    msgs
  }
  # where an error happened: the calls that were active at that moment (with the line in app.R), for the log of the server
  fairy_note_stack <- function() {
    cl <- sys.calls()
    out <- vapply(rev(utils::tail(cl, 16)), function(x) {
      sr <- attr(x, "srcref")
      paste0(substr(paste(deparse(x), collapse = " "), 1, 70), if (!is.null(sr)) paste0(" [app.R#", sr[1], "]") else "")
    }, character(1))
    message("[fairy]   stack: ", paste(out, collapse = "  <-  "))
  }
  observe_guarded <- function(event, handler, where = "go") {
    ev <- substitute(event); hd <- substitute(handler); env <- parent.frame()
    observeEvent(
      eventExpr = ev,
      handlerExpr = bquote(tryCatch(withCallingHandlers(.(hd), error = function(e) fairy_note_stack()), error = function(e) fairy_report_error(e, .(where)))),
      event.quoted = TRUE, handler.quoted = TRUE, event.env = env, handler.env = env
    )
  }
  fairy_run_hide <- function() session$sendCustomMessage("fairy_run_hide", list())
  # one way to tell the user something that needs attention: a toast that stays until it is closed (errors, warnings) or
  # goes away by itself (info). Replaces the pop-up windows (shinyalert), which blocked the page.
  # every notification of the app: information disappears by itself after the same time, warnings and errors stay until they are closed
  showNotification <- function(ui, action = NULL, duration = 5, closeButton = TRUE, id = NULL,
                               type = c("default", "message", "warning", "error"), session = shiny::getDefaultReactiveDomain(), sticky = FALSE) {
    type <- match.arg(type)
    shiny::showNotification(ui, action = action, duration = if (sticky || type %in% c("warning", "error")) NULL else 8,
                            closeButton = TRUE, id = id, type = type, session = session)
  }
  fairy_notify <- function(title, text = "", type = "warning", html = FALSE) {
    body <- if (nzchar(text)) paste0("<br>", if (html) text else gsub("\n", "<br>", htmltools::htmlEscape(text))) else ""
    showNotification(HTML(paste0("<b>", htmltools::htmlEscape(title), "</b>", body)),
                     type = if (type == "info") "message" else type, duration = if (type == "info") 8 else NULL)
  }

  # V-representations (vertex enumeration with scdd) run in separate R processes, so the window stays alive: it shows what is
  # computed and can be cancelled. State of the running job; `after` is what the Go run does when all vertices are there.
  # After the last running model was skipped the window does not close at once: a few seconds remain to take the skip back (Undo skip)
  ex_grace <- reactiveVal(NULL); v_grace <- reactiveVal(NULL); mn_grace <- reactiveVal(NULL)
  grace_wait <- function(rv, skipped) {
    if (length(skipped) == 0) return(FALSE)
    g <- isolate(rv())
    if (is.null(g)) { rv(Sys.time() + 5); session$sendCustomMessage("fairy_run_phase", list(text = "Skipped: going on in a moment")); session$sendCustomMessage("fairy_run_cancel_label", list(text = "Continue now")); return(TRUE) }
    if (Sys.time() < g) return(TRUE)
    rv(NULL); FALSE
  }
  # models whose V-representation was skipped by hand (their V switch is off): they stay in the run window as skipped, with Retry
  v_skipped_mem <- reactiveVal(character(0))
  poly_state <- reactiveVal(NULL)   # the last 3D polytope plot (traces, axis names, colours) for its vector PDF
  output$download_polytope_pdf <- downloadHandler(
    filename = function() paste0("polytope_", Sys.Date(), ".pdf"),
    content = function(file) {
      st <- isolate(poly_state())
      req(!is.null(st))
      r <- polytope_pdf(file, st$p, st$dims, isolate(input$plot_camera), st$cols)
      pdf_finish_link(file, attr(r, "link"))
    }
  )
  outputOptions(output, "download_polytope_pdf", suspendWhenHidden = FALSE)
  # the banner above the V-representation: which models were skipped by hand (same look as in the other calculations)
  output$v_skipped_note <- renderUI({
    sk <- v_skipped_mem()
    if (length(sk) == 0) return(NULL)
    tags$div(class = "fairy-skipnote",
      icon("circle-info"), tags$span(" Skipped earlier: ", tags$b(paste(sk, collapse = ", ")), " (no V-representation)."),
      actionLink("v_retry_mem", if (length(sk) > 1) "Retry all" else "Retry"))
  })
  observeEvent(input$v_retry_mem, {
    for (m0 in isolate(v_skipped_mem())) if (is.null(get0(m0, envir = mix_components, inherits = FALSE))) set_v_included(m0, TRUE)
    v_skipped_mem(character(0))
    shinyjs::runjs("var g = document.getElementById('go_v_h'); if (g) g.click();")
  })
  v_state <- reactiveValues(active = FALSE, dir = NULL, models = character(0), queue = character(0), procs = list(),
                            parallel = FALSE, after = NULL, skipped = character(0))
  v_kill_all <- function() {
    for (p in isolate(v_state$procs)) try(p$kill_tree(), silent = TRUE)
    v_state$procs <- list()
  }
  # switch the V-representation of a model on or off: the data frame behind the V buttons of the Input tab (a model that is a mixture
  # always has one and is not switched)
  set_v_included <- function(model_name, flag) {
    vtab <- isolate(mytable_v_reactive$value)
    if (is.null(vtab) || ncol(vtab) < 2) return(invisible())
    row_idx <- which(vtab[[1]] == model_name)
    if (length(row_idx) == 0) return(invisible())
    vtab[row_idx[1], 2] <- flag
    mytable_v_reactive$value <- vtab
    # a V-representation that was skipped was not calculated: it no longer counts as calculated, so switching it on again is a real change
    if (!isTRUE(flag)) for (rv in list(last_computed_snapshot, last_parsimony_snapshot)) {
      snap <- isolate(rv())
      if (!is.null(snap) && !is.null(snap$v_selection) && ncol(snap$v_selection) >= 2) {
        sv <- snap$v_selection; sv[[2]][sv[[1]] == model_name] <- FALSE; snap$v_selection <- sv; rv(snap)
      }
    }
  }
  v_start_jobs <- function(models) {
    v_kill_all()
    d <- tempfile("vrun_"); dir.create(d)
    writeLines(c("suppressMessages(library(rcdd))", "a <- commandArgs(TRUE)", "h <- readRDS(a[1])",
                 "res <- tryCatch(scdd(h), error = function(e) NULL)", "saveRDS(res, a[2])"), file.path(d, "job.R"))
    for (i in seq_along(models)) saveRDS(isolate(h_reactive[[models[i]]]), file.path(d, paste0("h", i, ".rds")))
    v_state$dir <- d; v_state$models <- models; v_state$queue <- models; v_state$procs <- list(); v_state$after <- NULL; v_state$skipped <- character(0)
    v_state$parallel <- isTRUE(isolate(input$use_parallel))
    v_grace(NULL)
    v_state$active <- TRUE
    session$sendCustomMessage("fairy_run_cancelable", list(on = TRUE, input = "v_cancel", label = "Skip all"))
    session$sendCustomMessage("fairy_run_limit", list(seconds = if (isTRUE(isolate(v_nolimit()))) 0 else V_REP_LIMIT, nolimit = isTRUE(isolate(v_nolimit())), label = "each V-representation"))
  }
  # fairy dust (five quick clicks on the title or the time of the run window): no time limit for the V-representations
  v_nolimit <- reactiveVal(FALSE)
  observeEvent(input$v_unlock, {
    v_nolimit(!isTRUE(v_nolimit()))
    if (isTRUE(isolate(v_state$active))) session$sendCustomMessage("fairy_run_limit", list(seconds = if (v_nolimit()) 0 else V_REP_LIMIT, nolimit = v_nolimit(), label = "each V-representation"))
    showNotification(if (v_nolimit()) "\u2728 Fairy dust: no time limit for the V-representations (five quick clicks on the title switch it off again)." else paste0("The time limit is back (", V_REP_LIMIT %/% 60, " minutes)."),
                     type = "message", duration = 6)
  })
  v_finish_models <- function(m, res) {
    h_cn <- colnames(isolate(h_reactive[[m]]))
    if (is.null(res) || nrow(data.frame(res)) == 0) {
      fairy_run_row(m, v = "fail")
    } else {
      pn <- isolate(probs_reactive$value)
      colnames(res$output) <- if (!is.null(h_cn) && length(h_cn) == ncol(res$output)) h_cn else c("", "", pn[, 2])
      v_reactive[[m]] <- res
      fairy_run_row(m, v = "done")
    }
  }
  observe({
    if (!isTRUE(v_state$active)) return()
    invalidateLater(400)
    d <- isolate(v_state$dir); models <- isolate(v_state$models)
    procs <- isolate(v_state$procs); queue <- isolate(v_state$queue)
    # collect what has finished
    for (m in names(procs)) {
      if (!procs[[m]]$is_alive()) {
        idx <- match(m, models)
        res <- tryCatch(readRDS(file.path(d, paste0("v", idx, ".rds"))), error = function(e) NULL)
        v_finish_models(m, res)
        procs[[m]] <- NULL
      }
    }
    # a V-representation that takes longer than the time limit is stopped (like a skip: the model can be retried)
    for (m in names(procs)) {
      p <- procs[[m]]
      if (is.null(p) || !p$is_alive()) next
      if (!isTRUE(isolate(v_nolimit())) && as.numeric(difftime(Sys.time(), p$get_start_time(), units = "secs")) > V_REP_LIMIT) {
        try(p$kill_tree(), silent = TRUE); procs[[m]] <- NULL
        v_state$skipped <- unique(c(isolate(v_state$skipped), m))
        last_recomputed_snapshot(NULL)
        if (is.null(get0(m, envir = mix_components, inherits = FALSE))) { set_v_included(m, FALSE); v_skipped_mem(union(isolate(v_skipped_mem()), m)) }
        fairy_run_row(m, v = "stop")
      }
    }
    # start the next one(s): one at a time, or all at once in parallel mode
    max_run <- if (isolate(v_state$parallel)) length(models) else 1L
    while (length(queue) > 0 && length(procs) < max_run) {
      m <- queue[1]; queue <- queue[-1]
      idx <- match(m, models)
      p <- tryCatch(processx::process$new(file.path(R.home("bin"), "Rscript"),
                      c(file.path(d, "job.R"), file.path(d, paste0("h", idx, ".rds")), file.path(d, paste0("v", idx, ".rds"))),
                      cleanup_tree = TRUE), error = function(e) NULL)
      if (is.null(p)) { fairy_run_row(m, v = "fail") } else { procs[[m]] <- p; fairy_run_row(m, v = "run") }
    }
    v_state$procs <- procs; v_state$queue <- queue
    if (length(queue) == 0 && length(procs) == 0 ) {
      v_state$active <- FALSE
      session$sendCustomMessage("fairy_run_limit", list(seconds = 0))
      af <- isolate(v_state$after)
      if (is.function(af)) isolate(af(character(0), isolate(v_state$skipped)))
      if (isTRUE(isolate(v_state$retry_go))) {
        v_state$retry_go <- FALSE
        shinyjs::runjs("var g = document.getElementById('go_v_h'); if (g) g.click();")
      }
    }
  })
  # one model is skipped: its process is stopped (or it leaves the queue), the others go on
  observeEvent(input$v_skip_model, {
    if (isTRUE(isolate(mix_job$active))) { mix_skip(input$v_skip_model); return() }   # the mixtures are being calculated
    if (!isTRUE(isolate(v_state$active))) return()
    m <- input$v_skip_model; procs <- isolate(v_state$procs); queue <- isolate(v_state$queue)
    if (is.null(procs[[m]]) && !(m %in% queue)) return()
    if (!is.null(procs[[m]])) { try(procs[[m]]$kill_tree(), silent = TRUE); procs[[m]] <- NULL; v_state$procs <- procs }
    v_state$queue <- setdiff(queue, m)
    v_state$skipped <- unique(c(isolate(v_state$skipped), m))
    # what Go found is no longer complete: the next Go must not decide that nothing changed (the V switch can be turned on again)
    last_recomputed_snapshot(NULL)
    # the same switch as the V button of the model on the Input tab; a mixture always has its V-representation (its switch stays on):
    # for a mixture the skip holds for this run only, the next Go calculates it again
    if (is.null(get0(m, envir = mix_components, inherits = FALSE))) { set_v_included(m, FALSE); v_skipped_mem(union(isolate(v_skipped_mem()), m)) }
    fairy_run_row(m, v = "skip")
  })
  # the skip is taken back: the model waits for its turn again
  observeEvent(input$v_unskip_model, {
    if (isTRUE(isolate(mix_job$active))) { mix_unskip(input$v_unskip_model); return() }
    if (!isTRUE(isolate(v_state$active))) {
      # after the run: the V switch of the model is on again and Go is repeated, the rest comes from the cache
      m0 <- input$v_unskip_model
      if (is.null(get0(m0, envir = mix_components, inherits = FALSE))) set_v_included(m0, TRUE)
      v_skipped_mem(setdiff(isolate(v_skipped_mem()), m0))
      shinyjs::runjs("var g = document.getElementById('go_v_h'); if (g) g.click();")
      return()
    }
    m <- input$v_unskip_model
    if (!(m %in% isolate(v_state$skipped))) {
      # skipped in an earlier run (not part of this one): the switch goes on and Go is repeated when this run is over
      if (m %in% isolate(v_skipped_mem())) {
        if (is.null(get0(m, envir = mix_components, inherits = FALSE))) set_v_included(m, TRUE)
        v_skipped_mem(setdiff(isolate(v_skipped_mem()), m))
        v_state$retry_go <- TRUE
        fairy_run_row(m, v = "wait")
      }
      return()
    }
    v_skipped_mem(setdiff(isolate(v_skipped_mem()), m))
    v_state$skipped <- setdiff(isolate(v_state$skipped), m)
    if (is.null(get0(m, envir = mix_components, inherits = FALSE))) set_v_included(m, TRUE)
    v_state$queue <- c(isolate(v_state$queue), m)
    fairy_run_row(m, v = "wait")
    v_grace(NULL); session$sendCustomMessage("fairy_run_phase", list(text = "Calculating")); session$sendCustomMessage("fairy_run_cancel_label", list(text = ""))
  })
  # Retry all: every skipped model gets its V switch back and Go is repeated once
  observeEvent(input$v_retry_all, {
    for (m0 in as.character(input$v_retry_all)) {
      if (is.null(get0(m0, envir = mix_components, inherits = FALSE))) set_v_included(m0, TRUE)
    }
    v_skipped_mem(setdiff(isolate(v_skipped_mem()), as.character(input$v_retry_all)))
    shinyjs::runjs("var g = document.getElementById('go_v_h'); if (g) g.click();")
  })
  observeEvent(input$v_cancel, {
    if (isTRUE(isolate(mix_job$active))) {
      # the mixtures are being calculated: everything stops, the input stays as it is
      left <- c(names(isolate(mix_job$procs)), isolate(mix_job$queue))
      mix_kill_all(); mix_job$queue <- character(0); mix_job$active <- FALSE
      for (m in left) fairy_run_row(m, h = "cancel", v = "cancel")
      session$sendCustomMessage("fairy_run_cancelable", list(on = FALSE))
      fairy_run_end("<b>Cancelled:</b> the mixtures were not calculated. Press Go to try again.")
      return()
    }
    if (!is.null(isolate(v_grace()))) { v_grace(Sys.time() - 1); return() }
    if (!isTRUE(isolate(v_state$active))) return()
    left <- c(names(isolate(v_state$procs)), isolate(v_state$queue))
    v_kill_all()
    v_state$queue <- character(0)
    v_state$active <- FALSE
    if (length(left) > 0) last_recomputed_snapshot(NULL)
    for (m in left) fairy_run_row(m, v = "cancel")
    af <- isolate(v_state$after)
    if (is.function(af)) isolate(af(left, isolate(v_state$skipped)))
  })
  session$onSessionEnded(function() { for (p in isolate(v_state$procs)) try(p$kill_tree(), silent = TRUE) })
  fairy_empty_set_note <- function(empty_set) {
    if (length(empty_set) == 0) return("")
    paste0("<b>Warning:</b> do not interpret the H- and V-descriptions of model(s) ",
      paste0(htmltools::htmlEscape(empty_set), collapse = ", "),
      " — they form an empty set. For instance, the input 'p1 > .5; p1 < .1' cannot be simultaneously satisfied.")
  }

  shinyjs::html(
    id = "banner",
    html = paste0("<p class='fairy-banner-text'>", if (nzchar(APP_UPDATED)) paste0("Updated ", APP_UPDATED, " &middot; ") else "",
                  "<a href='https://modeling-for-everyone.eu/posts/fairy/#whats-new' target='_blank' rel='noopener'>what's new</a> &middot; under active development &middot; ",
                  "<a href='mailto:mjekel@uni-koeln.de?subject=bug-report fairy app'>report a bug</a> &middot; <a href='#' id='fairy-kbd-open'>keyboard shortcuts (?)</a> &middot; <a href='#' id='fairy-tour-open'>take a tour</a></p>"),
    add = TRUE
  )


  hide("hidden_b")
  hide("open_b")


  hideTab(inputId = "tabs", target = "H-representation")
  hideTab(inputId = "tabs", target = "V-representation")
  hideTab(inputId = "tabs", target = "Model Properties")
  hideTab(inputId = "tabs", target = "Plot Polytope(s)")
  hideTab(inputId = "tabs", target = "Plot Edge Cases")

  observe({
    if (length(names_models_reactive$value) < 1 || all(is.na(names_models_reactive$value)))
      hideTab(inputId = "tabs", target = "Model Properties")
  })

  ##### Global Variables ####

  h_reactive <- reactiveValues()
  v_reactive <- reactiveValues()

  h_pars_reactive     <- reactiveValues()
  comp_int_reactive   <- reactiveValues(names = character())  # pairwise intersections auto-added for Parsimony
  # Row count of a model's H-representation BEFORE redundant() strips
  # implied clauses, captured where it's built (redundant()'s output is
  # what gets stored in h_reactive, so nothing downstream can otherwise see
  # how many rows there originally were). Used by the "theory-building
  # notes" redundancy check — comparing the already-minimized stored H
  # against itself would trivially always find nothing.
  h_raw_rows_reactive <- reactiveValues()

  mytable_v_reactive  <- reactiveValues(value = NULL)

  # Per-equality (not per-model) approximate-tolerance state: each of these
  # is keyed by model index (as a character, e.g. "1") to a plain numeric
  # vector where position k is the tolerance for the k-th "=" clause
  # encountered left-to-right in that model's spec (0 = exact, kept as a
  # real equality). Replaces the old single per-model scalar
  # (mytable_approx_reactive / the manual "Approximate equalities" dialog)
  # entirely — see the "≈" button that appears next to a model's Model
  # Specification box the moment it contains an "=" (conditionalPanel in
  # textboxes_relations_complete()), and the observeEvent(input$
  # eq_tol_btn_i, ...) wiring below that opens the dialog on click.
  #   equality_tolerances_reactive$value[[key]] — saved tolerances, one
  #     entry per equality occurrence (the actual setting used in
  #     computation, see "#### approx equal" below).
  #   equality_pending_reactive$value[[key]] — the clause list shown in
  #     the currently-open dialog for that model, read back by the
  #     dialog's own Save handler (by occurrence index, not by text) to
  #     know which eq_tol_switch_/eq_tol_value_ ids to collect.
  equality_tolerances_reactive <- reactiveValues(value = list())
  # the equality clauses the saved tolerances belong to (same order as the tolerance vector), so a tolerance
  # follows its equality when the text is changed; NULL = assume the vector fits the current text
  equality_clause_keys <- reactiveValues(value = list())
  tol_align_hold <- reactiveVal(FALSE)   # TRUE while a deleted row's neighbours are still being refilled with their texts
  equality_pending_reactive <- reactiveValues(value = list())

  # Cache for the polytope-overlap (intersection) computation so it only
  # recomputes when the SET of plotted models changes, not on axis changes.
  overlap_cache_reactive <- reactiveValues(key = NULL, coords = NULL, empty = FALSE)

  # Names of the pairwise model intersections whose H-descriptions are stored
  # in h_reactive (kept out of names_models_reactive so they do not enter the
  # per-model loops for parsimony / V-representations).
  intersections_reactive  <- reactiveValues(names = NULL, disjoint = NULL)
  mixtures_reactive       <- reactiveValues(names = NULL)
  mix_components          <- new.env()   # mixture name -> names of the models it is made of (for the marks in the V-representation)
  mytable_mix_reactive    <- reactiveValues(value = NULL)
  mytable_items_reactive  <- reactiveValues(value = NULL)
  items_reactive          <- reactiveValues(names = character())
  counter_mix             <- reactiveValues(n = 1)
  counter_items           <- reactiveValues(n = 1)

  # S4 class for volesti (defined once here; Parsimony observer re-calls setClass
  # which is idempotent when the definition matches)
  if (!isClass("model_s4"))
    setClass("model_s4", representation(A = "matrix", b = "numeric", type = "character"))

# ── Multiple-items H-rep builders (fully-crossed, arbitrary factors) ────────

  # factors:      list of list(name, n) — ordered factor definitions
  # param_factors: named integer vector — param name → factor index (1-based), 0 = Shared
  # substitutable: if TRUE, within each factor all level-combinations are used per slot;
  #                if FALSE (joint / fully-crossed), one level per factor per constraint copy.
  # factor_types: optional PER-FACTOR override of the above (a character
  # vector aligned with `factors`, values "joint"/"substitutable"/
  # "identical" — "identical" uses the joint/fully-crossed grid here too,
  # since its equality constraints are layered on afterward, not decided
  # at the grid level) — lets a single combined model mix substitutable
  # and joint/identical factors, rather than one substitutable/joint
  # choice for the whole model. Falls back to the uniform `substitutable`
  # flag when not given.
  # An items-expanded column's superscript — base^{(group,level)} — used
  # the group's name even for a SOLO (ungrouped) factor, where that name
  # is just the probability's own name again (see rows' own "name = ...
  # first$pname" for a solo row), producing e.g. "p_{1}^{(\text{p_{1}},1)}"
  # — the same name shown twice, once as the base and once inside its
  # own superscript. Reported directly as confusing ("repetitions in the
  # superscript and subscript"). A solo factor's copy index doesn't need
  # a group label at all — there's only one member, so "which group" is
  # never actually in question — so this drops the "\text{name},"
  # portion whenever the factor has exactly one member and its own name
  # is just that member's name (the solo-row signature), leaving the
  # plain "^{(1)}" a group name would otherwise be redundant next to.
  # A real (user-named) group still gets the full "^{(\text{name},1)}"
  # form, since there the name is the only thing distinguishing which
  # group a copy belongs to.
  items_superscript <- function(nm_f, group_name, lev) {
    paste0(nm_f, "^{(", lev, ")}")
  }
  build_items_h_core <- function(h_base, factors, param_factors, substitutable = FALSE, factor_types = NULL) {
    h_num   <- q2d(h_base)
    p_names <- colnames(h_base)[-(1:2)]
    n_p     <- length(p_names)
    F       <- length(factors)
    f_ns    <- vapply(factors, function(f) f$n, integer(1))   # levels per factor

    pf <- as.integer(param_factors[p_names])
    pf[is.na(pf)] <- 0L

    params_of <- lapply(seq_len(F), function(f) which(pf == f))  # orig indices per factor
    shared_pi <- which(pf == 0L)
    n_sh      <- length(shared_pi)
    n_pf      <- vapply(params_of, length, integer(1))

    # Column layout: [h1,h2 | shared | f1_lev1..levN1 | f2_lev1..levN2 | ...]
    tc <- 2L + n_sh + sum(n_pf * f_ns)
    fbase <- integer(F)                   # column start offset (after shared) per factor
    acc   <- 0L
    for (f in seq_len(F)) { fbase[f] <- acc; acc <- acc + n_pf[f] * f_ns[f] }

    col_sh <- function(li)         2L + li
    col_f  <- function(f, lev, li) 2L + n_sh + fbase[f] + (lev - 1L) * n_pf[f] + li

    all_rows <- list()

    for (ri in seq_len(nrow(h_num))) {
      a_vec <- h_num[ri, 3:(2L + n_p)]

      # Which factors have nonzero coefficients here, and which original param indices?
      nz_by_f <- lapply(seq_len(F), function(f) {
        pi <- params_of[[f]]; pi[a_vec[pi] != 0]
      })
      involved <- which(vapply(nz_by_f, length, integer(1)) > 0)
      nz_sh    <- shared_pi[a_vec[shared_pi] != 0]

      if (length(involved) == 0) {
        # constant or shared-only row
        row <- numeric(tc); row[1] <- h_num[ri, 1]; row[2] <- h_num[ri, 2]
        for (si in seq_along(nz_sh)) {
          li <- which(shared_pi == nz_sh[si])
          row[col_sh(li)] <- row[col_sh(li)] + a_vec[nz_sh[si]]
        }
        all_rows[[length(all_rows) + 1L]] <- row; next
      }

      # "average"-type factors don't duplicate the row per level like
      # joint/substitutable do — they want the ORIGINAL constraint to
      # hold for the MEAN across a member's copies, i.e. one row with
      # that member's original coefficient split evenly (a/n_f) across
      # all n_f of its level-columns, summed into a single column-value
      # (rather than the coefficient repeated whole in each of n_f
      # separate rows). That's simple enough to fold directly into a
      # base row template used by every combo below, with no grid/combo
      # step of its own — so these factors are excluded from `grids`
      # entirely, never taking part in the Cartesian product.
      is_avg <- function(f) !is.null(factor_types) && identical(factor_types[f], "average")
      avg_involved  <- involved[vapply(involved, is_avg, logical(1))]
      grid_involved <- involved[!vapply(involved, is_avg, logical(1))]

      base_row <- numeric(tc); base_row[1] <- h_num[ri, 1]; base_row[2] <- h_num[ri, 2]
      for (si in seq_along(nz_sh)) {
        li <- which(shared_pi == nz_sh[si])
        base_row[col_sh(li)] <- base_row[col_sh(li)] + a_vec[nz_sh[si]]
      }
      for (f in avg_involved) {
        nz  <- nz_by_f[[f]]
        n_f <- f_ns[f]
        for (slot in seq_along(nz)) {
          li <- which(params_of[[f]] == nz[slot])
          w  <- a_vec[nz[slot]] / n_f
          for (lev in seq_len(n_f)) {
            col <- col_f(f, lev, li)
            base_row[col] <- base_row[col] + w
          }
        }
      }

      if (length(grid_involved) == 0) {
        all_rows[[length(all_rows) + 1L]] <- base_row; next
      }

      # Build one level-assignment grid per remaining (joint/substitutable) factor
      grids <- lapply(grid_involved, function(f) {
        nz  <- nz_by_f[[f]]
        n_f <- f_ns[f]
        f_is_substitutable <- if (!is.null(factor_types)) identical(factor_types[f], "substitutable") else substitutable
        if (f_is_substitutable) {
          as.matrix(expand.grid(rep(list(seq_len(n_f)), length(nz)), KEEP.OUT.ATTRS = FALSE))
        } else {
          # fully crossed joint: same level for every slot of this factor
          matrix(rep(seq_len(n_f), each = length(nz)), ncol = length(nz), byrow = TRUE)
        }
      })

      # Cartesian product across the remaining factors' grid rows. Joint factors (item by item) that occur in the SAME constraint
      # share their item index (item k with item k of the other list); items that do not exist in all of them are left out.
      is_J <- vapply(grid_involved, function(f) !(if (!is.null(factor_types)) identical(factor_types[f], "substitutable") else substitutable), logical(1))
      dim_list <- list(); dim_of <- integer(length(grids)); jdim <- 0L
      for (gi_ in seq_along(grids)) {
        if (is_J[gi_] && sum(is_J) >= 2L) {
          if (jdim == 0L) { dim_list[[length(dim_list) + 1L]] <- seq_len(min(f_ns[grid_involved[is_J]])); jdim <- length(dim_list) }
          dim_of[gi_] <- jdim
        } else { dim_list[[length(dim_list) + 1L]] <- seq_len(nrow(grids[[gi_]])); dim_of[gi_] <- length(dim_list) }
      }
      combo <- as.matrix(expand.grid(dim_list, KEEP.OUT.ATTRS = FALSE))[, dim_of, drop = FALSE]

      for (ci in seq_len(nrow(combo))) {
        row <- base_row
        for (fi in seq_along(grid_involved)) {
          f   <- grid_involved[fi]
          nz  <- nz_by_f[[f]]
          g   <- grids[[fi]]
          gi  <- combo[ci, fi]
          for (slot in seq_along(nz)) {
            li  <- which(params_of[[f]] == nz[slot])
            lev <- g[gi, slot]
            col <- col_f(f, lev, li)
            row[col] <- row[col] + a_vec[nz[slot]]
          }
        }
        all_rows[[length(all_rows) + 1L]] <- row
      }
    }

    # "average" factors fold h_base's OWN rows into one averaged
    # constraint per row (see above) — but h_base's rows also include
    # the ordinary 0<=x<=1 domain bounds every probability needs, and
    # averaging THOSE away too would leave each individual copy's own
    # validity as a probability unconstrained: only the copies' AVERAGE
    # would stay pinned to [0,1], while an individual copy could drift
    # arbitrarily far outside it (confirmed directly — scdd() on the
    # resulting H-rep produces real vertices with a lone copy at 2, not
    # just a theoretical possibility). Re-add that per-copy domain bound
    # explicitly for every column of an "average" factor, regardless of
    # what happened to h_base's own bound rows; harmless/redundant()
    # strips it away for joint/substitutable columns, which already get
    # it for free by duplicating h_base's own bound rows unchanged.
    for (f in seq_len(F)) {
      if (is.null(factor_types) || !identical(factor_types[f], "average")) next
      for (li in seq_len(n_pf[f])) {
        for (lev in seq_len(f_ns[f])) {
          col <- col_f(f, lev, li)
          up <- numeric(tc); up[2] <- 1; up[col] <- -1  # copy <= 1
          lo <- numeric(tc); lo[2] <- 0; lo[col] <-  1  # copy >= 0
          all_rows[[length(all_rows) + 1L]] <- up
          all_rows[[length(all_rows) + 1L]] <- lo
        }
      }
    }

    mat <- do.call(rbind, all_rows)
    # Attach colnames using the exact same pf/params_of/shared_pi computed above
    cn_shared  <- if (n_sh > 0) p_names[shared_pi] else character(0)
    cn_factors <- unlist(lapply(seq_len(F), function(f) {
      nm_f <- p_names[params_of[[f]]]
      unlist(lapply(seq_len(f_ns[f]), function(lev) items_superscript(nm_f, factors[[f]]$name, lev)))
    }))
    colnames(mat) <- c("", "", cn_shared, cn_factors)
    mat
  }

  # Fully general per-factor H-rep builder for the "Repeated items" modal's
  # combined mode, where each probability picks its own type. Each
  # factor's grid strategy (joint/fully-crossed,
  # substitutable/all-permutations, or average/one-row-with-averaged-
  # coefficients) is honored independently via build_items_h_core's
  # factor_types argument — a factor's own semantics are the real thing
  # here, not approximated via another type, and coexist correctly with
  # other factors marked differently in the very same combined model.
  # "Identical" equality rows are then layered on top for the factors
  # flagged "identical" (average factors need no such extra layer — the
  # averaging is entirely built into build_items_h_core's own row
  # construction). Each MEMBER of an
  # "identical" factor gets its own tolerance (eps_per_param, keyed by
  # probability name) rather than one tolerance for the whole factor —
  # e.g. within one group, p1's copies can be forced equal within ±0.05
  # while p2's copies (same group) tolerate ±0.1; nothing about the
  # underlying equality rows requires them to match, each member's rows
  # are independent of every other member's. This composes cleanly
  # regardless of what grid strategy other factors used, since it only
  # depends on the (grid-strategy-independent) column layout.
  build_items_h_mixed <- function(h_base, factors, param_factors, factor_types, eps_per_param) {
    p_names <- colnames(h_base)[-(1:2)]
    F       <- length(factors)
    f_ns    <- vapply(factors, function(f) f$n, integer(1))
    pf      <- as.integer(param_factors[p_names]); pf[is.na(pf)] <- 0L
    n_pf    <- vapply(seq_len(F), function(f) sum(pf == f), integer(1))
    n_sh    <- sum(pf == 0L)
    tc      <- 2L + n_sh + sum(n_pf * f_ns)
    fbase   <- integer(F); acc <- 0L
    for (f in seq_len(F)) { fbase[f] <- acc; acc <- acc + n_pf[f] * f_ns[f] }
    col_f   <- function(f, lev, li) 2L + n_sh + fbase[f] + (lev - 1L) * n_pf[f] + li
    jh      <- build_items_h_core(h_base, factors, param_factors, factor_types = factor_types)
    eq_rows <- list()
    for (f in seq_len(F)) {
      if (!identical(factor_types[f], "identical")) next
      if (f_ns[f] < 2 || n_pf[f] == 0) next
      members_f <- p_names[pf == f]
      for (lev in 2:f_ns[f]) {
        for (li in seq_len(n_pf[f])) {
          eps <- if (!is.null(eps_per_param) && !is.na(eps_per_param[members_f[li]])) eps_per_param[members_f[li]] else 0
          if (eps == 0) {
            row <- numeric(tc); row[1] <- 1
            row[col_f(f, 1L,  li)] <-  1
            row[col_f(f, lev, li)] <- -1
            eq_rows[[length(eq_rows) + 1L]] <- row
          } else {
            row_a <- numeric(tc); row_a[2] <- eps
            row_a[col_f(f, 1L, li)] <- 1; row_a[col_f(f, lev, li)] <- -1
            row_b <- numeric(tc); row_b[2] <- eps
            row_b[col_f(f, 1L, li)] <- -1; row_b[col_f(f, lev, li)] <- 1
            eq_rows[[length(eq_rows) + 1L]] <- row_a
            eq_rows[[length(eq_rows) + 1L]] <- row_b
          }
        }
      }
    }
    if (length(eq_rows) > 0) {
      mat <- rbind(jh, do.call(rbind, eq_rows))
      colnames(mat) <- colnames(jh)
      mat
    } else jh
  }

  # Renders an already-computed items H-representation matrix as plain
  # ">/</=" constraint text using fresh, sequential p1, p2, ... names —
  # "what you would have had to type by hand, in a brand-new model with
  # exactly this many parameters, to get this same result" (direct user
  # request: an actual preview of the generated input, not just the
  # human-readable "N copies of X, linked together" description). Column
  # ORDER (not the real, item-tagged names like p1^{(A,1)}) becomes the
  # new p-numbering, so two items models with the same shape always
  # relabel identically. Reuses the same "move negative terms/constants
  # to the other side so nothing prints with a leading minus" convention
  # already used for the real H-representation table display, just as
  # plain text (";"-joined, no LaTeX/HTML) instead of an HTML table.
  h_matrix_to_plain_spec <- function(h_mat) {
    if (is.null(h_mat) || nrow(h_mat) == 0) return("")
    # build_items_h_core/build_items_h_mixed (this function's only caller)
    # work in and return plain numeric throughout, unlike most of this
    # app's other H-representation matrices, which stay in rcdd's
    # character/rational form until explicitly q2d()'d for display —
    # q2d() on an already-numeric matrix errors ("argument must be
    # character"), so only convert when it's actually still character.
    h_num <- if (is.character(h_mat)) q2d(h_mat) else h_mat
    n_p   <- ncol(h_num) - 2L
    new_names <- paste0("p", seq_len(n_p))
    # Skip the automatic "keep this probability inside [0,1]" bounds
    # (every model gets these added for free — see extract_info's own
    # `limits`) — they were never something you'd actually type, so
    # including them here would make this look unlike real input. Same
    # single-nonzero-unit-coefficient test already used for trivial_vec
    # in the real H-representation table.
    is_trivial <- function(coeffs, rhs) {
      nz <- which(coeffs != 0)
      length(nz) == 1 && ((coeffs[nz] == 1 && rhs == 1) || (coeffs[nz] == -1 && rhs == 0))
    }
    # Term/operator syntax matching what you'd actually type (see the
    # "Write linear in/equalities..." help text): bare "<"/">" — this
    # function's rows are always the "<=" convention (never flipped, see
    # the real table's own comment on that), so plain "<" — a coefficient
    # of 1 needs no "*", anything else uses "coef*pN" as documented, and
    # no leading "+" on a term (only between terms, where it's the actual
    # addition operator, not a sign).
    term_str <- function(coef, name) {
      if (coef == 1) name else paste0(num2str_lin(coef), "*", name)
    }
    join_terms <- function(const, terms) {
      parts <- c(if (const > 0) num2str_lin(const) else character(0), terms)
      if (length(parts) == 0) return("0")
      paste(parts, collapse = "+")
    }
    rows_txt <- character(0)
    for (ri in seq_len(nrow(h_num))) {
      is_eq  <- h_num[ri, 1] == 1
      rhs    <- h_num[ri, 2]
      coeffs <- -h_num[ri, 3:(2L + n_p)]
      if (!is_eq && is_trivial(coeffs, rhs)) next
      nz_all  <- which(coeffs != 0)
      neg_all <- nz_all[coeffs[nz_all] < 0]
      lhs_terms <- vapply(setdiff(nz_all, neg_all), function(j)
        term_str(coeffs[j], new_names[j]), character(1))
      moved_terms <- vapply(neg_all, function(j)
        term_str(abs(coeffs[j]), new_names[j]), character(1))
      lhs_const <- if (rhs < 0) abs(rhs) else 0
      rhs_const <- if (rhs > 0) rhs else 0
      lhs_str <- join_terms(lhs_const, lhs_terms)
      rhs_str <- join_terms(rhs_const, moved_terms)
      rows_txt <- c(rows_txt, paste0(lhs_str, if (is_eq) "=" else "<", rhs_str))
    }
    paste(rows_txt, collapse = "; ")
  }

  # Plain-English legend for what each fresh p1, p2, ... in
  # h_matrix_to_plain_spec's output actually is — which original
  # probability it came from, and (for a repeated one) which group/item
  # it stands for. Column ORDER here must match build_items_h_core's own
  # column construction exactly (shared params first, then each factor's
  # columns level-major/parameter-minor) since h_matrix_to_plain_spec's
  # p1, p2, ... are numbered by that same column order.
  # p3 -> p<sub>3</sub> (the same reading as the H-description); other names stay as they are
  sub_html <- function(nm) ifelse(grepl("^[A-Za-z]+[0-9]+$", nm), sub("^([A-Za-z]+)([0-9]+)$", "\\1<sub>\\2</sub>", nm), gsub("[<>&]", "", nm))
  items_column_legend <- function(h_base, factors, param_factors, lists = NULL) {
    p_names <- colnames(h_base)[-(1:2)]
    F  <- length(factors)
    pf <- as.integer(param_factors[p_names]); pf[is.na(pf)] <- 0L
    # A probability's display name is only guaranteed non-blank when its
    # Name field was never touched at all (extract_info's own name_p
    # falls back to "p_{i}" only when the input is entirely absent, i.e.
    # length 0) — a Name field cleared to empty text instead leaves
    # colnames(h_base) with a literal "" for that column, which
    # plain_p_name() then passes straight through, producing a legend
    # line with nothing before "(not repeated)"/"(group ...)". Fall back
    # to that column's own position ("param3") whenever its real name is
    # blank, so the legend always names something concrete.
    label_of <- function(nm, idx) {
      pn <- plain_p_name(nm)
      ifelse(nzchar(trimws(pn)), pn, paste0("param", idx))
    }
    # paste0(character(0), "x") does NOT return character(0) — it returns
    # "x" (length 1, missing part just blank), unlike most vectorized R
    # functions. With zero shared parameters (shared_idx empty, the
    # common/correct case whenever every real probability is grouped),
    # the naive paste0() below still produced one phantom, name-less
    # "(not repeated)" legend entry — the actual cause of the "still
    # shows an extra ungrouped parameter" report, confirmed via debug
    # output showing param_factors correctly all-grouped (1,1,1) with no
    # zeros. Guard every paste0() here that builds FROM a which()-derived
    # index vector with an explicit length check instead of trusting
    # paste0's recycling.
    shared_idx <- which(pf == 0L)
    legend_shared <- if (length(shared_idx) > 0) {
      paste0(sub_html(label_of(p_names[shared_idx], shared_idx)), " <span class='text-muted'>(not repeated)</span>")
    } else character(0)
    lists_v <- if (!is.null(lists)) unlist(lists) else NULL
    # the list a column belongs to: as stored for every probability (also for "every combination" / "average", whose groups are
    # split into single probabilities); older specs without it fall back to the name of the group
    list_suffix <- function(idx_f, f) vapply(idx_f, function(ix) {
      lst <- if (!is.null(lists_v) && !is.na(lists_v[p_names[ix]])) as.character(lists_v[p_names[ix]]) else as.character(factors[[f]]$list %||% "")[1]
      if (!nzchar(lst) && !grepl("^p_?\\{?[0-9]+\\}?$", factors[[f]]$name)) lst <- factors[[f]]$name
      if (nzchar(lst)) paste0(" <span class='text-muted'>(", gsub("[<>&]", "", sub("^group ", "list ", lst)), ")</span>") else ""
    }, character(1))
    legend_factors <- unlist(lapply(seq_len(F), function(f) {
      idx_f <- which(pf == f)
      if (length(idx_f) == 0) return(character(0))
      unlist(lapply(seq_len(factors[[f]]$n), function(lev)
        paste0(sub_html(label_of(p_names[idx_f], idx_f)), "<sup>(", lev, ")</sup>", list_suffix(idx_f, f))))
    }))
    c(legend_shared, legend_factors)
  }

  get_name_models_reactive <- function() {
    nms <- character()
    for (ls in seq_len(counter_input$n)) {
      nms <- c(nms, isolate(input[[paste0("textin_relations_name", ls)]]))
    }
    nms[!is.na(nms) & nms != ""]
  }

  # Probability names are typically typed as LaTeX source (e.g. "p_{1}",
  # rendered as a proper subscript via MathJax wherever the app actually
  # typesets math — the H-representation tables, mostly). A generated
  # MODEL name/description is plain text, though (a textAreaInput value,
  # not MathJax'd), so embedding the raw LaTeX source there just shows
  # the literal underscores and braces instead of anything nicer. Strip
  # them for display purposes only — the raw name is still what's passed
  # into build_items_h_core for column-name generation, where it DOES
  # get properly MathJax-rendered.
  plain_p_name <- function(nm) gsub("[_{}]", "", nm)

  # Member tolerances for factor `fi`, in that factor's own member order
  # (matching how build_items_h_mixed iterates them) — eps_per_param is a
  # named vector keyed by probability name, so this just looks each
  # member up by name; missing/NULL reads as 0 (no tolerance).
  member_eps_for_factor <- function(param_factors, eps_per_param, fi) {
    members <- names(param_factors)[param_factors == fi]
    if (is.null(eps_per_param)) return(rep(0, length(members)))
    vals <- unname(eps_per_param[members])
    vals[is.na(vals)] <- 0
    vals
  }

  # Readable tag for the bracket in an items model's name, e.g.
  # "p1, p2, p3: 2 items, substitutable" or "p1, p2: 2 items, joint; p3, p4: 3 items, joint".
  # Probabilities that are not grouped (own factor) with the same count and
  # kind are listed together; a group keeps its own segment. One function
  # for every place that builds the name, so they always match.
  items_tag_string <- function(factors, factor_types, param_factors, eps_per_param) {
    segs <- lapply(seq_along(factors), function(fi) {
      members <- names(param_factors)[param_factors == fi]
      if (length(members) == 0) members <- factors[[fi]]$name
      ev <- member_eps_for_factor(param_factors, eps_per_param, fi)
      kind <- switch(factor_types[fi],
        joint = "joint",
        substitutable = "substitutable",
        average = "average",
        identical = {
          dec <- function(x) as.character(round(x, 4))
          if (length(ev) == 0 || all(ev == 0)) "identical"
          else if (length(unique(round(ev, 10))) == 1) paste0("identical \u00b1", dec(ev[1]))
          else paste0("identical \u00b1", paste(vapply(ev, dec, character(1)), collapse = "/"))
        })
      list(members = vapply(members, plain_p_name, character(1)), n = factors[[fi]]$n, kind = kind,
           solo = length(members) == 1)
    })
    out <- list(); keys <- character(0)
    for (sg in segs) {
      key <- if (sg$solo) paste(sg$n, sg$kind, sep = "|") else paste0("g", length(out) + 1L)
      idx <- match(key, keys)
      if (is.na(idx)) { out[[length(out) + 1L]] <- sg; keys <- c(keys, key) }
      else out[[idx]]$members <- c(out[[idx]]$members, sg$members)
    }
    # one segment covering every expanded probability: no need to list them
    all_in_one <- length(out) == 1L && length(out[[1]]$members) == length(param_factors)
    kinds <- unique(vapply(out, function(sg) sg$kind, character(1)))
    ns <- vapply(out, function(sg) as.numeric(sg$n), numeric(1))
    mem <- function(sg) paste(sg$members, collapse = ", ")
    # one rule for every case:  "2 items \u00b7 average"  /  "2 items \u00b7 item by item (p2, p5), average (p3, p4)"
    #                           "average: p1, p2 (2 items), p3, p4 (3 items); item by item: p5 (2 items)"
    if (all_in_one) return(paste0(out[[1]]$n, " items \u00b7 ", out[[1]]$kind))
    if (length(unique(ns)) == 1L)
      return(paste0(ns[1], " items \u00b7 ", paste(vapply(out, function(sg) paste0(sg$kind, " (", mem(sg), ")"), character(1)), collapse = ", ")))
    paste(vapply(kinds, function(k) paste0(k, ": ", paste(vapply(Filter(function(sg) sg$kind == k, out), function(sg)
      paste0(mem(sg), " (", sg$n, " items)"), character(1)), collapse = ", ")), character(1)), collapse = "; ")
  }


  # Name(s) a single items spec produces. The Go pipeline and the model-row
  # delete handler both need exactly the same name(s) (the handler drops the
  # spec of a deleted row so it does not reappear on the next Go).
  items_spec_names <- function(spec) {
    base_m  <- spec$base
    factors <- spec$factors
    if (is.null(base_m) || nchar(base_m) == 0 || length(factors) == 0) return(character(0))
    factor_tag <- items_tag_string(factors, spec$factor_types, spec$param_factors, spec$eps_per_param)
    paste0(base_m, " [", factor_tag, "]")
  }


  # User selection of WHICH model pairs to intersect. The chosen pairs are the
  # only intersections shown anywhere (H-representation cards, downloads,
  # polytope overlap highlights and the overlap matrix).
  mytable_int_reactive <- reactiveValues(value = NULL)

  # How many intersections the user is defining (one column per intersection
  # in the "Model intersections" modal).
  counter_int <- reactiveValues(n = 1)

  # Whether the detailed per-algorithm parsimony table should default open —
  # only when it contains a model that ISN'T shown in any comparison table
  # (so the info wouldn't otherwise be visible anywhere).
  parsim_needs_open <- reactiveValues(value = FALSE)

  # The Parsimony tab's results (header/plot/table) only exist once
  # observeEvent(input$go, ...) has actually run — before that first
  # "Compute parsimony" click, their uiOutput()s are simply empty and the
  # whole tab reads as a blank page. This flag drives a placeholder (see
  # output$parsimony_placeholder_ui) that tells the user what to do
  # instead, and disappears the moment real results exist.
  parsim_has_results <- reactiveVal(FALSE)
  parsim_csv_data <- reactiveVal(NULL)
  parsim_bar_data <- reactiveVal(NULL)   # model, algorithm and volume of the bars of the chart (for the PDF)

  output$parsimony_placeholder_ui <- renderUI({
    if (isTRUE(parsim_has_results())) return(NULL)
    # Deliberately NOT class="model-card" — that class's ::after hover
    # rule adds a "click to expand" hint to every card, meant for the
    # real double-click-to-fullscreen cards elsewhere; this placeholder
    # isn't one of those; it doesn't do anything on a click, so hinting
    # that it does would just be misleading. Plain equivalent styling
    # instead, and a real icon() instead of an emoji glyph.
    div(
      class = "fairy-pars-placeholder",
      style = paste(
        "text-align:center; padding:28px 20px; color:#777;",
        "background-color: var(--fairy-panel); border: 1px solid var(--fairy-border);",
        "border-radius: 12px; box-shadow: 0 1px 3px rgba(16, 24, 40, 0.06);"
      ),
      icon("chart-column", style = "font-size:28px; color:var(--fairy-text-muted);"),
      p(style = "margin:10px 0 0 0; font-size:13.5px;",
        "No results yet. Click ", strong("Go"), " above (or press ⌘/Ctrl+Enter) to see volumes here."
      ),
      p(style = "margin:6px 0 0 0; font-size:12.5px;",
        "Next to Go you can switch the exact volume and the algorithms on or off (switch on Algorithms to choose Cooling Bodies, ",
        "Cooling Gaussian or Sequence of Balls), and adjust the algorithm settings (gear icon) before you start."
      )
    )
  })

  # "Multiple items" (see the button next to the Probabilities header):
  # ONE modal covering the whole set of probabilities at once, rather than
  # a separate icon/modal per p — the base model is chosen once, and each
  # probability gets its own row (items count, joint/substitutable/
  # identical, approx tolerance) so a single submit can expand several
  # probabilities together into one combined model.
  #
  # Also reused to EDIT an existing items model (see the small icon on
  # its row, wired below) — active_items_edit() records which row/spec is
  # being edited so submit_items_multi knows to update it in place rather
  # than add a new one, and prefill_base/prefill_rows pre-populate the
  # same modal from that spec's current values instead of the all-1s/
  # all-Joint defaults a brand new one starts from.
  active_items_edit <- reactiveVal(NULL)
  item_model_spec_idx <- reactiveValues(value = list())

  # pairs (hi, lo) the base model compares directly, e.g. p1 > p2 gives c(1, 2); from the non-redundant H-representation
  items_pairs_for <- function(model_name) {
    h <- isolate(h_reactive[[model_name]])
    if (is.null(h) || !is.matrix(h)) return(NULL)
    hn <- tryCatch(if (is.character(h)) q2d(h) else h, error = function(e) NULL)
    if (is.null(hn) || ncol(hn) < 4) return(NULL)
    A <- hn[, -(1:2), drop = FALSE]; pairs <- list()
    for (r in seq_len(nrow(hn))) {
      if (hn[r, 1] != 0 || abs(hn[r, 2]) > 1e-12) next
      nz <- which(abs(A[r, ]) > 1e-12)
      hi <- nz[A[r, nz] > 0]; lo <- nz[A[r, nz] < 0]
      if (length(nz) == 2 && length(hi) == 1 && length(lo) == 1) {
        ratio <- abs(A[r, lo]) / A[r, hi]
        lab <- if (abs(ratio - 1) < 1e-9) "" else tryCatch(frac_str(ratio), error = function(e) format(round(ratio, 3)))
        pairs[[length(pairs) + 1L]] <- list(as.integer(hi - 1L), as.integer(lo - 1L), lab)
      } else if (length(nz) %in% 3:5 && length(hi) >= 1 && length(lo) >= 1 && (length(hi) == 1 || length(lo) == 1)) {
        # a (weighted) sum on one side, e.g. 2 * p1 + p2 > p3: weights relative to the single probability
        sg <- if (length(hi) == 1) hi else lo
        wv <- function(ix) vapply(abs(A[r, ix]) / abs(A[r, sg]), function(v) if (abs(v - 1) < 1e-9) "1" else tryCatch(frac_str(v), error = function(e) format(round(v, 3))), character(1))
        pairs[[length(pairs) + 1L]] <- list(as.integer(hi - 1L), as.integer(lo - 1L), "",
                                            if (length(hi) > 1L) wv(hi) else "", if (length(lo) > 1L) wv(lo) else "")
      }
    }
    unique(pairs)
  }
  # comparisons exactly as typed: "p1 > p2 < p3; p1 > 1/5 * p3" gives (1,2), (3,2), (1,3, "1/5"), also redundant ones
  items_spec_pairs <- function(model_name) {
    n <- isolate(counter_input$n)
    nm <- vapply(seq_len(n), function(i) isolate(input[[paste0("textin_relations_name", i)]]) %||% paste0("m", i), character(1))
    idx <- which(nm == model_name)[1]
    if (is.na(idx)) return(NULL)
    spec <- paste(isolate(input[[paste0("textin_relations_", idx)]]) %||% "", isolate(input[["add_for_all_models"]]) %||% "", sep = ";")
    spec <- gsub("\u2265", ">=", gsub("\u2264", "<=", spec, fixed = TRUE), fixed = TRUE)
    # one flag per "=" sign of the text (also the one inside >= and <=): "1" when that equality is approximate
    eq_flags <- strsplit(equality_flags_str(spec, isolate(equality_tolerances_reactive$value[[as.character(idx)]])), ",", fixed = TRUE)[[1]]
    eq_ix <- 0L
    pairs <- list()
    for (cl in strsplit(spec, "[;,\n]")[[1]]) {
      ops <- regmatches(cl, gregexpr("<=|>=|<|>|=", cl))[[1]]
      opd <- trimws(strsplit(cl, "<=|>=|<|>|=")[[1]])
      if (length(ops) == 0 || length(opd) != length(ops) + 1) next
      parse_op <- function(x) {
        terms <- trimws(strsplit(x, "+", fixed = TRUE)[[1]])
        if (!length(terms) || any(!nzchar(terms))) return(NULL)
        ps <- integer(0); cf <- 1; cfs <- numeric(0); cst <- 0; cst_txt <- character(0)
        for (tm in terms) {
          if (grepl("^[0-9]*\\.?[0-9]+(/[0-9]*\\.?[0-9]+)?$", tm)) {      # a constant term such as 1/8
            v <- as.numeric(strsplit(tm, "/", fixed = TRUE)[[1]]); cst <- cst + (if (length(v) == 2) v[1] / v[2] else v)
            cst_txt <- c(cst_txt, tm); next
          }
          # a term as typed: p1, 2*p1, p1*2, 1/2*p1, p1*1/2 or p1/2
          cof <- function(x) { v <- as.numeric(strsplit(x, "/", fixed = TRUE)[[1]]); if (length(v) == 2) v[1] / v[2] else v }
          nmb <- "[0-9]*\\.?[0-9]+(?:/[0-9]*\\.?[0-9]+)?"
          m <- regmatches(tm, regexec(paste0("^(?:(", nmb, ")\\s*\\*\\s*)?p([0-9]+)$"), tm, perl = TRUE))[[1]]
          if (length(m)) { pv <- as.integer(m[3]); cf <- if (nzchar(m[2])) cof(m[2]) else 1 }
          else if (length(m <- regmatches(tm, regexec(paste0("^p([0-9]+)\\s*\\*\\s*(", nmb, ")$"), tm, perl = TRUE))[[1]])) { pv <- as.integer(m[2]); cf <- cof(m[3]) }
          else if (length(m <- regmatches(tm, regexec("^p([0-9]+)\\s*/\\s*([0-9]*\\.?[0-9]+)$", tm, perl = TRUE))[[1]])) { pv <- as.integer(m[2]); cf <- 1 / as.numeric(m[3]) }
          else return(NULL)
          ps <- c(ps, pv); cfs <- c(cfs, cf)
        }
        if (!length(ps)) return(NULL)
        list(ps = ps, p = ps[1], cf = if (length(ps) == 1L && !length(cst_txt)) cf else 1, cfs = cfs, cst = paste(cst_txt, collapse = "+"))
      }
      for (i in seq_along(ops)) {
        a1 <- parse_op(opd[i]); b1 <- parse_op(opd[i + 1])
        if (ops[i] %in% c("=", ">=", "<=")) eq_ix <- eq_ix + 1L
        if (ops[i] == "=") {
          # an equality of two single probabilities is drawn as a line without an arrow (9th entry: TRUE)
          if (!is.null(a1) && !is.null(b1) && length(a1$ps) == 1L && length(b1$ps) == 1L && !nzchar(a1$cst) && !nzchar(b1$cst) &&
              a1$cf == 1 && b1$cf == 1 && a1$ps != b1$ps)
            pairs[[length(pairs) + 1L]] <- list(as.integer(a1$ps - 1L), as.integer(b1$ps - 1L), "", "", "", "", "", "", TRUE,
              eq_ix <= length(eq_flags) && identical(eq_flags[eq_ix], "1"))
          next
        }
        if (is.null(a1) || is.null(b1) || length(intersect(a1$ps, b1$ps)) > 0) next
        gt <- substr(ops[i], 1, 1) == ">"
        hi <- if (gt) a1 else b1; lo <- if (gt) b1 else a1
        # weights as typed: p1/3 > .2 + p3 is written "1/3 * p1 > .2 + p3", and that is how it is shown
        cf_txt <- function(v) if (abs(v - 1) < 1e-9) "" else tryCatch(frac_str(v), error = function(e) format(round(v, 3)))
        lab <- cf_txt(lo$cf); hcf <- cf_txt(hi$cf)
        wl <- function(a) vapply(a$cfs, function(v) if (abs(v - 1) < 1e-9) "1" else tryCatch(frac_str(v), error = function(e) format(round(v, 3))), character(1))
        pairs[[length(pairs) + 1L]] <- list(as.integer(hi$ps - 1L), as.integer(lo$ps - 1L), lab,
                                            if (length(hi$ps) > 1L || nzchar(hi$cst)) wl(hi) else "", if (length(lo$ps) > 1L || nzchar(lo$cst)) wl(lo) else "",
                                            hi$cst, lo$cst, hcf)
      }
    }
    if (length(pairs)) unique(pairs) else NULL
  }
  # comparisons of one probability with a number, as typed: "p5 < .2" gives (4, "<", "0.2"); "0.1 < p5 < .2" gives two
  items_spec_consts <- function(model_name) {
    n <- isolate(counter_input$n)
    nm <- vapply(seq_len(n), function(i) isolate(input[[paste0("textin_relations_name", i)]]) %||% paste0("m", i), character(1))
    idx <- which(nm == model_name)[1]
    if (is.na(idx)) return(list())
    spec <- paste(isolate(input[["add_for_all_models"]]) %||% "", isolate(input[[paste0("textin_relations_", idx)]]) %||% "", sep = ";")
    spec <- gsub("\u2265", ">=", gsub("\u2264", "<=", spec, fixed = TRUE), fixed = TRUE)
    num_of <- function(x) {
      x <- trimws(x)
      if (!grepl("^[0-9]*\\.?[0-9]+(/[0-9]*\\.?[0-9]+)?$", x)) return(NA_real_)
      v <- as.numeric(strsplit(x, "/", fixed = TRUE)[[1]]); if (length(v) == 2) v[1] / v[2] else v
    }
    p_of <- function(x) { m <- regmatches(trimws(x), regexec("^p([0-9]+)$", trimws(x), perl = TRUE))[[1]]; if (length(m)) as.integer(m[2]) else NA_integer_ }
    flip <- c("<" = ">", ">" = "<", "<=" = ">=", ">=" = "<=", "=" = "=")
    out <- list()
    for (cl in strsplit(spec, "[;,\n]")[[1]]) {
      ops <- regmatches(cl, gregexpr("<=|>=|<|>|=", cl))[[1]]
      opd <- trimws(strsplit(cl, "<=|>=|<|>|=")[[1]])
      if (length(ops) == 0 || length(opd) != length(ops) + 1) next
      for (i in seq_along(ops)) {
        a <- opd[i]; b <- opd[i + 1]
        if (!is.na(p_of(a)) && !is.na(num_of(b))) { pp <- p_of(a); op <- ops[i]; v <- num_of(b) }
        else if (!is.na(num_of(a)) && !is.na(p_of(b))) { pp <- p_of(b); op <- unname(flip[ops[i]]); v <- num_of(a) }
        else next
        out[[length(out) + 1L]] <- list(as.integer(pp - 1L), op, as.character(round(v, 4)))
      }
    }
    unique(out)
  }
  # constraints on several probabilities at once: a sum compared with a number (p1 + p5 <= .4) is drawn as a row of its own (like the sums
  # in comparisons); other constraints that the picture cannot draw (differences, longer chains) are listed as text
  items_spec_sums_others <- function(model_name) {
    n <- isolate(counter_input$n)
    nm <- vapply(seq_len(n), function(i) isolate(input[[paste0("textin_relations_name", i)]]) %||% paste0("m", i), character(1))
    idx <- which(nm == model_name)[1]
    if (is.na(idx)) return(list(sums = list(), others = list()))
    spec <- paste(isolate(input[["add_for_all_models"]]) %||% "", isolate(input[[paste0("textin_relations_", idx)]]) %||% "", sep = ";")
    spec <- gsub("\u2265", ">=", gsub("\u2264", "<=", spec, fixed = TRUE), fixed = TRUE)
    num_of <- function(x) {
      if (!grepl("^[0-9]*\\.?[0-9]+(/[0-9]*\\.?[0-9]+)?$", x)) return(NA_real_)
      v <- as.numeric(strsplit(x, "/", fixed = TRUE)[[1]]); if (length(v) == 2) v[1] / v[2] else v
    }
    flip <- c("<" = ">", ">" = "<", "<=" = ">=", ">=" = "<=", "=" = "=")
    is_sum <- function(x) grepl("^p[0-9]+(\\+p[0-9]+)+$", x)
    is_comb <- function(x) grepl("^[+-]?p[0-9]+([+-]p[0-9]+)+$", x)   # sums and differences of probabilities
    has_comb <- function(x) grepl("p[0-9]+.*[+-]|[+-].*p[0-9]+", gsub("^[-+]", "", x))
    sums <- list(); others <- character(0)
    for (cl in strsplit(spec, "[;,\n]")[[1]]) {
      cl <- trimws(cl)
      if (!nzchar(cl) || !grepl("p[0-9]+", cl)) next
      ops <- regmatches(cl, gregexpr("<=|>=|<|>|=", cl))[[1]]
      opd <- gsub("\\s+", "", trimws(strsplit(cl, "<=|>=|<|>|=")[[1]]))
      if (!any(vapply(opd, has_comb, logical(1)))) next
      pretty <- function(op) switch(op, "<=" = "\u2264", "<" = "\u2264", ">=" = "\u2265", ">" = "\u2265", op)   # weak inequalities (closed polytopes)
      # a term as typed: p1, 2*p1, p1*2, p1/2 or a number
      nump <- "[0-9]*\\.?[0-9]+(?:/[0-9]*\\.?[0-9]+)?"
      grab <- function(core, pat) regmatches(core, regexec(pat, core, perl = TRUE))[[1]]
      # bring everything into the form (weighted sum of probabilities) op (number): p1 >= p2 - .2 becomes p1 - p2 >= -0.2
      side <- function(x) {   # -> list(cf = named coefficients, k = constant, ok)
        tm <- regmatches(x, gregexpr("[+-]?[^+-]+", x))[[1]]
        cf <- numeric(0); k <- 0; ok <- TRUE
        for (t in tm) {
          sg <- if (startsWith(t, "-")) -1 else 1; core <- sub("^[+-]", "", t)
          nmv <- NA_character_; cv <- NA_real_
          if (grepl("^p[0-9]+$", core)) { nmv <- core; cv <- 1 }
          else if (length(m <- grab(core, paste0("^(", nump, ")\\*(p[0-9]+)$")))) { nmv <- m[3]; cv <- num_of(m[2]) }
          else if (length(m <- grab(core, paste0("^(p[0-9]+)\\*(", nump, ")$")))) { nmv <- m[2]; cv <- num_of(m[3]) }
          else if (length(m <- grab(core, paste0("^(p[0-9]+)/(", nump, ")$")))) { nmv <- m[2]; cv <- 1 / num_of(m[3]) }
          if (!is.na(nmv) && is.finite(cv)) cf[nmv] <- (if (nmv %in% names(cf)) cf[[nmv]] else 0) + sg * cv
          else if (!is.na(num_of(core))) k <- k + sg * num_of(core)
          else ok <- FALSE
        }
        list(cf = cf, k = k, ok = ok)
      }
      handled <- logical(length(ops))
      for (i in seq_along(ops)) {   # chains (a <= b <= c) are read pair by pair
        if (!has_comb(opd[i]) && !has_comb(opd[i + 1])) { handled[i] <- TRUE; next }
        L <- side(opd[i]); Rr <- side(opd[i + 1])
        if (!(L$ok && Rr$ok)) next
        nm_all <- union(names(L$cf), names(Rr$cf))
        cfs <- vapply(nm_all, function(n) (if (n %in% names(L$cf)) L$cf[[n]] else 0) - (if (n %in% names(Rr$cf)) Rr$cf[[n]] else 0), numeric(1))
        cfs <- cfs[cfs != 0]; kk <- Rr$k - L$k
        if (length(cfs) == 0) next
        if (length(cfs) == 1) { handled[i] <- TRUE; next }   # one probability against a number: the label of its row; against another probability: an arrow
        if (kk == 0 && any(cfs > 0) && any(cfs < 0) && !grepl("-", cl, fixed = TRUE)) { handled[i] <- TRUE; next }   # one side against the other (p1 + p2 >= p3): the comparisons of the picture draw it
        op <- ops[i]
        if (ops[i] == "=") op <- "="
        if (all(cfs < 0)) { cfs <- -cfs; kk <- -kk; op <- unname(flip[op]) }   # .2 < p2 + p3 reads p2 + p3 > .2
        cfs <- cfs[order(cfs < 0, as.integer(sub("^p", "", names(cfs))))]       # the added parts first: p4 - p3, not -p3 + p4
        val <- as.character(round(kk, 4))
        fmt <- function(v) format(round(v, 4), trim = TRUE)
        txt_a <- paste0(vapply(seq_along(cfs), function(j) paste0(if (j == 1) (if (cfs[j] < 0) "\u2212" else "") else (if (cfs[j] < 0) " \u2212 " else " + "),
                                                                      if (abs(cfs[j]) != 1) paste0(fmt(abs(cfs[j])), "\u00b7") else "", names(cfs)[j]), character(1)), collapse = "")   # a real minus sign, like in the picture
        sums[[length(sums) + 1L]] <- list(parts = as.integer(sub("^p", "", names(cfs))) - 1L, w = unname(vapply(cfs, fmt, character(1))), op = op, val = val,
                                          text = paste0(txt_a, " ", pretty(op), " ", sub("^-", "\u2212", val)))
        handled[i] <- TRUE
      }
      if (all(handled)) next
      txt <- gsub("\\s+", "", cl)
      for (o in c("<=", ">=")) txt <- gsub(o, paste0(" ", pretty(o), " "), txt, fixed = TRUE)
      txt <- gsub("<", " \u2264 ", txt, fixed = TRUE); txt <- gsub(">", " \u2265 ", txt, fixed = TRUE)
      txt <- gsub("(?<![\u2264\u2265 ])(=)(?! )", " \\1 ", txt, perl = TRUE)
      txt <- gsub("\\+", " + ", txt); txt <- gsub("(?<=[0-9p])-", " - ", txt, perl = TRUE)
      others <- c(others, txt)
    }
    list(sums = sums, others = as.list(unique(others)))
  }
  items_pairs_json <- function(model_name) {
    pr <- items_spec_pairs(model_name)
    if (is.null(pr)) pr <- items_pairs_for(model_name)
    if (is.null(pr)) return("null")
    as.character(jsonlite::toJSON(pr, auto_unbox = TRUE))
  }

  open_items_modal <- function(prefill_base = NULL, prefill_rows = NULL) {
    model_choices <- get_name_models_reactive()
    if (length(model_choices) == 0) {
      fairy_notify("No models", "Define at least one model first.", type = "info")
      return()
    }
    n_p_all <- isolate(counter$n)
    p_names <- vapply(seq_len(n_p_all), function(i) {
      nm <- trimws(isolate(input[[paste0("textin_name_", i)]]) %||% "")
      if (nzchar(nm)) nm else paste0("p", i)
    }, character(1))
    is_edit <- !is.null(prefill_rows)
    adv_diff <- is_edit && length(prefill_rows) > 1 && {
      u <- function(f) length(unique(vapply(prefill_rows, function(r) as.character(f(r) %||% ""), character(1))))
      u(function(r) r$n) > 1 || u(function(r) r$type) > 1 || u(function(r) r$eps) > 1 || u(function(r) r$group) > 1
    }

    showModal(modalDialog(
      title = NULL,
      size = "l",
      class = "fairy-eq-tol-modal",
      tags$div(class = "fairy-eq-tol-header", tags$strong(if (is_edit) "Edit unpacking across items" else "Unpack across items")),
      tags$p(class = "fairy-eq-tol-help",
        HTML("Use this if your study has <b>several items</b> for each probability, e.g. several different jokes, stimuli or trials. The model is then applied to the items.")
      ),
      tags$script(HTML(paste0("window.fairyItemsPairs = ", items_pairs_json(prefill_base %||% model_choices[1]), "; window.fairyItemsConsts = ",
                              as.character(jsonlite::toJSON(items_spec_consts(prefill_base %||% model_choices[1]), auto_unbox = TRUE)),
                              "; window.fairyItemsOthers = ", as.character(jsonlite::toJSON(items_spec_sums_others(prefill_base %||% model_choices[1])$others, auto_unbox = TRUE)),
                              "; window.fairyItemsSums = ", as.character(jsonlite::toJSON(items_spec_sums_others(prefill_base %||% model_choices[1])$sums, auto_unbox = TRUE)), ";"))),
      # Each row is its OWN grid container rather than one flat grid for
      # header + all rows — conditionalPanel hides the tolerance cell via
      # display:none, and a display:none item drops out of grid flow
      # entirely (not just invisibly), which shifted every following
      # row's cells left by one column when a flat shared grid was used.
      # A row-local grid isn't affected by what a DIFFERENT row's grid
      # does with its own (independent) 4th column.
      #
      # Main dialog: how many items, and how the model should hold across them. It fills the
      # per-probability fields under "Advanced" (Group / Items / Model holds).
      {
        pf_all <- prefill_rows
        q_n    <- if (length(pf_all)) max(vapply(pf_all, function(r) as.integer(r$n %||% 1L), integer(1))) else 2L
        q_type <- if (length(pf_all)) (pf_all[[1]]$type %||% "joint") else "joint"
        # the tolerance belongs to the lists that use "shared value": take it from the first such row, not just from the first row
        q_eps  <- if (length(pf_all)) {
          idr <- Filter(function(r) identical(as.character(r$type %||% ""), "identical"), pf_all)
          as.numeric((if (length(idr)) idr[[1]] else pf_all[[1]])$eps %||% 0)
        } else 0
        opt <- function(value, label, expl, gloss = NULL)
          tags$label(class = paste("fairy-items-opt", if (identical(value, q_type)) "fairy-items-opt-sel" else ""),
            tags$input(type = "radio", name = "fairy_items_quick_type", value = value, class = "fairy-items-quick-type",
              checked = if (identical(value, q_type)) "checked" else NULL),
            tags$span(tags$b(label, if (!is.null(gloss)) tags$em(class = "fairy-items-gloss", gloss)), tags$span(expl)))
        qh <- function(num, text, hint = NULL, id = NULL)
          tags$div(class = "fairy-items-q", style = "display:flex; align-items:baseline; gap:8px; margin:14px 0 6px;",
            tags$span(class = "fairy-items-num", style = "flex:none; width:20px; height:20px; border-radius:50%; background:var(--fairy-primary, #3a6df0); color:#fff; font-size:11.5px; font-weight:700; display:inline-flex; align-items:center; justify-content:center;", num),
            tags$span(tags$strong(id = id, text, style = "font-size:13px;"),
              if (!is.null(hint)) tags$span(HTML(hint), style = "display:block; font-size:11.5px; color:var(--fairy-text-muted);")))
        tags$div(class = "fairy-items-quick", `data-edit` = if (is_edit) "1" else "0", `data-custom` = if (adv_diff) "1" else "0", style = "margin-top:8px; padding:12px; border-radius:8px; background:var(--ct-diag);",
          tags$style(HTML("
            .fairy-items-main { display:grid; grid-template-columns: 1fr 1.15fr; gap:22px; align-items:start; }
            .modal:has(#submit_items_multi) .modal-body { padding:16px 26px; }
            .fairy-items-opt { padding:8px 10px !important; margin-bottom:6px !important; }
