          ")),
          tags$div(class = "fairy-items-top",
          tags$div(id = "fairy_items_base_wrap", selectInput("items_base_model", "Base model", choices = model_choices,
            selected = prefill_base %||% model_choices[1], width = "100%")),
          tags$div(id = "fairy_items_q1",
          qh(1, "Same items for all probabilities?"),
          tags$div(style = "margin-left:28px;",
            tags$label(style = "display:block; font-weight:normal; font-size:13px; margin:0 0 4px; cursor:pointer;",
              tags$input(type = "radio", name = "fairy_items_two_choice", value = "same", class = "fairy-items-two-choice",
                checked = if (adv_diff) NULL else "checked", style = "margin-right:6px;"), "Yes, the same items"),
            tags$label(style = "display:block; font-weight:normal; font-size:13px; margin:0 0 4px; cursor:pointer;",
              tags$input(type = "radio", name = "fairy_items_two_choice", value = "two", class = "fairy-items-two-choice",
                checked = if (adv_diff) "checked" else NULL, style = "margin-right:6px;"),
              "No, different lists ",
              tags$span(style = "color:var(--fairy-text-muted); font-size:11.5px;", "(e.g. p1, p2 use a list of 3 jokes, p3, p4 a list of 5 puns)")))),
          tags$div(id = "fairy_items_count_same", style = if (adv_diff) "display:none;" else "",
            qh(2, "How many items?", "e.g. 3 different jokes"),
            tags$div(class = "fairy-items-nrow", style = "margin:0 0 4px 28px;",
              tags$input(id = "fairy_items_quick_n", type = "number", min = 1, max = 50, step = 1, value = q_n,
                class = "form-control", style = "width:80px;", `aria-label` = "Number of items")))),
          tags$div(id = "fairy_items_two_panel", style = if (adv_diff) "" else "display:none;",
            qh(2, "Which probabilities share a list, and how many items does each list have?"),
            tags$div(style = "margin:0 0 4px 28px; padding:8px 10px; border-radius:8px; background:var(--ct-default, #fff); border:1px solid var(--fairy-border, #d5d9e4);",
              tags$div(style = "font-size:12px; color:var(--fairy-text-muted);",
                "Click a probability to move it to the next list (A, B, C, \u2026). Probabilities in the same list use the same items."),
              tags$div(id = "fairy_items_chips", style = "display:flex; flex-wrap:wrap; gap:6px; margin:8px 0;"),
              tags$div(id = "fairy_items_sets", style = "margin:4px 0 2px;"))),
          qh(3, "Your model holds \u2026", id = "fairy_items_q3_text"),
          tags$div(id = "fairy_items_pairs_hint", style = "margin:-2px 0 8px 28px; font-size:11.5px; color:var(--fairy-text-muted);"),
          tags$div(class = "fairy-items-main",
            tags$div(
              opt("joint", "joint", "item 1 with item 1, item 2 with item 2, \u2026", "matching items"),
              opt("substitutable", "substitutable", "every item with every item", "all combinations of items"),
              opt("identical", "identical", "all items of a probability are equal", "e.g. p1 is the same number for every item"),
              opt("average", "average", "only the average over the items has to satisfy it", "e.g. average of p1 > average of p2"),
              tags$div(id = "fairy_items_perlist_wrap", style = "display:none;",
                opt("perlist", "differently for each list", "choose joint, substitutable, identical or average for every list"),
                # the choice per list sits right here under the option (not up in the box of the lists)
                tags$div(id = "fairy_items_perlist_rows", style = "margin:2px 0 8px 40px; font-size:12.5px;")),
              tags$div(id = "fairy_items_stmts", style = "font-size:12px;"),
              tags$div(id = "fairy_items_caption", style = "font-size:12px; margin-top:6px;")
            ),
            tags$div(class = "fairy-items-viz",
              tags$button(id = "fairy_items_expand", type = "button", title = "Expand the picture (Esc to close)", `aria-label` = "Expand the picture",
                HTML("<svg width='16' height='16' viewBox='0 0 16 16' fill='none' stroke='currentColor' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'><path d='M9.5 2.5h4v4M13.5 2.5l-4.5 4.5M6.5 13.5h-4v-4M2.5 13.5l4.5-4.5'/></svg>")),
              tags$button(id = "fairy_items_pdf", type = "button", title = "Download the picture as PDF (for slides, papers)", `aria-label` = "Download the picture as PDF",
                HTML("<svg width='16' height='16' viewBox='0 0 16 16' fill='none' stroke='currentColor' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'><path d='M8 2v8M4.5 7 8 10.5 11.5 7M3 13.5h10'/></svg>")),
              tags$div(id = "fairy_items_diagram", `aria-hidden` = "true"),
              tags$div(id = "fairy_items_legend", style = "font-size:11px; color:var(--fairy-text-muted); margin-top:8px; line-height:1.7; display:flex; flex-wrap:wrap; gap:2px 18px; justify-content:center; text-align:center;"),
              tags$label(id = "fairy_items_fade_wrap", style = "display:none; font-weight:normal; font-size:11.5px; margin:6px 0 0; cursor:pointer; color:var(--fairy-text-muted);",
                tags$input(id = "fairy_items_fade_toggle", type = "checkbox", checked = "checked", style = "margin:0 6px 0 0; vertical-align:-1px;"),
                "Show redundant comparisons"))),
          tags$div(id = "fairy_items_quick_eps_wrap", style = paste0(if (identical(q_type, "identical")) "" else "display:none;"),
            qh(4, "Are the items of a probability exactly equal, or only approximately?"),
            tags$div(style = "margin-left:28px; font-size:12.5px;",
              "They may differ by up to ",
              tags$input(id = "fairy_items_quick_eps", type = "number", min = 0, max = 1, step = 0.01, value = q_eps,
                class = "form-control", style = "width:76px; display:inline-block; height:26px; padding:2px 6px;", `aria-label` = "Allowed deviation"),
              " (0 = exactly equal, 0.05 = up to 0.05 apart)")),
          tags$div(id = "fairy_items_summary", style = "margin-top:14px; padding:8px 10px; border-left:3px solid var(--fairy-primary, #3a6df0); background:var(--ct-default, #fff); border-radius:4px; font-size:12.5px;")
        )
      },
      tags$div(style = "margin-top:12px;",
        tags$div(style = "display:none;",
      tags$div(
        id = "fairy-items-header-row",
        style = "display:grid; grid-template-columns: 1.6fr 1.6fr 1fr 1.6fr 1.4fr; gap:6px 10px; align-items:center; margin-top:6px;",
        tags$strong("Probability", style = "font-size:11.5px; color:var(--fairy-text-muted);"),
        tags$strong("Item set", class = "fairy-items-group-cell", style = "font-size:11.5px; color:var(--fairy-text-muted);"),
        tags$strong("Items", style = "font-size:11.5px; color:var(--fairy-text-muted);"),
        tags$strong("Model holds", style = "font-size:11.5px; color:var(--fairy-text-muted);"),
        tags$strong("May differ by", style = "font-size:11.5px; color:var(--fairy-text-muted);")
      ),
      lapply(seq_along(p_names), function(i) {
        pf <- prefill_rows[[p_names[i]]]
        # Group/Type/tolerance are all meaningless (no-ops) while this
        # row's own Items is still 1 — nothing to group, substitute, or
        # treat as identical yet. Greyed out and actually disabled until
        # Items > 1 (see the delegated JS below), rather than sitting
        # there editable but inert.
        tags$div(
          class = "fairy-items-row", style = "display:grid; grid-template-columns: 1.6fr 1.6fr 1fr 1.6fr 1.4fr; gap:6px 10px; align-items:center; margin-top:4px;",
          tags$span(p_names[i], style = "font-size:13px;"),
          tags$div(class = "fairy-items-group-cell",
            textInput(paste0("items_multi_group_", i), NULL, value = pf$group %||% "", placeholder = "own items", width = "100%")
          ),
          numericInput(paste0("items_multi_n_", i), NULL, value = pf$n %||% 1, min = 1, max = 50, step = 1, width = "100%"),
          selectInput(paste0("items_multi_type_", i), NULL,
            choices = c("Item by item" = "joint", "Any item with any item" = "substitutable", "All items the same" = "identical", "Only the average" = "average"),
            selected = pf$type %||% "joint", width = "100%"),
          conditionalPanel(
            condition = paste0("input.items_multi_type_", i, " == 'identical'"),
            numericInput(paste0("items_multi_eps_", i), NULL, value = pf$eps %||% 0, min = 0, max = 1, step = 0.01, width = "100%")
          )
        )
      })
        )
      ),
      tags$script(HTML(
        "
        (function() {
          function updateItemsRow(row) {
            // Tag-qualified (input[...]/select[...]), not just
            // [id^=...] — Shiny gives every one of these inputs a
            // sibling <label id=\"<inputId>-label\"> even when label=NULL
            // is passed, which also matches a bare [id^=...] attribute
            // selector and (being first in the DOM) was the one
            // querySelector actually returned — reading .value off a
            // <label> is always undefined, so n parsed as NaN -> fell
            // back to the 1/inactive default every time, regardless of
            // what was actually typed.
            var nInput = row.querySelector('input[id^=items_multi_n_]');
            var n = parseInt(nInput && nInput.value, 10) || 1;
            var active = n > 1;
            row.classList.toggle('fairy-items-row-inactive', !active);
            // Group stays editable regardless of this row's OWN Items
            // value — a grouped member inherits the group's item count
            // from whichever member actually has one set (see
            // submit_items_multi's own comment), so gating this on
            // n>1 made it impossible to even TYPE a group name into a
            // probability before first bumping its own Items to match,
            // which read as 'grouping it does nothing' (direct user
            // report: a probability assigned to a group still counted
            // as its own separate single-item factor).
            var typeSelect = row.querySelector('select[id^=items_multi_type_]');
            if (typeSelect) {
              typeSelect.disabled = !active;
              // selectInput's default selectize=TRUE wraps the real
              // <select> (now disabled) in its own styled UI, which
              // does not pick up the native disabled state on its own.
              if (typeSelect.selectize) {
                if (active) typeSelect.selectize.enable(); else typeSelect.selectize.disable();
              }
            }
            var eps = row.querySelector('input[id^=items_multi_eps_]');
            if (eps) eps.disabled = !active;
          }
          function updateAllItemsRows() {
            document.querySelectorAll('.fairy-items-row').forEach(updateItemsRow);
          }
          // Rows sharing a non-empty Group must always show the SAME
          // Items count, Type, and (when Type is Identical) Approx. tol.
          // -- all three are properties of the GROUP/factor, not of each
          // individual probability (see the modal's own Group/Type help
          // text: they share one item count and how the items inside a
          // group line up) -- sync them live as you type, rather than
          // only forcing agreement at Submit time, which let the fields
          // visibly disagree while the modal was still open.
          function syncGroupItems(changedRow, changedField) {
            var groups = {};
            document.querySelectorAll('.fairy-items-row').forEach(function(row) {
              var gInput = row.querySelector('input[id^=items_multi_group_]');
              var g = gInput && gInput.value.trim();
              if (!g) return;
              (groups[g] = groups[g] || []).push(row);
            });
            Object.keys(groups).forEach(function(g) {
              var rows = groups[g];
              if (rows.length < 2) return;
              var isChangedGroup = changedRow && rows.indexOf(changedRow) > -1;

              // Items: the actively-edited row wins ties; otherwise the
              // largest value currently set in the group.
              var targetN = null;
              if (isChangedGroup && changedField === 'n') {
                var cInput = changedRow.querySelector('input[id^=items_multi_n_]');
                targetN = parseInt(cInput && cInput.value, 10) || null;
              }
              if (!targetN) {
                rows.forEach(function(row) {
                  var nInput = row.querySelector('input[id^=items_multi_n_]');
                  var n = parseInt(nInput && nInput.value, 10) || 1;
                  if (targetN === null || n > targetN) targetN = n;
                });
              }
              rows.forEach(function(row) {
                var nInput = row.querySelector('input[id^=items_multi_n_]');
                if (nInput && parseInt(nInput.value, 10) !== targetN) {
                  nInput.value = targetN;
                  $(nInput).trigger('change');
                }
              });

              // Type: the actively-edited row wins; otherwise the first
              // row's current selection.
              var targetType = null;
              if (isChangedGroup && changedField === 'type') {
                var cSel = changedRow.querySelector('select[id^=items_multi_type_]');
                targetType = cSel && cSel.value;
              }
              if (!targetType) {
                var firstSel = rows[0].querySelector('select[id^=items_multi_type_]');
                targetType = firstSel && firstSel.value;
              }
              if (targetType) {
                rows.forEach(function(row) {
                  var sel = row.querySelector('select[id^=items_multi_type_]');
                  if (!sel || sel.value === targetType) return;
                  // selectize.js replaces the real <select> with its own
                  // styled dropdown UI and owns rendering it — setting
                  // sel.value directly changes the hidden native element
                  // but leaves the visible styled control (and selectize's
                  // own idea of the current value) stale/blank. Go through
                  // its own API instead so both the native select AND the
                  // visible UI end up in sync; selectize.setValue already
                  // updates the native select and fires Shiny's change
                  // binding on its own, non-silent so Shiny actually picks
                  // it up.
                  if (sel.selectize) sel.selectize.setValue(targetType);
                  else { sel.value = targetType; $(sel).trigger('change'); }
                });
              }

              // Approx. tol. is NOT synced across group members — unlike
              // Items and Type, it's genuinely a per-MEMBER setting (see
              // build_items_h_mixed's own comment): within one group,
              // p1's copies can be forced equal within a different
              // tolerance than p2's copies. Each row's own eps field is
              // left exactly as typed.

              rows.forEach(updateItemsRow);
            });
          }
          $(document).on('shown.bs.modal', updateAllItemsRows);
          $(document).on('shown.bs.modal', function() { syncGroupItems(null); });
          $(document).on('input change', '.fairy-items-row [id^=items_multi_n_]', function() {
            var row = this.closest('.fairy-items-row');
            updateItemsRow(row);
            syncGroupItems(row, 'n');
          });
          $(document).on('input change', '.fairy-items-row [id^=items_multi_group_]', function() {
            syncGroupItems(this.closest('.fairy-items-row'), 'group');
          });
          $(document).on('change', '.fairy-items-row [id^=items_multi_type_]', function() {
            syncGroupItems(this.closest('.fairy-items-row'), 'type');
          });
          // ---- item sets as coloured chips: click a probability to move it to the next set ----
          var chipState = { asg: [], sets: [] };
          var chipPal = ['#3a6df0', '#e07b00', '#2a9d6f', '#b04fd0', '#c2385a', '#7a7f8c'];
          function chipLetter(k) { return k < 26 ? String.fromCharCode(65 + k) : String(k + 1); }
          function chipColor(k) { return chipPal[k % chipPal.length]; }
          // lists can be renamed (the box in the list row); the default is list A, list B, ...
          var listNames = [];
          function cleanListName(v) { return String(v || '').replace(/[<>&\"']/g, '').trim().slice(0, 24); }
          function listTitle(k) { return listNames[k] ? listNames[k] : 'list ' + chipLetter(k); }
          // (two lists with the same name are merged into one when the name is entered, so the names are unique)
          function groupNameOf(k) {
            var b = listNames[k];
            return b ? b : 'group ' + chipLetter(k);
          }
          var CHIP_TYPES = [['joint', 'joint (matching items)'], ['substitutable', 'substitutable (all combinations)'], ['identical', 'identical (items equal)'], ['average', 'average (over the items)']];
          function chipRowName(i) {
            var rows = document.querySelectorAll('.fairy-items-row'), sp = rows[i] && rows[i].querySelector('span');
            var t = sp ? sp.textContent.replace(/[_{}]/g, '').trim() : '';
            return t || ('p' + (i + 1));
          }
          function chipsFromRows() {
            var rows = document.querySelectorAll('.fairy-items-row'), info = [];
            rows.forEach(function(r) {
              info.push({
                g: (r.querySelector('input[id^=items_multi_group_]').value || '').trim(),
                n: Math.max(1, parseInt(r.querySelector('input[id^=items_multi_n_]').value, 10) || 1),
                t: r.querySelector('select[id^=items_multi_type_]').value || 'joint'
              });
            });
            var uniform = info.every(function(x) { return !x.g && x.n === info[0].n && x.t === info[0].t; });
            var asg = [], sets = [], keyIdx = {}, gNames = [];
            info.forEach(function(x, i) {
              var key = uniform ? 'all' : (x.g ? 'g:' + x.g : 's:' + i);
              if (!(key in keyIdx)) {
                keyIdx[key] = sets.length + 1; sets.push({ n: x.n, type: x.t });
                // a list name that was given earlier (opening the dialog again): not the default group A, group B, ...
                gNames.push((!uniform && x.g && !/^(group [A-Z0-9]+|set [0-9]+)$/.test(x.g)) ? x.g : '');
              }
              asg.push(keyIdx[key]);
            });
            if (!listNames.some(Boolean)) listNames = gNames;
            var diffT = sets.some(function(x) { return x.type !== sets[0].type; });
            sets.forEach(function(x) { x.over = diffT ? x.type : ''; });
            chipState = { asg: asg, sets: sets, counts: info.map(function(x) { return x.n; }) };
          }
          function chipsCompact() {
            var used = [];
            chipState.asg.forEach(function(s) { if (used.indexOf(s) < 0) used.push(s); });
            used.sort(function(a, b) { return a - b; });
            var map = {}, ns = [];
            used.forEach(function(s, k) { map[s] = k + 1; ns.push(chipState.sets[s - 1] || { n: chipState.sets[0].n, type: chipState.sets[0].type, over: '' }); });
            // the names of the lists travel with their lists when the numbering changes
            listNames = used.map(function(s) { return listNames[s - 1] || ''; });
            chipState.asg = chipState.asg.map(function(s) { return map[s]; });
            chipState.sets = ns;
          }
          function chipsRender() { chipsRenderGroups(); }
          function chipsRenderGroups() {
            var ch = document.getElementById('fairy_items_chips'), sl = document.getElementById('fairy_items_sets');
            if (!ch || !sl) return;
            ch.textContent = ''; sl.textContent = '';
            var prows = document.getElementById('fairy_items_perlist_rows');
            if (prows) prows.textContent = '';
            chipState.asg.forEach(function(s, i) {
              var b = document.createElement('button');
              b.type = 'button'; b.className = 'fairy-chip'; b.setAttribute('data-p', i);
              b.textContent = chipRowName(i) + ' ' + String.fromCharCode(183) + ' ' + listTitle(s - 1);
              b.style.cssText = 'border:1.5px solid ' + chipColor(s - 1) + '; background:' + chipColor(s - 1) + '22; color:inherit; border-radius:14px; padding:3px 11px; font-size:12.5px; cursor:pointer;';
              ch.appendChild(b);
            });
            chipState.sets.forEach(function(st, k) {
              var row = document.createElement('div');
              row.style.cssText = 'display:flex; align-items:center; gap:8px; margin:5px 0; flex-wrap:wrap;';
              var dot = document.createElement('span'); dot.style.cssText = 'width:12px; height:12px; border-radius:50%; background:' + chipColor(k) + '; display:inline-block;';
              var lab = document.createElement('input'); lab.type = 'text'; lab.className = 'form-control fairy-set-name'; lab.value = listNames[k] || ''; lab.placeholder = 'list ' + chipLetter(k);
              lab.maxLength = 24; lab.setAttribute('data-set', k); lab.setAttribute('aria-label', 'Name of list ' + chipLetter(k)); lab.title = 'Click to rename this list';
              lab.style.cssText = 'width:112px; height:28px; padding:2px 8px; font-size:12.5px; font-weight:600;';
              var members = chipState.asg.map(function(s, i) { return s === k + 1 ? chipRowName(i) : null; }).filter(Boolean).join(', ');
              var mem = document.createElement('span'); mem.style.cssText = 'font-size:12px; color:var(--fairy-text-muted);'; mem.textContent = '(' + members + ')';
              var inp = document.createElement('input'); inp.type = 'number'; inp.min = 1; inp.max = 50; inp.value = st.n; inp.className = 'form-control fairy-set-n';
              inp.style.cssText = 'width:70px; height:28px; padding:2px 6px;'; inp.setAttribute('data-set', k); inp.setAttribute('aria-label', 'Items of list ' + chipLetter(k));
              var it = document.createElement('span'); it.style.fontSize = '12.5px'; it.textContent = 'items';
              var sel = document.createElement('select'); sel.className = 'form-control fairy-set-type'; sel.style.cssText = 'width:auto; height:28px; padding:2px 6px;'; sel.setAttribute('data-set', k);
              CHIP_TYPES.forEach(function(t) { var o = document.createElement('option'); o.value = t[0]; o.textContent = t[1]; if (t[0] === st.type) o.selected = true; sel.appendChild(o); });
              var parts = [dot, lab, mem, inp, it];
              var curT = document.querySelector('.fairy-items-quick-type:checked');
              if (curT && curT.value === 'perlist') {
                var ov = document.createElement('select'); ov.className = 'form-control fairy-set-over'; ov.style.cssText = 'width:auto; height:28px; padding:2px 6px; font-size:12px;'; ov.setAttribute('data-set', k);
                ov.setAttribute('aria-label', 'How the model is applied to list ' + chipLetter(k));
                CHIP_TYPES.forEach(function(t) { var o = document.createElement('option'); o.value = t[0]; o.textContent = t[1]; if (t[0] === (st.over || 'joint')) o.selected = true; ov.appendChild(o); });
                if (prows) {
                  var pl = document.createElement('div'); pl.style.cssText = 'display:flex; align-items:center; gap:8px; margin:5px 0; flex-wrap:wrap;';
                  var pdot = dot.cloneNode(true);
                  var pnm = document.createElement('span'); pnm.style.fontWeight = '600'; pnm.textContent = listNames[k] || ('list ' + chipLetter(k));
                  var pmem = mem.cloneNode(true);
                  pl.appendChild(pdot); pl.appendChild(pnm); pl.appendChild(pmem); pl.appendChild(ov);
                  prows.appendChild(pl);
                } else {
                  parts.push(ov);
                }
              }
              parts.forEach(function(e) { row.appendChild(e); });
              sl.appendChild(row);
            });
          }
          function chipsApply() {
            itemsApplying = true;
            var rows = document.querySelectorAll('.fairy-items-row');
            var epsEl = document.getElementById('fairy_items_quick_eps'), epsV = Math.min(1, Math.max(0, parseFloat(epsEl && epsEl.value) || 0));
            rows.forEach(function(row) { var g = row.querySelector('input[id^=items_multi_group_]'); if (g) { g.value = ''; $(g).trigger('input'); } });
            rows.forEach(function(row, i) { var st = chipState.sets[chipState.asg[i] - 1], nIn = row.querySelector('input[id^=items_multi_n_]'); if (nIn) { nIn.value = st.n; $(nIn).trigger('change'); } });
            var gT = document.querySelector('.fairy-items-quick-type:checked'); gT = gT ? gT.value : 'joint';
            rows.forEach(function(row, i) {
              var k = chipState.asg[i], st = { n: chipState.sets[k - 1].n, type: chipState.sets[k - 1].over || gT };
              var gIn = row.querySelector('input[id^=items_multi_group_]'), sel = row.querySelector('select[id^=items_multi_type_]'), eIn = row.querySelector('input[id^=items_multi_eps_]');
              if (st.n > 1) {
                if (sel) { if (sel.selectize) sel.selectize.setValue(st.type); else { sel.value = st.type; $(sel).trigger('change'); } }
                if (gIn) { gIn.value = groupNameOf(k - 1); $(gIn).trigger('input'); }
              }
              if (eIn) { eIn.value = st.type === 'identical' ? epsV : 0; $(eIn).trigger('change'); }
            });
            syncGroupItems(null);
            updateAllItemsRows();
            itemsApplying = false;
            itemsSummary();
            drawItemsDiagram();
          }
          function chipsApplyCounts() {
            itemsApplying = true;
            var rows = document.querySelectorAll('.fairy-items-row'), tEl = document.querySelector('.fairy-items-quick-type:checked'), type = tEl ? tEl.value : 'substitutable';
            rows.forEach(function(row, i) {
              var gIn = row.querySelector('input[id^=items_multi_group_]'), nIn = row.querySelector('input[id^=items_multi_n_]');
              var sel = row.querySelector('select[id^=items_multi_type_]'), eIn = row.querySelector('input[id^=items_multi_eps_]');
              if (gIn) { gIn.value = ''; $(gIn).trigger('input'); }
              if (nIn) { nIn.value = chipState.counts[i]; $(nIn).trigger('change'); }
              if (sel && chipState.counts[i] > 1) { if (sel.selectize) sel.selectize.setValue(type); else { sel.value = type; $(sel).trigger('change'); } }
              if (eIn) { eIn.value = 0; $(eIn).trigger('change'); }
            });
            updateAllItemsRows();
            itemsApplying = false;
            var same = chipState.counts.every(function(c) { return c === chipState.counts[0]; });
            markItemsCustom(!same);
          }
          $(document).on('input change', '.fairy-count-n', function() {
            var i = parseInt(this.getAttribute('data-p'), 10);
            chipState.counts[i] = Math.max(1, Math.min(50, parseInt(this.value, 10) || 1));
            chipsApplyCounts();
          });
          $(document).on('change', '.fairy-items-two-choice', function() {
            var two = twoKinds(), p = document.getElementById('fairy_items_two_panel'), cs = document.getElementById('fairy_items_count_same');
            if (p) p.style.display = two ? '' : 'none';
            if (cs) cs.style.display = two ? 'none' : '';
            if (!two) { var cur = document.querySelector('.fairy-items-quick-type:checked'); if (cur && cur.value === 'perlist') { var jr2 = document.querySelector('.fairy-items-quick-type[value=joint]'); if (jr2) jr2.checked = true; } }
            if (two) { chipsFromRows(); chipsRender(); quickChrome(); chipsApply(); } else { quickApply(); quickChrome(); }
          });
          $(document).on('click', '.fairy-chip', function() {
            var i = parseInt(this.getAttribute('data-p'), 10), cur = chipState.asg[i], mx = 0;
            chipState.asg.forEach(function(s, j) { if (j !== i && s > mx) mx = s; });
            var nxt = cur + 1; if (nxt > mx + 1) nxt = 1;
            if (!chipState.sets[nxt - 1]) chipState.sets[nxt - 1] = { n: chipState.sets[0].n, type: chipState.sets[0].type, over: '' };
            chipState.asg[i] = nxt; chipsCompact(); chipsRender(); chipsApply();
          });
          $(document).on('input change', '.fairy-set-n', function() {
            var k = parseInt(this.getAttribute('data-set'), 10); chipState.sets[k].n = Math.max(1, Math.min(50, parseInt(this.value, 10) || 1)); chipsApply();
          });
          $(document).on('change', '.fairy-set-type', function() {
            var k = parseInt(this.getAttribute('data-set'), 10); chipState.sets[k].type = this.value; chipsApply();
          });
          // renaming a list: chips and picture follow while typing, the group names of the rows when the box is left
          $(document).on('input', '.fairy-set-name', function() {
            var k = parseInt(this.getAttribute('data-set'), 10); listNames[k] = cleanListName(this.value);
            document.querySelectorAll('#fairy_items_chips > button').forEach(function(b) { var i = parseInt(b.getAttribute('data-p'), 10); b.textContent = chipRowName(i) + ' ' + String.fromCharCode(183) + ' ' + listTitle(chipState.asg[i] - 1); });
            drawItemsDiagram();
          });
          // the same name means the same list: the probabilities of this list join the list that already has the name
