              var LET = ['i', 'j', 'k', 'l', 'm', 'n'], OS = String.fromCharCode(216), DOT = String.fromCharCode(183), ELL = String.fromCharCode(8230);
              var sRows = [], total = 0, shownAny = false;
              PPs.slice(0, 5).forEach(function(p) {
                var sides = [0, 1].map(function(si) {
                  var sd = p[si], w = p[si + 3], ids = Array.isArray(sd) ? sd : [sd], ws = Array.isArray(w) ? w : [w];
                  return ids.map(function(r, kk) { return { r: r, w: (ids.length > 1 && ws[kk] && ws[kk] !== '1') ? ws[kk] : '' }; });
                });
                var terms = sides[0].concat(sides[1]), cT = [p[5] || '', p[6] || ''];
                if (terms.some(function(t) { return t.r >= nProb; })) return;
                var perList = {}, nextL = 0, count = 1, vars = [];
                terms.forEach(function(t) { t.s = spec(t.r); (perList[t.s.list] = perList[t.s.list] || []).push(t); });
                // joint lists of the same constraint share one item index (item k with item k); items that are not in all of them are left out
                var jKeys = Object.keys(perList).filter(function(lk) { return perList[lk][0].s.type === 'joint'; }), jL = null;
                var jAll = Object.keys(perList).filter(function(lk) { var ty0 = perList[lk][0].s.type; return ty0 === 'joint' || ty0 === 'identical'; });
                var jShare = jKeys.length >= 1 && jAll.length >= 2;
                var jN = Math.min.apply(null, jAll.map(function(lk) { return perList[lk][0].s.n; }));
                Object.keys(perList).forEach(function(lk) {
                  var sl = perList[lk], ty = sl[0].s.type, n = sl[0].s.n;
                  if (ty === 'joint' && jShare) { if (!jL) { jL = LET[nextL++]; count *= jN; vars.push({ l: jL, n: jN }); } sl.forEach(function(t) { t.ix = jL; }); }
                  else if (ty === 'joint') { var l1 = LET[nextL++]; sl.forEach(function(t) { t.ix = l1; }); count *= n; vars.push({ l: l1, n: n }); }
                  else if (ty === 'substitutable') sl.forEach(function(t) { var l2 = LET[nextL++]; t.ix = l2; count *= n; vars.push({ l: l2, n: n }); });
                  else if (ty === 'average') sl.forEach(function(t) { t.avg = true; });
                });
                var fmt = function(t) { return (t.w ? t.w + DOT : '') + (t.avg ? 'mean(' + nm(t.r) + ')' : nm(t.r) + (t.ix ? '(' + t.ix + ')' : '')); };
                var hiT = (cT[0] ? cT[0] + ' + ' : '') + sides[0].map(fmt).join(' + '), loT = (cT[1] ? cT[1] + ' + ' : '') + sides[1].map(fmt).join(' + ');
                if (p[2]) loT = p[2] + DOT + (sides[1].length > 1 || cT[1] ? '(' + loT + ')' : loT);
                if (p[7]) hiT = p[7] + DOT + (sides[0].length > 1 || cT[0] ? '(' + hiT + ')' : hiT);
                var allN = vars.every(function(v) { return v.n === vars[0].n; });
                var forT = !vars.length ? (terms.some(function(t) { return t.avg; }) ? 'averages over the items' : 'all items of a probability equal')
                  : (allN ? vars.map(function(v) { return v.l; }).join(', ') + ' = 1' + ELL + vars[0].n : vars.map(function(v) { return v.l + ' = 1' + ELL + v.n; }).join(', '));
                total += count; shownAny = true;
                sRows.push([hiT + ' ' + (p[8] ? (p[9] ? String.fromCharCode(8776) : '=') : String.fromCharCode(8805)) + ' ' + loT, forT + ' ' + String.fromCharCode(8212) + ' ' + count + (count === 1 ? ' statement' : ' statements')]);
              });
              if (realPairs) (window.fairyItemsConsts || []).forEach(function(cc) {
                if (cc[0] >= nProb) return;
                var sc = spec(cc[0]), sy = opSym(cc[1]), cnt1 = 1, lhs, forC;
                if (sc.type === 'average') { lhs = 'mean(' + nm(cc[0]) + ')'; forC = 'average over the items'; }
