              });
              stEl.textContent = '';
              stEl.hidden = !shownAny;
              if (shownAny) {
                var stH = document.createElement('div'); stH.style.cssText = 'font-weight:600; margin-bottom:4px;';
                var stTitle = (realPairs ? 'What this makes of your model' : 'What this would make of a model like p1 > p2');
                var stBody = document.createElement('div');
                // folded by default: the picture and the options say most of it already
                var setOpen = function(o) { window.fairyItemsStmtOpen = o; stBody.style.display = o ? '' : 'none'; var cp = document.getElementById('fairy_items_caption'); if (cp) cp.style.display = o ? '' : 'none'; stH.textContent = (o ? '\\u25BE ' : '\\u25B8 ') + stTitle; };
                stH.style.cursor = 'pointer'; stH.addEventListener('click', function() { setOpen(!window.fairyItemsStmtOpen); });
                stEl.appendChild(stH); stEl.appendChild(stBody);
                setOpen(!!window.fairyItemsStmtOpen);
                sRows.forEach(function(r) {
                  var d = document.createElement('div'); d.style.cssText = 'margin:3px 0;';
                  var a1 = document.createElement('div'); a1.style.cssText = 'font-family:ui-monospace,Menlo,Consolas,monospace; font-size:12px;'; a1.innerHTML = r[0].replace(/&/g, '&amp;').replace(/</g, '&lt;')
                    .replace(/\\b([A-Za-z]+)([0-9]+)\\b/g, '$1<sub>$2</sub>')
                    .replace(/(<\\/sub>|[A-Za-z])\\(([i-n])\\)/g, '$1<sup>($2)</sup>');
                  var b1 = document.createElement('div'); b1.style.cssText = 'font-size:11px; color:var(--fairy-text-muted);'; b1.textContent = r[1];
                  d.appendChild(a1); d.appendChild(b1); stBody.appendChild(d);
                });
                if (sRows.length > 1 || PPs.length > 5) {
                  var tt = document.createElement('div'); tt.style.cssText = 'margin-top:4px; font-size:11px; color:var(--fairy-text-muted);';
                  tt.textContent = 'Together ' + total + ' statements' + (PPs.length > 5 ? ' (and more, ' + ELL + ')' : '') + (total > 1000 ? '. That is a lot, the model may become slow.' : '.');
                  stBody.appendChild(tt);
                }
              }
            }
            if (cap) { cap.textContent = txt; cap.style.display = window.fairyItemsStmtOpen ? '' : 'none'; }
            // legend: only what is drawn in this picture
            var legEl = document.getElementById('fairy_items_legend');
            if (legEl) {
              var C9 = String.fromCharCode(9679), UP = String.fromCharCode(8593), MD = String.fromCharCode(183), NB = String.fromCharCode(160);
              var hasDash = !!svg.querySelector('path[stroke-dasharray]:not([data-minus])'), hasFade = Array.prototype.some.call(svg.querySelectorAll('line, path'), function(nd) { return nd.getAttribute('opacity') === '0.2'; }), hasTol = R.some(function(r) { return r.type === 'identical' && cnt[R.indexOf(r)] > 1; });
              var wLab = labs.some(function(l) { return l.indexOf(String.fromCharCode(215)) >= 0; });
              var cLab = !!(realPairs && (window.fairyItemsConsts || []).length);
              var SQ = String.fromCharCode(9633), AP = String.fromCharCode(8776);
              var entries = [[C9, 'one item', null], [String.fromCharCode(8594), 'points to the smaller one', BL]];
              if (vN.length) entries.push([SQ, 'sum (grey lines: its parts)', null]);
              if (svg.querySelector('[data-minus]')) entries.push([null, 'dashed grey line: this part is subtracted', null]);
              try { R.forEach(function(r, i) {
                if (!r.hubM) return;
                var other = {};
                (vM[vN.indexOf(r.name)] || []).forEach(function(pm) { var l2 = chipState.asg[pm]; if (l2 !== r.list) other[l2] = true; });
                Object.keys(other).forEach(function(l2) {
                  var n2 = chipState.sets[l2 - 1].n;
                  if (r.jm) entries.push([null, 'item k of ' + listTitle(r.list - 1) + ' is added to item k of ' + listTitle(l2 - 1) + ' (k = 1' + ELL + r.n + '); items without a partner are left out', null]);
                  else entries.push([null, 'each of the ' + chipState.sets[r.list - 1].n + ' items of ' + listTitle(r.list - 1) + ' is added to each of the ' + n2 + ' items of ' + listTitle(l2 - 1) + ': ' + (chipState.sets[r.list - 1].n * n2) + ' sums', null]);
                });
              }); } catch (eH) { entries.push([null, 'ERR ' + eH.message, null]); }
              if (R.some(function(r) { return r.hub; })) entries.push([null, 'one square for a sum of parts from different lists: every item of one part is added to every item of the others', null]);
              if (hasAvg) entries.push([String.fromCharCode(9675), 'average over the items', BL]);
              if (hasTol) entries.push(['=', 'items equal (' + AP + ': roughly)', null]);
              if (pdisp.some(function(q) { return q[5] && !q[6]; })) entries.push(['=', 'probabilities equal (line without arrow)', BL]);
              if (pdisp.some(function(q) { return q[5] && q[6]; })) entries.push([AP, 'probabilities roughly equal (line without arrow)', BL]);
              if (hasFade) entries.push([null, 'faded: the same for the other items', null]);
              if (hubDrawn) entries.push([C9, 'lines meet here: every item above is compared with every item below', BL]);
              if (wLab || cLab) entries.push([null, 'labels: ' + (wLab ? 'weight (2' + String.fromCharCode(215) + ' p2)' : '') + (wLab && cLab ? ', ' : '') + (cLab ? 'compared with a number (p5 < 0.1)' : ''), null]);
              if ((window.fairyItemsOthers || []).length) entries.push([null, 'not drawn, but valid for every item: ' + window.fairyItemsOthers.join('; '), null]);
              if (more) entries.push([String.fromCharCode(8230), 'more items', null]);
              legEl.textContent = '';
              entries.forEach(function(en, ei) {
                var sp = document.createElement('span'); sp.style.cssText = 'white-space:nowrap; margin-right:2px;';
                if (en[0]) { var sy = document.createElement('b'); sy.textContent = en[0] + NB; if (en[2]) sy.style.color = en[2]; sp.appendChild(sy); }
                sp.appendChild(document.createTextNode(en[1]));
                legEl.appendChild(sp);
                if (ei < entries.length - 1) legEl.appendChild(document.createTextNode(' '));
              });
            }
          }
          if (window.Shiny && Shiny.addCustomMessageHandler) Shiny.addCustomMessageHandler('fairy_items_pairs', function(msg) { window.fairyItemsPairs = (msg && msg.pairs) || null; window.fairyItemsConsts = (msg && msg.consts) || []; window.fairyItemsOthers = (msg && msg.others) || []; window.fairyItemsSums = (msg && msg.sums) || []; drawItemsDiagram(); });
          // Quick setup -> fills the per-probability rows (Group / Items / Model holds) under Advanced.
          var itemsApplying = false;
          function markItemsCustom(on) { }
          var lastGlobalType = 'joint';
          function twoKinds() { var r = document.querySelector('.fairy-items-two-choice:checked'); return !!r && r.value === 'two'; }
          function itemsSummary() {
            var el = document.getElementById('fairy_items_summary'), tEl = document.querySelector('.fairy-items-quick-type:checked'), nEl = document.getElementById('fairy_items_quick_n');
            if (!el || !tEl) return;
            var words = { joint: 'joint (matching items: item 1 with item 1, item 2 with item 2, ...)', substitutable: 'substitutable (every item with every item)', identical: 'identical (each probability is the same for all items)', average: 'average (only the average over the items has to satisfy it)' };
            var epsEl = document.getElementById('fairy_items_quick_eps'), epsV = parseFloat(epsEl && epsEl.value) || 0, parts;
            if (twoKinds() && chipState.sets.length > 1) {
              parts = chipState.sets.map(function(st, k) {
                var mem = chipState.asg.map(function(g, i) { return g === k + 1 ? chipRowName(i) : null; }).filter(Boolean).join(', ');
                return mem + ': ' + st.n + ' items' + (st.over ? ' (' + words[st.over] + ')' : '');
              }).join('; ');
            } else parts = (parseInt(nEl && nEl.value, 10) || 1) + ' items';
            el.textContent = 'Summary: your model holds ' + (tEl.value === 'perlist' ? 'differently for each list' : words[tEl.value]) + (tEl.value === 'identical' && epsV > 0 ? ' (items may differ by up to ' + epsV + ')' : '') + ', with ' + parts + '.';
          }
          function quickChrome() {
            document.querySelectorAll('.fairy-items-opt').forEach(function(t) {
              var r = t.querySelector('input'); t.classList.toggle('fairy-items-opt-sel', !!(r && r.checked));
            });
            drawItemsDiagram();
            var tEl = document.querySelector('.fairy-items-quick-type:checked'), wrap = document.getElementById('fairy_items_quick_eps_wrap');
            var anyIdent = tEl && (tEl.value === 'identical' || (tEl.value === 'perlist' && chipState.sets.some(function(x) { return x.over === 'identical'; })));
            if (wrap) wrap.style.display = anyIdent ? '' : 'none';
            var pw = document.getElementById('fairy_items_perlist_wrap');
            if (pw) pw.style.display = twoKinds() ? '' : 'none';
          }
          function quickDispatch() {
            var tv = document.querySelector('.fairy-items-quick-type:checked');
            tv = tv ? tv.value : 'joint';
            // remember the global choice also while there is only one list: the per-list mode starts from it
            if (tv !== 'perlist') lastGlobalType = tv;
            if (twoKinds()) {
              chipState.sets.forEach(function(st) { if (tv === 'perlist') { if (!st.over) st.over = lastGlobalType; } else st.over = ''; });
              chipsRender(); quickChrome(); chipsApply();
            } else {
              if (tv === 'perlist') { var jr = document.querySelector('.fairy-items-quick-type[value=joint]'); if (jr) jr.checked = true; }
              quickApply();
            }
          }
          function quickApply() {
            itemsApplying = true;
            document.querySelectorAll('.fairy-items-opt').forEach(function(t) {
              var r = t.querySelector('input'); t.classList.toggle('fairy-items-opt-sel', !!(r && r.checked));
            });
            drawItemsDiagram();
            var nEl = document.getElementById('fairy_items_quick_n');
            var tEl = document.querySelector('.fairy-items-quick-type:checked');
            if (!nEl || !tEl) return;
            var n = Math.max(1, parseInt(nEl.value, 10) || 1), type = tEl.value;
            var linked = type === 'joint' || type === 'identical';
            var epsEl = document.getElementById('fairy_items_quick_eps');
            var epsV = Math.min(1, Math.max(0, parseFloat(epsEl && epsEl.value) || 0));
            var wrap = document.getElementById('fairy_items_quick_eps_wrap');
            if (wrap) wrap.style.display = type === 'identical' ? '' : 'none';
            // pass 1: clear all groups and set the count everywhere (otherwise the old groups pull the counts back)
            document.querySelectorAll('.fairy-items-row').forEach(function(row) {
              var gIn = row.querySelector('input[id^=items_multi_group_]');
              if (gIn) { gIn.value = ''; $(gIn).trigger('input'); }
            });
            document.querySelectorAll('.fairy-items-row').forEach(function(row) {
              var nIn = row.querySelector('input[id^=items_multi_n_]');
              if (nIn) { nIn.value = n; $(nIn).trigger('change'); }
            });
            // pass 2: model type, group and tolerance
            document.querySelectorAll('.fairy-items-row').forEach(function(row) {
              var gIn = row.querySelector('input[id^=items_multi_group_]');
              var sel = row.querySelector('select[id^=items_multi_type_]');
              if (n > 1) {
                if (sel) { if (sel.selectize) sel.selectize.setValue(type); else { sel.value = type; $(sel).trigger('change'); } }
                if (gIn && linked) { gIn.value = 'set 1'; $(gIn).trigger('input'); }
              }
              var eIn = row.querySelector('input[id^=items_multi_eps_]');
              if (eIn) { eIn.value = type === 'identical' ? epsV : 0; $(eIn).trigger('change'); }
            });
            syncGroupItems(null);
            updateAllItemsRows();
            itemsApplying = false;
            chipsFromRows(); chipsRender(); itemsSummary();
          }
          $(document).on('input change', '.fairy-items-quick-type, #fairy_items_quick_n, #fairy_items_quick_eps', quickDispatch);
          $(document).on('input change', '.fairy-items-row input', function(e) {
            if (!itemsApplying && e.originalEvent) markItemsCustom(true);
          });
          $(document).on('input change', '.fairy-items-row input', function() { setTimeout(drawRowsDiagram, 30); });
          $(document).on('change', '.fairy-items-row select', function() { if (!itemsApplying) markItemsCustom(true); setTimeout(drawRowsDiagram, 30); });
          $(document).on('click', '#fairy_items_reset', function(e) { e.preventDefault(); quickApply(); });
          setTimeout(function() {
            var q = document.querySelector('.fairy-items-quick');
            if (q && q.getAttribute('data-custom') === '1') markItemsCustom(true);
          }, 300);
          // a new dialog starts from the defaults shown above (edit mode keeps the saved values)
          setTimeout(function() {
            var q = document.querySelector('.fairy-items-quick');
            if (q && q.getAttribute('data-edit') !== '1') quickApply(); else { drawItemsDiagram(); chipsFromRows(); chipsRender(); var two = chipState.sets.length > 1; if (two) { var rr = document.querySelector('.fairy-items-two-choice[value=two]'); if (rr) rr.checked = true; var pn = document.getElementById('fairy_items_two_panel'); if (pn) pn.style.display = ''; var cs2 = document.getElementById('fairy_items_count_same'); if (cs2) cs2.style.display = 'none'; } if (chipState.sets.some(function(x) { return x.over; })) { var pr = document.querySelector('.fairy-items-quick-type[value=perlist]'); if (pr) pr.checked = true; } chipsRender(); quickChrome(); itemsSummary(); }
          }, 200);
          // Selectize finishes initializing asynchronously after this
