    }, character(1))

    showModal(modalDialog(
      title = NULL,
      size = "s",
      class = "fairy-combo-modal",
      tags$div(class = "fairy-combo-header", tags$strong("Add mixture model")),
      tags$p(class = "fairy-combo-help", "Pick two or more models for a mixture."),
      if (any(vapply(seq_len(n), is_h_only_row, logical(1))))
        tags$p(class = "fairy-combo-help", style = "font-style:italic;",
          "Models unpacked across items can only be combined with other unpacked models that have the same number of items for every probability. The app only checks that; you decide that item k of a probability means the same thing in both models."),
      checkboxGroupInput("mixture_model_picker", NULL,
        choices = setNames(seq_len(n), model_names)),
      uiOutput("combo_warn_mix"),
      footer = tagList(
        modalButton("Cancel"),
        actionBttn("submit_mixture_model", "Add", style = "material-flat", color = "primary", size = "sm")
      ),
      easyClose = TRUE
    ))
  })

  observeEvent(input$submit_mixture_model, {
    selected_idx <- suppressWarnings(as.integer(input$mixture_model_picker))
    selected_idx <- selected_idx[!is.na(selected_idx)]
    if (length(selected_idx) < 2) {
      return()
    }
    its <- vapply(selected_idx, is_h_only_row, logical(1))
    if (any(its) && !all(its)) {
      showModal(modalDialog(title = "Cannot mix", items_combine_msg, easyClose = TRUE))
      return()
    }

    n <- isolate(counter_input$n)
    selected_names <- vapply(selected_idx, function(i) {
      isolate(input[[paste0("textin_relations_name", i)]]) %||% paste0("m", i)
    }, character(1))

    combined_name <- paste0("mix_", paste(selected_names, collapse = "_"))
    if (all(its)) {
      mix_lab <- combo_label_h(selected_names, "mix")
      if (!is.na(mix_lab)) combined_name <- mix_lab
    }
    new_n <- n + 1

    pending_relations_restore(c(rep(NA_character_, n), ""))
    pending_relations_name_restore(c(rep(NA_character_, n), combined_name))
    mixture_model_flags$value[[as.character(new_n)]] <- paste0("Mixture of ", paste(selected_names, collapse = ", "))
    derived_model_sources$value[[as.character(new_n)]] <- if (all(its)) list(type = "mixture", source_idx = selected_idx, by_h = TRUE) else list(type = "mixture", source_idx = selected_idx)
    counter_input$n <- new_n

    removeModal()
  })

  # Keeps the "Models to plot" picker (Plot Polytope(s) tab) in step with
  # the models the plot can actually draw. A model seen for the FIRST time
  # is selected automatically (so the plot is not empty until you pick
  # something, and a freshly added model shows up right away); a model you
  # deselected stays deselected across recomputations, and models that
  # no longer exist drop out of the selection.
  plot_models_known <- reactiveVal(character(0))
  observeEvent(names_available_models_reactive$value, {
    nm <- names_available_models_reactive$value
    nm <- unique(nm[!is.na(nm)])
    known <- isolate(plot_models_known())
    selected <- union(intersect(isolate(input$name_model_plot), nm), setdiff(nm, known))
    plot_models_known(union(known, nm))
    updatePickerInput(session, "name_model_plot", choices = nm, selected = selected)
  }, ignoreNULL = FALSE)

  observeEvent(input$submit_inter, {
    removeModal()
  })

  ###




  #### Checkbox Events ####

  textboxes_names <- reactive({
    n <- counter$n

    if (n > 0) {
      isolate({
        # If an upload restore is pending, use its names directly for this
        # render instead of the "p_{i}" placeholder — the box is then born
        # with the correct value instead of relying on a later
        # updateTextAreaInput() to overwrite the placeholder, which can lose
        # a race against the debounced auto-detect observer above and leave
        # the last box(es) stuck on the default. See restoring_upload.
        pending <- pending_name_restore()
        lapply(seq_len(n), function(i) {
          restored <- if (!is.null(pending) && i <= length(pending) &&
                          !is.na(pending[i]) && nchar(pending[i]) > 0) pending[i] else NULL
          textAreaInput(
            inputId = paste0("textin_name_", i),
            label = paste0("Name of p", i),
