  })

  ####

  # Joins a model's unique spec with the shared spec for the "Model
  # Specification" preview — only inserting "; " between them when BOTH
  # sides actually have content, so an empty unique or shared spec doesn't
  # leave a bare/dangling ";" in the preview.
  # NOTE: this box's real value is NOT cosmetic-only — the Go/Parsimony
  # pipeline reads input$textin_relations_complete_N directly as the source
  # of the parsed constraints (see make_parsimony_snapshot / the Go
  # handler's mytable_input construction), so it must stay literal ">"/"<".
  # An earlier version of this baked ≥/≤ into it for display,
  # which silently broke computation — do not reintroduce that here.
  join_specs <- function(a, b) {
    a <- paste(a, collapse = "")
    b <- paste(b, collapse = "")
    if (nzchar(trimws(a)) && nzchar(trimws(b))) paste(a, b, sep = "; ") else paste0(a, b)
  }

  # One observer in total (not one per model per model-count change, which
  # piled up duplicates and made every added model slower than the last).
  # Re-runs when the model count, the shared spec, or any model's own spec
  # changes, and refreshes every hidden combined textarea.
  observe({
    n <- counter_input$n
    shared <- input$add_for_all_models
    specs <- lapply(seq_len(n), function(i) input[[paste0("textin_relations_", i)]])
    for (i in seq_len(n)) {
      updateTextAreaInput(session, paste0("textin_relations_complete_", i),
        value = expand_equality_chains(join_specs(specs[[i]], shared)))
    }
  })

  # Mute Download until something's typed — genuinely reactive (Shiny's
  # own dependency graph, not a client-side DOM poll guessing at when to
  # recheck): re-runs whenever counter_input$n changes (a model added/
  # removed) or ANY of the current Unique/Shared Model Specification
  # boxes' text changes, and toggles fairy-btn-muted (see its own CSS)
  # via shinyjs accordingly. isolate() on the per-model reads is safe —
  # this observe() already has its own real reactive dependency on each
  # one via the direct (non-isolated) input$textin_relations_<i> read
  # inside the loop below.
  observe({
    n <- counter_input$n
    filled <- nzchar(trimws(input$add_for_all_models %||% ""))
    if (!filled && n > 0) {
      for (i in seq_len(n)) {
        if (nzchar(trimws(input[[paste0("textin_relations_", i)]] %||% ""))) {
          filled <- TRUE
          break
        }
      }
    }
    shinyjs::toggleClass(id = "download", class = "fairy-btn-muted", condition = !filled)
  })

  ####

  # NOTE: this box's DISPLAY substitution (plain >/< shown as the words
  # >=/<=  is done client-side (see the small script near the top of the
  # UI matching id^="model_spec_display_") rather than here in R. An
  # R-side version using unicode escapes / enc2utf8() was tried first and
  # reliably rendered as the literal text "<U+2265>" instead of the actual
  # character — that is R's own fallback notation for a character it
  # cannot represent in the server's locale (observed with an ASCII-only
  # LC_CTYPE), which no amount of encoding-marking on the R side fixes.
  # Expands the "{p1,p2} < {p3,3*p4}" shortcut into the real clauses it
  # stands for ("p1<p3; p1<3*p4; p2<p3; p2<3*p4") for DISPLAY only, in
  # the read-only Model Specification preview — so a user can see what
  # the shorthand actually means without having to mentally expand it
  # themselves. Mirrors expand_scalar's own logic (the version the Go
  # pipeline actually computes from, further down in this file) rather
  # than calling it directly — that one lives deep inside the parsing
  # pipeline and isn't meant to be called standalone from here.
  expand_batch_shortcuts_for_display <- function(spec) {
    if (is.null(spec) || !nzchar(spec)) return(spec %||% "")
    clauses <- unlist(strsplit(spec, ";"))
    expanded <- vapply(clauses, function(clause) {
      if (!grepl("{", clause, fixed = TRUE)) return(clause)
      batches <- strsplit(gsub("[{} ]", "", clause), "[><=]")[[1]]
      if (length(batches) != 2) return(clause)
      batch1 <- unlist(strsplit(batches[1], ","))
      batch2 <- unlist(strsplit(batches[2], ","))
      separator <- gsub("[p{}]", "", gsub("[^><=]", "", clause))
      comparisons <- character()
      for (a in batch1) for (b in batch2) comparisons <- c(comparisons, paste0(a, separator, b))
      paste(comparisons, collapse = "; ")
    }, character(1), USE.NAMES = FALSE)
    paste(expanded, collapse = "; ")
  }

  # This function used to only strip the <U+2265>-style fallback
  # notation; now also unpacks {..}/{..} shortcuts for display (see
  # expand_batch_shortcuts_for_display's own comment) before that.
  ineq_words <- function(s) expand_batch_shortcuts_for_display(s %||% "")

  # Comma-separated "1"/"0" per "=" clause found (left-to-right) in `spec`,
  # "1" only for a clause whose corresponding entry in `tol_vec` is a real,
  # actually-set nonzero tolerance — never for one that's merely present
  # but still exact. Shared by both the read-only Model Specification
  # display and the editable Unique Model Specification box's own overlay
  # (see their respective eq_approx_flags_*/substForBox() client-side
  # code) so "which = is approximate" is computed exactly once, the same
  # way, in both places.
  equality_flags_str <- function(spec, tol_vec, neighbours = TRUE) {
    raw_clauses <- trimws(unlist(strsplit(spec %||% "", ";")))
    raw_clauses <- raw_clauses[nzchar(raw_clauses)]
    # One flag per literal "=" character of the text (the client-side substitution walks exactly those, left to
    # right): "1" when the equality between the two terms next to that "=" is approximate (for {p1,p2}=p3: when any of its
    # equalities is). Equalities between terms that are not next to each other are only visible in the Model Specification. The "=" inside ">=" / "<=" is no equality: "0".
    # k counts the equality rows in the order the tolerances (equality_tolerances_reactive) are keyed by.
    is_set <- function(k) !is.null(tol_vec) && k <= length(tol_vec) && !is.na(tol_vec[k]) && tol_vec[k] != 0
    if (!neighbours) {
      # the read-only Model Specification lists every equality as its own row (chains and {..} sets written out): one flag per row
      eq_rows_all <- spec_eq_rows(spec)
      if (length(eq_rows_all) == 0) return("")
      return(paste(vapply(seq_along(eq_rows_all), function(k) if (is_set(k)) "1" else "0", character(1)), collapse = ","))
    }
    flags <- character(0)
    uniq_keys <- vapply(spec_eq_rows(spec), eq_row_key, character(1), USE.NAMES = FALSE)   # the list the tolerances belong to
    set_for <- function(a1, b1) { idx <- match(eq_row_key(paste0(a1, "=", b1)), uniq_keys); !is.na(idx) && is_set(idx) }
    for (cl in raw_clauses) {
      cln <- norm_ops(cl)
      toks <- regmatches(cl, gregexpr(">=|<=|[=<>]", cl))[[1]]
      terms <- trimws(strsplit(cln, "[=<>]")[[1]]); ops <- regmatches(cln, gregexpr("[=<>]", cln))[[1]]
      ok <- length(toks) == length(ops) && length(terms) == length(ops) + 1
      if (!ok) next
      for (i in seq_along(ops)) {
        if (toks[i] %in% c(">=", "<=")) { flags <- c(flags, "0"); next }
        if (ops[i] != "=") next
        hit <- FALSE
        for (a1 in chain_side_items(terms[i])) for (b1 in chain_side_items(terms[i + 1])) if (set_for(a1, b1)) hit <- TRUE
        flags <- c(flags, if (hit) "1" else "0")
      }
    }
    if (length(flags) == 0) return("")
    paste(flags, collapse = ",")
  }

  # The slice of `src_idx`'s own equality-tolerance vector that actually
  # belongs to its Unique Model Specification alone (join_specs() puts
  # unique text first, so the tolerance vector's first N entries are
  # always the unique text's own N equality clauses — see
  # eq_approx_flags_unique_i's identical reasoning). Used to carry a
  # source model's approximate-equality settings over into a derived
  # intersection model, whose combined spec is built purely from source
  # models' unique specs (never their shared spec, which already applies
  # automatically anyway).
  unique_model_tol_slice <- function(src_idx) {
    spec <- input[[paste0("textin_relations_", src_idx)]] %||% ""
    raw_clauses <- trimws(unlist(strsplit(spec, ";")))
    raw_clauses <- raw_clauses[nzchar(raw_clauses)]
    # Chain-expand — see expand_clause_to_rows's own comment — so this
    # slices by the same per-row occurrence index equality_tolerances_
    # reactive is actually keyed by, not by raw semicolon-clause count.
    clauses <- spec_eq_rows(spec)
    if (length(clauses) == 0) {
      return(numeric(0))
    }
    tol_vec <- equality_tolerances_reactive$value[[as.character(src_idx)]]
    vapply(seq_along(clauses), function(k) {
      if (!is.null(tol_vec) && k <= length(tol_vec) && !is.na(tol_vec[k])) tol_vec[k] else 0
    }, numeric(1))
  }

  # Tolerances of an intersection of the models `src_idx`: one value per equality of the combined text (the same list the
  # tolerances belong to). An equality that appears in several sources must hold in all of them, so the strictest tolerance
  # wins: exact (0) beats approximate, a smaller tolerance beats a larger one.
  combine_source_tols <- function(src_idx) {
    keys <- character(0); tols <- numeric(0)
    for (sidx in src_idx) {
      rows <- spec_eq_rows(input[[paste0("textin_relations_", sidx)]] %||% "")
      if (length(rows) == 0) next
      tv <- unique_model_tol_slice(sidx)
      kk <- vapply(rows, eq_row_key, character(1), USE.NAMES = FALSE)
      for (m in seq_along(kk)) {
        pos <- match(kk[m], keys)
        if (is.na(pos)) { keys <- c(keys, kk[m]); tols <- c(tols, tv[m]) }
        else if (tv[m] == 0 || tols[pos] == 0) tols[pos] <- 0
        else tols[pos] <- min(tols[pos], tv[m])
      }
    }
    tols
  }

  # Moves the saved tolerances along with their equalities when the specification text changes: an equality that
  # is still there keeps its tolerance, one that was edited in place keeps the tolerance of its position,
  # a new one starts exact, a deleted one takes its tolerance with it.
  align_tolerances <- function(old_keys, old_tol, new_keys) {
    new_tol <- rep(NA_real_, length(new_keys))
    used <- rep(FALSE, length(old_keys))
    for (i in seq_along(new_keys)) {
      j <- which(!used & old_keys == new_keys[i])[1]
      if (!is.na(j)) { used[j] <- TRUE; new_tol[i] <- if (j <= length(old_tol)) old_tol[j] else 0 }
    }
    left_new <- which(is.na(new_tol))
    left_old <- which(!used)
    for (m in seq_len(min(length(left_new), length(left_old)))) {
      j <- left_old[m]
      new_tol[left_new[m]] <- if (j <= length(old_tol)) old_tol[j] else 0
    }
    new_tol[is.na(new_tol)] <- 0
    new_tol
  }
  observe({
    # while a saved file or link is being loaded the text boxes are filled in step by step: do not move tolerances then
    if (isTRUE(restoring_upload())) { isolate(equality_clause_keys$value <- list()); return() }
    if (isTRUE(tol_align_hold())) return()
    n <- counter_input$n
    for (i in seq_len(n)) {
      txt <- input[[paste0("textin_relations_complete_", i)]]
      if (is.null(txt)) next
      key <- as.character(i)
      if (!is.null(isolate(derived_model_sources$value[[key]])) || !is.null(isolate(item_model_spec_idx$value[[key]]))) next
      cl <- gsub("\\s+", "", spec_eq_rows(txt))
      old_keys <- isolate(equality_clause_keys$value[[key]])
      old_tol <- isolate(equality_tolerances_reactive$value[[key]])
      if (is.null(old_keys) || identical(old_keys, cl)) {
        if (!identical(old_keys, cl)) equality_clause_keys$value[[key]] <- cl
        next
      }
      if (!is.null(old_tol) && length(old_tol) > 0) {
        equality_tolerances_reactive$value[[key]] <- align_tolerances(old_keys, old_tol, cl)
      }
      equality_clause_keys$value[[key]] <- cl
    }
  })

  # marking shared vertices / showing only the unique ones needs at least two models
  # ... and two models whose vertices live in the same space (same number of probabilities): otherwise there is nothing to compare
  observe({
    vs <- shiny::reactiveValuesToList(v_reactive)
    # the stored V-representation is the result of scdd(): a list whose $output is the matrix of the vertices
    vmat <- function(x) if (is.list(x) && is.matrix(x$output)) x$output else if (is.matrix(x)) x else NULL
    vs <- lapply(vs, vmat)
    vs <- vs[vapply(vs, function(x) !is.null(x) && nrow(x) > 0, logical(1))]
    widths <- vapply(vs, ncol, integer(1))
    several <- isTRUE(counter_input$n > 1) && length(widths) > 1 && any(table(widths) > 1)
    shinyjs::toggle("v_compare_cap", condition = several)
    shinyjs::toggle("v_shared_wrap", condition = several)
    shinyjs::toggle("v_unique_wrap", condition = several)
  })

  # header of a specification box: title, a small info icon with a tooltip, and one line saying what it holds
  spec_label_info <- function(title, tip, sub) {
    tagList(
      tags$span(title,
        tags$span(class = "fairy-info-icon fairy-tooltip fairy-tooltip-down", `data-tooltip` = tip,
          style = "margin-left:6px; cursor:help; color:var(--fairy-text-muted, #667085);", icon("circle-info"))),
      if (!is.null(sub)) tags$small(style = "display:block; font-weight:400; color:var(--fairy-text-muted, #667085); margin:1px 0 3px;", sub))
  }

  textboxes_relations <- reactive({
    n <- counter_input$n

    if (n > 0) {
      isolate({
        pending <- pending_relations_restore()
        lapply(seq_len(n), function(i) {
          restored <- if (!is.null(pending) && i <= length(pending) && !is.na(pending[i])) pending[i] else NULL
          mix_label <- mixture_model_flags$value[[as.character(i)]]
          derived_info <- derived_model_sources$value[[as.character(i)]]
          is_derived <- !is.null(derived_info)
          box <- if (!is.null(mix_label)) {
            # A mixture isn't expressible as a plain constraint list (see
            # mixture_model_flags's own comment) — disabled and grayed
            # out with the description as its placeholder, rather than an
            # editable box, since there's nothing meaningful to type here.
            shinyjs::disabled(
              textAreaInput(
                inputId = paste0("textin_relations_", i),
                label = if (i == 1) spec_label_info("Unique Model Specification", "Constraints for this model only, e.g. p1 > p2 > p3. Together with the Shared Model Specification they make up the complete model.", NULL) else tags$span(class = "sr-only", paste0("Unique Model Specification (row ", i, ")")),
                value = "",
                width = "100%",
                height = "80px",
                placeholder = mix_label,
                resize = "none"
              )
            )
          } else if (is_derived) {
            # Intersection model: disabled too, but shows the REAL (live,
            # not a one-time snapshot — see wired_derived_ids) combined
            # spec rather than a placeholder, since this one genuinely
            # does have constraint text worth showing.
            shinyjs::disabled(
              textAreaInput(
                inputId = paste0("textin_relations_", i),
                label = if (i == 1) spec_label_info("Unique Model Specification", "Constraints for this model only, e.g. p1 > p2 > p3. Together with the Shared Model Specification they make up the complete model.", NULL) else tags$span(class = "sr-only", paste0("Unique Model Specification (row ", i, ")")),
                value = if (!is.null(restored)) restored else AllInputs()[[paste0("textin_relations_", i)]],
                width = "100%",
                height = "80px",
                resize = "none"
              )
            )
          } else {
            textAreaInput(
              inputId = paste0("textin_relations_", i),
              # Header shown once, above the first model only — repeating
              # it on every row read as clutter once there were more than
              # a couple of models.
              label = if (i == 1) spec_label_info("Unique Model Specification", "Constraints for this model only, e.g. p1 > p2 > p3. Together with the Shared Model Specification they make up the complete model.", NULL) else tags$span(class = "sr-only", paste0("Unique Model Specification (row ", i, ")")),
              value = if (!is.null(restored)) restored else AllInputs()[[paste0("textin_relations_", i)]],
              width = "100%",
              height = "80px",
              placeholder = "p1 > p2; ...",
              resize = "none"
            )
          }
          tags$div(
            class = paste("fairy-model-row", if (i %% 2 == 0) "fairy-row-even" else "fairy-row-odd"),
            `data-row-idx` = i,
            style = "position: relative;",
            if (is.null(mix_label) && !is_derived) tags$button(
              class = "fairy-expand-btn", type = "button",
              title = "Expand",
              `data-target` = paste0("textin_relations_", i),
              style = paste0("position:absolute; top:", if (i == 1) "26px" else "4px", "; right:4px; z-index:5; border:none; background:transparent; cursor:pointer; font-size:14px; color:#888;"),
              HTML("&#10530;")
            ),
            box,
            # an intersection shows the combined constraints of its models: say so, so they are not read as an already computed result
            if (is_derived && is.null(mix_label) && identical(derived_info$type, "intersection")) tags$div(
              class = "fairy-derived-note",
              paste0("Intersection of ", paste(vapply(derived_info$source_idx, function(j)
                isolate(input[[paste0("textin_relations_name", j)]]) %||% paste0("m", j), character(1)), collapse = ", "),
                ": the constraints of these models combined")
            ),
            tags$div(
              style = "display:none;",
              textOutput(paste0("eq_approx_flags_unique_", i))
            )
          )
        })
      })
    }
  })

  textboxes_relations_complete <- reactive({
    n <- counter_input$n

    if (n > 0) {
      isolate({
        lapply(seq_len(n), function(i) {
          # The client-side overlay technique used for the editable boxes
          # (see the JS near the top of the UI) turned out unreliable for
          # this specific box across repeated attempts — its content only
          # ever changes via server-pushed updateTextAreaInput() calls, and
          # exactly why the overlay didn't reliably pick those up was never
          # pinned down. Sidestepping that class of bug entirely here: the
          # real textarea (id textin_relations_complete_i, still literal
          # >/<) stays exactly as before and keeps feeding the Go/
          # Parsimony pipeline unchanged, just visually hidden — a plain,
          # genuinely reactive text output sits in its place showing the
          # words-substituted version, recomputed natively by Shiny on
          # every keystroke, no client-side JS or event-timing involved.
          local({
            ii <- i
            output_id <- paste0("model_spec_display_", ii)
            output[[output_id]] <- renderText({
              # A mixture (or an intersection involving one) has no
              # constraint text to show at all — same placeholder as its
              # Unique Model Specification box (see mixture_model_flags's
              # own comment and textboxes_relations()) instead of
              # whatever join_specs()/ineq_words() would otherwise compute
              # from its (empty, or misleadingly partial) spec.
              mix_label <- mixture_model_flags$value[[as.character(ii)]]
              if (!is.null(mix_label)) {
                return(mix_label)
              }
              # Also depend on this model's approx tolerances (even though
              # they don't change the STRING itself — that only ever has
              # literal >/</=, never ≈, per ineq_words()'s own comment) so
              # Shiny re-sends this text whenever a tolerance is
              # toggled/changed. That re-send is what lets the client-side
              # poll (near the top of the UI, matching
              # id^="model_spec_display_") tell the difference between "="
              # that should now render as "≈" and one that shouldn't —
              # without it, toggling approximate on/off wouldn't change
              # anything already sitting in the DOM since the underlying
              # spec text itself didn't change.
              equality_tolerances_reactive$value[[as.character(ii)]]
              ineq_words(join_specs(input[[paste0("textin_relations_", ii)]], input$add_for_all_models))
            })

            # Comma-separated 1/0 flags, one per "=" clause (in the same
            # left-to-right order the popup/computation use), read by that
            # same client-side poll to know which "=" occurrences in the
            # text above should display as "≈" (only ever "1" for a
            # clause actually switched to approximate — see
            # equality_flags_str()'s own comment). Hidden — purely a data
            # channel to the client, never shown itself.
            flags_id <- paste0("eq_approx_flags_", ii)
            output[[flags_id]] <- renderText({
              spec <- join_specs(input[[paste0("textin_relations_", ii)]], input$add_for_all_models)
              equality_flags_str(spec, equality_tolerances_reactive$value[[as.character(ii)]], neighbours = FALSE)
            })
            # This output lives in a display:none wrapper (it's a pure
            # data channel to the client-side poll, never shown itself) —
            # Shiny suspends computing outputs it thinks aren't visible by
            # default, which would otherwise mean it never actually runs.
            outputOptions(output, flags_id, suspendWhenHidden = FALSE)

            # Same idea, but scoped to JUST this model's Unique Model
            # Specification box (not the Unique+Shared combined text) —
            # read by the editable-box overlay script (see wireBox()'s
            # substForBox()) so that box shows "≈" too, not only the
            # read-only Model Specification preview above. Since
            # join_specs() puts the unique text first ("unique; shared"),
            # the k-th "=" clause in the unique text alone is always the
            # SAME k-th entry of this model's tolerance vector — no
            # separate storage needed, just a shorter clause list.
            flags_unique_id <- paste0("eq_approx_flags_unique_", ii)
            output[[flags_unique_id]] <- renderText({
              equality_flags_str(input[[paste0("textin_relations_", ii)]], equality_tolerances_reactive$value[[as.character(ii)]])
            })
            outputOptions(output, flags_unique_id, suspendWhenHidden = FALSE)

            # Comma-separated 1/0 flags, one per actual H-rep ROW in the
            # Model Specification box (see model_redundant_clause_flags's
            # own comment on why this is per-row, not per typed clause —
            # a shortcut clause's rows don't all have to be redundant
            # together) — "1" means that row turned out to be logically
            # redundant given the model's H-representation. Empty string
            # when nothing should be highlighted (no H-rep yet, or the
            # row-to-clause mapping couldn't be trusted for this model).
            # Read by the same client-side poll that already recolors this
            # text for ≥/≤/≈.
            redundant_flags_id <- paste0("redundant_flags_", ii)
            output[[redundant_flags_id]] <- renderText({
              spec <- join_specs(input[[paste0("textin_relations_", ii)]], input$add_for_all_models)
              model_name <- input[[paste0("textin_relations_name", ii)]] %||% paste0("m", ii)
              flags <- model_redundant_clause_flags(model_name, spec)
              if (is.null(flags)) "" else paste(ifelse(flags, "1", "0"), collapse = ",")
            })
            outputOptions(output, redundant_flags_id, suspendWhenHidden = FALSE)

            # Tells the client-side substitution poll (near the top of the
            # UI) to leave this row's Model Specification pre completely
            # alone — for a mixture (or mixture-involving intersection),
            # model_spec_display_i's own text IS the real content (the
            # placeholder description), not raw constraint text to
            # re-derive ≥/≤/≈ from; without this the poll would overwrite
            # it with whatever's in the (empty) hidden textarea instead.
            placeholder_flag_id <- paste0("model_spec_is_placeholder_", ii)
            output[[placeholder_flag_id]] <- renderText({
              if (!is.null(mixture_model_flags$value[[as.character(ii)]])) "1" else "0"
            })
            outputOptions(output, placeholder_flag_id, suspendWhenHidden = FALSE)
          })
          tags$div(
            class = paste("fairy-model-row", if (i %% 2 == 0) "fairy-row-even" else "fairy-row-odd"),
            `data-row-idx` = i,
            # The hidden textarea is pulled fully out of the visual flow
            # via absolute positioning + zero size, so it cannot affect
            # the layout of the label/box below it regardless of anything
            # else on this page.
            tags$textarea(
              id = paste0("textin_relations_complete_", i),
              class = "form-control",
              style = "position:absolute; width:0; height:0; padding:0; margin:0; border:0; overflow:hidden; opacity:0; pointer-events:none;",
              `aria-hidden` = "true",
              tabindex = "-1",
              readonly = "readonly",
              AllInputs()[[paste0("textin_relations_", i)]] %||% ""
            ),
            # Plain flow — label then box, nothing exotic. Now that the
            # row itself is a plain table (see above), there's no more
            # need for the label/box to be independently pixel-pinned;
            # ordinary block stacking is enough.
            # (The approximate-tolerance shortcut for this model's
            # equalities lives next to Model Name now, alongside the
            # delete button — see textboxes_relations_name().)
            # Header shown once, above the first model only.
            if (i == 1) tags$label(spec_label_info("Model Specification", "The complete model that is computed: your own constraints plus the shared ones. You cannot edit it here.", NULL), class = "control-label"),
            # Outer div is a hard overflow:hidden boundary at the fixed
            # box size — see .fairy-model-spec-outer's own comment for why
            # (a Safari-specific scrollbar-space quirk).
            tags$div(
              class = "fairy-model-spec-outer",
              verbatimTextOutput(paste0("model_spec_display_", i))
            ),
            tags$div(
              style = "display:none;",
              textOutput(paste0("eq_approx_flags_", i))
            ),
            tags$div(
              style = "display:none;",
              textOutput(paste0("redundant_flags_", i))
            ),
            tags$div(
              style = "display:none;",
              textOutput(paste0("model_spec_is_placeholder_", i))
            )
          )
        })
      })
    }
  })



  textboxes_relations_name <- reactive({
    n <- counter_input$n

    if (n > 0) {
      isolate({
        pending <- pending_relations_name_restore()
        lapply(seq_len(n), function(i) {
          restored <- if (!is.null(pending) && i <= length(pending) &&
                          !is.na(pending[i]) && nchar(pending[i]) > 0) pending[i] else NULL

          # This model's V-representation on/off button is its own small
          # reactive output (not just plain HTML like the other two icons)
          # because its color needs to track mytable_v_reactive$value —
          # the same shared state the "V-representations" dialog reads
          # and writes — so ticking it in either place stays in sync.
          local({
            ii <- i
            output[[paste0("vrep_toggle_ui_", ii)]] <- renderUI({
              # A mixture's V-representation is always built as part of
              # constructing the mixture itself (see the helpText in the
              # "Mixture model" dialog) — shown permanently "on" but
              # disabled, since there's nothing to actually toggle. A
              # "Multiple items" row's disabled Unique Model Specification
              # box reuses this SAME mixture_model_flags mechanism (see
              # submit_items_multi's own comment) purely for the visual
              # "disabled, auto-generated text" styling — its
              # V-representation is a real, independently computed thing
              # a user may genuinely want to include/exclude, unlike a
              # mixture's, so item_model_spec_idx excludes it from this
              # forced-on-and-disabled branch.
              if (!is.null(mixture_model_flags$value[[as.character(ii)]]) &&
                  is.null(item_model_spec_idx$value[[as.character(ii)]])) {
                return(shinyjs::disabled(
                  actionButton(
                    paste0("vrep_toggle_btn_", ii), label = vrep_icon(),
                    class = "btn action-button fairy-vrep-toggle-btn active fairy-tooltip",
                    `data-tooltip` = "Always included for mixtures",
                    style = "padding:2px 7px; font-size:11px; border-radius:6px; min-width:0;"
                  )
                ))
              }
              model_name <- input[[paste0("textin_relations_name", ii)]] %||% paste0("m", ii)
              # while the name is empty for a moment (being retyped) the button keeps showing the choice of the old name
              if (!nzchar(trimws(model_name))) {
                old_nm <- rename_state$names[ii]
                model_name <- if (length(old_nm) == 1 && !is.na(old_nm) && nzchar(old_nm)) old_nm else model_name
              }
              vtab <- mytable_v_reactive$value
              active <- !is.null(vtab) && nrow(vtab) > 0 &&
                model_name %in% vtab[[1]][vtab[[2]] == TRUE]
              actionButton(
                paste0("vrep_toggle_btn_", ii), label = vrep_icon(),
                class = paste("btn action-button fairy-vrep-toggle-btn fairy-tooltip", if (active) "active" else ""),
                `data-tooltip` = if (active) "Included in V-representation — click to remove" else "Include this model in V-representation computation",
                style = "padding:2px 7px; font-size:11px; border-radius:6px; min-width:0;"
              )
            })
          })

          tags$div(
            class = paste("fairy-model-row", if (i %% 2 == 0) "fairy-row-even" else "fairy-row-odd"),
            `data-row-idx` = i,
            # flex-start, not stretch: a repeated-items row's icon column
            # can hold up to 5 buttons (delete/cube/edit/preview/copy)
            # stacked vertically — taller than a plain row's 2-3 and
            # taller than the Model Name box's own fixed height. Stretch
            # would force THIS row's Model Name/spec boxes to grow to
            # match its own (taller) icon column, leaving every
            # repeated-items row visibly bigger than a plain model row
            # right next to it — exactly the "different sized boxes"
            # mismatch reported. flex-start instead lets each child keep
            # its own natural height: the boxes stay the same fixed size
            # on every row regardless of icon count, and a tall icon
            # column simply extends a little past the box's bottom edge
            # instead of dragging the box down with it.
            style = "display:flex; align-items:flex-start; gap:6px;",
            # All per-model icon buttons (delete, V-representation on/off,
            # and — once this model has an "=" — the approximate-tolerance
            # shortcut) live together to the left of the Model Name box
            # instead of scattered across the row, so there is one place
            # to look for "actions on this model".
            tags$div(
              class = "fairy-model-icon-col",
              # Plain single-column stack, same as always — a 2-column
              # grid was tried to keep a repeated-items row's up-to-5
              # icons from overflowing its box, but packing small round
              # icon buttons into a cramped 2-wide block looked worse
              # than the overflow it was fixing. Simpler fix: the boxes
              # themselves (Model Name / Unique Model Specification /
              # Model Specification — see their own height=, all kept in
              # sync) are now tall enough for a single column of 5 icons
              # to fit without overflowing OR needing to stretch per-row,
              # so every row gets the same uniform (taller) box height
              # regardless of its own icon count.
              style = paste0(
                "display:flex; flex-direction:column; align-items:center; gap:4px; padding-top:",
                if (i == 1) "24px" else "4px", ";",
                if (i == 1) " position:relative;" else ""
              ),
              # Master V-rep include/exclude-all toggle floats directly
              # above the first row's own per-model cube button (rather
              # than off in the "Model(s)" header toolbar) so it visually
              # reads as "applies to the whole column below it". Absolutely
              # positioned (not a normal flow sibling) specifically so it
              # adds no height to row 1's icon column — an earlier, in-flow
              # version made row 1 taller than every other row, which then
              # stretched row 1's Model Name / Unique Model Specification
              # boxes taller too (fairy-model-row uses align-items:stretch)
              # and broke the uniform row height every other row still had.
              # Only makes sense with 2+ models — "toggle everything" is a
              # no-op (identical to the single per-model button) with one.
              if (i == 1 && n > 1) tags$div(
                # left:0 (not centered) — this pair is wider than row 1's
                # own narrow icon column, so centering it over that column
                # pushed its left half out past the card's own left edge
                # (visibly hanging off the panel border). Left-aligned to
                # the icon column's own edge instead, growing rightward
                # into the empty space above Model Name, keeps the whole
                # pair inside the card no matter how many buttons it has.
                style = "position:absolute; top:-40px; left:0; display:flex; align-items:center; gap:6px;",
                tags$span(class = "fairy-tooltip",
                  `data-tooltip` = "Include or exclude every model's V-representation at once",
                  uiOutput("vrep_toggle_all_ui", inline = TRUE)),
                # Same n>1 gate as the V-rep master toggle right next to
                # it — "delete everything" is meaningless with only one
                # model already (and delete_model_at_idx's own n<=1
                # branch, which this ultimately still ends on, exists
                # specifically to reset that LAST row rather than leave
                # zero — not to be reachable directly from here). Same
                # first-appearance pulse as that button too — id-based
                # consume-once check, same as vrep_toggle_all_appear_id's
                # own comment (a one-shot boolean flag isn't enough:
                # this render pass can be re-read many times with no new
                # transition, e.g. every resume from tab-hidden
                # suspension, and needs to remember which id it already
                # showed a pulse for).
                (function() {
                  cur_id_del <- del_all_models_appear_id()
                  just_appeared <- cur_id_del > isolate(del_all_models_last_shown_id())
                  if (just_appeared) del_all_models_last_shown_id(cur_id_del)
                  btn <- tags$span(class = "fairy-tooltip",
                    `data-tooltip` = "Delete all models",
                    tags$button(
                      id = "delete_all_models_btn", class = "fairy-del-all-models-btn",
                      type = "button",
                      style = "cursor:pointer; font-size:14px; color:#c0392b;",
                      HTML("&#128465;")
                    )
                  )
                  if (just_appeared) tags$span(class = "fairy-intro-pulse-wrap", btn) else btn
                })(),
                # Fills the empty space that otherwise just sits there next
                # to these two buttons with a bit of context for what they
                # act on — its own renderUI (not computed inline here) so
                # it reactively updates on its own whenever model count or
                # V-representation inclusion changes, not just on a full
                # row re-render.
                uiOutput("model_count_summary_ui", inline = TRUE)
              ),
              tags$button(
                class = "fairy-del-model-btn fairy-tooltip", type = "button",
                `data-tooltip` = "Delete this model",
                `data-model-idx` = i,
                style = "border:none; background:transparent; cursor:pointer; font-size:14px; color:#c0392b; padding:0;",
                HTML("&#128465;")
              ),
              uiOutput(paste0("vrep_toggle_ui_", i), inline = TRUE),
              # Reopens the "Multiple items" modal pre-filled with this
              # row's current settings (see item_model_spec_idx and
              # open_items_modal) — only shown on rows actually created
              # that way, so a settings change can be made after the
              # fact instead of only at creation time.
              if (!is.null(item_model_spec_idx$value[[as.character(i)]])) actionButton(
                paste0("items_edit_btn_", i), label = NULL, icon = icon("sliders"),
                class = "btn action-button fairy-eq-tol-btn fairy-tooltip",
                `data-tooltip` = "Edit repeated-items settings",
                style = "padding:2px 7px; font-size:11px; border-radius:6px; min-width:0;"
              ),
              # Shows the generated model as plain p1, p2, ... constraint
              # text — "as if freshly typed" — plus a legend for what each
              # of those stands for, on click (see
              # observeEvent(input$items_preview_btn_i, ...)). Computed
              # fresh at click time rather than cached anywhere, so it's
              # never stale and always reflects whether the base model has
              # actually been computed yet.
              if (!is.null(item_model_spec_idx$value[[as.character(i)]])) actionButton(
                paste0("items_preview_btn_", i), label = NULL, icon = icon("keyboard"),
                class = "btn action-button fairy-eq-tol-btn fairy-tooltip",
                `data-tooltip` = "Show as typed input",
                style = "padding:2px 7px; font-size:11px; border-radius:6px; min-width:0;"
              ),
              # Duplicates this row into a new, independent model row —
              # its repeated-items spec too, if it has one — a starting
              # point for trying a variant without losing or overwriting
              # the original. Not shown for an intersection/mixture row,
              # same reasoning as the eq-tolerance button just below: its
              # content is derived from source models, not a standalone
              # spec there's anything meaningful to copy.
              if (is.null(derived_model_sources$value[[as.character(i)]])) actionButton(
                paste0("copy_model_btn_", i), label = NULL, icon = icon("copy"),
                class = "btn action-button fairy-eq-tol-btn fairy-tooltip",
                `data-tooltip` = "Copy this model to a new row",
                style = "padding:2px 7px; font-size:11px; border-radius:6px; min-width:0;"
              ),
              # Not shown for an intersection model — its approximate
              # tolerances are carried over from (and kept live-synced
              # with) its source models automatically, see
              # derived_model_sources; a manual override here would just
              # get overwritten the next time a source changes. Nor for an
              # items model: its equalities come from the unpacked items, and
              # their tolerance is set in the items dialog (the sliders button).
              if (is.null(derived_model_sources$value[[as.character(i)]]) && is.null(item_model_spec_idx$value[[as.character(i)]])) conditionalPanel(
                condition = paste0(
                  "input.textin_relations_complete_", i,
                  " && input.textin_relations_complete_", i, ".replace(/[<>]=/g, '').indexOf('=') > -1"
                ),
                actionButton(
                  paste0("eq_tol_btn_", i), label = NULL, icon = icon("equals"),
                  class = "btn action-button fairy-eq-tol-btn fairy-tooltip",
                  `data-tooltip` = "Set approximate tolerance for equalities in this model",
                  style = "padding:2px 7px; font-size:11px; border-radius:6px; min-width:0;"
                )
              )
            ),
            tags$div(
              style = "flex: 1; min-width: 0;",
              textAreaInput(
                inputId = paste0("textin_relations_name", i),
                label = if (i == 1) "Model Name" else tags$span(class = "sr-only", paste0("Model Name (row ", i, ")")),
                value = if (!is.null(restored)) restored else ifelse(
                  is.null(AllInputs()[[paste0("textin_relations_name", i)]]) == TRUE,
                  paste0("m", i),
                  AllInputs()[[paste0("textin_relations_name", i)]]
                ),
                width = "100%",
                height = "80px",
                resize = "none"
              )
            )
          )
        })
      })
    }
  })

  output$textbox_ui_name <- renderUI({
    textboxes_names()
  })
  output$textbox_ui_rel <- renderUI({
    textboxes_relations()
  })
  output$textbox_ui_rel_complete <- renderUI({
    textboxes_relations_complete()
  })


  #### Display Intersection

  output$textbox_ui_name_rel <-
    renderUI({
      textboxes_relations_name()
    })


  #### Download ####

  # Writes the complete app input (names, specifications, intersections, mixtures,
  # items, tolerances, V selection) to an .xlsx file. Used by the Download button and
  # by the share link, so both carry exactly the same information.
  build_user_input <- function() {
      missing_table <- data.frame("none")
      colnames(missing_table) <- ""

      mytable_v <- mytable_v_reactive$value
      if (is.null(mytable_v)) {
        mytable_v <- missing_table
      }

      name_probs <- numeric()

      for (loop_save in seq_len(counter$n)) {
        name_probs <- c(name_probs, isolate(input[[paste0("textin_name_", loop_save)]]))
      }

      name_models <- numeric()

      for (loop_save in seq_len(counter_input$n)) {
        name_models <- c(name_models, isolate(input[[paste0("textin_relations_name", loop_save)]]))
      }

      input_models <- numeric()

      for (loop_save in seq_len(counter_input$n)) {
        input_models <- c(input_models, isolate(input[[paste0("textin_relations_", loop_save)]]))
      }

      shared_input_model <- AllInputs()$add_for_all_models

      # Per-equality tolerances (one number per individual "=" occurrence,
      # keyed by model index) — see equality_tolerances_reactive's own
      # comment. Nested/nonuniform shape, so JSON like replication/items
      # below rather than a flat table like the old per-model version of
      # this sheet.
      equality_tol_json <- toJSON(equality_tolerances_reactive$value, auto_unbox = TRUE, null = "null")

      # Model intersections / mixtures are flat data.frames (rows = pairs,
      # columns = which models are selected), so they round-trip through
      # xlsx directly. Replication / multi-item specs are nested R lists
      # (base model + factor definitions + parameter-to-type assignments,
      # not a flat table), so they're serialized to a single JSON cell
      # instead — write_xlsx/read_excel can't represent nested structures.
      mytable_int   <- mytable_int_reactive$value
      if (is.null(mytable_int)) mytable_int <- missing_table

      mytable_mix   <- mytable_mix_reactive$value
      if (is.null(mytable_mix)) mytable_mix <- missing_table

      # param_factors and eps_per_param are both NAMED vectors (p1/p2/p3
      # -> type index / -> tolerance). toJSON serializes a bare named
      # atomic vector as an array, dropping the names — convert both to
      # named lists first so they round-trip as JSON objects instead,
      # preserving which parameter maps to which value.
      items_for_json <- lapply(mytable_items_reactive$value, function(s) {
        s$param_factors <- as.list(s$param_factors)
        if (!is.null(s$eps_per_param)) s$eps_per_param <- as.list(s$eps_per_param)
        if (!is.null(s$lists)) s$lists <- as.list(s$lists)
        s
      })
      items_json <- toJSON(items_for_json, auto_unbox = TRUE, null = "null")

      # These three are only ever written by the "Intersection model" /
      # "Mixture model" / "Multiple items" buttons (not saved anywhere
      # before this) — without them, a restored mixture-model row loses
      # the state that actually drives its convex-hull computation
      # (its Unique Model Specification is deliberately left empty by
      # design, so the row would otherwise come back as just a blank,
      # non-computing model — see mixture_model_flags's own comment),
      # an intersection-model row loses its live-sync-with-sources
      # behavior, and a multi-item row loses its "reopen settings" edit
      # button. Same named-list-keyed-by-row-index-string shape as
      # equality_tolerances_reactive above, so the same toJSON/fromJSON
      # round-trip already proven for that applies here unchanged.
      # the stored shapes of deleted source models (extra_v / extra_h) are matrices: written as {cols, rows}
      mat_json <- function(m) list(cols = if (is.null(colnames(m))) character(0) else colnames(m), rows = matrix(as.character(m), nrow(m), ncol(m)))
      derived_for_json <- lapply(derived_model_sources$value, function(info) {
        if (!is.null(info$extra_v)) info$extra_v <- lapply(info$extra_v, mat_json)
        if (!is.null(info$extra_h)) info$extra_h <- lapply(info$extra_h, mat_json)
        info
      })
      derived_sources_json <- toJSON(derived_for_json, auto_unbox = TRUE, null = "null", matrix = "rowmajor")
      mixture_flags_json   <- toJSON(mixture_model_flags$value, auto_unbox = TRUE, null = "null")
      item_spec_idx_json   <- toJSON(item_model_spec_idx$value, auto_unbox = TRUE, null = "null")
      # the order of the probabilities chosen for QTEST / multinomineq (one permutation per unpacked model)
      qtest_order_json     <- toJSON(isolate(qtest_perm$map), null = "null")
      # the numbers and settings of the multinomineq analysis and the switches of the volume calculation travel with the input
      analysis_json <- toJSON(list(
        mn_data = isolate(mn_user_data()), mn_share = isolate(mn_share()), mn_settings = isolate(mn_settings()),
        switches = list(EX = isolate(input$EX), ALG = isolate(input$ALG), CB = isolate(input$CB), CG = isolate(input$CG),
                        SoB = isolate(input$SoB), use_parallel = isolate(input$use_parallel))
      ), auto_unbox = TRUE, null = "null", digits = NA)

      out <- list(
        "V-description" = mytable_v,
        "Number of models" = data.frame(counter_input$n),
        "Number of probabilitiy" = data.frame(counter$n),
        "Names of probabilities" = data.frame(name_probs),
        "Name of models" = data.frame(name_models),
        "Unique input models" = data.frame(input_models),
        "Shared input models" = data.frame(shared_input_model),
        "Approximately identical equalities" = data.frame(json = as.character(equality_tol_json)),
        "Model intersections" = mytable_int,
        "Model mixtures" = mytable_mix,
        "Multi-item models" = data.frame(json = as.character(items_json)),
        "Derived model sources" = data.frame(json = as.character(derived_sources_json)),
        "Mixture model flags" = data.frame(json = as.character(mixture_flags_json)),
        "Item model spec idx" = data.frame(json = as.character(item_spec_idx_json)),
        "QTEST order" = data.frame(json = as.character(qtest_order_json)),
        "Analysis settings" = data.frame(json = as.character(analysis_json))
      )

      out
  }

  # ---- Export the session as an R script (package 'fairy') ----
  # ---- QTEST: the order of the probabilities of an unpacked model can be chosen (draggable list) ----
  qtest_perm <- reactiveValues(map = list())
  qtest_valid_perm <- function(p, N) {
    p <- suppressWarnings(as.integer(unlist(p)))
    if (length(p) == N && !anyNA(p) && setequal(p, seq_len(N))) p else seq_len(N)
  }
  # what each column of an unpacked model is (HTML, in the order of its columns); NULL when it cannot be told
  items_model_legend <- function(nm) {
    n <- isolate(counter_input$n)
    for (i in seq_len(n)) {
      nmi <- isolate(input[[paste0("textin_relations_name", i)]]) %||% paste0("m", i)
      if (!identical(nmi, nm)) next
      idx <- isolate(item_model_spec_idx$value[[as.character(i)]]); specs <- isolate(mytable_items_reactive$value)
      if (is.null(idx) || is.null(specs) || idx > length(specs)) return(NULL)
      spec <- specs[[idx]]; hb <- isolate(h_reactive[[spec$base]])
      if (is.null(hb) || is.null(spec$factors)) return(NULL)
      return(items_column_legend(hb, spec$factors, spec$param_factors, spec$lists))
    }
    NULL
  }

  # The default order of the probabilities of an unpacked model, the same for every model: first by probability (p1, p2, ... of the
  # input), then by item. The model itself is built differently (not repeated probabilities first, then item by item), so without
  # this the same probability would sit at a different place in different unpacked models. NULL when it cannot be told.
  items_canonical_perm <- function(nm) {
    n <- isolate(counter_input$n)
    for (i in seq_len(n)) {
      nmi <- isolate(input[[paste0("textin_relations_name", i)]]) %||% paste0("m", i)
      if (!identical(nmi, nm)) next
      idx <- isolate(item_model_spec_idx$value[[as.character(i)]]); specs <- isolate(mytable_items_reactive$value)
      if (is.null(idx) || is.null(specs) || idx > length(specs)) return(NULL)
      spec <- specs[[idx]]; hb <- isolate(h_reactive[[spec$base]]); h <- isolate(h_reactive[[nm]])
      if (is.null(hb) || is.null(h) || is.null(spec$factors)) return(NULL)
      pf <- as.integer(spec$param_factors[colnames(hb)[-(1:2)]]); pf[is.na(pf)] <- 0L
      par <- which(pf == 0L); lev <- rep(0L, length(par))
      for (f in seq_along(spec$factors)) {
        idx_f <- which(pf == f)
        if (length(idx_f) == 0) next
        for (l in seq_len(spec$factors[[f]]$n)) { par <- c(par, idx_f); lev <- c(lev, rep(l, length(idx_f))) }
      }
      if (length(par) != ncol(h) - 2L) return(NULL)
      return(order(par, lev))
    }
    NULL
  }
  # every unpacked model without an order of its own gets the default order
  observe({
    nms <- items_reactive$names
    for (nm in nms) h_reactive[[nm]]
    isolate({
      for (nm in nms) {
        if (!is.null(qtest_perm$map[[nm]])) next
        pm <- items_canonical_perm(nm)
        if (!is.null(pm) && !identical(as.integer(pm), seq_along(pm))) qtest_perm$map[[nm]] <- as.integer(pm)
      }
    })
  })
  # Card title: "m1 [long description of the unpacking]" -> the description goes onto a small second line of its own;
  # the text content stays exactly the full name (the cards are ordered and sized by it).
  card_title_html <- function(nm) {
    nm <- as.character(nm)
    m <- regmatches(nm, regexec("^(.*?) (\\[.*\\])$", nm))[[1]]
    if (length(m) == 3L) paste0("<span class='fairy-card-name'>", m[2], "</span><span class='fairy-card-tag'> ", m[3], "</span>")
    else paste0("<span class='fairy-card-name'>", nm, "</span>")
  }
  # the whole input as one URL-safe token (gzipped JSON): used by the share link and by the R script download
  share_token <- function() tryCatch({
    sheets_out <- lapply(isolate(build_user_input()), function(d) { d <- as.data.frame(d); rownames(d) <- NULL; d })
    js <- toJSON(sheets_out, dataframe = "columns", na = "null", digits = NA)
    raw <- memCompress(charToRaw(as.character(js)), type = "gzip")
    chartr("+/", "-_", gsub("=+$", "", gsub("\\s", "", jsonlite::base64_enc(raw))))
  }, error = function(e) NULL)
  # link that opens the app with this input (the public address when the app runs locally)
  app_share_url <- function() {
    tok <- share_token()
    if (is.null(tok)) return(NULL)
    cd <- session$clientData
    host <- cd$url_hostname %||% ""
    base <- if (!nzchar(host) || host %in% c("localhost", "127.0.0.1")) "https://fairy.decision-research.de/" else
      paste0(cd$url_protocol, "//", host, if (nzchar(cd$url_port %||% "")) paste0(":", cd$url_port), cd$url_pathname)
    paste0(base, "#s=", tok)
  }
  build_r_script <- function() {
    q <- function(x) encodeString(as.character(x), quote = '"')
    # "  name = c(a, b, c)," broken over several lines so that no line gets long
    fmt_c <- function(prefix, vals, last = FALSE, width = 74) {
      open <- paste0("  ", prefix, " = c("); lines <- character(); cur <- open
      for (k in seq_along(vals)) {
        tok <- paste0(vals[k], if (k < length(vals)) ", " else ")")
        if (nchar(cur) + nchar(tok) > width && cur != open) { lines <- c(lines, sub("\\s+$", "", cur)); cur <- "      " }
        cur <- paste0(cur, tok)
      }
      c(lines, paste0(cur, if (!last) "," else ""))
    }
    # a comment paragraph, wrapped
    cm <- function(x, width = 76) paste0("# ", strwrap(x, width = width))
    n_rows <- isolate(counter_input$n)
    n_p <- isolate(counter$n)
    shared <- trimws(isolate(input[["add_for_all_models"]]) %||% "")
    row_name <- vapply(seq_len(n_rows), function(i) isolate(input[[paste0("textin_relations_name", i)]]) %||% paste0("m", i), character(1))
    dms <- isolate(derived_model_sources$value)
    idx_map <- isolate(item_model_spec_idx$value)
    specs <- isolate(mytable_items_reactive$value)
    flags <- isolate(mixture_model_flags$value)
    tols <- isolate(equality_tolerances_reactive$value)
    app_url <- tryCatch(app_share_url(), error = function(e) NULL)
    out <- c(
      paste0("# Session exported from the Fairy app on ", format(Sys.Date()), "."),
      cm("It rebuilds every model of the session with the R package 'fairy' and reports dimension, vertices, constraints, volume and largest Bayes factor."),
      if (!is.null(app_url)) c("", "# ---- The same input in the app --------------------------------------------",
        cm("This link opens the Fairy app with exactly the probabilities, models and settings of this script. Everything is stored in the part of the link after '#s=' (nothing is saved on a server), so the link can be bookmarked or sent to someone else."),
        cm("To open it, remove the '#' in front of browseURL() below and run the line, or paste the link into a browser. Changes made in the app afterwards are not written back to this script."),
        paste0("fairy_app_url <- ", q(app_url)), "# browseURL(fairy_app_url)", ""),
      "# install.packages(\"remotes\")",
      "# remotes::install_github(\"marc-jekel/fairy\", subdir = \"pkg\",",
      "#                         upgrade = \"always\")",
      "library(fairy)", "",
      paste0("n_p <- ", n_p, "   # number of probabilities"), ""
    )
    pn <- vapply(seq_len(n_p), function(i) trimws(isolate(input[[paste0("textin_name_", i)]]) %||% ""), character(1))
    if (any(nzchar(pn))) out <- c(out, cm(paste0("names given to the probabilities in the app: ", paste0("p", seq_len(n_p), " = ", ifelse(nzchar(pn), pn, paste0("p", seq_len(n_p))), collapse = ", "))), "")
    obj <- paste0("h", seq_len(n_rows))
    unpacked_rows <- integer(0)
    for (i in seq_len(n_rows)) {
      key <- as.character(i); com <- paste0("   # ", gsub("[\r\n]+", " ", row_name[i]))
      info <- dms[[key]]; ii <- idx_map[[key]]
      if (!is.null(info)) {
        srcs <- obj[info$source_idx[info$source_idx >= 1 & info$source_idx <= n_rows]]
        # the last shapes of deleted source models (kept inside the model in the app) are written out as vertices
        stored <- c(info$extra_v %||% list(), lapply(info$extra_h %||% list(), function(h) {
          n_h <- ncol(h) - 2L
          cube_s <- d2q(rbind(makeH(a1 = -diag(n_h), b1 = rep(0, n_h)), makeH(a1 = diag(n_h), b1 = rep(1, n_h))))
          h_full <- rbind(h, cube_s); attr(h_full, "representation") <- "H"
          v_out <- tryCatch(scdd(h_full)$output, error = function(e) NULL)
          if (is.null(v_out)) NULL else v_out[v_out[, 2] == "1", , drop = FALSE]
        }))
        stored <- Filter(function(m) !is.null(m) && nrow(m) > 0, stored)
        for (k in seq_along(stored)) {
          co <- stored[[k]][, -(1:2), drop = FALSE]
          nm_s <- paste0(obj[i], "_stored", k)
          out <- c(out, paste0(nm_s, " <- fairy_from_vertices(matrix(c(", paste(q(as.vector(t(co))), collapse = ", "), "), ncol = ", ncol(co), ", byrow = TRUE))   # last shape of a deleted source model of ", row_name[i]))
          srcs <- c(srcs, nm_s)
        }
        fn <- if (identical(info$type, "mixture")) "fairy_mixture" else "fairy_intersect"
        out <- c(out, paste0(obj[i], " <- ", fn, "(", paste(srcs, collapse = ", "), ")", com))
      } else if (!is.null(ii) && !is.null(specs) && ii <= length(specs)) {
        sp <- specs[[ii]]
        b <- match(sp$base, row_name)
        pf <- sp$param_factors; fcs <- sp$factors
        if (is.na(b) || is.null(sp$factor_types)) { out <- c(out, paste0("# ", row_name[i], ": the unpacking of this model could not be exported")); obj[i] <- NA; next }
        items <- vapply(seq_along(pf), function(k) if (pf[[k]] > 0) as.integer(fcs[[pf[[k]]]]$n) else 1L, integer(1))
        lst <- if (!is.null(sp$lists)) as.character(unname(sp$lists))[seq_along(pf)] else rep("", length(pf))
        miss <- is.na(lst) | !nzchar(lst)
        lst[miss] <- ifelse(unname(pf)[miss] > 0, paste0("list", unname(pf)[miss]), paste0("single_p", seq_along(pf)[miss]))   # a probability with one item belongs to no list
        lev <- unique(lst)
        ty <- vapply(lev, function(l) { k <- which(lst == l)[1]; kk <- pf[[k]]; if (kk > 0) as.character(sp$factor_types[[kk]]) else "joint" }, character(1))   # a list of one item belongs to no factor
        eps <- if (!is.null(sp$eps_per_param)) as.numeric(unname(sp$eps_per_param))[seq_along(pf)] else rep(0, length(pf))
        out <- c(out, paste0(obj[i], " <- fairy_unpack("), paste0("  ", obj[b], ","),
          fmt_c("items", items), fmt_c("lists", q(lst)), fmt_c("type", paste0(q(lev), " = ", q(ty))),
          fmt_c("eps", eps, last = TRUE), paste0(")", com))
        unpacked_rows <- c(unpacked_rows, i)
      } else if (!is.null(flags[[key]])) {
        out <- c(out, paste0("# ", row_name[i], ": a row without constraint text that could not be exported"))
        obj[i] <- NA
      } else {
        own <- trimws(isolate(input[[paste0("textin_relations_", i)]]) %||% "")
        txt <- paste(c(if (nzchar(own)) own, if (nzchar(shared)) shared), collapse = "; ")   # same order as the app (the tolerances follow it)
        txt <- gsub("≥", ">=", gsub("≤", "<=", txt, fixed = TRUE), fixed = TRUE)
        txt <- expand_equality_chains(txt)   # a chain p1=p2=p3 stands for all its pairs, as in the app
        tv <- as.numeric(unlist(tols[[key]])); tv <- tv[!is.na(tv) & tv > 0]
        # fairy_h() has ONE tolerance for all equalities of a model: it can only stand for the app's setting if every equality is
        # approximate with that same value (a mix of exact and approximate equalities, or different values, cannot be written)
        eq_rows <- unlist(lapply(trimws(strsplit(txt, ";")[[1]]), function(cl) if (nzchar(cl)) expand_clause_to_rows(cl) else NULL))
        n_eq <- sum(grepl("=", eq_rows))
        tv_all <- as.numeric(unlist(tols[[key]])); tv_all <- c(tv_all, rep(0, max(0, n_eq - length(tv_all))))[seq_len(n_eq)]; tv_all[is.na(tv_all)] <- 0
        tol_arg <- if (n_eq > 0 && any(tv_all > 0)) {
          if (all(tv_all > 0) && length(unique(tv_all)) == 1) paste0(", approx_tol = ", tv_all[1])
          else paste0(", approx_tol = c(", paste(tv_all, collapse = ", "), ")")   # one tolerance per equality, in the order of the model
        } else ""
        one <- paste0(obj[i], " <- fairy_h(", q(txt), ", n_p = n_p", tol_arg, ")", com)
        out <- c(out, if (nchar(one) <= 78) one else c(paste0(obj[i], " <- fairy_h("), paste0("  ", q(txt), ","),
          paste0("  n_p = n_p", tol_arg), paste0(")", com)))
      }
    }
    ok <- which(!is.na(obj))
    vtab <- isolate(mytable_v_reactive$value)
    vnames <- if (!is.null(vtab) && ncol(vtab) >= 2) as.character(vtab[[1]][vapply(vtab[[2]], isTRUE, logical(1))]) else character(0)
    vnames <- unique(vnames[vnames %in% row_name[ok]])
    # the order of the probabilities chosen for QTEST (draggable list in the app), only where it is not the default one
    qo <- list()
    for (nm0 in row_name[ok]) {
      pm0 <- isolate(qtest_perm$map[[nm0]]); h0 <- isolate(h_reactive[[nm0]])
      if (!is.null(pm0) && !is.null(h0) && length(pm0) == ncol(h0) - 2L && setequal(pm0, seq_len(length(pm0))) && !identical(as.integer(pm0), seq_along(pm0))) qo[[nm0]] <- as.integer(pm0)
    }
    qo_lines <- if (length(qo)) c(
      cm("Order of the probabilities in the QTEST files, as chosen in the app: the first number is the probability of the model that becomes p1 in the files, and so on."),
      "qtest_order <- list(", paste0("  ", q(names(qo)), " = c(", vapply(qo, function(p) paste(p, collapse = ", "), character(1)), ")", c(rep(",", length(qo) - 1), "")), ")") else character(0)
    out <- c(out, "", "# all models of the session",
      "models <- list(", paste0("  ", q(row_name[ok]), " = ", obj[ok], c(rep(",", length(ok) - 1), "")), ")", "",
      "# Summary table with one row per model:",
      "#   dim       dimension of the model (number of probabilities,",
      "#             minus one for each equality)",
      "#   vertices  number of extreme cases (rows of the V-description)",
      "#   inequalities, equalities",
      "#             number of constraints of each kind (rows of the",
      "#             H-description)",
      "#   volume    share of all combinations of the probabilities (each",
      "#             between 0 and 1) that the model allows; smaller = more",
      "#             restrictive; 0 if the model contains an equality",
      "#   max_bf    1 / volume: the largest Bayes factor in favour of the",
      "#             model against the unconstrained model that any data",
      "#             could produce (uniform prior); Inf if the volume is 0",
      cm("The volume is estimated with the R package volesti (its default settings). The seed makes the numbers reproducible; further volesti::volume() settings can be added to the list."),
      cm("For the exact value use fairy_info(h, method = \"exact\") (can be slow for many probabilities)."),
      "vol_settings <- list(seed = 1)", "",
      "info <- do.call(rbind, lapply(names(models), function(nm) {",
      "  h <- models[[nm]]",
      "  cbind(model = nm, fairy_info(h, settings = vol_settings))",
      "}))",
      "print(info)", "",
      "# H-description of every model, one table per model.",
      cm("How to read it: each row is one constraint, and a model is the set of all combinations of the probabilities that satisfy ALL rows. 'p2 <= p1' means p2 is at most p1; a row of type 'equality' fixes a relation exactly. Redundant constraints are left out; the bounds 0 <= p <= 1 appear only where they restrict the model."),
      "h_tables <- lapply(models, fairy_h_table)",
      "for (nm in names(h_tables)) {",
      "  cat(\"\\nH-description of\", nm, \"\\n\")",
      "  print(h_tables[[nm]])",
      "}",
      cm("fairy_h_table(h, style = \"paper\") writes the form of the paper (- p1 + p2 <= 0), style = \"matrix\" the coefficients."),
      cm("fairy_table_write(table, file = \"table.md\") writes any table as Markdown (or format = \"latex\" / \"csv\")."), "",
      cm("The H-description of every model as LaTeX: a .tex file that compiles as it is (one align* block per model). trivial = \"hide\" leaves out the trivial bounds 0 <= p <= 1, \"gray\" grays them out."),
      "fairy_write_latex(models, file = \"H-representation.tex\", trivial = \"show\")", "",
      if (length(vnames) > 0) c(
        cm("V-description (extreme cases) of the models for which it was switched on in the app. How to read it: each row is a vertex, a combination of values of the probabilities that the model allows and that cannot be written as a mixture of two other allowed combinations. Every allowed combination is a weighted mixture of the rows. (words = TRUE writes 'none' and 'all' for 0 and 1.)"),
        paste0("v_models <- c(", paste(q(vnames), collapse = ", "), ")"),
        "v_tables <- lapply(models[v_models], fairy_v_table)",
        "for (nm in names(v_tables)) {",
        "  cat(\"\\nV-description of\", nm, \"\\n\")",
        "  print(v_tables[[nm]])",
        "}", ""),
      cm("Input file for other software, written to the working directory (a .tar archive)."),
      cm("QTEST: one .txt file per model with the H-representation (A and b, integer-scaled). QTEST cannot express equalities: for a model with equalities the file lists them in an extra block and its name ends with _needs_editing_for_qtest (nothing is substituted)."),
      qo_lines,
      paste0("fairy_write_qtest(models, file = \"QTEST_H-representation.tar\"", if (length(qo)) ", order = qtest_order" else "", ")"))
    out
  }
  # the "Volume by model" chart as a PDF (vector graphic), drawn with base graphics: same bars, colours and axis as on the screen
  # extra last page of the PDFs written by the app: the link that recreates the input, as text and as a QR code
  pdf_link_page <- function(w, h) {
    url <- tryCatch(isolate(app_share_url()), error = function(e) NULL)
    if (is.null(url) || !nzchar(url)) return(NULL)
    graphics::par(fig = c(0, 1, 0, 1), mai = c(0, 0, 0, 0), new = TRUE); graphics::plot.new(); graphics::plot.window(c(0, w), c(0, h), xaxs = "i", yaxs = "i")
    lt <- "Restore these models in the Fairy app"
    graphics::text(0.3, 0.14, lt, adj = c(0, 0.5), cex = 0.6, col = "#1a5fb4")
    lw <- graphics::strwidth(lt, cex = 0.6)
    graphics::segments(0.3, 0.095, 0.3 + lw, 0.095, col = "#1a5fb4")
    list(rect = c(0.3, 0.07, 0.3 + lw, 0.22) * 72, url = url, page = 1)
  }
  # the PDF is finished (device closed): make the blue line clickable
  pdf_finish_link <- function(file, lk) { if (!is.null(lk)) pdf_add_link(file, lk$rect, lk$url, page = lk$page); invisible(file) }
  parsimony_pdf <- function(df, file) {
    algo_colors <- c("Cooling Bodies" = "#7a4fc4", "Cooling Gaussian" = "#f0ad4e", "Sequence of Balls" = "#5cb85c", "Exact" = "#8b93a7")
    models <- unique(df$Model); algos <- unique(df$Algorithm)
    pos <- df$Volume[is.finite(df$Volume) & df$Volume > 0]
    use_log <- length(pos) > 0 && min(pos) < 0.01
    k <- length(algos); n <- length(models)
    ph <- max(2.8, 1.9 + n * (0.3 + 0.18 * k)); has_url <- !is.null(tryCatch(isolate(app_share_url()), error = function(e) NULL))
    if (has_url) ph <- ph + 0.4
    grDevices::pdf(file, width = 8, height = ph)
    on.exit(grDevices::dev.off())
    labs <- vapply(models, function(z) paste(strwrap(z, 38), collapse = "\n"), character(1))
    graphics::par(mai = c(0.9, 0.5, 0.6, 0.2))
    lw <- max(graphics::strwidth(labs, units = "inches", cex = 0.8)) + 0.25
    graphics::par(mai = c(0.9 + if (has_url) 0.4 else 0, lw, 0.6, 0.2))
    xlim <- if (use_log) c(min(pos) / 3, 1) else c(0, 1)
    graphics::plot(NA, xlim = xlim, ylim = c(0.5, n + 0.5), log = if (use_log) "x" else "", xaxt = "n", yaxt = "n",
                   xlab = if (use_log) "Volume (log scale)" else "Volume", ylab = "", bty = "n")
    if (use_log) {
      ex <- seq(floor(log10(xlim[1])), 0)
      graphics::axis(1, at = 10^ex, labels = parse(text = paste0("10^", ex)))
      graphics::abline(v = 10^ex, col = "grey88")
    } else {
      graphics::axis(1)
      graphics::abline(v = seq(0, 1, 0.2), col = "grey88")
    }
    bh <- 0.8 / k
    for (i in seq_len(n)) for (j in seq_len(k)) {
      v <- df$Volume[df$Model == models[i] & df$Algorithm == algos[j]]
      if (length(v) == 1 && is.finite(v) && v > 0) {
        top <- n - i + 1 + 0.4 - (j - 1) * bh
        graphics::rect(xlim[1], top - bh * 0.9, v, top, col = unname(algo_colors[algos[j]]), border = NA)
      }
    }
    graphics::axis(2, at = n:1, labels = labs, las = 1, tick = FALSE, cex.axis = 0.8)
    if (k > 1) graphics::legend("topleft", legend = algos, fill = unname(algo_colors[algos]), horiz = TRUE, bty = "n",
                                inset = c(0, -0.13), xpd = NA, cex = 0.8)
    lk <- if (has_url) pdf_link_page(8, ph)
    invisible(structure(file, link = lk))
  }
  # QR code of the share link: shown in the middle of the screen (Share menu), downloadable as PDF or PNG
  # highest error correction that still holds the link: with "Q" or "H" a small fairy fits in the middle of the code
  qr_matrix <- function(url) {
    if (is.null(url) || !nzchar(url) || nchar(url) >= 2300 || !requireNamespace("qrcode", quietly = TRUE)) return(NULL)
    for (e in c("H", "Q", "M", "L")) {
      m <- tryCatch(as.matrix(qrcode::qr_code(url, ecl = e)), error = function(err) NULL)
      if (!is.null(m)) {
        # H / Q: the modules in the middle are cleared for the fairy (the error correction restores them); no frame is drawn
        if (e %in% c("H", "Q")) {
          n <- nrow(m); k <- ceiling(n * 0.025) + 1; v <- (n - 17) / 4
          # somewhere in the data area (not at a corner, not on the timing lines, not on an alignment pattern): the fairy is a small easter egg
          al <- numeric(0)
          if (v >= 2) { num <- v %/% 7 + 2; lastp <- n - 7; st <- if (num > 2) ceiling((lastp - 6) / (num - 1) / 2) * 2 else 0
                        al <- if (num > 2) c(6, lastp - st * ((num - 2):0)) else c(6, lastp) }
          ok <- function(r, cc) {
            if (r < 11 || cc < 11 || r + k > n - 10 || cc + k > n - 10) return(FALSE)
            for (ar in al) for (ac in al) { if ((ar == 6 && ac == 6) || (ar == 6 && ac == max(al)) || (ac == 6 && ar == max(al))) next
              if (r < ar + 5 && r + k + 1 > ar - 4 && cc < ac + 5 && cc + k + 1 > ac - 4) return(FALSE) }
            TRUE
          }
          pos <- NULL
          for (tr in 1:200) { r0 <- sample.int(max(1, n - k - 12), 1) + 10; c0 <- sample.int(max(1, n - k - 12), 1) + 10; if (ok(r0, c0)) { pos <- c(r0, c0); break } }
          if (is.null(pos)) { attr(m, "ecl") <- "M"; return(m) }
          m[pos[1] + seq_len(k) - 1, pos[2] + seq_len(k) - 1] <- FALSE; attr(m, "logo") <- c(pos, k)
        }
        attr(m, "ecl") <- e; return(m)
      }
    }
    NULL
  }
  # the fairy of the app (same drawing as the logo, see fairy_svg), as polygons / lines in the unit square (y up)
  fairy_polys <- function() {
    bez <- function(p0, p1, p2, p3, n = 14) { t <- seq(0, 1, length.out = n); cbind((1 - t)^3 * p0[1] + 3 * (1 - t)^2 * t * p1[1] + 3 * (1 - t) * t^2 * p2[1] + t^3 * p3[1],
                                                                                 (1 - t)^3 * p0[2] + 3 * (1 - t)^2 * t * p1[2] + 3 * (1 - t) * t^2 * p2[2] + t^3 * p3[2]) }
    U <- function(xy) cbind((xy[, 1] - 4) / 56, 1 - (xy[, 2] - 6) / 56)   # the drawing is 64 x 64 (y down); the empty margin is cut off
    th <- seq(0, 2 * pi, length.out = 30)[-30]
    wing_l <- rbind(bez(c(31, 34), c(16, 20), c(6, 24), c(10, 34)), bez(c(10, 34), c(6, 44), c(18, 44), c(31, 34)))
    wing_r <- rbind(bez(c(33, 34), c(48, 20), c(58, 24), c(54, 34)), bez(c(54, 34), c(58, 44), c(46, 44), c(33, 34)))
    seg <- function(x1, y1, x2, y2) list(xy = U(rbind(c(x1, y1), c(x2, y2))), col = "#000000", line = TRUE, bw = 2.4)
    list(
      list(xy = U(wing_l), col = "#000000", border = "#000000", bw = 1.5),
      list(xy = U(wing_r), col = "#ffffff", border = "#000000", bw = 1.5),
      list(xy = U(cbind(32 + 5 * cos(th), 20 + 5 * sin(th))), col = "#ffffff", border = "#000000", bw = 1.4),
      seg(32, 25, 32, 44), seg(32, 30, 26, 38), seg(32, 30, 38, 38), seg(32, 44, 27, 52), seg(32, 44, 37, 52),
      list(xy = U(rbind(c(50, 12), c(51.6, 15.4), c(55, 17), c(51.6, 18.6), c(50, 22), c(48.4, 18.6), c(45, 17), c(48.4, 15.4))), col = "#000000"))
  }
  qr_with_fairy <- function(qr) !is.null(attr(qr, "logo"))
  # demo of the run window for the tour (no real calculation): the same messages as a real run sends, until the tour ends
  observeEvent(input$fairy_run_demo, {
    fairy_run_begin(title = "Calculating", skippable = TRUE)
    fairy_run_row("m1", h = "done", v = "run")
    fairy_run_row("m2", h = "wait", v = "wait")
    session$sendCustomMessage("fairy_run_cancelable", list(on = TRUE, input = "tour_demo_cancel", label = "Skip all"))
    session$sendCustomMessage("fairy_run_limit", list(seconds = V_REP_LIMIT, nolimit = FALSE, label = "each V-representation"))
  })
  observeEvent(input$fairy_run_demo_stop, { session$sendCustomMessage("fairy_run_hide", list()) })
  observeEvent(input$qr_request, {
    url <- tryCatch(app_share_url(), error = function(e) NULL)
    qr <- qr_matrix(url)
    if (is.null(qr)) { showNotification("This input is too large for a QR code. Use \"Copy link\" in this menu instead.", type = "warning", duration = 8); return() }
    n <- nrow(qr); q <- 4
    cells <- character()
    for (i in seq_len(n)) { r <- which(qr[i, ]); if (length(r)) cells <- c(cells, sprintf("M%d %dh1v1h-1z", r - 1 + q, i - 1 + q)) }
    logo <- ""
    if (qr_with_fairy(qr)) {
      lg <- attr(qr, "logo"); ls <- n * 0.025; lx <- q + lg[2] - 1 + (lg[3] - ls) / 2; ly <- q + lg[1] - 1 + (lg[3] - ls) / 2
      pts <- vapply(fairy_polys(), function(z) {
        xy <- paste(sprintf("%.2f,%.2f", lx + z$xy[, 1] * ls, ly + (1 - z$xy[, 2]) * ls), collapse = " ")
        sw <- (z$bw %||% 0) * ls / 56
        if (isTRUE(z$line)) sprintf('<polyline fill="none" stroke="%s" stroke-width="%.3f" stroke-linecap="round" points="%s"/>', z$col, sw, xy)
        else sprintf('<polygon fill="%s" %s opacity="%s" stroke-linejoin="round" points="%s"/>', z$col, if (is.null(z$border)) "" else sprintf('stroke="%s" stroke-width="%.3f"', z$border, sw), z$alpha %||% 1, xy)
      }, character(1))
      logo <- paste(pts, collapse = "")
    }
    svg <- sprintf('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %d %d" shape-rendering="crispEdges"><rect width="100%%" height="100%%" fill="#fff"/><path fill="#000" d="%s"/>%s</svg>', n + 2 * q, n + 2 * q, paste(cells, collapse = ""), logo)
    session$sendCustomMessage("fairy_qr", list(svg = svg, url = url))
  })
  qr_draw <- function(url, w, h, with_link = TRUE) {
    qr <- qr_matrix(url); req(!is.null(qr))
    graphics::par(mai = c(0, 0, 0, 0)); graphics::plot.new(); graphics::plot.window(c(0, w), c(0, h), xaxs = "i", yaxs = "i")
    n <- nrow(qr); sz <- w - 0.6; cw <- sz / n; top <- h - 0.3
    for (i in seq_len(n)) for (j in seq_len(n)) if (isTRUE(qr[i, j]))
      graphics::rect(0.3 + (j - 1) * cw, top - i * cw, 0.3 + j * cw, top - (i - 1) * cw, col = "black", border = NA)
    if (qr_with_fairy(qr)) {
      lg <- attr(qr, "logo"); ls <- n * 0.025 * cw; lx <- 0.3 + (lg[2] - 1 + (lg[3] - n * 0.025) / 2) * cw; ly <- top - (lg[1] - 1 + (lg[3] + n * 0.025) / 2) * cw
      for (z in fairy_polys()) {
        lwd <- max(0.1, (z$bw %||% 0) * ls * 96 / 56)
        if (isTRUE(z$line)) graphics::lines(lx + z$xy[, 1] * ls, ly + z$xy[, 2] * ls, col = z$col, lwd = lwd, lend = 1)
        else graphics::polygon(lx + z$xy[, 1] * ls, ly + z$xy[, 2] * ls, col = grDevices::adjustcolor(z$col, alpha.f = z$alpha %||% 1), border = if (is.null(z$border)) NA else z$border, lwd = lwd, lend = 1, ljoin = 1)
      }
    }
    if (!with_link) return(NULL)
    lt <- "Restore these models in the Fairy app"; cx <- 0.8
    tw <- graphics::strwidth(lt, cex = cx); x0 <- (w - tw) / 2
    graphics::text(x0, 0.28, lt, adj = c(0, 0.5), cex = cx, col = "#1a5fb4")
    graphics::segments(x0, 0.2, x0 + tw, 0.2, col = "#1a5fb4")
    c(x0, 0.12, x0 + tw, 0.42)
  }
