    upload_file(input$upload$datapath)
    upload_trigger(isolate(upload_trigger()) + 1)
  })

  # Share link: the whole input travels in the URL hash (#s=...), so nothing is stored on the server.
  observeEvent(input$share_request, {
    tok <- share_token()
    if (is.null(tok)) {
      showNotification("The share link could not be created.", type = "error")
      return()
    }
    session$sendCustomMessage("fairy_share", list(token = tok))
  })
  # Auto-save: every 30 seconds the state is sent to the browser (only when it changed since the start of the session)
  autosave_state <- reactiveValues(base = NULL, last = NULL)
  observe({
    invalidateLater(30000)
    tok <- tryCatch(isolate(share_token()), error = function(e) NULL)
    if (is.null(tok)) return()
    if (is.null(isolate(autosave_state$base))) { autosave_state$base <- tok; return() }
    if (identical(tok, isolate(autosave_state$base)) || identical(tok, isolate(autosave_state$last))) return()
    autosave_state$last <- tok
    session$sendCustomMessage("fairy_autosave", list(token = tok))
  })
  observeEvent(input$share_payload, {
    tok <- as.character(input$share_payload)
    if (length(tok) != 1 || is.na(tok) || nchar(tok) > 1e6 || !grepl("^[A-Za-z0-9_-]+$", tok)) return()
    tok <- chartr("-_", "+/", tok)
    tok <- paste0(tok, strrep("=", (4 - nchar(tok) %% 4) %% 4))
    tmp <- tempfile(fileext = ".xlsx")
    ok <- tryCatch({
      txt <- rawToChar(memDecompress(jsonlite::base64_dec(tok), type = "gzip"))
      sheets <- fromJSON(txt, simplifyVector = TRUE)
      stopifnot(is.list(sheets), length(sheets) %in% c(14, 15, 16))
      sheets <- lapply(sheets, function(x) as.data.frame(x, stringsAsFactors = FALSE, check.names = FALSE))
      write_xlsx(sheets, tmp)
      TRUE
    }, error = function(e) FALSE)
    if (!isTRUE(ok)) {
      showNotification("This share link is not valid (or was cut off).", type = "error", duration = 10)
      return()
    }
    upload_file(tmp)
    upload_trigger(isolate(upload_trigger()) + 1)
  })

  observeEvent(upload_trigger(), {
    req(upload_file())
    # Block the auto-detect observer (app.R ~2771) from fighting with this
    # restore for the whole restore window — see restoring_upload's own
    # comment for why. Cleared further down once the delayed restore of the
    # name/spec boxes has had time to fully round-trip.
    restoring_upload(TRUE)

    # read_excel() returns a tibble, whose `[` never drops to a bare vector
    # like a plain data.frame's does — code elsewhere (e.g. `which(mytable_v[,
    # 2])`, `sum(tab[, 2])`) expects mytable_v_reactive$value to behave like
    # a normal data.frame column access. Coerce immediately, same fix as for
    # mytable_int_reactive/mytable_mix_reactive below.
    mytable_v_reactive$value <- as.data.frame(read_excel(upload_file(), 1))

    if (length(mytable_v_reactive$value) == 1) {
      mytable_v_reactive$value <- NULL
    }

    # Read everything before touching counters
    new_counter_input_n <- unlist(read_excel(upload_file(), 2))
    new_counter_n       <- unlist(read_excel(upload_file(), 3))

    # write_xlsx/read_excel does NOT round-trip an empty string as an
    # empty string — it comes back as NA (confirmed directly: writing
    # c("p1>p2", "", "p3>p4") and reading it back gives c("p1>p2", NA,
    # "p3>p4")). Every one of these four is routinely blank in practice
    # (an unnamed probability, a model with no Unique Model
    # Specification, an empty Shared Model Specification — the last one
    # especially, since most models never set one) — restoring the NA
    # as-is fed straight into updateTextAreaInput()/pending_*_restore(),
    # which show it as the literal text "NA" instead of leaving the box
    # empty. Direct cause of a model "looking different" after a
    # download/upload round-trip.
    blank_na <- function(x) { x[is.na(x)] <- ""; x }

    name_probs <- blank_na(unlist(read_excel(upload_file(), 4)))
    names(name_probs) <- NULL

    name_models <- blank_na(unlist(read_excel(upload_file(), 5)))
    names(name_models) <- NULL

    input_models <- blank_na(unlist(read_excel(upload_file(), 6)))
    names(input_models) <- NULL

    shared_input_model <- blank_na(unlist(read_excel(upload_file(), 7)))
    names(shared_input_model) <- NULL

    # Sheet 8 used to be a flat "one tolerance per model" table (the old
    # manual "Approximate equalities" dialog); it's now a single JSON cell
    # holding equality_tolerances_reactive$value (one tolerance per
    # individual "=" occurrence, keyed by model index) — same
    # nested-structure-via-JSON approach as replication/items below. A
    # save file from before this change has the old flat-table shape
    # there instead, which fromJSON() will fail to parse — caught here so
    # older files still load, just without their approx settings, same
    # graceful-degradation as the sheets-9-12-missing case below.
    equality_clause_keys$value <- list()
    equality_tolerances_reactive$value <- tryCatch({
      raw <- fromJSON(read_excel(upload_file(), 8)$json[1], simplifyVector = FALSE)
      lapply(raw, function(x) as.numeric(unlist(x)))
    }, error = function(e) list())

    # Sheets 9-11 (intersections/mixtures/items) were added
    # after the original save format — wrap in tryCatch so save files from
    # before this existed still load instead of erroring out entirely.
    mytable_int_reactive$value <- tryCatch({
      # read_excel() returns a tibble. Unlike a plain data.frame, tibble's
      # `[` never drops to a bare vector, so prev[k, cn] elsewhere (e.g.
      # observeEvent(input$show_intersections, ...)) would return a 1x1
      # tibble instead of a scalar TRUE/FALSE — and isTRUE() on a tibble is
      # always FALSE regardless of its actual value, silently discarding
      # every restored checkbox selection. Coerce to a plain data.frame so
      # it behaves exactly like the in-session (non-upload) code path that
      # builds this table via observeEvent(input$submit_int, ...).
      tab <- as.data.frame(read_excel(upload_file(), 9))
      if (length(tab) == 1) NULL else tab
    }, error = function(e) NULL)

    mytable_mix_reactive$value <- tryCatch({
      tab <- as.data.frame(read_excel(upload_file(), 10))
      if (length(tab) == 1) NULL else tab
    }, error = function(e) NULL)

    mytable_items_reactive$value <- tryCatch({
      items_specs_from_json(read_excel(upload_file(), 11)$json[1])
    }, error = function(e) NULL)

    # Sheets 12-14 (added after sheets 9-11) — same tryCatch/graceful-
    # degradation pattern for save files from before these existed.
    # Without these, a restored mixture-model row silently loses the
    # state driving its actual computation (see the download side's own
    # comment); intersection-model rows lose their live-source-sync;
    # multi-item rows lose their "reopen settings" edit button.
    derived_model_sources$value <- tryCatch({
      derived_sources_from_json(read_excel(upload_file(), 12)$json[1])
    }, error = function(e) list())

    mixture_model_flags$value <- tryCatch({
      mixture_flags_from_json(read_excel(upload_file(), 13)$json[1])
    }, error = function(e) list())

    item_model_spec_idx$value <- tryCatch({
      item_spec_idx_from_json(read_excel(upload_file(), 14)$json[1])
    }, error = function(e) list())

    # sheet 15: the order of the probabilities for QTEST / multinomineq (files and links from before it simply have none)
    qtest_perm$map <- tryCatch({
      raw <- fromJSON(read_excel(upload_file(), 15)$json[1], simplifyVector = FALSE)
      lapply(raw, function(x) as.integer(unlist(x)))
    }, error = function(e) list())

    # sheet 16: numbers and settings of the multinomineq analysis, switches of the volume calculation (older files have none)
    tryCatch({
      an <- fromJSON(read_excel(upload_file(), 16)$json[1], simplifyVector = FALSE)
      mn_user_data(if (length(an$mn_data)) an$mn_data else list())
      mn_share(if (length(an$mn_share)) an$mn_share else list())
      mn_settings(if (length(an$mn_settings)) an$mn_settings else list())
      for (sw in c("EX", "ALG", "CB", "CG", "SoB", "use_parallel")) {
        v <- an$switches[[sw]]
        if (!is.null(v)) shinyWidgets::updateMaterialSwitch(session, sw, value = isTRUE(v))
      }
    }, error = function(e) {
      mn_user_data(list()); mn_share(list()); mn_settings(list())
    })

    # Each modal's row count is a SEPARATE counter (counter_int$n,
    # counter_mix$n, ...) from the actual data just restored above — the
    # modal only renders seq_len(counter$n) rows regardless of how many
    # rows/specs the restored table actually has. Without updating these,
    # reopening a modal after upload would only show however many rows the
    # counter happened to be at, hiding the rest of what was restored.
    counter_int$n   <- max(1, if (!is.null(mytable_int_reactive$value))   nrow(mytable_int_reactive$value)     else 1)
    counter_mix$n   <- max(1, if (!is.null(mytable_mix_reactive$value))   nrow(mytable_mix_reactive$value)     else 1)
    counter_items$n <- max(1, if (!is.null(mytable_items_reactive$value)) length(mytable_items_reactive$value) else 1)

    # Stash the restored names/specs so the renders that counter_input$n and
    # counter$n are about to trigger (below) can use them directly instead
    # of blank/default boxes — see pending_name_restore's own comment.
    pending_name_restore(name_probs)
    pending_relations_restore(input_models)
    pending_relations_name_restore(name_models)

    # Update counters — this triggers Shiny to re-render the input rows
    counter_input$n <- new_counter_input_n
    counter$n       <- new_counter_n
    # extra probabilities are intentional: keep them as the floor, otherwise the auto-detect
    # pass shrinks the count to the highest p referenced in the specifications
    manual_p_floor(max(1L, min(30L, as.integer(new_counter_n))))

    # Still update via updateTextAreaInput too, as a fallback for any box
    # that existed (and so wasn't freshly rendered) before this upload, and
    # to restore the other input types below.
    shinyjs::delay(400, {
      pending_name_restore(NULL)
      pending_relations_restore(NULL)
      pending_relations_name_restore(NULL)
      for (loop_load in seq_len(length(name_probs))) {
        updateTextAreaInput(session,
          inputId = paste0("textin_name_", loop_load),
          value   = name_probs[loop_load]
        )
      }
      for (loop_load in seq_len(length(name_models))) {
        updateTextAreaInput(session,
          inputId = paste0("textin_relations_name", loop_load),
          value   = name_models[loop_load]
        )
      }
      for (loop_load in seq_len(length(input_models))) {
        updateTextAreaInput(session,
          inputId = paste0("textin_relations_", loop_load),
          value   = input_models[loop_load]
        )
      }
      updateTextAreaInput(session,
        inputId = "add_for_all_models",
        value   = shared_input_model
      )
    })

    # Release the guard well after the restored spec-text boxes have both
    # round-tripped back to the server (400ms delay above) and let the
    # 800ms-debounced auto-detect observer settle on them, so it doesn't
    # fire mid-restore and clobber a just-restored name.
    shinyjs::delay(1600, {
      restoring_upload(FALSE)
      session$sendCustomMessage("fairy_share_done", list())
    })
  })

  #### Function LaTeX ####

  #### Function Plot ####

  # Adds one model's marker + surface trace(s) to a Plot Polytope(s) figure.
  # matrix_pl: data.frame of the model's vertices, already subset to the 3
  # currently-selected plot dimensions. Returns the updated plotly object.
  # Real edges of a convex hull (not the diagonals of its triangulated faces): edges between two facets that are not coplanar.
  hull_edge_lines <- function(pts, hull_faces) {
    nf <- nrow(hull_faces)
    fn <- t(vapply(seq_len(nf), function(i) {
      a <- pts[hull_faces[i, 1], ]; b <- pts[hull_faces[i, 2], ]; cc <- pts[hull_faces[i, 3], ]
      nv <- c((b[2]-a[2])*(cc[3]-a[3]) - (b[3]-a[3])*(cc[2]-a[2]), (b[3]-a[3])*(cc[1]-a[1]) - (b[1]-a[1])*(cc[3]-a[3]), (b[1]-a[1])*(cc[2]-a[2]) - (b[2]-a[2])*(cc[1]-a[1]))
      nv / (sqrt(sum(nv^2)) + 1e-15)
    }, numeric(3)))
    ek <- list()
    for (i in seq_len(nf)) for (e in list(c(1, 2), c(2, 3), c(1, 3))) {
      v <- sort(hull_faces[i, e]); key <- paste(v, collapse = "-")
      ek[[key]] <- c(ek[[key]], i)
    }
    xs <- numeric(0); ys <- numeric(0); zs <- numeric(0)
    for (key in names(ek)) {
      fi <- ek[[key]]
      keep <- length(fi) == 1 || abs(sum(fn[fi[1], ] * fn[fi[2], ])) < 0.9999
      if (!keep) next
      v <- as.integer(strsplit(key, "-")[[1]])
      xs <- c(xs, pts[v, 1], NA); ys <- c(ys, pts[v, 2], NA); zs <- c(zs, pts[v, 3], NA)
    }
    list(x = xs, y = ys, z = zs)
  }
  darker_col <- function(col, f = 0.6) {
    rgbv <- tryCatch(grDevices::col2rgb(col), error = function(e) matrix(c(80, 80, 80), ncol = 1))
    grDevices::rgb(t(rgbv * f), maxColorValue = 255)
  }
  # The 3D polytope plot as a vector graphic (PDF): the traces of the plot (faces, edges, vertices) are projected with the camera
  # the plot is turned to and drawn with base graphics, so the lines and text stay sharp at any size.
  polytope_pdf <- function(file, p, dim_names, camera = NULL, cols = list()) {
    tr <- plotly::plotly_build(p)$x$data
    cam <- camera %||% list(eye = list(x = 1.55, y = 1.55, z = 1.55))
    vec3 <- function(l, d) if (is.null(l)) d else c(l$x, l$y, l$z)
    eye <- vec3(cam$eye, c(1.55, 1.55, 1.55)); ctr <- vec3(cam$center, c(0, 0, 0)); upv <- vec3(cam$up, c(0, 0, 1))
    unit <- function(v) v / sqrt(sum(v^2))
    cross <- function(a, b) c(a[2] * b[3] - a[3] * b[2], a[3] * b[1] - a[1] * b[3], a[1] * b[2] - a[2] * b[1])
    fw <- unit(ctr - eye); rt <- unit(cross(fw, upv)); uu <- cross(rt, fw)
    proj <- function(m) {                                   # data in [0, 1]^3 -> screen x, y and depth
      d <- sweep(m - 0.5, 2, eye, "-")
      dep <- as.vector(d %*% fw)
      cbind(as.vector(d %*% rt) / dep, as.vector(d %*% uu) / dep, dep)
    }
    num <- function(x) suppressWarnings(as.numeric(unlist(x)))
    # the box of the plot
    corners <- as.matrix(expand.grid(x = 0:1, y = 0:1, z = 0:1))
    cube_edges <- NULL
    for (a in 1:7) for (b in (a + 1):8) if (sum(corners[a, ] != corners[b, ]) == 1) cube_edges <- rbind(cube_edges, c(a, b))
    # faces, edges, vertices of the traces
    tris <- list(); segs <- list(); pts <- list(); legend_rows <- list()
    # the colour of a polytope: the model colour (for an overlap the colour of its markers)
    marker_col <- list()
    for (t in tr) if (identical(t$type, "scatter3d") && grepl("markers", as.character(t$mode)[1]) && !is.null(t$marker$color) && is.null(marker_col[[as.character(t$name)]]))
      marker_col[[as.character(t$name)]] <- as.character(t$marker$color)[1]
    for (t in tr) {
      xyz <- cbind(num(t$x), num(t$y), num(t$z))
      if (nrow(xyz) == 0) next
      if (identical(t$type, "mesh3d") && !is.null(t$i)) {
        idx <- cbind(num(t$i), num(t$j), num(t$k)) + 1
        P <- proj(xyz)
        col <- cols[[as.character(t$name)]] %||% marker_col[[as.character(t$name)]] %||% "#999999"
        al <- if (!is.null(t$opacity)) num(t$opacity)[1] else 0.3
        for (r in seq_len(nrow(idx))) {
          v <- idx[r, ]
          tris[[length(tris) + 1]] <- list(x = P[v, 1], y = P[v, 2], depth = mean(P[v, 3]), col = col, alpha = al)
        }
      } else if (identical(t$type, "scatter3d")) {
        P <- proj(xyz)
        mode <- as.character(t$mode)[1]
        if (grepl("lines", mode)) {
          segs[[length(segs) + 1]] <- list(P = P, col = if (!is.null(t$line$color)) as.character(t$line$color)[1] else "#444444",
                                           lwd = if (!is.null(t$line$width)) num(t$line$width)[1] else 3)
        }
        if (grepl("markers", mode)) {
          mc <- if (!is.null(t$marker$color)) as.character(t$marker$color)[1] else "#444444"
          pts[[length(pts) + 1]] <- list(P = P, col = mc, size = if (!is.null(t$marker$size)) num(t$marker$size)[1] else 5)
          if (!isFALSE(t$showlegend) && !is.null(t$name)) legend_rows[[as.character(t$name)]] <- cols[[as.character(t$name)]] %||% mc
        }
      }
    }
    # the drawing area: everything that is drawn, plus room for the axis labels
    xr <- range(proj(corners)[, 1]); yr <- range(proj(corners)[, 2]); pad <- 0.12 * max(diff(xr), diff(yr))
    has_url <- !is.null(tryCatch(isolate(app_share_url()), error = function(e) NULL))
    grDevices::pdf(file, width = 8, height = if (has_url) 7.6 else 7.2)
    on.exit(grDevices::dev.off(), add = TRUE)
    graphics::par(mai = c(if (has_url) 0.4 else 0, 0, 0, 0), family = "sans")
    graphics::plot.new()
    cx <- mean(xr); cy <- mean(yr); half <- max(diff(xr), diff(yr)) / 2 + pad
    graphics::plot.window(xlim = c(cx - half * 1.25, cx + half * 1.25), ylim = c(cy - half, cy + half), asp = 1)
    # the box: the edges that lie in the back are fainter
    Pc <- proj(corners); dmid <- mean(Pc[, 3])
    for (e in seq_len(nrow(cube_edges))) {
      a <- cube_edges[e, 1]; b <- cube_edges[e, 2]
      back <- mean(Pc[c(a, b), 3]) > dmid
      graphics::segments(Pc[a, 1], Pc[a, 2], Pc[b, 1], Pc[b, 2], col = if (back) "#e3e6ee" else "#b8bfcc", lwd = 0.8)
    }
    # faces from the back to the front (the colours of overlapping polytopes blend)
    if (length(tris) > 0) {
      ord <- order(vapply(tris, function(z) z$depth, numeric(1)), decreasing = TRUE)
      for (z in tris[ord]) graphics::polygon(z$x, z$y, col = grDevices::adjustcolor(z$col, alpha.f = z$alpha), border = NA)
    }
    for (s in segs) {
      P <- s$P; na <- which(!is.finite(P[, 1]) | !is.finite(P[, 2])); br <- c(0, na, nrow(P) + 1)
      for (q in seq_len(length(br) - 1)) {
        ii <- seq.int(br[q] + 1, br[q + 1] - 1)
        if (length(ii) >= 2) graphics::lines(P[ii, 1], P[ii, 2], col = s$col, lwd = s$lwd * 0.35)
      }
    }
    for (s in pts) {
      ok <- is.finite(s$P[, 1])
      graphics::points(s$P[ok, 1], s$P[ok, 2], pch = 21, bg = s$col, col = "white", cex = s$size / 6, lwd = 0.5)
    }
    # axes along the outer edges of the box: for every axis the one of its four parallel edges that lies farthest out in the picture
    lab <- function(x) tryCatch(parse(text = gsub("_[{]([^}]*)[}]", "[\\1]", x))[[1]], error = function(e) x)
    # text with a white edge: it stays readable where it lies over lines and faces
    halo_text <- function(x, y, labels, cex, col) {
      h <- 0.006 * half
      for (dx in c(-1, 0, 1)) for (dy in c(-1, 0, 1)) if (dx != 0 || dy != 0) graphics::text(x + dx * h, y + dy * h, labels, cex = cex, col = "white")
      graphics::text(x, y, labels, cex = cex, col = col)
    }
    ctr2 <- proj(matrix(c(0.5, 0.5, 0.5), 1))
    for (ax in 1:3) {
      oth <- setdiff(1:3, ax); best <- NULL; bestd <- -1
      for (u in 0:1) for (v in 0:1) {
        base <- c(0, 0, 0); base[oth] <- c(u, v)
        mid <- base; mid[ax] <- 0.5
        pm <- proj(matrix(mid, 1)); d <- sqrt((pm[1] - ctr2[1])^2 + (pm[2] - ctr2[2])^2)
        if (d > bestd) { bestd <- d; best <- base }
      }
      pm <- proj(matrix(replace(best, ax, 0.5), 1))
      away <- c(pm[1] - ctr2[1], pm[2] - ctr2[2]); away <- away / max(sqrt(sum(away^2)), 1e-9)
      p0 <- proj(matrix(replace(best, ax, 0), 1)); p1 <- proj(matrix(replace(best, ax, 1), 1))
      graphics::segments(p0[1], p0[2], p1[1], p1[2], col = "#7a8397", lwd = 1.1)
      for (tv in seq(0, 1, by = 0.2)) {
        pp <- proj(matrix(replace(best, ax, tv), 1))
        graphics::segments(pp[1], pp[2], pp[1] + 0.02 * half * away[1], pp[2] + 0.02 * half * away[2], col = "#7a8397", lwd = 0.8)
        graphics::text(pp[1] + 0.055 * half * away[1], pp[2] + 0.055 * half * away[2], format(tv), cex = 0.7, col = "#667085")
      }
      graphics::text(pm[1] + 0.15 * half * away[1], pm[2] + 0.15 * half * away[2], lab(dim_names[ax]), cex = 0.95, col = "#1f2430")
    }
    # legend
    if (length(legend_rows) > 0)
      graphics::legend("topright", inset = c(0.01, 0.01), legend = names(legend_rows), pch = 21, pt.bg = unlist(legend_rows), col = "white", pt.cex = 1.1, bty = "n", cex = 0.85)
    lk <- pdf_link_page(8, 7.6)
    invisible(structure(file, link = lk))
  }
  add_model_trace <- function(p, matrix_pl, model_col, name_model,
                               mesh_opacity, mesh_opacity_hull) {
    trace1 <- list(
      mode = "markers",
      type = "scatter3d",
      x = (matrix_pl[, 1]),
      y = (matrix_pl[, 2]),
      z = (matrix_pl[, 3])
    )

    trace2 <- list(
      type = "mesh3d",
      x = (matrix_pl[, 1]),
      y = (matrix_pl[, 2]),
      z = (matrix_pl[, 3]),
      opacity = 0.05,
      alphahull = 0
    )

    ### check dimensionality using principal component analysis

    prcomp_sol <- summary(prcomp(matrix_pl))$importance[2, ]
    shape_point <- ifelse(sum(prcomp_sol != 0) == 1, 1, 0)
    shape_point <- ifelse(nrow(matrix_pl) == 1, 1, shape_point)
    shape_cube <- ifelse(sum(prcomp_sol != 0) == 3, 1, 0)
    shape_cube <- ifelse(shape_point == 1, 0, shape_cube)

    if (shape_point != 1) {
      p <-
        add_trace(
          p,
          mode = trace1$mode,
          type = trace1$type,
          x = trace1$x,
          y = trace1$y,
          z = trace1$z,
          marker = list(color = darker_col(model_col, 0.65), size = 5, line = list(color = darker_col(model_col, 0.4), width = 1)),
          # what the hover box shows: the model, the vertex number and its coordinates
          text = vapply(seq_len(nrow(matrix_pl)), function(r_i) paste0(name_model, " \u00b7 vertex ", r_i, "<br>",
            paste(paste0(gsub("[_{}]", "", colnames(matrix_pl)), " = ", format(round(as.numeric(matrix_pl[r_i, ]), 3), trim = TRUE)), collapse = "<br>")), character(1)),
          hoverinfo = "text",
          name = name_model,
          legendgroup = name_model
        )

      # Plotly's own triangulation (alphahull=0 for the cube case, a
      # per-axis Delaunay stack otherwise) can silently draw nothing or
      # produce wrong/crossing facets for some point sets — the same
      # issue diagnosed and fixed for the overlap-intersection mesh
      # below. Compute the exact convex hull ourselves and hand Plotly
      # explicit face indices, for both shapes, for consistency and
      # correctness; only fall back to the per-axis approximation if
      # the point set is degenerate (e.g. exactly coplanar) and has no
      # true 3D convex hull.
      hull_faces <- tryCatch(
        geometry::convhulln(as.matrix(matrix_pl)),
        error = function(e) NULL
      )
      if (!is.null(hull_faces)) {
        p <-
          add_trace(
            p,
            type = "mesh3d",
            x = trace2$x, y = trace2$y, z = trace2$z,
            i = hull_faces[, 1] - 1, j = hull_faces[, 2] - 1, k = hull_faces[, 3] - 1,
            opacity = if (shape_cube == 1) mesh_opacity else mesh_opacity_hull,
            color = I(model_col),
            # flat faces: with smooth vertex shading the two triangles of one flat side look like separate shapes
            hoverinfo = "skip",
            flatshading = TRUE,
            lighting = list(ambient = 0.85, diffuse = 0.35, specular = 0, roughness = 1, fresnel = 0),
            name = name_model,
            legendgroup = name_model,
            showlegend = FALSE
          )
        # darker edges, drawn through the surface, so the hidden (bottom) edges can be followed too
        edges <- tryCatch(hull_edge_lines(as.matrix(matrix_pl), hull_faces), error = function(e) NULL)
        if (!is.null(edges) && length(edges$x) > 0) {
          p <- add_trace(p, type = "scatter3d", mode = "lines", x = edges$x, y = edges$y, z = edges$z,
            line = list(color = darker_col(model_col), width = 4), hoverinfo = "skip",
            name = name_model, legendgroup = name_model, showlegend = FALSE)
        }
      } else {
        for (d_axis in c("x", "y", "z")) {
          p <-
            add_trace(
              p,
              type = trace2$type,
              x = trace2$x,
              y = trace2$y,
              z = trace2$z,
              opacity = mesh_opacity_hull,
              color = I(model_col),
              alphahull = -1,
              delaunayaxis = d_axis,
              name = name_model,
              legendgroup = name_model,
              showlegend = FALSE
            )
        }
      }
    } else {
      p <-
        add_trace(
          p,
          x = trace1$x,
          y = trace1$y,
          z = trace1$z,
          type = "scatter3d",
          mode = "lines+markers",
          opacity = 1,
          line = list(width = 4, color = model_col),
          marker = list(color = model_col),
          name = name_model,
          legendgroup = name_model
        )
    }
    p
  }

  # Adds the "Highlight model overlaps" traces (intersection markers + hull
  # surface for each currently-plotted pair) to a Plot Polytope(s) figure.
  # Reuses the intersections the user selected in the "Model intersections"
  # modal (already computed as H-descriptions and stored in h_reactive).
  # Only pairs whose BOTH models are currently plotted are drawn. Vertices
  # are enumerated once per set and cached, so changing plot axes does not
  # recompute them.
  add_overlap_traces <- function(p, select_models_to_plot, select_plot, dim_names) {
    int_names_all <- isolate(intersections_reactive$names)
    if (is.null(int_names_all)) int_names_all <- character()

    # keep only intersections whose member models are all plotted
    int_names_plot <- int_names_all[vapply(int_names_all, function(nm) {
      parts <- unlist(str_split(nm, fixed(" AND ")))
      length(parts) >= 2 && all(parts %in% select_models_to_plot)
    }, logical(1))]

    # An intersection that has its own V-description is already drawn by
    # the model loop above; do not draw it a second time as a highlight.
    int_names_plot <- int_names_plot[!(int_names_plot %in% select_models_to_plot)]

    if (length(int_names_plot) == 0) return(p)

    model_key <- paste(sort(int_names_plot), collapse = "|")

    if (!identical(isolate(overlap_cache_reactive$key), model_key)) {
      overlaps <- list()

      for (nm in int_names_plot) {
        H_int <- isolate(h_reactive[[nm]])
        if (is.null(H_int)) next

        V_int <- tryCatch(scdd(H_int)$output, error = function(e) NULL)
        if (is.null(V_int) || nrow(V_int) == 0) next

        overlaps[[length(overlaps) + 1]] <- list(
          name = nm,
          coords = matrix(as.numeric(q2d(V_int[, 3:ncol(V_int)])),
            ncol = ncol(V_int) - 2
          )
        )
      }

      isolate({
        overlap_cache_reactive$coords <- overlaps
        overlap_cache_reactive$empty <- (length(overlaps) == 0)
        overlap_cache_reactive$key <- model_key
      })
    }

    overlaps <- isolate(overlap_cache_reactive$coords)

    if (isTRUE(isolate(overlap_cache_reactive$empty)) || length(overlaps) == 0) return(p)

    # Distinct colour per overlapping pair.
    overlap_pal <- c(
      "#E31A1C", "#FF7F00", "#6A3D9A", "#B15928", "#E7298A",
      "#1F78B4", "#33A02C", "#A6761D", "#666666"
    )
    for (ov_i in seq_along(overlaps)) {
      ov <- overlaps[[ov_i]]
      ov_col <- overlap_pal[((ov_i - 1) %% length(overlap_pal)) + 1]
      int_pl <- data.frame(ov$coords)[, select_plot, drop = FALSE]
      colnames(int_pl) <- dim_names

      p <- add_trace(p,
        type = "scatter3d", mode = "markers",
        x = int_pl[, 1], y = int_pl[, 2], z = int_pl[, 3],
        marker = list(color = ov_col, size = 5),
        name = ov$name, legendgroup = ov$name, showlegend = TRUE
      )
      if (nrow(int_pl) >= 4) {
        # Plotly's own alphahull=0 triangulation can silently fail to
        # draw any surface for some point sets, and a per-axis
        # Delaunay approximation (three stacked 2D triangulations)
        # can produce spurious crossing facets that don't match the
        # true polytope boundary. Compute the exact convex hull
        # ourselves and hand Plotly explicit face indices instead.
        hull_faces <- tryCatch(
          geometry::convhulln(as.matrix(int_pl)),
          error = function(e) NULL
        )
        if (!is.null(hull_faces)) {
          p <- add_trace(p,
            type = "mesh3d",
            x = int_pl[, 1], y = int_pl[, 2], z = int_pl[, 3],
            i = hull_faces[, 1] - 1, j = hull_faces[, 2] - 1, k = hull_faces[, 3] - 1,
            opacity = 0.45, color = I(ov_col),
            flatshading = TRUE,
            lighting = list(ambient = 0.85, diffuse = 0.35, specular = 0, roughness = 1, fresnel = 0),
            name = ov$name, legendgroup = ov$name, showlegend = FALSE
          )
        }
      }
    }
    p
  }

  function_plot <- function(pl_obj, n_submodels) {
    showTab(inputId = "tabs", target = "Plot Polytope(s)")
    showTab(inputId = "tabs", target = "Plot Edge Cases")



    output$plot <- renderPlotly({
      session$sendCustomMessage("fairy_poly_vec", list(on = FALSE))   # only the 3D plot has the vector PDF
      all_v_rep_in_list <- pl_obj

      # name_model_plot is a multi-select picker now (see its own comment
      # in the UI) — already a vector of exact model names, or NULL when
      # nothing is selected, so no splitting on ";" any more.
      models_to_plot <- trimws(as.character(input$name_model_plot))

      names_available_models <- rep(NA, n_submodels)

      matrix_pl_all <- numeric()
      expected_ncol <- NULL

      for (loop_pl in seq_len(n_submodels)) {
        extract_name <- all_v_rep_in_list[[loop_pl]]
        this_name <- extract_name[1, 1]

        all_plot_actual <- all_v_rep_in_list[[loop_pl]]
        all_plot_actual <- all_plot_actual[, 2:ncol(all_plot_actual), drop = FALSE]

        if (is.null(expected_ncol)) {
          expected_ncol <- ncol(all_plot_actual)
          colnames_v_representation_plot_all <- colnames(all_plot_actual)
        } else if (ncol(all_plot_actual) != expected_ncol) {
          # Different parameter-space size than the first available model,
          # so it can't share matrix_pl_all's columns. Leave its name OUT of
          # names_available_models (not just skip adding its rows) — the
          # previous version recorded the name unconditionally above, so an
          # incompatible model could still be picked in "Plot Polytope(s)",
          # pass the models_to_plot filter below, and end up as a 0-row
          # matrix that crashed prcomp()/the hull code downstream.
          next
        }

        names_available_models[loop_pl] <- this_name

        all_plot_actual <- matrix(as.numeric(q2d(unlist(all_plot_actual))), ncol = ncol(all_plot_actual))

        matrix_pl_all <- rbind(
          matrix_pl_all,
          data.frame(names_available_models[loop_pl], (all_plot_actual))
        )
      }

      colnames(matrix_pl_all) <- c("models", colnames_v_representation_plot_all)

      names_available_models_reactive$value <- names_available_models


      select_models_to_plot <- names_available_models[names_available_models %in% models_to_plot]

      matrix_pl_all <- matrix_pl_all[matrix_pl_all[, 1] %in% select_models_to_plot, ]

      # one probability: a line from the smallest to the largest allowed value
      if (length(select_models_to_plot) > 0 && ncol(matrix_pl_all) == 2) {
        runjs("$('#dim_pick_heading').hide(); $('#dim_1, #dim_2, #dim_3').closest('.form-group').hide(); $('#auto_rotate_plot').prop('checked', false).trigger('change'); $('#auto_rotate_plot').closest('.row').hide();")
        pal1 <- c("#E69F00", "#56B4E9", "#009E73", "#D55E00", "#CC79A7", "#0072B2", "#F0E442", "#000000", "#999999")
        ax1 <- plain_axis_name(colnames(matrix_pl_all)[2])
        p1d <- plot_ly(height = 220 + 60 * length(select_models_to_plot))
        for (k1 in seq_along(select_models_to_plot)) {
          nm1 <- select_models_to_plot[k1]; col1 <- pal1[((k1 - 1) %% length(pal1)) + 1]
          vv <- sort(unique(round(as.numeric(matrix_pl_all[matrix_pl_all[, 1] == nm1, 2]), 10)))
          if (length(vv) == 0) next
          yy <- rep(k1, length(vv))
          if (length(vv) >= 2) p1d <- add_trace(p1d, x = range(vv), y = c(k1, k1), type = "scatter", mode = "lines",
            line = list(color = darker_col(col1), width = 8), hoverinfo = "skip", name = nm1, legendgroup = nm1, showlegend = FALSE)
          p1d <- add_trace(p1d, x = vv, y = yy, type = "scatter", mode = "markers",
            marker = list(color = darker_col(col1, 0.65), size = 11, line = list(color = darker_col(col1, 0.4), width = 1)),
            text = paste0(nm1, " \u00b7 vertex ", seq_along(vv), "<br>", ax1, " = ", format(round(vv, 3), trim = TRUE)),
            hoverinfo = "text", name = nm1, legendgroup = nm1)
        }
        return(layout(p1d,
          xaxis = list(title = ax1, range = c(-0.02, 1.02), zeroline = FALSE),
          yaxis = list(tickmode = "array", tickvals = seq_along(select_models_to_plot), ticktext = select_models_to_plot,
            range = c(0.4, length(select_models_to_plot) + 0.6), showgrid = FALSE, zeroline = FALSE, automargin = TRUE, title = ""),
          showlegend = FALSE,
          margin = list(t = 30, b = 50)))
      }

      # two probabilities: a flat picture (polygon, line or point per model) instead of the 3D scene
      if (length(select_models_to_plot) > 0 && ncol(matrix_pl_all) == 3) {
        runjs("$('#dim_pick_heading').show(); $('#dim_1, #dim_2').closest('.form-group').show(); $('#dim_3').closest('.form-group').hide(); $('#auto_rotate_plot').prop('checked', false).trigger('change'); $('#auto_rotate_plot').closest('.row').hide();")
        pal2 <- c("#E69F00", "#56B4E9", "#009E73", "#D55E00", "#CC79A7", "#0072B2", "#F0E442", "#000000", "#999999")
        ax_names <- plain_axis_name(colnames(matrix_pl_all)[2:3])
        p2 <- plot_ly()
        for (k2 in seq_along(select_models_to_plot)) {
          nm2 <- select_models_to_plot[k2]; col2 <- pal2[((k2 - 1) %% length(pal2)) + 1]
          pts <- unique(round(as.matrix(matrix_pl_all[matrix_pl_all[, 1] == nm2, 2:3, drop = FALSE]), 10))
          if (nrow(pts) == 0) next
          p2 <- add_trace(p2, x = pts[, 1], y = pts[, 2], type = "scatter", mode = "markers",
            marker = list(color = darker_col(col2, 0.65), size = 9, line = list(color = darker_col(col2, 0.4), width = 1)),
            text = vapply(seq_len(nrow(pts)), function(r_i) paste0(nm2, " \u00b7 vertex ", r_i, "<br>",
              paste0(ax_names, " = ", format(round(pts[r_i, ], 3), trim = TRUE), collapse = "<br>")), character(1)),
            hoverinfo = "text", name = nm2, legendgroup = nm2)
          if (nrow(pts) >= 3 && qr(sweep(pts, 2, pts[1, ]), tol = 1e-9)$rank == 2) {
            hh2 <- grDevices::chull(pts); hh2 <- c(hh2, hh2[1])
            p2 <- add_trace(p2, x = pts[hh2, 1], y = pts[hh2, 2], type = "scatter", mode = "lines", fill = "toself",
              fillcolor = grDevices::adjustcolor(col2, 0.35), line = list(color = darker_col(col2), width = 2),
              hoverinfo = "skip", name = nm2, legendgroup = nm2, showlegend = FALSE)
          } else if (nrow(pts) >= 2) {
            o2 <- order(pts[, 1], pts[, 2])
            p2 <- add_trace(p2, x = pts[o2, 1], y = pts[o2, 2], type = "scatter", mode = "lines",
              line = list(color = darker_col(col2), width = 3), hoverinfo = "skip", name = nm2, legendgroup = nm2, showlegend = FALSE)
          }
        }
        return(layout(p2,
          xaxis = list(title = ax_names[1], range = c(-0.02, 1.02), constrain = "domain", zeroline = FALSE),
          yaxis = list(title = ax_names[2], range = c(-0.02, 1.02), scaleanchor = "x", scaleratio = 1, constrain = "domain", zeroline = FALSE),
          showlegend = TRUE,   # also for a single model (plotly hides a legend with one entry by itself)
          margin = list(t = 30, b = 50)))
      }

      runjs("$('#dim_pick_heading').show(); $('#dim_1, #dim_2, #dim_3').closest('.form-group').show(); $('#auto_rotate_plot').closest('.row').show();")
      if (length(select_models_to_plot) > 0) {
        plot_cols <- list()
        for (loop_pl in 1:length(select_models_to_plot)) {
          all_plot_actual <- matrix_pl_all[matrix_pl_all[, 1] == select_models_to_plot[loop_pl], 2:ncol(matrix_pl_all)]

          mixture_v_plot_names <- colnames(all_plot_actual)

          name_model <- select_models_to_plot[loop_pl]
          matrix_pl <- data.frame(all_plot_actual)
          colnames(matrix_pl) <- colnames(all_plot_actual)

          # Distinct colour per model + a visible fill opacity, so where two
          # translucent polytopes overlap the colours blend and the shared
          # region reads darker (Plot Polytope overlap cue).
          model_pal <- c(
            "#E69F00", "#56B4E9", "#009E73", "#D55E00", "#CC79A7",
            "#0072B2", "#F0E442", "#000000", "#999999"
          )
          model_col <- model_pal[((loop_pl - 1) %% length(model_pal)) + 1]
          plot_cols[[name_model]] <- model_col
          # Single convex mesh (cube case) can take a moderate opacity; the
          # hull case below stacks THREE meshes (delaunay x/y/z), so it needs a
          # much lower per-mesh opacity to avoid a muddy near-opaque result.
          mesh_opacity <- 0.35
          mesh_opacity_hull <- 0.12

          select_plot <- as.numeric(c(input$dim_1, input$dim_2, input$dim_3))

          updatePickerInput(
            session,
            inputId = "dim_1",
            choices = (1:ncol(matrix_pl))[-select_plot[c(2, 3)]],
            selected = input$dim_1
          )
          updatePickerInput(
            session,
            inputId = "dim_2",
            choices = (1:ncol(matrix_pl))[-select_plot[c(1, 3)]],
            selected = input$dim_2
          )
          updatePickerInput(
            session,
            inputId = "dim_3",
            choices = (1:ncol(matrix_pl))[-select_plot[c(1, 2)]],
            selected = input$dim_3
          )

          matrix_pl <- matrix_pl[, select_plot]


          dim_names <- mixture_v_plot_names[c(
            as.numeric(input$dim_1),
            as.numeric(input$dim_2),
            as.numeric(input$dim_3)
          )]

          colnames(matrix_pl) <- dim_names


          axx <- list(
            nticks = .1,
            range = c(0, 1),
            title = unicode_axis_name(dim_names[1])
          )

          axy <- list(
            nticks = .1,
            range = c(0, 1),
            title = unicode_axis_name(dim_names[2])
          )

          axz <- list(
            nticks = .1,
            range = c(0, 1),
            title = unicode_axis_name(dim_names[3])
          )

          if (loop_pl == 1) {
            p <- plot_ly(
              colors = c("#000000", "#E69F00", "#56B4E9", "#009E73", "#F0E442", "#0072B2", "#D55E00", "#CC79A7", "#999999"),
              height = 800,
              name = name_model
            )
          }

          p <- add_model_trace(p, matrix_pl, model_col, name_model, mesh_opacity, mesh_opacity_hull)
        }

        overlap_note <- NULL
        p <- add_overlap_traces(p, select_models_to_plot, select_plot, dim_names)

        p_out <- p %>% layout(
          annotations = if (!is.null(overlap_note)) {
            list(list(
              text = overlap_note, showarrow = FALSE,
              xref = "paper", yref = "paper", x = 0.5, y = 1,
              font = list(color = "#E31A1C", size = 14)
            ))
          } else {
            list()
          },
          scene = list(
            xaxis = axx,
            yaxis = axy,
            zaxis = axz,
            aspectmode = "manual",
            aspectratio = list(x = 1, y = 1, z = 1),
            # lifted and a little smaller, so the figure and its axis labels do not hang at the lower edge
            domain = list(x = c(0.02, 0.98), y = c(0.14, 0.98)),
            # the view the user had turned the plot to (set from the browser, read without a dependency)
            camera = isolate(input$plot_camera) %||% list(eye = list(x = 1.55, y = 1.55, z = 1.55))
          ),
          # inside the plot area (top left): a legend outside would take width away from the cube, which then
          # moved sideways whenever a model was added or removed
          showlegend = TRUE,   # also for a single model
          legend = list(x = 0.99, y = 0.99, xanchor = "right", yanchor = "top", bgcolor = "rgba(255,255,255,0.6)"),
          margin = list(t = 30, b = 50)
        )
        poly_state(list(p = p_out, dims = dim_names, cols = plot_cols))   # for the vector PDF
        session$sendCustomMessage("fairy_poly_vec", list(on = TRUE))
        p_out
      } else {
        # No models selected (e.g. after clicking "-" to clear the list).
        # A NULL return here would leave the previous plot's stale widget on
        # screen — renderPlotly's htmlwidget binding doesn't clear it the
        # way renderPlot does — so explicitly hand back an empty scene.
        plot_ly(type = "scatter3d", mode = "markers") %>%
          layout(scene = list(
            xaxis = list(range = c(0, 1)),
            yaxis = list(range = c(0, 1)),
            zaxis = list(range = c(0, 1))
          ))
      }
    })
  }


  # A default probability name (e.g. "p_{1}") is valid LaTeX on its own —
  # render it as-is. A user-typed custom label (e.g. "success rate", stored
  # with spaces already turned into underscores) is NOT: math mode renders
  # multi-character names as spaced-out italic variables (each letter
  # treated as its own factor), not as a readable word. Wrap those in
  # \text{...} instead, with underscores turned back into spaces, so they
  # render as the label the user actually typed.
  # Vectorized (ifelse, not if) — every call site so far happened to pass
  # a single name, until the V-representation DT header fix passed a whole
  # column-name vector at once and crashed with "condition has length > 1".
  tex_name <- function(nm) {
    # Items-expanded column names already carry their OWN LaTeX
    # structure — base^{(\text{group},level)}, see cn_factors in
    # build_items_h_core — so only the base portion in front of that
    # structure is a raw probability name that might need \text{}
    # wrapping. The previous version ran the whole string (base AND
    # superscript together) through one check and, for any custom name,
    # wrapped the ENTIRE thing — superscript included — in an outer
    # \text{...}. \text{}'s content is literal text and can't itself
    # contain a nested ^{...}/\text{...} structure, so MathJax failed to
    # parse the result and fell back to showing the raw, unrendered
    # LaTeX source (exactly what got reported for any items-expanded
    # model using custom probability names). Split off the "^{...}"
    # suffix first (if any — a replication name's own outer brace pair,
    # e.g. "{p_{1}}^{(2)}", counts as part of the base, not the suffix,
    # same as the old regex's optional trailing group did), wrap only
    # the base, then reattach the suffix untouched.
    base_of   <- sub("\\^\\{.*$", "", nm)
    suffix_of <- ifelse(grepl("\\^\\{", nm), sub("^[^\\^]+", "", nm), "")
    is_default <- grepl("^\\{?p_\\{[0-9]+\\}\\}?$", base_of)
    base_tex <- ifelse(is_default, base_of, paste0("\\text{", gsub("_", " ", base_of), "}"))
    paste0(base_tex, suffix_of)
  }

  # Same base-name split tex_name uses (an items-expanded column's
  # "^{...}" suffix is which COPY, not which parameter), so every copy
  # of one parameter shares one color regardless of table layout.
  param_base_name <- function(nm) sub("\\^\\{.*$", "", nm)

  # A fixed, colorblind-conscious qualitative palette, cycled by each
  # parameter's position among the app's probabilities — assigns the
  # same color to every occurrence (every item-copy, every model card)
  # of one probability, so e.g. p1 is always the same color whether
  # you're looking at model m1 or m2, not just within one table.
  fairy_param_palette <- c(
    "#2563eb", "#dc2626", "#16a34a", "#d97706", "#9333ea",
    "#0891b2", "#db2777", "#65a30d", "#4f46e5", "#ea580c",
    # more parameters than ten: further colours, all dark enough to read on white (the first ten stay as they were)
    "#0f766e", "#a21caf", "#92400e", "#475569", "#9f1239",
    "#1e3a8a", "#166534", "#a16207", "#0369a1", "#6b21a8",
    "#b45309", "#3f6212", "#be123c", "#134e4a"
  )
  # global_order: the app's full, current list of probability names (in
  # their display order) — when given, color is keyed by each name's
  # position in THAT list, so it's shared across every model/table.
  # Falls back to per-table position (old behavior) when omitted, so any
  # caller that hasn't been updated to pass it still works.
  param_color_map <- function(p_names, global_order = NULL) {
    base <- param_base_name(p_names)
    if (!is.null(global_order) && length(global_order) > 0) {
      idx <- match(base, global_order)
      missing <- which(is.na(idx))
      if (length(missing) > 0) {
        extra_uniq <- unique(base[missing])
        idx[missing] <- length(global_order) + match(base[missing], extra_uniq)
      }
      return(setNames(fairy_param_palette[((idx - 1) %% length(fairy_param_palette)) + 1], NULL))
    }
    uniq <- unique(base)
    pal  <- fairy_param_palette[((seq_along(uniq) - 1) %% length(fairy_param_palette)) + 1]
    setNames(pal[match(base, uniq)], NULL)
  }

  # Plain-text (NOT LaTeX) column-name label, for contexts that cannot
  # render LaTeX at all — e.g. a plotly axis, which just prints tex_name's
  # raw "\text{...}" source literally instead of typesetting it, since
  # plotly text has no MathJax pass the way the H-rep tables do. Turns
  # "p_{1}^{(\text{g},1)}" into "p1 [g #1]", or "p_{1}" alone into "p1";
  # a SOLO factor (group label == the probability's own name) collapses
  # to "p1 (copy 1)" instead of repeating the name in brackets. Peels the
  # suffix apart with plain string stripping rather than one regex with a
  # nested capture group — a DEFAULT probability name is itself "p_{i}",
  # so a solo factor's group label contains its own {}'s (e.g.
  # "...^{(\text{p_{1}},1)}"), which a single "stop at the first }"
  # capture group cannot see past (confirmed directly: it silently
  # returned "p_1" for every copy instead of "p_1 (copy 1)"/"(copy 2)").
  plain_axis_name <- function(nm) {
    # plotly tick text understands <sub>/<sup>: p_{2}^{(1)} reads like the H-description, p<sub>2</sub><sup>(1)</sup>
    sub_p <- function(b) {
      # only the default names p_{1}; a typed name such as success_rate keeps its underscore
      if (grepl("^[^_]+_\\{[^}]+\\}$", b)) return(sub("^([^_]+)_\\{([^}]+)\\}$", "\\1<sub>\\2</sub>", b))
      b <- gsub("[{}]", "", b)
      if (grepl("^[A-Za-z]+[0-9]+$", b)) return(sub("^([A-Za-z]+)([0-9]+)$", "\\1<sub>\\2</sub>", b))
      b
    }
    vapply(nm, function(x) {
      if (!grepl("\\^\\{", x)) return(sub_p(x))
      # current items columns: "p_{1}^{(2)}" -> p<sub>1</sub><sup>(2)</sup>
      if (grepl("^.*\\^\\{\\([0-9]+\\)\\}$", x))
        return(paste0(sub_p(sub("\\^\\{.*$", "", x)), "<sup>(", sub("^.*\\^\\{\\(([0-9]+)\\)\\}$", "\\1", x), ")</sup>"))
      base_of    <- sub("\\^\\{.*$", "", x)
      base_plain <- gsub("[{}]", "", base_of)
      # Strip the fixed "^{(\text{" prefix and ")}" suffix that wrap
      # every items-expanded column (see cn_factors), leaving just
      # "GROUP},LEVEL" — GROUP may still carry its own {}'s (a default
      # probability name), LEVEL never does, so split on the LAST comma.
      inner   <- sub("^\\^\\{\\(\\\\text\\{", "", sub("^[^\\^]+", "", x))
      inner   <- sub("\\)\\}$", "", inner)
      lev     <- sub(".*,([0-9]+)$", "\\1", inner)
      grp     <- gsub("[{}]", "", sub("\\}$", "", sub(",[0-9]+$", "", inner)))
      if (identical(grp, base_plain)) paste0(sub_p(base_of), "<sup>(", lev, ")</sup>")
      else paste0(sub_p(base_of), " [", grp, " #", lev, "]")
    }, character(1), USE.NAMES = FALSE)
  }

  # 3D scene titles are drawn by WebGL, which shows <sub>/<sup> tags literally: use the Unicode characters there
  unicode_axis_name <- function(nm) {
    sub_d <- c("0" = "\u2080", "1" = "\u2081", "2" = "\u2082", "3" = "\u2083", "4" = "\u2084", "5" = "\u2085", "6" = "\u2086", "7" = "\u2087", "8" = "\u2088", "9" = "\u2089")
    sup_d <- c("0" = "\u2070", "1" = "\u00b9", "2" = "\u00b2", "3" = "\u00b3", "4" = "\u2074", "5" = "\u2075", "6" = "\u2076", "7" = "\u2077", "8" = "\u2078", "9" = "\u2079", "(" = "\u207d", ")" = "\u207e")
    conv <- function(x, tag, map) {
      m <- gregexpr(paste0("<", tag, ">[^<]*</", tag, ">"), x)
      regmatches(x, m) <- lapply(regmatches(x, m), function(parts) vapply(parts, function(p) {
        ch <- strsplit(gsub("</?[a-z]+>", "", p), "")[[1]]
        paste(ifelse(ch %in% names(map), map[ch], ch), collapse = "")
      }, character(1)))
      x
    }
    vapply(plain_axis_name(nm), function(x) conv(conv(x, "sub", sub_d), "sup", sup_d), character(1), USE.NAMES = FALSE)
  }

  # Long decimals like 0.333333333333333 (from thirds, etc.) are hard to
  # read — show them as simplified fractions instead, same convention the
  # H-representation table itself already uses (MASS::fractions). Defined
  # via num2str_lin (declared below in this same server scope, safe to
  # reference here since neither is called until the app is live) so both
  # share its guard against fractions() silently rounding tiny values to 0.
  # round() here is only meant to clean up floating-point noise from LP/
  # rational-arithmetic round-trips (e.g. 0.49999999999997 -> 0.5), not to
  # limit precision — 8 digits was tight enough to truncate a genuinely
  # typed value like 0.000000001 to exactly 0 before num2str_lin ever saw
  # it. 12 digits comfortably clears normal floating-point noise while
  # still preserving values down to ~1e-11.
  frac_str <- function(x) trimws(num2str_lin(round(x, 12)))

  #### Model Properties Table ####

  # LP-based nesting: is every point of H_a also in H_b?
  nesting_lp <- function(H_a, H_b) {
    H_a_ch <- H_a   # already a rational character matrix from rcdd
    attr(H_a_ch, "representation") <- "H"
    H_b_n  <- q2d(H_b)
    dvec0   <- rep("0", ncol(H_a_ch) - 2L)
    feas_a <- tryCatch(lpcdd(H_a_ch, dvec0)$solution.type, error = function(e) "Error")
    if (feas_a == "Inconsistent" || feas_a == "Error") return(NA)

    for (j in seq_len(nrow(H_b_n))) {
      a_j   <- as.numeric(H_b_n[j, 3:ncol(H_b_n)])
      dvec  <- as.vector(d2q(matrix(a_j, nrow = 1)))
      res   <- tryCatch(lpcdd(H_a_ch, dvec), error = function(e) NULL)
      if (is.null(res) || res$solution.type %in% c("Inconsistent", "Error")) return(NA)
      if (res$solution.type != "Optimal") next
      min_val <- H_b_n[j, 2] + q2d(res$optimal.value)
      if (H_b_n[j, 1] == 0 && min_val < -1e-8) return(FALSE)
      if (H_b_n[j, 1] == 1) {
        if (min_val < -1e-8) return(FALSE)
        res2 <- tryCatch(lpcdd(H_a_ch, as.vector(d2q(matrix(-a_j, nrow = 1)))), error = function(e) NULL)
        if (!is.null(res2) && res2$solution.type == "Optimal" &&
            H_b_n[j, 2] - q2d(res2$optimal.value) > 1e-8) return(FALSE)
      }
    }
    TRUE
  }

  # Combine every model the user has defined — base, replication, and
  # multi-item, plus their intersections/mixtures — into the single list
  # that feeds ONE comparison table. This mirrors Table 3 in the paper,
  # which spans all ten of its models at once: pairs that share a
  # parameter space get a real relationship (⊂/⊃/∩/XD/=/∅), pairs that
  # don't (e.g. a 3-parameter base model vs. an 18-parameter replication)
  # show ≠dim in that cell, per build_comp_html's own compatibility check
  # — there was previously no reason to physically split these into three
  # separate table widgets, since build_comp_html already handles
  # incompatible pairs cell-by-cell rather than needing pre-grouping.
  # Deliberately NOT isolated: called both from reactive contexts (the
  # comparison table and the stale-warning check below, which both need
  # to re-run when the model list changes) and from inside observeEvent
  # handlers (which Shiny already isolates the body of automatically, so
  # no extra dependencies leak in there). Wrap in isolate() explicitly at
  # any call site that specifically wants a frozen snapshot instead.
  all_comparison_model_names <- function() {
    all_int <- intersections_reactive$names
    all_int <- all_int[!is.na(all_int) & nchar(all_int) > 0]
    all_mix <- mixtures_reactive$names
    all_mix <- all_mix[!is.na(all_mix) & nchar(all_mix) > 0]
    nms <- c(
      names_models_reactive$value,
      items_reactive$names,
      all_int, all_mix
    )
    unique(nms[!is.na(nms) & nchar(nms) > 0])
  }

  #### Normalise a linear in/equality ####
  # Rewrites ANY linear constraint into the canonical form
  #   c1*p1 + c2*p2 + ... <op> constant
  # so users no longer have to keep constants on one side or avoid
  # parentheses. Works by evaluating each side as a linear function:
  # the constant is f(0) and the coefficient of p_i is f(e_i) - f(0).
  # Anything that cannot be evaluated is returned untouched, so unusual
  # input still falls through to the original parser.

  # ---- exact fractions (same code as the package, pkg/R/exact.R) ----
  # A typed number such as 1/3 or 0.0001 stays an exact fraction up to rcdd; going through a floating-point number would round it.
  # one decimal number or a fraction of two ("0.25", ".5", "12", "3/8", "0.1/0.3", optionally with a sign) as an exact rational
  # string; NA when the text is anything else
  q_from_text <- function(s) {
    num <- "[0-9]+\\.?[0-9]*|\\.[0-9]+"
    m <- regmatches(s, regexec(paste0("^([+-]?)(", num, ")(/(", num, "))?$"), s))[[1]]
    if (length(m) == 0) return(NA_character_)
    dec <- function(x) {
      parts <- strsplit(x, ".", fixed = TRUE)[[1]]
      int <- if (length(parts) >= 1 && nzchar(parts[1])) parts[1] else "0"
      frac <- if (length(parts) >= 2) parts[2] else ""
      # "x." gives one part only; "x.y" gives two
      if (!nzchar(frac)) return(sub("^0+(?=[0-9])", "", int, perl = TRUE))
      n <- sub("^0+(?=[0-9])", "", paste0(int, frac), perl = TRUE)
      paste0(n, "/1", strrep("0", nchar(frac)))
    }
    v <- dec(m[3])
    if (nzchar(m[5])) {
      d <- dec(m[5])
      if (qsign(q2q(d)) == 0) return(NA_character_)
      v <- qdq(q2q(v), q2q(d))
    } else {
      v <- q2q(v)
    }
    if (identical(m[2], "-")) v <- qneg(v)
    v
  }

  # exact negation of a matrix/vector of rational strings, keeping its shape
  qneg_m <- function(x) {
    y <- qneg(as.character(x))
    dim(y) <- dim(x); dimnames(y) <- dimnames(x)
    y
  }

  # a double (e.g. a tolerance typed as number) as the exact rational of its shortest decimal text, 0.05 -> 1/20
  q_from_number <- function(x) {
    r <- q_from_text(format(x, scientific = FALSE, digits = 15, trim = TRUE))
    if (is.na(r)) d2q(x) else r
  }

  # Linear form of an expression with exact coefficients: list(a = rational per probability, c = rational constant).
  # NULL when the expression is not linear (or not understood); then the caller keeps the text as it is.
  linear_form <- function(s, n_p) {
    s <- gsub("[[:space:]]", "", s)
    chars <- strsplit(s, "")[[1]]
    pos <- 1L
    nch <- length(chars)
    peek <- function() if (pos <= nch) chars[pos] else ""
    zero <- function() list(a = rep("0", n_p), c = "0")
    is_const <- function(f) all(f$a == "0")
    add <- function(f, g, sign = 1) {
      op <- if (sign > 0) qpq else qmq
      list(a = op(f$a, g$a), c = op(f$c, g$c))
    }
    scale <- function(f, k) list(a = qxq(f$a, rep(k, n_p)), c = qxq(f$c, k))
    fail <- function() stop("not linear", call. = FALSE)

    expr <- function() {
      f <- term()
      while (peek() %in% c("+", "-")) {
        op <- peek(); pos <<- pos + 1L
        g <- term()
        f <- add(f, g, if (op == "+") 1 else -1)
      }
      f
    }
    term <- function() {
      f <- factor_()
      while (peek() %in% c("*", "/")) {
        op <- peek(); pos <<- pos + 1L
        g <- factor_()
        if (op == "*") {
          if (is_const(g)) f <- scale(f, g$c)
          else if (is_const(f)) f <- scale(g, f$c)
          else fail()
        } else {
          if (!is_const(g) || qsign(g$c) == 0) fail()
          f <- scale(f, qinv(g$c))
        }
      }
      f
    }
    factor_ <- function() {
      ch <- peek()
      if (ch == "+") { pos <<- pos + 1L; return(factor_()) }
      if (ch == "-") { pos <<- pos + 1L; return(scale(factor_(), "-1")) }
      if (ch == "(") {
        pos <<- pos + 1L
        f <- expr()
        if (peek() != ")") fail()
        pos <<- pos + 1L
        return(f)
      }
      if (ch == "p") {
        pos <<- pos + 1L
        st <- pos
        while (grepl("^[0-9]$", peek())) pos <<- pos + 1L
        if (pos == st) fail()
        i <- as.integer(paste(chars[st:(pos - 1L)], collapse = ""))
        if (i < 1L || i > n_p) fail()
        f <- zero(); f$a[i] <- "1"
        return(f)
      }
      st <- pos
      while (grepl("^[0-9.]$", peek())) pos <<- pos + 1L
      if (pos == st) fail()
      v <- q_from_text(paste(chars[st:(pos - 1L)], collapse = ""))
      if (is.na(v)) fail()
      f <- zero(); f$c <- v
      f
    }
    tryCatch({
      f <- expr()
      if (pos <= nch) NULL else f
    }, error = function(e) NULL)
  }

  num2str_lin <- function(x) {
    if (!is.finite(x)) return(format(x, scientific = FALSE, trim = TRUE))
    if (x == round(x)) return(format(x, scientific = FALSE, trim = TRUE))
    fr <- attr(fractions(x), "fracs")
    # fractions()'s continued-fraction approximation has a limited
    # denominator search and silently rounds values it can't represent
    # well (e.g. 0.000001 -> "0") instead of erroring — always verify the
    # approximation actually reproduces x before trusting it, or a small
    # typed constant gets corrupted to 0.
    if (!is.null(fr) && length(fr) == 1 && !is.na(fr)) {
      fr_val <- tryCatch(eval(parse(text = as.character(fr))), error = function(e) NA_real_)
      # A RELATIVE check, not all.equal()'s absolute tolerance — an
      # absolute 1e-9 tolerance is meaningless once x itself is near 1e-9
      # (comparing 0 vs 1e-9 "passes" an absolute-1e-9 check even though
      # it's 100% wrong), so this must scale with the magnitude of x.
      rel_ok <- if (!is.na(fr_val)) {
        if (x == 0) fr_val == 0 else abs(fr_val - x) / abs(x) < 1e-8
      } else FALSE
      if (rel_ok) {
        # as.character() writes large denominators as 1e+05, which the parser does not read: write them out in full
        fr_txt <- as.character(fr)
        if (grepl("e", fr_txt, fixed = TRUE)) fr_txt <- paste(format(as.numeric(strsplit(fr_txt, "/", fixed = TRUE)[[1]]), scientific = FALSE, trim = TRUE), collapse = "/")
        return(fr_txt)
      }
    }
    format(x, scientific = FALSE, trim = TRUE, digits = 15)
  }

  # numeric version (probing with doubles): only for what the exact reader above does not understand (1e-3, sqrt(2), pi, ...)
  normalize_constraint_numeric <- function(cstr, n_p) {
    if (is.na(cstr) || cstr == "") return(cstr)

    # the app treats "<" as "<=", so >=/<= collapse onto >/<
    cstr <- str_replace_all(cstr, ">=|=>", ">")
    cstr <- str_replace_all(cstr, "<=|=<", "<")

    # only single-relation constraints (chains are split earlier)
    if (str_count(cstr, "<|>|=") != 1) return(cstr)

    op <- str_extract(cstr, "<|>|=")
    sides <- str_split_fixed(cstr, "<|>|=", 2)
    lhs <- sides[1]
    rhs <- sides[2]
    if (lhs == "" || rhs == "") return(cstr)

    ev <- function(s, vals) {
      env <- as.list(vals)
      names(env) <- paste0("p", seq_along(vals))
      tryCatch(as.numeric(eval(parse(text = s), envir = env)),
        error = function(e) NA_real_, warning = function(w) NA_real_
      )
    }

    # a value is usable only if it is a single finite number; 1/(p1+p2) at
    # p = 0 yields Inf, which must NOT be treated as a valid evaluation
    ok_num <- function(x) length(x) == 1 && !is.na(x) && is.finite(x)

    # probe points: 0 and two generic interior points. Using non-zero probes
    # keeps expressions such as 1/(p1+p2) from being evaluated only at a pole.
    zero <- rep(0, n_p)
    base <- rep(0.25, n_p)

    c_l <- ev(lhs, zero)
    c_r <- ev(rhs, zero)
    if (!ok_num(c_l) || !ok_num(c_r)) return(cstr)

    coef <- numeric(n_p)
    for (i in seq_len(n_p)) {
      e_i <- zero
      e_i[i] <- 1
      a <- ev(lhs, e_i)
      b <- ev(rhs, e_i)
      if (!ok_num(a) || !ok_num(b)) return(cstr)
      coef[i] <- (a - c_l) - (b - c_r)
    }

    # verify linearity: the difference must scale exactly with the step size,
    # both at a doubled step and around a shifted base point
    for (i in seq_len(n_p)) {
      e_i <- zero
      e_i[i] <- 2
      a <- ev(lhs, e_i)
      b <- ev(rhs, e_i)
      if (!ok_num(a) || !ok_num(b)) return(cstr)
      d2 <- ((a - c_l) - (b - c_r)) - 2 * coef[i]
      if (!ok_num(d2) || abs(d2) > 1e-9) return(cstr)

      f_l <- ev(lhs, base)
      f_r <- ev(rhs, base)
      s_i <- base
      s_i[i] <- s_i[i] + 1
      g_l <- ev(lhs, s_i)
      g_r <- ev(rhs, s_i)
      if (!ok_num(f_l) || !ok_num(f_r) || !ok_num(g_l) || !ok_num(g_r)) return(cstr)
      d3 <- ((g_l - f_l) - (g_r - f_r)) - coef[i]
      if (!ok_num(d3) || abs(d3) > 1e-9) return(cstr)
    }

    if (all(coef == 0)) return(cstr)

    terms <- paste0(
      ifelse(coef >= 0, "+", "-"),
      vapply(abs(coef), num2str_lin, character(1)),
      "*p", seq_len(n_p)
    )

    paste0(paste(terms, collapse = ""), op, num2str_lin(c_r - c_l))
  }

  normalize_constraint <- function(cstr, n_p) {
    if (is.na(cstr) || cstr == "") return(cstr)

    # the app treats "<" as "<=", so >=/<= collapse onto >/<
    cstr <- str_replace_all(cstr, ">=|=>", ">")
    cstr <- str_replace_all(cstr, "<=|=<", "<")

    # only single-relation constraints (chains are split earlier)
    if (str_count(cstr, "<|>|=") != 1) return(cstr)

    op <- str_extract(cstr, "<|>|=")
    sides <- str_split_fixed(cstr, "<|>|=", 2)
    lhs <- sides[1]
    rhs <- sides[2]
    if (lhs == "" || rhs == "") return(cstr)

    # exact linear forms of both sides; anything that is not linear (or not understood) is returned untouched,
    # so unusual input still falls through to the original parser
    l <- linear_form(lhs, n_p)
    r <- linear_form(rhs, n_p)
    if (is.null(l) || is.null(r)) return(normalize_constraint_numeric(cstr, n_p))

    coef <- qmq(l$a, r$a)
    const <- qmq(r$c, l$c)
    if (all(coef == "0")) return(cstr)

    terms <- paste0(ifelse(qsign(coef) >= 0, "+", "-"), qabs(coef), "*p", seq_len(n_p))
    paste0(paste(terms, collapse = ""), op, const)
  }

  # TRUE when a single constraint contains a probability but is NOT linear in
  # the p's (e.g. "1/(p1+p3) > p2"). Used to name the offending constraint in
  # the error message instead of showing a generic example.
  is_nonlinear_constraint <- function(cstr, n_p) {
    if (is.na(cstr) || cstr == "") return(FALSE)
    if (!str_detect(cstr, "p[0-9]")) return(FALSE)
    if (str_count(cstr, "<|>|=") != 1) return(FALSE)
    identical(normalize_constraint(cstr, n_p), cstr)
  }

  # Splits a raw model specification the same way extract_info does, so the
  # error message can point at the exact constraint that failed.
  split_spec <- function(spec) {
    s <- str_replace_all(spec, "\n", ";")
    chars <- unlist(str_split(s, ""))
    depth <- 0
    for (i in seq_along(chars)) {
      if (chars[i] == "{") depth <- depth + 1
      if (chars[i] == "}") depth <- depth - 1
      if (chars[i] == "," && depth <= 0) chars[i] <- ";"
    }
    parts <- unlist(str_split(paste(chars, collapse = ""), ";"))
    parts <- trimws(parts)
    parts[parts != ""]
  }

  # How many H-representation rows ONE typed clause turns into, mirroring
  # (not calling — this is purely predictive, for the display below; the
  # real computation still goes through extract_info() untouched) the two
  # ways extract_info() expands a single clause into several rows:
  #   - a chained comparison ("p1>p2>p3") into one row per adjacent pair
  #     (here: "p1>p2", "p2>p3")
  #   - a "{p1,p2}>{p3,p4}" batch shortcut into one row per pair across
  #     the two sets (here: 2*2 = 4 rows)
  # ...and both together ("{p1,p2}>{p3}>{p4}"): chained first, each
  # resulting pair batch-expanded on its own, exactly like extract_info()
  # itself does (chain-split happens before batch-expansion there too).
  clause_expected_row_count <- function(clause) {
    clause <- norm_ops(clause)
    pc <- pure_prob_chain(clause)
    if (!is.null(pc)) return(sum(vapply(chain_pair_clauses(pc), clause_expected_row_count, integer(1))))
    op_pos <- gregexpr("[=><]", clause)[[1]]
    if (op_pos[1] == -1) return(1L)
    args <- strsplit(clause, "[=><]")[[1]]
    if (length(args) < 2) return(1L)
    ops <- regmatches(clause, gregexpr("[=><]", clause))[[1]]
    side_factor <- function(side) {
      side <- trimws(side)
      if (grepl("^\\{", side)) {
        length(unlist(strsplit(gsub("[{} ]", "", side), ",")))
      } else 1L
    }
    total <- 0L
    for (k in seq_len(length(args) - 1)) {
      total <- total + side_factor(args[k]) * side_factor(args[k + 1])
    }
    total
  }

  # Same expansion as clause_expected_row_count, but returns the actual
  # atomic sub-clauses instead of just a count — e.g. "p1=p4=0" becomes
  # c("p1=p4", "p4=0"), "{p1,p2}=p3" becomes c("p1=p3", "p2=p3"). Used to
  # enumerate a model's "=" occurrences in the SAME order/count
  # extract_info() actually produces H-representation rows in, rather than
  # naive one-per-semicolon-clause — a chain like "p1=p4=0" is ONE typed
  # clause but TWO real equality rows, and every equality after it in the
  # spec shifts by however many extra rows the chain added. Both the
  # equality-tolerance popup (equality_tolerances_reactive, keyed by this
  # per-row occurrence index) and the "=" -> "≈" display substitution
  # (equality_flags_str, one flag per literal "=" character the client
  # substitutes) need this same per-row enumeration to stay aligned with
  # what the Go pipeline's all_operators actually iterates over — see the
  # bug this fixed: a model with a chained "=" clause silently applied an
  # approximate-equality tolerance to the WRONG (or no) later equality,
  # because the popup was counting raw semicolon-clauses instead of rows.
  # A chain of three or more plain probabilities joined by "=" only (p1=p2=p3): returns the
  # probabilities, otherwise NULL. Such a chain stands for ALL its pairs (p1=p2, p1=p3, p2=p3),
  # so that each pair can get its own tolerance whatever order the user typed them in.
  # members of one side of a clause: "{p1,p2}" -> p1, p2; anything else is one term
  # ">=" and "<=" (and the symbols) mean the same as ">" and "<" here, which the app shows as ≥ and ≤
  norm_ops <- function(x) {
    x <- gsub("\u2265", ">", x, fixed = TRUE); x <- gsub("\u2264", "<", x, fixed = TRUE)
    gsub("<=", "<", gsub(">=", ">", x, fixed = TRUE), fixed = TRUE)
  }
  chain_side_items <- function(side) {
    side <- trimws(side)
    if (grepl("^\\{", side)) unlist(strsplit(gsub("[{} ]", "", side), ",")) else side
  }
  chain_is_number <- function(x) grepl("^-?([0-9]+\\.?[0-9]*|\\.[0-9]+)(/[0-9]+)?$", x)
  # A clause in which three or more terms are joined by "=" (also with comparison signs elsewhere in the clause,
  # and with terms like 2*p1, p1+p2 or {p1,p2}): returns its terms and signs, otherwise NULL.
  pure_prob_chain <- function(clause) {
    clause <- norm_ops(clause)
    if (!grepl("=", clause)) return(NULL)
    terms <- trimws(strsplit(clause, "[=<>]")[[1]])
    ops <- regmatches(clause, gregexpr("[=<>]", clause))[[1]]
    if (length(terms) < 3 || length(ops) != length(terms) - 1 || any(!nzchar(terms))) return(NULL)
    # needs a run of at least three terms joined by "=" only (the part that stands for all its pairs)
    runs <- rle(ops == "=")
    if (!any(runs$values & runs$lengths >= 2)) return(NULL)
    list(terms = terms, ops = ops)
  }
  # all clauses of such a clause: every pair inside a run of "=", and the comparison signs between the runs as before
  chain_pair_clauses <- function(pc) {
    terms <- pc$terms; ops <- pc$ops; n <- length(terms)
    out <- character(0); i <- 1L
    while (i <= n) {
      j <- i
      while (j < n && ops[j] == "=") j <- j + 1L
      run <- terms[i:j]
      if (length(run) >= 3) {
        mem <- unlist(lapply(run, chain_side_items))
        pr <- utils::combn(length(mem), 2)
        keep <- !(chain_is_number(mem[pr[1, ]]) & chain_is_number(mem[pr[2, ]]))   # number = number says nothing
        out <- c(out, paste0(mem[pr[1, keep]], "=", mem[pr[2, keep]]))
      } else if (length(run) == 2) {
        out <- c(out, paste0(run[1], "=", run[2]))
      }
      if (j < n) out <- c(out, paste0(terms[j], ops[j], terms[j + 1]))
      i <- j + 1L
    }
    out
  }
  # "p1=p2" and "p2=p1" are the same equality, "p1=p1" says nothing: such rows are left out (inequalities stay as they are)
  eq_row_key <- function(row) {
    pr <- trimws(strsplit(row, "=", fixed = TRUE)[[1]])
    if (length(pr) != 2) return(NA_character_)
    paste(sort(pr), collapse = "=")
  }
  dedupe_eq_rows <- function(rows) {
    is_eq <- grepl("=", rows) & !grepl("[<>]", rows)
    keys <- vapply(rows, eq_row_key, character(1), USE.NAMES = FALSE)
    trivial <- is_eq & vapply(rows, function(r) { p <- trimws(strsplit(r, "=", fixed = TRUE)[[1]]); length(p) == 2 && p[1] == p[2] }, logical(1), USE.NAMES = FALSE)
    dup <- is_eq & !is.na(keys) & duplicated(ifelse(is_eq, keys, NA_character_))
    rows[!(trivial | dup)]
  }
  # every equality of a specification text, one per row, without duplicates: this is the list the tolerances belong to
  spec_eq_rows <- function(spec) {
    raw <- trimws(unlist(strsplit(spec %||% "", ";")))
    rows <- unlist(lapply(raw[nzchar(raw)], expand_clause_to_rows))
    rows <- rows[grepl("=", rows) & !grepl("[<>]", rows)]
    dedupe_eq_rows(rows)
  }
  # the same chain expanded for the text the pipeline reads: "p1=p2=p3" -> "p1=p2; p1=p3; p2=p3"
  expand_equality_chains <- function(spec) {
    if (is.null(spec) || length(spec) == 0 || !nzchar(spec)) return(spec)
    spec <- norm_ops(spec)
    if (!grepl("=", spec, fixed = TRUE)) return(spec)
    raw <- trimws(unlist(strsplit(spec, ";", fixed = TRUE)))
    rows <- dedupe_eq_rows(unlist(lapply(raw[nzchar(raw)], expand_clause_to_rows)))
    paste(rows, collapse = "; ")
  }

  expand_clause_to_rows <- function(clause) {
    clause <- norm_ops(clause)
    pc <- pure_prob_chain(clause)
    if (!is.null(pc)) return(unlist(lapply(chain_pair_clauses(pc), expand_clause_to_rows)))
    op_pos <- gregexpr("[=><]", clause)[[1]]
    if (op_pos[1] == -1) return(clause)
    args <- strsplit(clause, "[=><]")[[1]]
    if (length(args) < 2) return(clause)
    ops <- regmatches(clause, gregexpr("[=><]", clause))[[1]]
    side_items <- function(side) {
      side <- trimws(side)
      if (grepl("^\\{", side)) unlist(strsplit(gsub("[{} ]", "", side), ",")) else side
    }
    segs <- character()
    for (k in seq_len(length(args) - 1)) {
      b1 <- side_items(args[k])
      b2 <- side_items(args[k + 1])
      for (a in b1) for (b in b2) segs <- c(segs, paste0(a, ops[k], b))
    }
    segs
  }

  # Which of a model's typed clauses (in the exact order split_spec()
  # returns them for its full "Model Specification" text) turned out
  # logically redundant — built on the raw-H/redundant()-index capture
  # already done in the Go pipeline (see h_raw_rows_reactive, mixed_eq_ineq's
  # own comment). A clause that expanded into several H-rep rows (a chain
  # or a batch shortcut, see clause_expected_row_count) counts as
  # redundant only if EVERY row it produced did — a partially-redundant
  # chain still asserts something new overall. Returns NULL — meaning
  # "don't highlight anything for this model" — whenever the mapping from
  # row index back to typed-clause index can't be trusted:
  #   - no H-representation captured yet for this model (h_raw_rows_reactive
  #     empty — Go hasn't run since this spec last changed)
  #   - equalities and inequalities were mixed (makeH() reorders rows then,
  #     see mixed_eq_ineq)
  #   - the PREDICTED row count (summed per clause) doesn't match the raw
  #     row count actually attributable to the user — most likely a
  #     trivial "p1<p1" clause silently dropped by extract_info's own
  #     cleanup step, which this predictive count doesn't know about
  # Deliberately silent/no-highlight rather than guessing in these cases —
  # a wrong red clause is worse than none.
  model_redundant_clause_flags <- function(model_name, spec_text) {
    info <- h_raw_rows_reactive[[model_name]]
    if (is.null(info) || isTRUE(info$mixed_eq_ineq)) return(NULL)
    n_user <- info$n_user_clauses
    if (is.null(n_user) || is.na(n_user) || n_user <= 0) return(NULL)
    clauses <- split_spec(spec_text %||% "")
    if (length(clauses) != n_user) return(NULL)
    n_p <- ncol(info$raw_H) - 2L
    user_row_count <- nrow(info$raw_H) - 2L * n_p
    row_counts <- vapply(clauses, clause_expected_row_count, integer(1))
    if (sum(row_counts) != user_row_count) return(NULL)
    is_redundant_row <- logical(user_row_count)
    is_redundant_row[info$redundant_rows[info$redundant_rows >= 1 & info$redundant_rows <= user_row_count]] <- TRUE
    # One flag per actual H-rep ROW, not collapsed to one per typed
    # clause — a shortcut clause ("{p1}>{p2,p3,p5}") expands to several
    # rows that don't all have to be redundant together: if only its
    # "p1>p2" row duplicates a later plain clause, that ROW should be
    # markable on its own. Collapsing to all-rows-in-this-clause-must-
    # agree (the old behavior) hid exactly that — when a shortcut's
    # rows and separately-typed duplicate rows split which one rcdd
    # actually flags as removable, NEITHER clause passed the all-or-
    # nothing test, so nothing lit up despite a genuine duplicate. The
    # client-side display (which independently expands the same
    # shortcuts for rendering — see expandBatchShortcut in the model
    # spec display script) now zips 1:1 against this per-row vector
    # instead of re-deriving a clause-to-row mapping of its own.
    is_redundant_row
  }

  #### Function to extract In/equalities from Input ####

  extract_info <- function(test, loop_numb_models, func_mytable_input) {
    check_input <- paste(func_mytable_input[, 2], collapse = ";")

    # only real numbers after a p count; an empty match (p_{1}, a lone p) used to turn this into NA and broke the whole session
    p_nums <- suppressWarnings(as.numeric(unlist(str_extract_all(check_input, "(?<=p)[0-9]+"))))
    max_p <- if (any(!is.na(p_nums))) max(p_nums, na.rm = TRUE) else NA_real_

    if (!is.na(max_p) && isTRUE(counter$n < max_p)) counter$n <- max_p

    probs <- data.frame()


    for (loop in 1:counter$n) {
      name_p <- str_replace_all(eval(parse(
        text = paste("unlist(AllInputs()$textin_name_", loop, ")", sep = "")
      )), fixed(" "), "_")
      name_p <- ifelse(length(name_p) == 0, paste("p_{", loop, "}", sep = ""), name_p)


      probs <- rbind(
        probs,
        c(
          paste("p_", loop, sep = ""),
          name_p
        )
      )
    }

    ####

    probs <- data.frame(probs, rep(0, nrow(probs)), rep(1, nrow(probs)))
    colnames(probs) <- c("variable", "name", "p_min", "p_max")

    ####* split and remove ####

    limits <- paste(paste(paste("p", 1:counter$n, sep = ""), "< 1", collapse = ";"),
      paste(paste("p", 1:counter$n, sep = ""), "> 0", collapse = ";"),
      sep = ";"
    )


    test <- str_replace_all(test, "\n", ";")

    # Accept "," as a constraint separator as well, but NOT inside "{...}",
    # where commas belong to the "{p1,p2} < {p3}" batch shortcut.
    commas_outside_braces_to_semicolon <- function(s) {
      if (is.na(s) || !str_detect(s, ",")) {
        return(s)
      }
      chars <- unlist(str_split(s, ""))
      depth <- 0
      for (i in seq_along(chars)) {
        if (chars[i] == "{") depth <- depth + 1
        if (chars[i] == "}") depth <- depth - 1
        if (chars[i] == "," && depth <= 0) chars[i] <- ";"
      }
      paste(chars, collapse = "")
    }

    test <- vapply(test, commas_outside_braces_to_semicolon,
      FUN.VALUE = character(1), USE.NAMES = FALSE
    )

    # Count clauses the user actually typed, before the automatic 0-1
    # bounds ("limits") get appended below — this is what lets the
    # theory-building notes distinguish a genuinely redundant typed clause
    # from one of the routine, expected-to-be-redundant automatic bounds.
    n_user_clauses_reactive$value <- length(Filter(nzchar, trimws(unlist(str_split(test, ";")))))

    test <- paste0(test, ";", limits, collapse = "")

    test <- unlist(str_split(test, ";"))
    test <- str_replace_all(test, "\u2013", "-")
    test <- str_replace_all(test, "\u2014", "-")
    test <- str_replace_all(test, " ", "")

    test <- unlist(test)

    if (length(which(test %in% "")) > 0) {
      test <- test[-which(test %in% "")]
    }

    #### new ####

    numb_test <- length(test)


    for (loop_test in 1:numb_test) {
      pos_signs <- str_locate_all(test[loop_test], "[=><]")[[1]][, 1]

      signs <- numeric()

      for (loop_string in 1:length(pos_signs)) {
        signs <- c(signs, substr(test[loop_test], pos_signs[loop_string], pos_signs[loop_string]))
      }

      arguments <- strsplit(test[loop_test], "[=><]")[[1]]

      for (loop_length_arguments in 1:(length(arguments) - 1)) {
        test <- c(test, paste(arguments[loop_length_arguments],
          signs[loop_length_arguments],
          arguments[loop_length_arguments + 1],
          sep = ""
        ))
      }
    }

    test <- test[-(1:numb_test)]

    #### {p1,p2} > {p3,p4}  ####

    expand_scalar <- function(scalar) {
      # Extract the first and second batches of 'p' variables
      batches <- strsplit(gsub("[{} ]", "", scalar), "[><=]")[[1]]
      batch1 <- unlist(strsplit(batches[1], ","))
      batch2 <- unlist(strsplit(batches[2], ","))

      # Determine the separator used in the original scalar
      separator <- gsub("[p{}]", "", gsub("[^><=]", "", scalar))

      comparisons <- character()

      # Generate comparisons between the first and second batch of 'p' variables
      for (p1 in batch1) {
        for (p2 in batch2) {
          comparisons <- c(comparisons, paste0(p1, separator, p2))
        }
      }

      output <- paste(comparisons, collapse = ";")
      return(output)
    }

    test_new <- numeric()

    for (loop_sep in 1:length(test)) {
      if (grepl("{", test[loop_sep], fixed = TRUE) == T) {
        test_new <- c(test_new, expand_scalar(test[loop_sep]))
      } else {
        test_new <- c(test_new, test[loop_sep])
      }
    }

    test <- test_new
    test <- unlist(str_split(test, ";"))

    #### cut string ####

    test_new <- numeric()

    for (loop_check in 1:length(test)) {
      lr_side <- unlist(str_split(test[loop_check], ">|=|<"))

      if (lr_side[1] != lr_side[2]) {
        test_new <- c(test_new, test[loop_check])
      }
    }

    test <- test_new

    # A bare leading "." in a number (".000001") needs a "0" in front so the
    # downstream tokenizer parses it correctly. The clause-initial case
    # (".5<p1") was the only one handled here — a "." right after an
    # operator or sign, anywhere else in the clause (e.g. "p3<.000001",
    # "p1<p2>p3<.000001"), was missed, silently truncating that number to 0.
    test <- str_replace_all(test, "(?<![0-9])\\.", "0.")

    ####* normalise constraints ####
    # allows free-form linear input (parentheses, constants on either side)
    if (length(test) > 0) {
      test <- vapply(test, normalize_constraint,
        FUN.VALUE = character(1), n_p = counter$n, USE.NAMES = FALSE
      )
    }

    ####* extract structure ####

    loc_above <- str_locate_all(test, ">")
    loc_equal <- str_locate_all(test, "=")
    loc_below <- str_locate_all(test, "<")

    loc_add <- str_locate_all(test, fixed("+"))
    loc_subtract <- str_locate_all(test, "-")
    loc_divide <- str_locate_all(test, "/")
    loc_multiply <- str_locate_all(test, fixed("*"))

    loc_digits <- str_locate_all(test, "[:digit:]")
    loc_prob <- str_locate_all(test, fixed("p"))

    loc_paren_open <- str_locate_all(test, fixed("("))
    loc_paren_closed <- str_locate_all(test, fixed(")"))
    loc_point <- str_locate_all(test, fixed("."))

    #** loop here

    loop_all <- 1
    all_extracted <- list()

    for (loop_bit in 1:length(test)) {
      test_actual <- test[loop_bit]
      test_actual_single <- unlist(str_split(test_actual, ""))

      pos <- rbind(
        "above" = data.frame(loc_above[loop_bit]),
        "below" = data.frame(loc_below[loop_bit]),
        "equal" = data.frame(loc_equal[loop_bit]),
        "add" = data.frame(loc_add[loop_bit]),
        "subtract" = data.frame(loc_subtract[loop_bit]),
        "multiply" = data.frame(loc_multiply[loop_bit]),
        "divide" = data.frame(loc_divide[loop_bit]),
        "digit" = data.frame(loc_digits[loop_bit]),
        "p" = data.frame(loc_prob[loop_bit]),
        "point" = data.frame(loc_point[loop_bit]),
        "open" = data.frame(loc_paren_open[loop_bit]),
        "closed" = data.frame(loc_paren_closed[loop_bit])
      )
      pos <- pos[order(pos[, 1]), ]


      pos <- data.frame(t(pos))

      info_type <- colnames(pos)

      info_type <- str_replace_all(info_type, fixed("."), "")
      info_type <- str_replace_all(info_type, "[:digit:]", "")

      #####* extract sub inequalities and equalities

      ineq_equ_parts_loc <- which(info_type == "above" |
        info_type == "below" |
        info_type == "equal")

      ineq_equ_parts_loc <- c(1, ineq_equ_parts_loc, length(info_type))

      loc_subparts <- numeric()

      for (loop_loc in 1:(length(ineq_equ_parts_loc) - 2)) {
        loc_act <- ineq_equ_parts_loc[c(1, 3) + (loop_loc - 1)]

        if (loop_loc == 1) {
          loc_act[2] <- loc_act[2] - 1
        }

        if (loop_loc < (length(ineq_equ_parts_loc) - 2) &
          loop_loc != 1) {
          loc_act[1] <- loc_act[1] + 1
          loc_act[2] <- loc_act[2] - 1
        }

        if (loop_loc == (length(ineq_equ_parts_loc) - 2)) {
          loc_act[1] <- loc_act[1] + 1
          loc_act[2] <- loc_act[2]
        }

        loc_subparts <- c(loc_subparts, loc_act)
      }

      loc_subparts <- t(matrix(loc_subparts, nrow = 2))

      subparts <- list()

      if (nrow(loc_subparts) == 1) {
        subparts[[paste0("part", loop_loc)]] <-
          rbind(
            info_type[1:length(info_type)],
            test_actual_single[1:length(info_type)]
          )
      } else {
        for (loop_loc in 1:nrow(loc_subparts)) {
          subparts[[paste0("part", loop_loc)]] <-
            rbind(
              info_type[loc_subparts[loop_loc, 1]:loc_subparts[loop_loc, 2]],
              test_actual_single[loc_subparts[loop_loc, 1]:loc_subparts[loop_loc, 2]]
            )
        }
      }

      ###* loop over subparts

      for (loop_sub_part in 1:length(subparts)) {
        subparts_actual <- data.frame(subparts[loop_sub_part])


        pos_p <- which(subparts_actual[1, ] == "p")
        pos_before_p <- pos_p - 1

        if (pos_before_p[1] == 0) {
          subparts_actual <- cbind(cbind(c("add", "+"), c("digit", "1"), c("multiply", "*")), subparts_actual)
        }

        if (subparts_actual[1, 1] == "digit") {
          subparts_actual <- cbind(cbind(c("add", "+")), subparts_actual)
        }

        ####

        loc_after_relation <- which(
          subparts_actual[1, ] == "below" |
            subparts_actual[1, ] == "above" |
            subparts_actual[1, ] == "equal"
        ) + 1

        if (subparts_actual[1, loc_after_relation] == "digit" |
          subparts_actual[1, loc_after_relation] == "point") {
          subparts_actual <- cbind(
            subparts_actual[, 1:(loc_after_relation - 1)],
            c("add", "+"),
            subparts_actual[, loc_after_relation:ncol(subparts_actual)]
          )
        }


        add_multiply_function <- function() {
          pos_p <- which(subparts_actual[1, ] == "p")
          pos_before_p <- pos_p - 1

          add_multiply <- ifelse(
            subparts_actual[1, pos_before_p] == "add" |
              subparts_actual[1, pos_before_p] ==
                "below" |
              subparts_actual[1, pos_before_p] ==
                "above" |
              subparts_actual[1, pos_before_p] ==
                "equal",
            1,
            0
          )

          add_multiply <- ifelse(
            subparts_actual[1, pos_before_p] == "below" |
              subparts_actual[1, pos_before_p] ==
                "above" |
              subparts_actual[1, pos_before_p] ==
                "equal",
            2,
            add_multiply
          )

          add_multiply <- ifelse(subparts_actual[1, pos_before_p] == "subtract", -1,
            add_multiply
          )


          fix_factors <- pos_before_p[add_multiply != 0]
          add_multiply <- add_multiply[add_multiply != 0]

          return(list(fix_factors, add_multiply))
        }

        res_cadd_multiply_function <- add_multiply_function()

        fix_factors <- unlist(res_cadd_multiply_function[1])
        add_multiply <- unlist(res_cadd_multiply_function[2])

        if (length(add_multiply) > 0) {
          for (loop_add_multiply in 1:length(add_multiply)) {
            if (add_multiply[1] == -1) {
              subparts_actual <-
                cbind(
                  subparts_actual[, 1:fix_factors[1]],
                  cbind(c("digit", "1"), c("multiply", "*")),
                  subparts_actual[, (fix_factors[1] + 1):ncol(subparts_actual)]
                )
            }

            if (add_multiply[1] == 1) {
              subparts_actual <-
                cbind(
                  subparts_actual[, 1:fix_factors[1]],
                  cbind(c("digit", "1"), c("multiply", "*")),
                  subparts_actual[, (fix_factors[1] + 1):ncol(subparts_actual)]
                )
            }

            if (add_multiply[1] == 2) {
              subparts_actual <-
                cbind(
                  subparts_actual[, 1:fix_factors[1]],
                  cbind(
                    c("add", "+"),
                    c("digit", "1"),
                    c("multiply", "*")
                  ),
                  subparts_actual[, (fix_factors[1] + 1):ncol(subparts_actual)]
                )
            }

            res_cadd_multiply_function <- add_multiply_function()
            fix_factors <- unlist(res_cadd_multiply_function[1])
            add_multiply <- unlist(res_cadd_multiply_function[2])
          }
        }

        #####* extract p ####

        keep <- numeric()

        for (loop_extract in 1:ncol(subparts_actual)) {
          if (subparts_actual[1, loop_extract] == "p") {
            keep <- c(keep, 1)
          }

          if (loop_extract > 1 &
            subparts_actual[1, loop_extract] != "p") {
            if (subparts_actual[1, loop_extract] != "p" &
              subparts_actual[1, loop_extract] == "digit" &
              keep[loop_extract - 1] == 1) {
              keep <- c(keep, 1)
            } else {
              keep <- c(keep, 0)
            }
          }

          if (loop_extract == 1 &
            subparts_actual[1, loop_extract] != "p") {
            keep <- c(keep, 0)
          }
        }

        extract_p <- subparts_actual[2, keep == 1]
        extract_p <- paste0(extract_p, collapse = "")
        extract_p <- unlist(str_split(extract_p, "p"))
        extract_p <- extract_p[2:length(extract_p)]
        extract_p <- as.numeric(extract_p)

        ####* extract relation ####

        location_relation <- which(
          subparts_actual[1, ] == "below" |
            subparts_actual[1, ] == "above" |
            subparts_actual[1, ] == "equal"
        )

        relation_subpart <- subparts_actual[1, location_relation]
        relation_subpart <- unlist(relation_subpart)

        ####* extract factors ####

        left_side <- data.frame(subparts_actual[, 1:(location_relation -
          1)])
        right_side <- data.frame(subparts_actual[, (location_relation +
          1):ncol(subparts_actual)])


        location_add_subtract_left <- which(left_side[1, ] == "subtract" |
          left_side[1, ] == "add")

        location_p_left <- which(left_side[1, ] == "p")


        location_add_subtract_right <- which(right_side[1, ] == "subtract" |
          right_side[1, ] == "add")

        location_p_right <- which(right_side[1, ] == "p")


        ####** left side

        factor_left <- numeric()

        if (length(location_p_left) == 0) {
          factor_left <- paste0(left_side[2, ], collapse = "")
          extract_p <- c("numb", extract_p)
        } else {
          for (loop_loc in 1:length(location_add_subtract_left)) {
            factor_left <- c(
              factor_left,
              paste0(left_side[2, location_add_subtract_left[loop_loc]:(location_p_left[loop_loc] -
                2)], collapse = "")
            )
          }
        }

        ####** right side

        factor_right <- numeric()

        if (length(location_p_right) == 0) {
          factor_right <- paste0(right_side[2, ], collapse = "")

          extract_p <- c(extract_p, "numb")
        } else {
          for (loop_loc in 1:length(location_add_subtract_right)) {
            factor_right <- c(
              factor_right,
              paste0(right_side[2, location_add_subtract_right[loop_loc]:(location_p_right[loop_loc] -
                2)], collapse = "")
            )
          }
        }

        ####** combine extract

        extracted <- rbind(
          extract_p,
          c(
            rep("left", length(
              factor_left
            )),
            rep("right", length(
              factor_right
            ))
          ),
          c(factor_left, factor_right),
          relation_subpart
        )

        row.names(extracted) <- c("p", "left/right", "factor", "relation")
        colnames(extracted) <- paste("sub_", 1:ncol(extracted), sep = "")
        extracted <- data.frame(extracted)

        all_extracted[[paste0("line", loop_all)]] <- extracted

        loop_all <- loop_all + 1
      }
    }

    if (length(all_extracted) > 0) {
      numb_p <- numeric()

      for (loop_numb_p in 1:length(all_extracted)) {
        numb_p <- c(numb_p, (unlist(data.frame(
          all_extracted[loop_numb_p]
        )[1, ])))
      }

      numb_p <- numb_p[numb_p != "numb"]
      numb_p <- as.numeric(numb_p)
      numb_p <- max(numb_p)
    } else {
      all_extracted <- list()
      numb_p <- 0
    }

    ###

    numb_equl_ineq <- length(all_extracted)

    ineq_eq_left <- matrix(NA, ncol = numb_p, nrow = numb_equl_ineq)
    ineq_eq_right <- rep(NA, numb_equl_ineq)
    all_operators <- rep(NA, numb_equl_ineq)

    ###

    for (loop_relations in 1:length(all_extracted)) {
      actual_relations <- data.frame(all_extracted[loop_relations])

      # every factor as an exact fraction (text that is not a plain number, e.g. a non-linear expression, goes through a double)
      extract_factors <- character()

      for (loop_factors in 1:ncol(actual_relations)) {
        q_fac <- q_from_text(actual_relations[3, loop_factors])
        extract_factors <- c(extract_factors, if (is.na(q_fac)) d2q(as.numeric(eval(parse(text = actual_relations[3, loop_factors])))) else q_fac)
      }

      actual_relations[3, ] <- (extract_factors)

      actual_relations_left <- actual_relations[, actual_relations[2, ] == "left"]
      actual_relations_right <- actual_relations[, actual_relations[2, ] == "right"]
      actual_relations_operator <- actual_relations[4, 1]

      actual_relations_left <- data.frame(actual_relations_left)
      actual_relations_right <- data.frame(actual_relations_right)

      numb_left <- which(actual_relations_left[1, ] == "numb")
      numb_right <- which(actual_relations_right[1, ] == "numb")

      non_numb_left <- which(actual_relations_left[1, ] != "numb")
      non_numb_right <- which(actual_relations_right[1, ] != "numb")

      #### change signs

      if (actual_relations_operator == "equal" &
        length(non_numb_right) > 0 & length(non_numb_left) > 0) {
        actual_relations_right[3, non_numb_right] <- qneg(as.character(unlist(actual_relations_right[3, non_numb_right])))
      }

      if (actual_relations_operator == "below" &
        length(non_numb_right) > 0) {
        actual_relations_right[3, non_numb_right] <- qneg(as.character(unlist(actual_relations_right[3, non_numb_right])))
        actual_relations_left[3, numb_left] <- qneg(as.character(unlist(actual_relations_left[3, numb_left])))
      }

      if (actual_relations_operator == "above" &
        length(non_numb_left) > 0) {
        actual_relations_left[3, non_numb_left] <- qneg(as.character(unlist(actual_relations_left[3, non_numb_left])))
        actual_relations_right[3, numb_right] <- qneg(as.character(unlist(actual_relations_right[3, numb_right])))
        actual_relations_operator <- "below"
        actual_relations_left[4, ] <- "below"
        actual_relations_right[4, ] <- "below"
      }

      ## do fractions

      actual_relations_left <- data.frame(actual_relations_left)
      actual_relations_right <- data.frame(actual_relations_right)



      ## translate into RCDD input

      total_rcdd <- data.frame(actual_relations_left, actual_relations_right)

      total_rcdd_leftside <- data.frame(total_rcdd[, total_rcdd[1, ] != "numb"])
      total_rcdd_rightside <- data.frame(total_rcdd[, total_rcdd[1, ] == "numb"])

      if (length(total_rcdd_rightside) == 0) {
        total_rcdd_rightside <- t(data.frame("numb", "right", "0", actual_relations_operator))
      }

      ###

      ineq_eq_left[loop_relations, as.numeric(unlist(total_rcdd_leftside[1, ]))] <- unlist(total_rcdd_leftside[3, ])
      ineq_eq_left[loop_relations, -as.numeric(unlist(total_rcdd_leftside[1, ]))] <- "0"
      ineq_eq_right[loop_relations] <- total_rcdd_rightside[3, ]
      all_operators[loop_relations] <- actual_relations_operator
    }

    #### approx equal


    add_ineq_eq_left <- numeric()
    add_ineq_eq_right <- character()
    add_all_operators <- numeric()

    ####*** add approx equalities when selected ####

    # Per-equality tolerances: tol_vec[k] is the tolerance for the k-th
    # "=" clause encountered left-to-right in this model's spec (set via
    # the popup that appears the moment a new one is typed — see
    # equality_tolerances_reactive's own comment). An occurrence with no
    # tolerance recorded for it (vector too short, or a value of 0) stays
    # an exact equality; only occurrences with a nonzero tolerance get
    # converted to the below/below pair below. This replaces the old
    # single per-model tune_knob that was applied uniformly to every "="
    # in a model.
    tol_vec <- equality_tolerances_reactive$value[[as.character(loop_numb_models)]]

    keep_as_equal <- rep(TRUE, length(all_operators))
    eq_occurrence <- 0

    for (loop_tune in seq_along(all_operators)) {
      if (all_operators[loop_tune] == "equal") {
        eq_occurrence <- eq_occurrence + 1
        this_tol <- if (!is.null(tol_vec) && eq_occurrence <= length(tol_vec) && !is.na(tol_vec[eq_occurrence])) tol_vec[eq_occurrence] else 0

        if (this_tol != 0) {
          keep_as_equal[loop_tune] <- FALSE

          add_ineq_eq_left <- rbind(add_ineq_eq_left, (ineq_eq_left[loop_tune, , drop = FALSE]))
          add_ineq_eq_left <- rbind(add_ineq_eq_left, qneg(ineq_eq_left[loop_tune, , drop = FALSE]))

          add_ineq_eq_right <- c(
            add_ineq_eq_right,
            qpq(ineq_eq_right[loop_tune], q_from_number(this_tol)),
            qpq(qneg(ineq_eq_right[loop_tune]), q_from_number(this_tol))
          )

          add_all_operators <- c(add_all_operators, rep("below", 2))
        }
      }
    }

    if (length(add_all_operators) > 0) {
      ineq_eq_left <- ineq_eq_left[keep_as_equal, , drop = FALSE]
      ineq_eq_right <- ineq_eq_right[keep_as_equal]
      all_operators <- all_operators[keep_as_equal]

      ineq_eq_left <- rbind(ineq_eq_left, add_ineq_eq_left)
      ineq_eq_right <- c(ineq_eq_right, add_ineq_eq_right)
      all_operators <- c(all_operators, add_all_operators)
    }



    all_operators_reactive$value <- all_operators
    ineq_eq_left_reactive$value <- ineq_eq_left
    ineq_eq_right_reactive$value <- ineq_eq_right
    probs_reactive$value <- probs
  }

  #### Function for Representations ####

  ####* H-representation input models ####

  # The main "Go" pipeline. Everything here shares local state (mytable_input,
  # empty_set, recomputed_models, ...) and runs strictly in this order —
  # later sections read results (and reactive values: h_reactive, v_reactive,
  # intersections_reactive, mixtures_reactive, items_reactive, ...) that
  # earlier sections wrote, so they cannot be safely reordered or extracted
  # without re-threading that state explicitly. Stages, in order:
  #   1. Parse Input tab rows into mytable_input (model name + spec)
  #   2. Build each model's H-representation (####** loop models)
  #   3. Auto-detect pairwise intersections for the Model Properties table
  #   4. Compute user-selected model intersections (####* Model intersection)
  #   5. Compute user-selected model mixtures (####* Model mixtures)
  #   6. Compute multi-item models — runs before replication so items models
  #      can serve as a replication base (####* Multiple-items models)
  #   7. Compute replication models (####* Replication models)
  #   8. Compute V-representations for everything selected (####* V-representation)
  #   9. Build the H-representation formula/LaTeX display and V-rep tables
  observe_guarded(input$go_v_h, {
    # the repeated run after the mixtures were calculated (same window, nothing is asked again)
    resume_go <- isTRUE(isolate(mix_job$resume)); mix_job$resume <- FALSE
    # Skip if inputs are identical to the last recomputation.
    current_snap <- make_snapshot()
    # (not after a mixture was skipped: the next Go has to try it again although nothing in the input changed)
    if (!resume_go && !isTRUE(isolate(mix_job$stale)) && !is.null(isolate(last_recomputed_snapshot())) &&
        snap_same(isolate(last_recomputed_snapshot()), current_snap)) {
      showNotification("Everything is already calculated: nothing has changed since the last Go.", type = "message", duration = 5)
      return()
    }
    if (!resume_go) { mix_job$skipped <- character(0); mix_job$stale <- FALSE }
    # Check the input before computing anything and say precisely what is wrong.
    precheck_msgs <- character()
    for (i_chk in seq_len(counter_input$n)) {
      nm_chk <- unlist(AllInputs()[[paste0("textin_relations_name", i_chk)]])
      label_chk <- if (length(nm_chk) && nzchar(nm_chk[1])) nm_chk[1] else paste("model", i_chk)
      key_chk <- as.character(i_chk)
      if (!is.null(isolate(derived_model_sources$value)[[key_chk]]) ||
          !is.null(isolate(mixture_model_flags$value)[[key_chk]]) ||
          !is.null(isolate(item_model_spec_idx$value)[[key_chk]])) next
      spec_chk <- paste(AllInputs()[[paste0("textin_relations_complete_", i_chk)]], collapse = " ")
      if (!nzchar(trimws(spec_chk))) {
        precheck_msgs <- c(precheck_msgs, paste0("<b>", htmltools::htmlEscape(label_chk), "</b> has no specification yet."))
        next
      }
      # a "p" without a number (p instead of p1) cannot be read; say so instead of failing further down
      bare_pat <- "(?<![A-Za-z_{\\\\])p(?![0-9A-Za-z_{])"   # a p without a number, also after a weight (2p)
      bare_cl <- Filter(function(cl) grepl(bare_pat, gsub("\\s", "", cl), perl = TRUE), trimws(strsplit(spec_chk, "[;,\n]")[[1]]))
      if (length(bare_cl) > 0) {
        shown <- vapply(bare_cl, function(cl) gsub(bare_pat, "<u style='color:#c9353b'>p</u>", htmltools::htmlEscape(gsub("\\s", "", cl)), perl = TRUE), character(1))
        precheck_msgs <- c(precheck_msgs, paste0("<b>", htmltools::htmlEscape(label_chk), "</b>: a <u>p</u> without a number in <b>", paste(shown, collapse = "</b>, <b>"),
          "</b>. Write p1, p2, p3, \u2026 (for example 2*p1 or 2p1)."))
      }
      # a probability that does not exist (p20 with six probabilities) cannot be calculated: say which one
      # a model is a set of linear constraints: 1/p1, p1*p2, p1^2 or functions of probabilities cannot be calculated
      nonlinear_clause <- function(cl) {
        dens <- regmatches(cl, gregexpr("/\\s*(\\([^)]*\\)|[A-Za-z0-9_.]+)", cl))[[1]]
        prods <- regmatches(cl, gregexpr("p[0-9]+\\s*[*]\\s*(p[0-9]+|\\()|\\)\\s*[*]\\s*(p[0-9]+|\\()|[*]\\s*\\([^)]*p[0-9]", cl))[[1]]
        pows <- regmatches(cl, gregexpr("[A-Za-z0-9_.)]+\\s*\\^\\s*[A-Za-z0-9_.(]+", cl))[[1]]
        funs <- regmatches(cl, gregexpr("(sqrt|log|exp|abs|sin|cos|tan|min|max)\\s*\\([^)]*\\)", cl, ignore.case = TRUE))[[1]]
        length(c(dens[grepl("p[0-9]+", dens)], prods, pows[grepl("p[0-9]+", pows)], funs[grepl("p[0-9]+", funs)])) > 0
      }
      nl_cl <- Filter(nonlinear_clause, trimws(strsplit(spec_chk, "[;\n]")[[1]]))
      if (length(nl_cl) > 0) {
        precheck_msgs <- c(precheck_msgs, paste0("<b>", htmltools::htmlEscape(label_chk), "</b>: <code>", htmltools::htmlEscape(nl_cl[1]),
          "</code> is not linear. A model can only use sums and differences of probabilities, with weights and numbers, for example <code>2*p1 + p2 &ge; .5</code> or <code>p1 &ge; p2 + .1</code>."))
      }
      pn_chk <- regmatches(spec_chk, gregexpr("(?<![A-Za-z0-9_{\\\\])p[0-9]+(?![0-9A-Za-z_{])", spec_chk, perl = TRUE))[[1]]
      pn_num <- suppressWarnings(as.integer(sub("^p", "", pn_chk)))
      pn_bad <- unique(pn_chk[!is.na(pn_num) & (pn_num < 1L | pn_num > counter$n)])
      if (length(pn_bad) > 0) {
        precheck_msgs <- c(precheck_msgs, paste0("<b>", htmltools::htmlEscape(label_chk), "</b>: ", paste(pn_bad, collapse = ", "),
          if (length(pn_bad) == 1) " does not exist" else " do not exist", ", you have p1 to p", counter$n, "."))
      }
    }
    conflict_msgs <- character()
    for (i_chk in seq_len(counter_input$n)) {
      spec_c <- paste(AllInputs()[[paste0("textin_relations_complete_", i_chk)]], collapse = " ")
      if (!nzchar(trimws(spec_c))) next
      cf <- fairy_bound_conflicts(spec_c)
      if (length(cf) > 0) {
        nm_c <- unlist(AllInputs()[[paste0("textin_relations_name", i_chk)]])
        conflict_msgs <- c(conflict_msgs, paste0("<b>", htmltools::htmlEscape(if (length(nm_c) && nzchar(nm_c[1])) nm_c[1] else paste("model", i_chk)),
          "</b>: ", htmltools::htmlEscape(paste(cf, collapse = "; ")), " (empty set)."))
      }
    }
    if (length(conflict_msgs) > 0) {
      showNotification(HTML(paste0("Contradicting bounds, found before calculating:<br>", paste(conflict_msgs, collapse = "<br>"))),
        type = "warning", duration = 15)
    }
    if (length(precheck_msgs) > 0) {
      fairy_notify("Please check your input", paste(precheck_msgs, collapse = "<br><br>"), type = "error", html = TRUE)
      return()
    }

    last_recomputed_snapshot(current_snap)

    n_input_models <- counter_input$n

    ####** input

    mytable_input <- data.frame()

    for (loop in 1:counter_input$n) {
      mytable_input <- rbind(
        mytable_input,
        c(
          eval(parse(
            text = paste(
              "unlist(AllInputs()$textin_relations_name",
              loop,
              ")",
              sep = ""
            )
          )),
          eval(parse(
            text = paste(
              "unlist(AllInputs()$textin_relations_complete_",
              loop,
              ")",
              sep = ""
            )
          ))
        )
      )
    }

    colnames(mytable_input) <- c("model name", "input_models")
    # mytable_input[, 2] = str_replace_all( mytable_input[, 2],",",";") # !!!!!!!!

    names_models_reactive$value <- mytable_input$`model name`

    if (length(mytable_input$`model name`) >= 1)
      showTab(inputId = "tabs", target = "Model Properties")

    ####** start conversion ####

    empty_set <- numeric()

    # A "Mixture model" row (see mixture_model_flags) is deliberately left
    # with an empty spec — it's a placeholder, not a real constraint list
    # (see that reactiveValues' own comment) — so it shouldn't trip the
    # "you left a spec blank" validation below the way an ordinary empty
    # model would. It still gets converted like any other row after this
    # point, on whatever its (empty) spec parses to — full mixture support
    # in this pipeline is a separate, larger piece of follow-up work.
    mixture_rows <- as.integer(names(isolate(mixture_model_flags$value)))
    blocking_empty <- sum(mytable_input[, 2] == "" & !(seq_len(nrow(mytable_input)) %in% mixture_rows))

    if (blocking_empty == 0) {
      showTab(inputId = "tabs", target = "H-representation")

      ####** loop models ####

      numb_models_to_convert <- n_input_models

      feedback_h_models <- numeric()

      feedback_name <- numeric()

      cache <- isolate(model_snap_cache())
      recomputed_models <- character()
      if (!resume_go) fairy_run_begin(skippable = TRUE)
      # kind label in the run window: intersection / mixture rows come from the
      # Input tab buttons (see derived_model_sources), everything else is a model
      dms_run <- isolate(derived_model_sources$value)
      kinds_run <- vapply(seq_len(numb_models_to_convert), function(i) {
        t <- dms_run[[as.character(i)]]$type
        if (!is.null(t)) t
        else if (!is.null(isolate(item_model_spec_idx$value[[as.character(i)]]))) "items"
        else "model"
      }, character(1))
      # the rows of the run window are listed in the order the models are worked on (models, intersections, mixtures, items),
      # so the window does not jump between rows
      run_rank <- c(model = 0, intersection = 1, mixture = 2, items = 3)[kinds_run]; run_rank[is.na(run_rank)] <- 0
      row_order <- order(run_rank, seq_along(run_rank))
      names(run_rank) <- as.character(mytable_input[seq_len(numb_models_to_convert), 1])
      session$sendCustomMessage("fairy_kinds", setNames(as.list(kinds_run), as.character(mytable_input[seq_len(numb_models_to_convert), 1])))
      # models selected for the V-representation already show "waiting" in the V column, so the
      # run window is not misleading during the H phase
      v_sel_run <- isolate(mytable_v_reactive$value)
      v_included_run <- if (!is.null(v_sel_run) && ncol(v_sel_run) >= 2) as.character(v_sel_run[[1]][which(as.logical(v_sel_run[[2]]))]) else character()
      # (not in the repeated run after the mixtures: the rows already show what the first run did)
      # models whose V-representation was skipped earlier stay in the window as skipped (with Retry); a model whose V switch was
      # turned on again by hand is no longer remembered
      if (!resume_go) v_skipped_mem(intersect(isolate(v_skipped_mem()), setdiff(as.character(mytable_input[seq_len(numb_models_to_convert), 1]), v_included_run)))
      for (i_run in if (resume_go) integer(0) else row_order) {
        nm_run <- mytable_input[i_run, 1]
        fairy_run_row(nm_run, kinds_run[i_run], h = "wait",
          v = if (nm_run %in% v_included_run) "wait" else if (nm_run %in% isolate(v_skipped_mem())) "skip" else NULL)
      }

      for (loop_numb_models in 1:numb_models_to_convert) {
        name_m <- mytable_input[loop_numb_models, 1]
        # A mixture row gets its real H and V together in the mixture step further down; its trivial
        # placeholder H here must not show up in the run window as a separate calculation.
        run_row_here <- function(...) if (!identical(kinds_run[loop_numb_models], "mixture") && !isTRUE(dms_run[[as.character(loop_numb_models)]]$by_h)) fairy_run_row(...)

        # a multiple-items model gets its H-representation in its own step further down (from its base model):
        # computing it here from the row's text as well was a second, unused calculation
        if (identical(kinds_run[loop_numb_models], "items")) next
        model_snap <- list(
          spec    = mytable_input[loop_numb_models, 2],
          n_p     = counter$n,
          # A renamed probability doesn't change `spec` (the typed
          # constraint text always uses the fixed p1/p2/... handles, not
          # the display name) but DOES change h_base's own column names
          # (see build_items_h_core) — without tracking it here, this
          # per-model cache kept reusing the pre-rename h_reactive entry
          # even after the global go_v_h snapshot check (see
          # make_snapshot's own comment on the same class of bug) was
          # fixed to no longer skip the whole recompute on a rename.
          p_names = vapply(seq_len(counter$n), function(i)
            isolate(input[[paste0("textin_name_", i)]]) %||% "", character(1)),
          approx = isolate(equality_tolerances_reactive$value[[as.character(loop_numb_models)]])
        )

        if (!is.null(cache[[name_m]]) &&
            identical(cache[[name_m]], model_snap) &&
            !is.null(isolate(h_reactive[[name_m]]))) {
          feedback_name <- c(feedback_name, name_m)
          run_row_here(name_m, h = "cached")
          next
        }
        recomputed_models <- c(recomputed_models, name_m)

        run_row_here(name_m, h = "run")

        feedback_name <- c(feedback_name, name_m)


        # A malformed specification should report the offending model instead
        # of taking the whole app down.
        parse_ok <- tryCatch(
          {
            extract_info(mytable_input[loop_numb_models, 2], loop_numb_models, mytable_input)
            TRUE
          },
          error = function(e) FALSE
        )
        # Captured immediately, not re-read later via isolate() — extract_info()
        # writes n_user_clauses_reactive$value as a side effect, and it's the
        # SAME shared reactive for every model in this loop. The h_raw_rows_
        # reactive assignment further down used to re-read it fresh at that
        # point instead of using this captured value, which was fine as long
        # as nothing else touched the reactive in between — but was one
        # accidental extra write away (this loop, a future edit, anything
        # triggering a flush) from silently attributing the WRONG model's
        # clause count to THIS model's h_raw_rows_reactive entry, breaking
        # redundant-clause highlighting for it intermittently. Capturing right
        # here removes that window entirely.
        n_user_clauses_here <- isolate(n_user_clauses_reactive$value)

        if (!parse_ok) {
          spec_txt <- mytable_input[loop_numb_models, 2]

          bad <- tryCatch(
            {
              pieces <- split_spec(spec_txt)
              pieces[vapply(str_replace_all(pieces, " ", ""),
                is_nonlinear_constraint,
                FUN.VALUE = logical(1), n_p = counter$n
              )]
            },
            error = function(e) character()
          )

          bare_pat2 <- "(?<![A-Za-z_{\\\\])p(?![0-9A-Za-z_{])"
          pieces_all <- tryCatch(split_spec(spec_txt), error = function(e) character())
          bare_pieces <- pieces_all[grepl(bare_pat2, gsub("\\s", "", pieces_all), perl = TRUE)]
          # does a clause really multiply or divide probabilities, or raise them to a power?
          looks_nonlinear <- function(cl) {
            cl <- gsub("\\s", "", cl)
            dens <- regmatches(cl, gregexpr("/\\s*(\\([^)]*\\)|[A-Za-z0-9_.]+)", cl))[[1]]
            prods <- regmatches(cl, gregexpr("p[0-9]+\\s*[*]\\s*(p[0-9]+|\\()|\\)\\s*[*]\\s*(p[0-9]+|\\()|[*]\\s*\\([^)]*p[0-9]", cl))[[1]]
            pows <- regmatches(cl, gregexpr("[A-Za-z0-9_.)]+\\s*\\^\\s*[A-Za-z0-9_.(]+", cl))[[1]]
            length(c(dens[grepl("p[0-9]+", dens)], prods, pows[grepl("p[0-9]+", pows)])) > 0
          }
          if (length(bare_pieces) > 0) {
            shown <- vapply(bare_pieces, function(cl) gsub(bare_pat2, "<u style='color:#c9353b'>p</u>", htmltools::htmlEscape(gsub("\\s", "", cl)), perl = TRUE), character(1))
            msg <- paste0("A <u>p</u> without a number:<br><br><b>", paste(shown, collapse = "</b><br><b>"), "</b>",
                          "<br><br>Write p1, p2, p3, \u2026 (for example 2*p1 or 2p1).")
          } else if (length(bad) > 0 && any(vapply(bad, looks_nonlinear, logical(1)))) {
            msg <- paste0(
              "This constraint is not <b>linear</b> in the probabilities:",
              "<br><br><b>", paste(bad, collapse = "</b><br><b>"), "</b>",
              "<br><br>A model is a polytope, so a probability may not be divided by, ",
              "multiplied by, or raised to the power of another probability. ",
              "Please rewrite the constraint so that each probability appears only ",
              "multiplied by a number."
            )
          } else {
            msg <- paste0(
              "Please check the input:<br><br><b>", spec_txt, "</b>",
              "<br><br>Separate constraints with \";\" or \",\" and use only linear ",
              "terms in the probabilities."
            )
          }

          run_row_here(name_m, h = "fail")
          fairy_run_hide()
          fairy_notify(paste0("Could not read the specification of model ", name_m, "."), msg, type = "error", html = TRUE)
          return(NULL)
        }

        feedback_h_models <- paste(feedback_h_models,
          paste(
            "#", loop_numb_models, " of ",
            numb_models_to_convert,
            ": Creating H-representation of ",
            name_m
          ),
          sep = "<br>"
        )

        probs <- isolate(probs_reactive$value)

        ineq_eq_left <- isolate(ineq_eq_left_reactive$value)
        ineq_eq_right <- isolate(ineq_eq_right_reactive$value)
        all_operators <- isolate(all_operators_reactive$value)

        if (sum(all_operators != "equal") > 0 &
          sum(all_operators == "equal") > 0) {
          # drop = FALSE: with a single probability the selected rows would collapse to a plain vector (ncol(a1) != ncol(a2))
          h_representation <- makeH(
            ineq_eq_left[all_operators != "equal", , drop = FALSE],
            ineq_eq_right[all_operators != "equal"],
            ineq_eq_left[all_operators == "equal", , drop = FALSE],
            ineq_eq_right[all_operators == "equal"]
          )
        }

        if (sum(all_operators != "equal") == 0 &
          sum(all_operators == "equal") > 0) {
          h_representation <- makeH(
            a2 = as.matrix(ineq_eq_left),
            b2 = ineq_eq_right
          )
        }

        if (sum(all_operators != "equal") > 0 &
          sum(all_operators == "equal") == 0) {
          h_representation <- makeH(
            ineq_eq_left,
            ineq_eq_right
          )
        }

        names_p_multi <- c("", "", probs[, 2])

        # Row order matches ineq_eq_left (user clauses first, automatic
        # 0-1 bounds appended after) only when no "=" clauses are mixed in
        # with inequalities — the makeH() branches above reorder rows
        # (all inequalities, then all equalities) when both are present.
        # n_user_clauses is still used to separate "your clause" from
        # "automatic bound" in that mixed case; it can mislabel a handful
        # of rows there, but is exact for the common inequality-only case.
        # 'mixed': whether both equalities and inequalities were present
        # for this model — that's exactly the condition (see comment
        # above) under which makeH() reorders rows relative to
        # ineq_eq_left's original per-clause order, so redundant_rows can
        # no longer be trusted to index into the typed clause order.
        # Used by the "Model Specification" redundant-clause highlighting
        # (see model_redundant_clause_flags) to skip that model entirely
        # rather than risk mislabeling a clause as redundant.
        mixed_eq_ineq <- sum(all_operators != "equal") > 0 && sum(all_operators == "equal") > 0
        if (nrow(h_representation) > 1) {
          red_check <- redundant(h_representation)
          h_raw_rows_reactive[[mytable_input[loop_numb_models, 1]]] <- list(
            raw_H = h_representation,
            redundant_rows = red_check$redundant,
            # implied.linearity: row numbers of inequality rows that,
            # TOGETHER, force an equality (e.g. p1<=p2 and p1>=p2 typed
            # separately actually assert p1==p2) — rcdd computes this
            # directly as part of redundant(), no extra LP needed.
            implied_linearity = red_check$implied.linearity,
            n_user_clauses = n_user_clauses_here,
            mixed_eq_ineq = mixed_eq_ineq
          )
          h_representation <- red_check$output
        } else {
          h_raw_rows_reactive[[mytable_input[loop_numb_models, 1]]] <- list(
            raw_H = h_representation,
            redundant_rows = integer(0),
            implied_linearity = integer(0),
            n_user_clauses = n_user_clauses_here,
            mixed_eq_ineq = mixed_eq_ineq
          )
        }

        colnames(h_representation) <- names_p_multi

        valid_hrep <- lpcdd(h_representation, rep("0", ncol(h_representation) - 2))
        valid_hrep <- ifelse(valid_hrep$solution.type == "Inconsistent", 0, 1)


        ####* Save h-represenation ####

        h_reactive[[mytable_input[loop_numb_models, 1]]] <- h_representation
        cache[[name_m]] <- model_snap


        if (valid_hrep == 0) {
          # loop_numb_models always ranges within 1:nrow(mytable_input) here
          # (both are built from counter_input$n), so this branch was
          # unconditionally taken; a since-removed `else` referenced an
          # undefined `mytable_inter` object that would have crashed this
          # handler had the loop bound ever changed relative to
          # mytable_input.
          empty_set <- c(empty_set, mytable_input[loop_numb_models, 1])
        }

        run_row_here(name_m, h = if (valid_hrep == 0) "warn" else "done")
      }

      model_snap_cache(cache)

      ####* Auto-detect pairwise intersections for Model Properties ####
      # Run pairwise nesting/overlap LP checks now so intersection H-reps
      # exist before the user ever visits the Parsimony tab.
      {
        cur_model_names <- names_models_reactive$value
        n_models <- length(cur_model_names)
        if (n_models >= 2) {
          for (ii in seq_len(n_models - 1)) {
            for (jj in (ii + 1):n_models) {
              nm_i <- cur_model_names[ii]
              nm_j <- cur_model_names[jj]
              H_i <- isolate(h_reactive[[nm_i]])
              H_j <- isolate(h_reactive[[nm_j]])
              if (is.null(H_i) || is.null(H_j)) next

              ij <- tryCatch(nesting_lp(H_i, H_j), error = function(e) NA)
              ji <- tryCatch(nesting_lp(H_j, H_i), error = function(e) NA)

              # only overlapping (non-nested, non-disjoint) pairs need an
              # intersection model; nested models are subsets so volume is
              # the smaller model's own volume
              is_nested <- isTRUE(ij) || isTRUE(ji)
              is_disjoint <- isFALSE(ij) && isFALSE(ji)

              if (!is_nested && !is_disjoint && !is.na(ij) && !is.na(ji)) {
                int_key <- paste0("[", paste(sort(c(nm_i, nm_j)), collapse = " ∩ "), "]")
                if (is.null(isolate(h_reactive[[int_key]]))) {
                  H_comb <- rbind(H_i, H_j)
                  attr(H_comb, "representation") <- "H"
                  H_red <- tryCatch(redundant(H_comb)$output, error = function(e) H_comb)
                  h_reactive[[int_key]] <- H_red
                  cur_ci_names <- isolate(comp_int_reactive$names)
                  if (!int_key %in% cur_ci_names)
                    comp_int_reactive$names <- c(cur_ci_names, int_key)
                }
              }
            }
          }
        }
      }

      if (length(names_models_reactive$value) >= 2)
        showTab(inputId = "tabs", target = "Model Properties")

      ####* Model intersection ####
      # The intersection of a set of models is simply their combined
      # H-description (all constraints must hold simultaneously). The user
      # picks the models in the "Model intersections" modal, so any number of
      # models can be intersected (two -> pairwise, three or more ->
      # higher-order). A cheap LP feasibility test (lpcdd) detects an empty
      # intersection; otherwise the result is reduced with redundant() and
      # stored in h_reactive under "m1 AND m2 AND ..." so it can be displayed,
      # downloaded and converted to a V-description like any other model.
      # Computed BEFORE the V-representation block so V-descriptions can be
      # built for the intersections too.

      intersection_names <- character()
      disjoint_pairs <- character()

      int_table <- isolate(mytable_int_reactive$value)

      int_jobs <- list()
      if (!is.null(int_table) && ncol(int_table) >= 2 && nrow(int_table) >= 1) {
        # one intersection per ROW; columns are the models
        model_cols <- colnames(int_table)[-1]

        for (row_k in seq_len(nrow(int_table))) {
          ticked <- vapply(model_cols, function(cn) isTRUE(int_table[row_k, cn]), logical(1))
          selected_models <- model_cols[ticked]
          all_valid <- c(names_models_reactive$value,
            isolate(items_reactive$names))
          selected_models <- selected_models[selected_models %in% all_valid]

          if (length(selected_models) < 2) next

          int_name <- paste(selected_models, collapse = " AND ")

          # a set already handled by another row
          if (int_name %in% intersection_names || int_name %in% disjoint_pairs) next

          # skip if cached and no component was recomputed
          if (!is.null(isolate(h_reactive[[int_name]])) &&
              !any(selected_models %in% recomputed_models)) {
            intersection_names <- c(intersection_names, int_name)
            next
          }

          int_jobs[[int_name]] <- selected_models
        }
      }

      if (length(int_jobs) > 0) {
        for (nm_run in names(int_jobs)) fairy_run_row(nm_run, "intersection", h = "run")

        h_snapshot <- setNames(
          lapply(names(h_reactive), function(m) isolate(h_reactive[[m]])),
          names(h_reactive)
        )
        int_results <- par_lapply(names(int_jobs), function(int_name) {
          sel <- int_jobs[[int_name]]
          H_sel <- lapply(sel, function(m) h_snapshot[[m]])
          if (any(vapply(H_sel, is.null, logical(1)))) return(list(status = "missing"))
          ncols <- vapply(H_sel, ncol, integer(1))
          if (length(unique(ncols)) > 1) return(list(status = "incompatible"))
          H_comb <- do.call(rbind, H_sel)
          attr(H_comb, "representation") <- "H"
          feasible <- tryCatch(
            lpcdd(H_comb, rep("0", ncol(H_comb) - 2))$solution.type != "Inconsistent",
            error = function(e) TRUE
          )
          if (!feasible) return(list(status = "disjoint"))
          hh <- tryCatch({
            if (nrow(H_comb) > 1) H_comb <- redundant(H_comb)$output
            colnames(H_comb) <- colnames(H_sel[[1]])
            H_comb
          }, error = function(e) NULL)
          list(status = "ok", h = hh)
        })
        names(int_results) <- names(int_jobs)

        incompatible_ints <- character()
        for (int_name in names(int_results)) {
          res <- int_results[[int_name]]
          if (res$status == "incompatible") {
            incompatible_ints <- c(incompatible_ints, int_name)
            fairy_run_row(int_name, h = "fail")
          } else if (res$status == "disjoint") {
            disjoint_pairs <- c(disjoint_pairs, int_name)
            fairy_run_row(int_name, h = "warn")
          } else if (res$status == "ok" && !is.null(res$h)) {
            fairy_run_row(int_name, h = "done")
            h_reactive[[int_name]] <- res$h
            intersection_names <- c(intersection_names, int_name)
            # Without this, the later V-representation recompute check
            # (`m %in% recomputed_models`) never sees intersection names, so
            # an intersection's V-rep (vertices used for plotting/volume)
            # stays stale after its H-rep has just been rebuilt above.
            recomputed_models <- c(recomputed_models, int_name)
          }
        }
        if (length(incompatible_ints) > 0) {
          fairy_notify("Incompatible parameter spaces",
            paste0("The following intersections were skipped because the selected models have different numbers of parameters:\n",
              paste(incompatible_ints, collapse = "\n")), type = "warning")
        }
      }

      intersections_reactive$names <- intersection_names
      intersections_reactive$disjoint <- disjoint_pairs

      ####* Model mixtures ####
      # The mixture of a set of models is the convex hull of the union of their
      # V-representations. Pool all vertices, then call scdd() to get the H-rep
      # of the convex hull. Must run AFTER the V-rep block since it needs
      # v_reactive to be populated.
      #
      # Sourced from derived_model_sources (the "Mixture model" button on
      # the Input tab — see its own comment) rather than the old
      # mytable_mix_reactive dialog table: a mixture is now a real row in
      # the model list (with its own given name, e.g. "mix_m1_m2") instead
      # of a synthetic "m1 OR m2" name kept separate from the main model
      # list. Its trivial/empty H-representation from the main per-model
      # loop above gets OVERWRITTEN here with the real convex-hull result.
      # No caching against a previous run — mixtures are recomputed every
      # Go press, which is fine since the underlying scdd() work is only
      # as expensive as an intersection of the same size.

      mixture_names <- character()
      mix_fail_notes <- character()
      mix_pending <- list()   # mixtures that have to be calculated in their own processes
      # Rows that have to wait for the unpacked models: those built from H-representations of rows that are computed later
      # (unpacked models, and intersections that involve a mixture), and mixtures of such rows.
      dms_all <- isolate(derived_model_sources$value)
      is_late <- function(key, depth = 0) {
        sx <- dms_all[[as.character(key)]]
        if (is.null(sx) || depth > 10) return(FALSE)
        if (isTRUE(sx$by_h)) return(TRUE)
        if (identical(sx$type, "mixture")) return(any(vapply(sx$source_idx, is_late, logical(1), depth = depth + 1)))
        if (identical(sx$type, "intersection"))
          return(any(vapply(sx$source_idx, function(z) identical(dms_all[[as.character(z)]]$type, "mixture") || is_late(z, depth + 1), logical(1))))
        FALSE
      }
      mixture_specs <- dms_all[vapply(names(dms_all), function(k) identical(dms_all[[k]]$type, "mixture") && !is_late(k), logical(1))]

      if (length(mixture_specs) > 0) {
        mix_feedback <- character()
        all_mix_names <- vapply(names(mixture_specs), function(mix_key) {
          mix_row_idx <- suppressWarnings(as.integer(mix_key))
          if (is.na(mix_row_idx) || mix_row_idx > nrow(mytable_input)) return(NA_character_)
          mytable_input$`model name`[mix_row_idx]
        }, character(1))
        all_mix_names <- all_mix_names[!is.na(all_mix_names)]

        for (mix_key in names(mixture_specs)) {
          info <- mixture_specs[[mix_key]]
          mix_row_idx <- suppressWarnings(as.integer(mix_key))
          if (is.na(mix_row_idx) || mix_row_idx > nrow(mytable_input)) next
          mix_name <- mytable_input$`model name`[mix_row_idx]

          selected_mix <- mytable_input$`model name`[info$source_idx[info$source_idx <= nrow(mytable_input)]]
          all_valid_mix <- c(names_models_reactive$value,
            isolate(items_reactive$names))
          selected_mix <- selected_mix[selected_mix %in% all_valid_mix]

          extra_mix <- info$extra_v %||% list()   # vertices of deleted components that stay in the mixture
          # all components deleted, only their stored shapes are left: the mixture keeps its last result
          if (length(selected_mix) == 0 && length(extra_mix) >= 2) {
            fz <- mixture_cache[[mix_name]]
            if (is.null(fz)) {
              # e.g. after loading a saved file: build the mixture from the stored shapes alone
              fz <- tryCatch({
                V_comb <- do.call(rbind, extra_mix); attr(V_comb, "representation") <- "V"
                hh <- scdd(V_comb)$output
                if (nrow(hh) > 1) { hh <- redundant(hh)$output; attr(hh, "representation") <- "H" }
                if (!is.null(colnames(extra_mix[[1]]))) colnames(hh) <- colnames(extra_mix[[1]])
                vv <- scdd(hh)
                if (!is.null(colnames(extra_mix[[1]])) && ncol(vv$output) == ncol(extra_mix[[1]])) colnames(vv$output) <- colnames(extra_mix[[1]])
                list(h = hh, v = vv)
              }, error = function(e) NULL)
              if (!is.null(fz)) mixture_cache[[mix_name]] <- list(sig = NA_character_, h = fz$h, v = fz$v)
            }
            if (!is.null(fz)) {
              h_reactive[[mix_name]] <- fz$h
              v_reactive[[mix_name]] <- fz$v
              mixture_names <- c(mixture_names, mix_name)
              fairy_run_row(mix_name, "mixture", h = "cached", v = "cached")
            }
            next
          }
          if (length(selected_mix) < 1 || length(selected_mix) + length(extra_mix) < 2) next
          assign(mix_name, selected_mix, envir = mix_components)

          # unchanged components (same H-representations as at the last Go): reuse the last mixture
          mix_sig <- paste(selected_mix, collapse = "+")
          mix_sig <- paste(c(mix_sig, vapply(selected_mix, function(m) {
            h <- isolate(h_reactive[[m]])
            if (is.null(h)) "NULL" else paste(c(dim(h), as.vector(h)), collapse = ",")
          }, character(1))), collapse = "|")
          if (length(extra_mix) > 0) mix_sig <- paste(c(mix_sig, vapply(extra_mix, function(m) paste(c(dim(m), as.vector(m)), collapse = ","), character(1))), collapse = "|")
          mix_prev <- mixture_cache[[mix_name]]
          if (!is.null(mix_prev) && identical(mix_prev$sig, mix_sig)) {
            h_reactive[[mix_name]] <- mix_prev$h
            v_reactive[[mix_name]] <- mix_prev$v
            mixture_names <- c(mixture_names, mix_name)
            fairy_run_row(mix_name, "mixture", h = "cached", v = "cached")
            next
          }

          # A mixture that was skipped in this run is left out (the next Go calculates it again)
          mix_res <- get0(mix_sig, envir = mixture_results, inherits = FALSE)
          if (is.null(mix_res) && mix_name %in% isolate(mix_job$skipped)) {
            fairy_run_row(mix_name, "mixture", h = "skip", v = "skip")
            next
          }

          mix_ncols <- vapply(selected_mix, function(m) {
            h <- isolate(h_reactive[[m]]); if (is.null(h)) NA_integer_ else ncol(h)
          }, integer(1))
          if (length(unique(na.omit(mix_ncols))) > 1) {
            ref_ncols <- mix_ncols[1]
            bad_models <- selected_mix[!is.na(mix_ncols) & mix_ncols != ref_ncols]
            fairy_run_row(mix_name, h = "fail", v = "fail")
            fairy_notify("Incompatible parameter spaces",
              paste0(
                "Mixture '", mix_name, "' was skipped because the following models have a different number of parameters than the others: ",
                paste(bad_models, collapse = ", "),
                ". Models can only be mixed if they share the same parameter space."
              ), type = "warning")
            next
          }

          if (is.null(mix_res)) {
            # The model H-reps do not include simplex constraints, so their raw V-reps contain only rays/lines (no finite
            # vertices). To compute a geometrically meaningful mixture the simplex constraints (p_i >= 0, sum = 1) are added
            # to each component before extracting vertices. The calculation itself runs in its own process (see mix_start_jobs).
            h_base_mix <- isolate(h_reactive[[selected_mix[1]]])
            n_p_mix    <- ncol(h_base_mix) - 2L
            cube_h_mix <- d2q(rbind(
              makeH(a1 = -diag(n_p_mix), b1 = rep(0, n_p_mix)),
              makeH(a1 =  diag(n_p_mix), b1 = rep(1, n_p_mix))
            ))
            v1_first <- isolate(v_reactive[[selected_mix[1]]])
            mix_pending[[mix_name]] <- list(sig = mix_sig, input = list(
              sel = selected_mix,
              h = setNames(lapply(selected_mix, function(m) isolate(h_reactive[[m]])), selected_mix),
              cube = cube_h_mix, extra = extra_mix,
              h1_cols = colnames(isolate(h_reactive[[selected_mix[1]]])),
              v1cols = if (!is.null(v1_first) && is.list(v1_first) && !is.null(v1_first$output)) colnames(v1_first$output) else NULL))
            next
          }
          mix_result <- if (!is.null(mix_res$error)) {
            mix_fail_notes <- c(mix_fail_notes, paste0(mix_name, ": ", mix_res$error)); NULL
          } else list(h = mix_res$h, v = mix_res$v)

          if (!is.null(mix_result)) {
            h_reactive[[mix_name]] <- mix_result$h
            v_reactive[[mix_name]] <- mix_result$v
            mixture_names <- c(mixture_names, mix_name)
            mixture_cache[[mix_name]] <- list(sig = mix_sig, h = mix_result$h, v = mix_result$v)
          }
          mix_feedback <- c(mix_feedback, mix_name)
          fairy_run_row(mix_name, h = if (!is.null(mix_result)) "done" else "fail", v = if (!is.null(mix_result)) "done" else "fail")
        }
        # mixtures that still have to be calculated: start their processes and stop here; the run is repeated when they are done
        if (length(mix_pending) > 0) {
          mix_start_jobs(mix_pending)
          last_recomputed_snapshot(NULL)
          return(invisible())
        }
      }

      mixtures_reactive$names <- mixture_names

      ####* Multiple-items models ####
      # Runs BEFORE replication so items models can serve as base for replication.

      items_names  <- character()
      items_specs  <- isolate(mytable_items_reactive$value)
      # Parallel to items_specs — records the computed items_name actually
      # used for h_reactive under THIS spec's position, filled in below
      # regardless of whether it was freshly computed or reused from
      # cache. Used after this block to alias h_reactive back onto
      # whatever name(s) the owning row(s) currently DISPLAY (see the
      # alias pass' own comment for why that can differ from items_name).
      items_name_by_pos <- rep(NA_character_, length(items_specs))

      if (!is.null(items_specs) && length(items_specs) > 0) {
        for (spec_pos in seq_along(items_specs)) {
          spec <- items_specs[[spec_pos]]
          base_m  <- spec$base
          factors <- spec$factors
          pf      <- spec$param_factors

          if (is.null(base_m) || !base_m %in% names(h_reactive)) next
          if (length(factors) == 0) next
          h_base  <- isolate(h_reactive[[base_m]])

          # Which original parameter maps to which stimulus type — NOT
          # captured by items_name (base + factor names/counts + type), so
          # two specs can collide on the same items_name while assigning
          # parameters differently. Compare against the cached matrix's own
          # tag (see type_assignment attr below) to force a recompute when
          # only the assignment changed, instead of silently reusing stale
          # data for the new assignment.
          # pf can include 0 for parameters assigned to "Shared" (not tied
          # to any factor) — factors[[0]] is invalid in R, so those must be
          # excluded from the factor-name lookup rather than indexed.
          pf_assigned <- pf[pf > 0]
          cur_assignment <- paste(
            vapply(pf_assigned, function(fi) factors[[fi]]$name, character(1)),
            collapse = ","
          )

          # A type PER FACTOR (factor_types) and a tolerance PER
          # PROBABILITY (eps_per_param — see build_items_h_mixed's own
          # comment) — produces exactly ONE combined model per spec,
          # named from each factor's own type and its members' own
          # tolerances.
          factor_types  <- spec$factor_types
          eps_per_param <- spec$eps_per_param

          factor_tag_full <- items_tag_string(factors, factor_types, pf, eps_per_param)
          items_name <- paste0(base_m, " [", factor_tag_full, "]")
          items_name_by_pos[spec_pos] <- items_name

          if (!items_name %in% items_names) {
            cached_h <- isolate(h_reactive[[items_name]])
            if (!is.null(cached_h) && !base_m %in% recomputed_models &&
                identical(attr(cached_h, "type_assignment"), cur_assignment)) {
              items_names <- c(items_names, items_name)
              fairy_run_row(items_name, "items", h = "cached")
            } else {
              fairy_run_row(items_name, "items", h = "run")

              h_it <- tryCatch({
                # build_items_h_mixed honors each factor's own type
                # (joint/substitutable/identical/average, real semantics
                # for each — see its own comment) independently, so it is
                # correct whether every factor shares one type or they
                # are genuinely mixed.
                m_mat <- build_items_h_mixed(h_base, factors, pf, factor_types, eps_per_param)
                saved_cn <- colnames(m_mat)
                m_mat <- d2q(m_mat); attr(m_mat, "representation") <- "H"
                if (nrow(m_mat) > 1) {
                  m_mat <- redundant(m_mat)$output; attr(m_mat, "representation") <- "H"
                }
                colnames(m_mat) <- saved_cn
                attr(m_mat, "type_assignment") <- cur_assignment
                m_mat
              }, error = function(e) { message("items error [", items_name, "]: ", conditionMessage(e)); NULL })

              if (!is.null(h_it)) {
                h_reactive[[items_name]] <- h_it
                items_names <- c(items_names, items_name)
                recomputed_models <- c(recomputed_models, items_name)
                fairy_run_row(items_name, h = "done")
              } else {
                fairy_run_row(items_name, h = "fail")
                fairy_notify(paste0("Failed: ", items_name), "Check the R console for details.", type = "error")
              }
            }
          }
        }
      }

      # An items row's REAL data always lives in h_reactive under its
      # spec-computed items_name (base model's name + factor tag) — but
      # the "loop models" pass just above processes EVERY row, including
      # this one, off its own (blank, since the row's spec box is
      # disabled) typed text, writing an empty/unconstrained
      # h_reactive[[<row's own current display name>]] for it — normally
      # harmless, since that display name starts out equal to items_name
      # and this items block's own write (above, same h_reactive[[
      # items_name]] key) simply overwrites it right back to the correct
      # value. But once a user renames the ROW itself (its Name box) to
      # something that no longer matches the auto-generated items_name —
      # a supported, ordinary rename, no different from renaming any
      # other model — the two keys diverge: the row's own display name
      # keeps pointing at the stale EMPTY entry the main loop wrote,
      # while the correct data sits under a name nothing on screen shows
      # anymore. Confirmed directly: renaming an items row produced a
      # SECOND, unconstrained card under the new name, alongside the
      # correct one still sitting under the old computed name. Move
      # (not just copy) h_reactive's entry onto whatever name the row
      # currently displays, and drop the old computed name out of
      # items_names too, so exactly one card shows — under the row's
      # own current name, same as every other model type already works.
      if (length(items_specs) > 0) {
        spec_idx_map <- isolate(item_model_spec_idx$value)
        for (row_key in names(spec_idx_map)) {
          si <- spec_idx_map[[row_key]]
          if (is.null(si) || si < 1 || si > length(items_name_by_pos) || is.na(items_name_by_pos[si])) next
          computed_name <- items_name_by_pos[si]
          row_idx <- suppressWarnings(as.integer(row_key))
          if (is.na(row_idx) || row_idx < 1 || row_idx > nrow(mytable_input)) next
          row_display_name <- mytable_input[row_idx, 1]
          if (!identical(row_display_name, computed_name) &&
              !is.null(isolate(h_reactive[[computed_name]]))) {
            h_reactive[[row_display_name]] <- isolate(h_reactive[[computed_name]])
            # a copy of an unpacked row has the same computed name as the row it was copied from: that row still shows the
            # computed name, so its entry must stay (copy instead of move), or the original loses its H-representation
            other_rows_use_it <- computed_name %in% mytable_input[-row_idx, 1]
            if (other_rows_use_it) {
              items_names <- union(items_names, row_display_name)
              if (computed_name %in% recomputed_models) recomputed_models <- union(recomputed_models, row_display_name)
              next
            }
            h_reactive[[computed_name]] <- NULL
            items_names[items_names == computed_name] <- row_display_name
            # recomputed_models also still says computed_name — same
            # rename applied here so the V-representation block's own
            # "was this model just recomputed" check (a few lines below,
            # keyed by the row's CURRENT display name) still finds it and
            # doesn't skip a stale pre-rename V-rep cache entry.
            recomputed_models[recomputed_models == computed_name] <- row_display_name
          }
        }
      }

      items_reactive$names <- items_names

      ####* Intersections of unpacked models ####
      # An intersection row built from unpacked rows that share the same items has no constraint text: its
      # H-representation is the stack of its sources' H-representations (same item space, same columns).
      # intersections that involve a mixture (also ones saved by an earlier version), unpacked-model combinations and
      # mixtures of those: built from the H-representations of their sources
      hint_specs <- dms_all[vapply(names(dms_all), is_late, logical(1))]
      hint_mix_names <- character()
      hint_notes <- character()
      for (hk in names(hint_specs)[order(suppressWarnings(as.integer(names(hint_specs))))]) {
        info <- hint_specs[[hk]]
        h_row_idx <- suppressWarnings(as.integer(hk))
        if (is.na(h_row_idx) || h_row_idx > nrow(mytable_input)) next
        h_row_name <- mytable_input[h_row_idx, 1]
        src_nm <- mytable_input[info$source_idx[info$source_idx <= nrow(mytable_input)], 1]
        is_mix_h <- identical(info$type, "mixture")
        fairy_run_row(h_row_name, if (is_mix_h) "mixture" else "intersection", h = "run")
        H_src <- lapply(src_nm, function(m) isolate(h_reactive[[m]]))
        H_src <- c(H_src, info$extra_h %||% list())   # last H-representations of deleted source models
        if (length(H_src) < 2 || any(vapply(H_src, is.null, logical(1)))) {
          fairy_run_row(h_row_name, h = "fail"); next
        }
        # same item space = same set of probability/item columns; the order depends on how the items were grouped
        ref_cn <- colnames(H_src[[1]])
        same_space <- all(vapply(H_src, function(h) ncol(h) == length(ref_cn) && !anyDuplicated(colnames(h)[-(1:2)]) &&
          setequal(colnames(h)[-(1:2)], ref_cn[-(1:2)]), logical(1)))
        if (same_space) H_src <- lapply(H_src, function(h) {
          if (identical(colnames(h), ref_cn)) return(h)
          h2 <- h[, c(1:2, 2L + match(ref_cn[-(1:2)], colnames(h)[-(1:2)])), drop = FALSE]
          colnames(h2) <- ref_cn
          h2
        })
        if (!same_space) {
          fairy_run_row(h_row_name, h = "fail")
          hint_notes <- c(hint_notes, paste0(h_row_name, ": its models do not have the same number of items for every probability, so they live in different spaces"))
          next
        }
        # unchanged sources (same H-representations as at the last Go): reuse the last result instead of recomputing it
        hint_sig <- paste(c(info$type, vapply(H_src, function(h) paste(c(dim(h), as.vector(h)), collapse = ","), character(1))), collapse = "|")
        hint_prev <- hint_cache[[h_row_name]]
        if (!is.null(hint_prev) && identical(hint_prev$sig, hint_sig)) {
          h_reactive[[h_row_name]] <- hint_prev$h
          if (!is.null(hint_prev$v)) v_reactive[[h_row_name]] <- hint_prev$v
          if (is_mix_h) hint_mix_names <- c(hint_mix_names, h_row_name)
          fairy_run_row(h_row_name, h = "cached", v = if (!is.null(hint_prev$v)) "cached" else NULL)
          next
        }
        if (is_mix_h) {
          # mixture: convex hull of the union of the sources' vertices (inside the unit cube)
          n_p_h <- ncol(H_src[[1]]) - 2L
          cube_h_i <- d2q(rbind(makeH(a1 = -diag(n_p_h), b1 = rep(0, n_p_h)), makeH(a1 = diag(n_p_h), b1 = rep(1, n_p_h))))
          V_src <- lapply(H_src, function(h) {
            h_full <- rbind(h, cube_h_i); attr(h_full, "representation") <- "H"
            v_out <- tryCatch(scdd(h_full)$output, error = function(e) NULL)
            if (is.null(v_out)) NULL else v_out[v_out[, 2] == "1", , drop = FALSE]
          })
          V_src <- Filter(function(v) !is.null(v) && nrow(v) > 0, V_src)
          if (length(V_src) == 0) {
            fairy_run_row(h_row_name, h = "fail", v = "fail")
            hint_notes <- c(hint_notes, paste0(h_row_name, ": its models have no extreme cases to combine"))
            next
          }
          h_cn_mix <- colnames(H_src[[1]])
          mix_res <- tryCatch({
            V_comb <- do.call(rbind, V_src); attr(V_comb, "representation") <- "V"
            hh <- scdd(V_comb)$output
            if (nrow(hh) > 1) { hh <- redundant(hh)$output; attr(hh, "representation") <- "H" }
            colnames(hh) <- h_cn_mix
            vv <- scdd(hh)
            if (ncol(vv$output) == length(h_cn_mix)) colnames(vv$output) <- h_cn_mix
            list(h = hh, v = vv)
          }, error = function(e) NULL)
          if (is.null(mix_res)) {
            fairy_run_row(h_row_name, h = "fail", v = "fail")
            hint_notes <- c(hint_notes, paste0(h_row_name, ": the mixture could not be computed"))
            next
          }
          h_reactive[[h_row_name]] <- mix_res$h
          v_reactive[[h_row_name]] <- mix_res$v
          hint_cache[[h_row_name]] <- list(sig = hint_sig, h = mix_res$h, v = mix_res$v)
          recomputed_models <- c(recomputed_models, h_row_name)
          hint_mix_names <- c(hint_mix_names, h_row_name)
          fairy_run_row(h_row_name, h = "done", v = "done")
          next
        }
        H_comb <- do.call(rbind, lapply(H_src, function(h) { attr(h, "type_assignment") <- NULL; h }))
        attr(H_comb, "representation") <- "H"
        feasible <- tryCatch(lpcdd(H_comb, rep("0", ncol(H_comb) - 2))$solution.type != "Inconsistent", error = function(e) TRUE)
        if (!feasible) {
          fairy_run_row(h_row_name, h = "warn")
          hint_notes <- c(hint_notes, paste0(h_row_name, ": the models have nothing in common (empty set)"))
          next
        }
        h_cn_int <- colnames(H_src[[1]])
        hh <- tryCatch({
          if (nrow(H_comb) > 1) H_comb <- redundant(H_comb)$output
          attr(H_comb, "representation") <- "H"
          colnames(H_comb) <- h_cn_int
          H_comb
        }, error = function(e) NULL)
        if (is.null(hh)) { fairy_run_row(h_row_name, h = "fail"); next }
        h_reactive[[h_row_name]] <- hh
        recomputed_models <- c(recomputed_models, h_row_name)
        fairy_run_row(h_row_name, h = "done", v = "run")
        vv <- tryCatch(scdd(hh), error = function(e) NULL)
        if (!is.null(vv) && nrow(vv$output) > 0) {
          if (ncol(vv$output) == length(h_cn_int)) colnames(vv$output) <- h_cn_int
          v_reactive[[h_row_name]] <- vv
          hint_cache[[h_row_name]] <- list(sig = hint_sig, h = hh, v = vv)
          fairy_run_row(h_row_name, v = "done")
        } else {
          fairy_run_row(h_row_name, v = "fail")
        }
      }

      if (length(hint_mix_names)) mixtures_reactive$names <- unique(c(isolate(mixtures_reactive$names), hint_mix_names))

      ####* V-representation ####
      # Runs after items so all H-reps are available.


      # Used to blindly overwrite mytable_v_reactive$value's names by
      # POSITION with mytable_input's current names — a leftover
      # assumption from when that table was always fully rebuilt (by the
      # old "V-representations" dialog's Submit) in exactly mytable_
      # input's order, so position-based realignment happened to be safe.
      # The per-model V toggle (fairy-vrep-toggle-btn) instead grows this
      # table incrementally via rbind() as models get toggled, in
      # whatever order that happened — no longer guaranteed to match
      # mytable_input's order or length, so renaming by position silently
      # reassigned some models' V-representation selection to a
      # DIFFERENT model. Now a no-op; a model renamed after being toggled
      # on will keep its selection under the old name instead (a milder,
      # pre-existing-style edge case, not active misattribution).
      sync_model_rows <- function(nm) nm

      if (!is.null(mytable_v_reactive$value)) {
        mytable_v_reactive$value$`Model name` <-
          sync_model_rows(mytable_v_reactive$value$`Model name`)
      }

      mytable_v <- mytable_v_reactive$value

      if (!exists("names_p_multi")) {
        probs_tmp <- isolate(probs_reactive$value)
        names_p_multi <- c("", "", probs_tmp[, 2])
      }

      v_async <- FALSE; v_pending_note <- ""
      if (!is.null(mytable_v) && sum(mytable_v[, 2]) > 0) {
        mytable_v_reactive$value$`Model name` <- sync_model_rows(mytable_v$`Model name`)
        mytable_v$`Model name` <- sync_model_rows(mytable_v$`Model name`)

        models_picked_for_v_representation <- mytable_v[which(mytable_v[, 2]), 1]
        models_picked_for_v_representation <-
          models_picked_for_v_representation[!is.na(models_picked_for_v_representation)]
        # a stale row of the V-selection table (a model that was renamed or removed
        # since) has no H-representation and must not show up as a failed model
        models_picked_for_v_representation <-
          models_picked_for_v_representation[models_picked_for_v_representation %in% isolate(names(h_reactive))]

        invalid_model <- character()

        models_to_compute_v <- models_picked_for_v_representation[vapply(
          models_picked_for_v_representation,
          function(m) is.null(isolate(v_reactive[[m]])) || m %in% recomputed_models,
          logical(1)
        )]

        # the vertices are worked on in the same order as the rows of the window
        if (exists("run_rank", inherits = FALSE) && length(models_to_compute_v) > 1) {
          rk <- run_rank[models_to_compute_v]; rk[is.na(rk)] <- 0
          models_to_compute_v <- models_to_compute_v[order(rk, seq_along(rk))]
        }
        for (m_run in models_picked_for_v_representation)
          fairy_run_row(m_run, v = if (m_run %in% models_to_compute_v) "wait" else "cached")

        v_run_note <- paste0(fairy_empty_set_note(empty_set),
          if (length(mix_fail_notes)) paste0("<br><b>Mixture failed</b> - ", paste(htmltools::htmlEscape(mix_fail_notes), collapse = "; ")) else "",
          if (length(hint_notes)) paste0("<br><b>Intersection failed</b> - ", paste(htmltools::htmlEscape(hint_notes), collapse = "; ")) else "")
        if (length(models_to_compute_v) > 0) {
          # the vertices are computed in separate processes (the window shows the progress and can cancel); the tables of the
          # V-representation are built when they are there (render_v_tail, see below)
          v_async <- TRUE
          v_pending_note <- v_run_note
          v_start_jobs(models_to_compute_v)
        } else {
          fairy_run_end(v_run_note)
        }
      } else {
        hideTab(inputId = "tabs", target = "V-representation")
        hideTab(inputId = "tabs", target = "Plot Polytope(s)")
        hideTab(inputId = "tabs", target = "Plot Edge Cases")
        fairy_run_end(paste0(fairy_empty_set_note(empty_set),
          if (length(mix_fail_notes)) paste0("<br><b>Mixture failed</b> - ", paste(htmltools::htmlEscape(mix_fail_notes), collapse = "; ")) else "",
          if (length(hint_notes)) paste0("<br><b>Intersection failed</b> - ", paste(htmltools::htmlEscape(hint_notes), collapse = "; ")) else ""))
      }

      ####* Display Formula H-Representation ####

      equation_all_total <- numeric()
      # Parallel plain-LaTeX collection (see equation_all_total_latex_
      # reactive's own comment) — one align* block appended per model,
      # alongside (not instead of) the HTML card text above.
      equation_all_total_latex <- list()

      # Global parameter display order (p1, p2, ... in their current,
      # possibly-renamed form), fixed once per Go run so param_color_map
      # can assign the SAME color to the same probability across every
      # model card below, instead of a fresh per-table assignment that
      # drifted whenever a model's own column order differed.
      global_param_names <- isolate(probs_reactive$value)[, 2]

      # unique(): mixture_names now overlaps names_models_reactive$value —
      # a "Mixture model" row is a real, named row in the model list
      # itself (see derived_model_sources), not a separate synthetic name
      # the way the old dialog-driven mixtures were.
      all_display_names <- unique(c(names_models_reactive$value, intersection_names, mixture_names, items_names))
      # Reorder to match the Input tab's own row order (top to bottom)
      # instead of this category-grouped order (plain models, then
      # intersections, then mixtures, then items) — an intersection or
      # mixture row can sit anywhere among the plain ones on Input (it's
      # a real row there too, not appended separately), so the H-rep/
      # V-rep cards should read top-to-bottom the same way. row_order
      # below is exactly that visual order; intersect() keeps only names
      # actually in scope here while adopting row_order's ordering, and
      # setdiff() tacks on anything (rare) not yet reflected in a row —
      # same fallback the old unqualified order effectively was.
      row_order <- if (counter_input$n > 0) vapply(seq_len(counter_input$n), function(i)
        input[[paste0("textin_relations_name", i)]] %||% paste0("m", i), character(1)) else character(0)
      all_display_names <- c(intersect(row_order, all_display_names), setdiff(all_display_names, row_order))
      for (loop_latex in seq_along(all_display_names)) {
        current_name <- all_display_names[loop_latex]

        h_representation_latex <- q2d(h_reactive[[current_name]])
        h_representation_latex <- fractions(h_representation_latex)

        p_names_lt <- colnames(h_representation_latex)[-(1:2)]
        n_p_lt    <- length(p_names_lt)

        # Remove adjacent duplicate parameter columns (can arise in some model constructions)
        if (n_p_lt > 1) {
          keep <- c(TRUE, p_names_lt[-1] != p_names_lt[-n_p_lt])
          if (!all(keep)) {
            keep_cols <- c(1L, 2L, which(keep) + 2L)
            h_representation_latex <- h_representation_latex[, keep_cols, drop = FALSE]
            p_names_lt <- p_names_lt[keep]
            n_p_lt <- length(p_names_lt)
          }
        }

        n_equal   <- sum(h_representation_latex[, 1] == 1)
        n_inequal <- sum(h_representation_latex[, 1] == 0)

        # Non-trivial inequality count, for the corner badge below — the
        # same "+p_i <= 1" / "-p_i <= 0" bound test used for the
        # fairy-trivial-row class further down, computed once up front
        # here so both the badge and the per-row class share one
        # definition instead of drifting apart.
        trivial_vec <- vapply(seq_len(nrow(h_representation_latex)), function(ri) {
          row <- h_representation_latex[ri, ]
          if (row[1] == 1) return(FALSE)
          rhs <- row[2]
          cf  <- -row[-(1:2)]
          nz  <- which(cf != 0)
          length(nz) == 1 && ((cf[nz] == 1 && rhs == 1) || (cf[nz] == -1 && rhs == 0))
        }, logical(1))
        n_inequal_real <- n_inequal - sum(trivial_vec)

        # One color per column, keyed by the parameter's position in the
        # app's global probability list, so the same probability keeps
        # the same color across every model card (see global_param_names
        # above and param_color_map's own comment).
        col_color <- param_color_map(p_names_lt, global_param_names)

        if (TRUE) {

          row_data <- lapply(seq_len(nrow(h_representation_latex)), function(ri) {
            row    <- h_representation_latex[ri, ]
            is_eq  <- row[1] == 1
            rhs    <- row[2]
            # rcdd's H-representation stores coefficients as the negation of
            # the constraint's true left-hand side (a = -v internally), so
            # the row must be negated back before display or the printed
            # inequality/equation reads in the wrong direction.
            coeffs <- -row[-(1:2)]
            # Inequalities always stay "<=" — never flipped to ">=" (an
            # earlier version flipped the whole row, negating every
            # coefficient and the rhs, whenever that meant fewer minus
            # signs; dropped because novices reading ">=" sporadically
            # mixed in with "<=" rows was its own source of confusion).
            # Minus signs are still cleared, just via the trick below
            # instead — moving negative terms across to the rhs, which
            # doesn't touch the operator at all.
            nz_all <- which(coeffs != 0)
            neg_all <- nz_all[coeffs[nz_all] < 0]
            # Move every negative term across to the rhs — "+p1 -p2 <= 0"
            # becomes "p1 <= p2", "-p1 -p2 +p3 <= 5" becomes
            # "p3 <= 5 +p1 +p2" — algebraically identical (add the term
            # to both sides), the general "move it to the other side"
            # from school algebra. Applies to equalities too (an "="
            # doesn't care which side a term is on either) — only the
            # earlier whole-row FLIP was inequality-specific (it swapped
            # the operator, which "=" has no direction to swap). If
            # EVERY coefficient is negative (e.g. the trivial "-p_i <= 0"
            # bound), moving all of them leaves the lhs with nothing —
            # handled below by showing an explicit "0" there
            # ("0 <= p_i") rather than a blank-looking gap in front of
            # the operator.
            move_idx <- neg_all
            # A negative CONSTANT (rhs < 0, e.g. "p3 <= p2 - 1/3") is the
            # same "novices reading a minus sign" problem the term-moving
            # above already solves for variable coefficients — move it to
            # the lhs too, same "add it to both sides" algebra, so it
            # shows up as a positive number there instead
            # ("1/3 + p3 <= p2"). Rendered in its own leading cell rather
            # than folded into one of the per-parameter <td>s, since it
            # isn't tied to any single parameter's column.
            lhs_const <- if (rhs < 0) abs(rhs) else 0
            rhs_const <- if (rhs > 0) rhs else 0
            list(is_eq = is_eq, coeffs = coeffs, nz_all = nz_all, move_idx = move_idx,
                 lhs_const = lhs_const, rhs_const = rhs_const)
          })
          # co/aco carry the "fractions" class from the matrix-wide
          # fractions() call above; as.character()/paste0() on a
          # fractions value invoke its print formatter, which has the
          # same silent-rounds-tiny-numbers-to-0 issue as num2str_lin
          # was fixed for — go through num2str_lin on the plain numeric
          # instead of trusting the fractions formatter directly.
          # a term only gets a "+" when something already stands in front of it on its side of the row
          math_of <- function(co, j, lead = FALSE) {
            aco <- abs(co)
            coef_str <- if (aco == 1) "" else num2str_lin(as.numeric(aco))
            paste0(if (co > 0) (if (lead) "" else "+") else "-", coef_str, tex_name(p_names_lt[j]))
          }
          # Plain (Aligned layout): column position ALREADY is the
          # same-parameter cue there, so an added color would be
          # redundant noise, not a second signal.
          # the item of a term (p_{1}^{(2)} is item 2): the wrapper only carries it; the background shows when "Items" is switched on
          item_wrap <- function(j, inner) {
            m <- regmatches(p_names_lt[j], regexec("\\^\\{\\((?:.*,)?([0-9]+)\\)\\}$", p_names_lt[j], perl = TRUE))[[1]]
            if (length(m) != 2) return(inner)
            paste0('<span class="fairy-iw" data-item="', ((as.integer(m[2]) - 1L) %% 8L) + 1L, '">', inner, '</span>')
          }
          # the colour of the parameter only travels with the term (--pc); whether it shows is a switch in the CSS, so switching the
          # colour on or off changes nothing in the size or the place of anything
          # position of the parameter in the app's list of probabilities (0 = unknown): the buttons that grey a parameter out use it
          col_par_idx <- match(param_base_name(p_names_lt), global_param_names)
          col_par_idx[is.na(col_par_idx)] <- 0L
          term_html <- function(co, j, lead = FALSE)
            item_wrap(j, paste0('<span class="fairy-pt', if (!grepl("\\^\\{\\((?:.*,)?[0-9]+\\)\\}$", p_names_lt[j], perl = TRUE)) ' fairy-pt-solo' else '', '" data-par="', col_par_idx[j], '" style="--pc:', col_color[j], ';">\\(', math_of(co, j, lead), '\\)</span>'))
          # Colored (Compact layout only): color by column (see
          # col_color/param_color_map), set before the \\(...\\) so
          # MathJax's rendered output inherits it (renders in
          # currentColor by default) — the substitute cue once Compact
          # has dropped column alignment.
          term_html_colored <- function(co, j, lead = FALSE)
            item_wrap(j, paste0('<span style="color:', col_color[j], ';">\\(', math_of(co, j, lead), '\\)</span>'))

          # ---- Aligned layout: one <td> per parameter column, same
          # column top-to-bottom for the same parameter (see
          # h_layout_toggle_group's own comment). Empty cells get almost no
          # padding since they carry no text — real savings only when a
          # column is genuinely unused by every row, but harmless
          # otherwise. Built twice, once plain and once with
          # term_html_colored — color used to be Compact-only (column
          # position already being Aligned's own same-parameter cue was
          # reason enough not to bother), but color is now its own
          # independent toggle (see h_layout_toggle_group / h_color_
          # toggle_group's own comments) that has to work under EITHER
          # layout, not just Compact. ----
          build_aligned_rows <- function(term_fn) {
            vapply(seq_along(row_data), function(ri) {
              d <- row_data[[ri]]
              lhs_empty <- d$lhs_const == 0 && length(d$move_idx) > 0 && length(d$move_idx) == length(d$nz_all)
              bg <- if (ri %% 2 == 0) 'background:var(--ct-default);' else 'background:var(--fairy-panel);'
              lhs_first <- { l <- setdiff(d$nz_all, d$move_idx); if (length(l)) min(l) else NA }
              rhs_first <- if (length(d$move_idx)) min(d$move_idx) else NA
              lhs_const_cell <- paste0('<td style="padding:3px ', if (d$lhs_const > 0) '4px' else '1px', ';text-align:right;">',
                if (d$lhs_const > 0) paste0('\\(', num2str_lin(as.numeric(d$lhs_const)), '\\)') else '',
                '</td>')
              td_cells <- paste(vapply(seq_len(n_p_lt), function(j) {
                co <- d$coeffs[j]
                if (co == 0 || j %in% d$move_idx)
                  return('<td style="padding:3px 1px;"></td>')
                paste0('<td style="padding:3px 4px;text-align:right;">', term_fn(co, j, lead = d$lhs_const == 0 && isTRUE(j == lhs_first)), '</td>')
              }, character(1)), collapse = "")
              td_cells <- paste0(lhs_const_cell, td_cells)
              op_math  <- if (d$is_eq) "=" else "\\leq"
              if (lhs_empty) op_math <- paste0("0 ", op_math)
              # Right side laid out the same way as the left: its own
              # constant cell, then one cell per parameter, each moved term
              # in the SAME column index j its parameter already occupies
              # on the lhs — column order lines up top-to-bottom with the
              # lhs's own p1, p2, p3... layout instead of a free-form blob
              # that could list moved terms in a different order row to
              # row (items-expanded models lay columns out level-major,
              # not always p1-before-p2 — see the reordering this avoids).
              rhs_const_cell <- paste0('<td style="padding:3px ', if (d$rhs_const > 0) '4px' else '1px', ';text-align:right;">',
                if (d$rhs_const > 0) paste0('\\(', num2str_lin(as.numeric(d$rhs_const)), '\\)') else '',
                '</td>')
              rhs_td_cells <- paste(vapply(seq_len(n_p_lt), function(j) {
                if (!(j %in% d$move_idx))
                  return('<td style="padding:3px 1px;"></td>')
                paste0('<td style="padding:3px 4px;text-align:right;">', term_fn(abs(d$coeffs[j]), j, lead = d$rhs_const == 0 && isTRUE(j == rhs_first)), '</td>')
              }, character(1)), collapse = "")
              rhs_empty <- d$rhs_const == 0 && length(d$move_idx) == 0
              rhs_cells <- paste0(rhs_const_cell, rhs_td_cells)
              if (rhs_empty) {
                # Neither side has anything left after the constant/term
                # moves above (e.g. a bound that fully collapsed) — same
                # "show an explicit 0 instead of a blank-looking gap"
                # handling the lhs_empty case already gets, just mirrored
                # onto the (per-column) rhs: put it in the rhs's own
                # constant cell rather than leaving every cell empty.
                rhs_cells <- paste0(
                  '<td style="padding:3px 4px;text-align:right;">\\(0\\)</td>',
                  paste(rep('<td style="padding:3px 1px;"></td>', n_p_lt), collapse = "")
                )
              }
              # Trivial row: the automatic "keep this probability inside
              # [0,1]" bound rather than something the user actually typed
              # — see trivial_vec above (single source of truth, also used
              # for the card's non-trivial-count badge below). Flagged with
              # a class so the client-side show/gray/hide toggle (see the
              # tags$script below) can act on it without a server round-trip.
              tr_class <- if (trivial_vec[ri]) ' class="fairy-trivial-row"' else ""
              paste0('<tr', tr_class, ' style="', bg, '">',
                     td_cells,
                     '<td style="padding:3px 6px;text-align:center;">\\(', op_math, '\\)</td>',
                     rhs_cells,
                     '</tr>')
            }, character(1))
          }
          row_htmls_aligned_plain   <- build_aligned_rows(term_html)

          # ---- Compact layout: every row packs only its OWN terms into
          # one cell per side, so a row is exactly as wide as its own
          # content regardless of how many other parameters exist
          # elsewhere in the model — no reserved-but-empty columns. Built
          # twice, once plain and once with term_html_colored (col_color
          # is the substitute same-parameter cue once packing drops
          # column position) — color is its own independent toggle (see
          # h_color_toggle_group's own comment), not tied to this layout
          # specifically; Aligned gets the same plain/colored pair above
          # for the same reason. ----
          build_packed_rows <- function(term_fn) {
            vapply(seq_along(row_data), function(ri) {
              d <- row_data[[ri]]
              bg <- if (ri %% 2 == 0) 'background:var(--ct-default);' else 'background:var(--fairy-panel);'
              lhs_idx <- setdiff(d$nz_all, d$move_idx)
              lhs_parts <- c(
                if (d$lhs_const > 0) paste0('\\(', num2str_lin(as.numeric(d$lhs_const)), '\\)') else NULL,
                vapply(seq_along(lhs_idx), function(k) term_fn(d$coeffs[lhs_idx[k]], lhs_idx[k], lead = d$lhs_const <= 0 && k == 1), character(1))
              )
              if (length(lhs_parts) == 0) lhs_parts <- '\\(0\\)'
              rhs_parts <- c(
                if (d$rhs_const > 0) paste0('\\(', num2str_lin(as.numeric(d$rhs_const)), '\\)') else NULL,
                vapply(seq_along(d$move_idx), function(k) term_fn(abs(d$coeffs[d$move_idx[k]]), d$move_idx[k], lead = d$rhs_const <= 0 && k == 1), character(1))
              )
              if (length(rhs_parts) == 0) rhs_parts <- '\\(0\\)'
              op_math <- if (d$is_eq) "=" else "\\leq"
              tr_class <- if (trivial_vec[ri]) ' class="fairy-trivial-row"' else ""
              paste0('<tr', tr_class, ' style="', bg, '">',
                     '<td style="padding:3px 8px;text-align:right;">', paste(lhs_parts, collapse = " "), '</td>',
                     '<td style="padding:3px 6px;text-align:center;">\\(', op_math, '\\)</td>',
                     '<td style="padding:3px 8px;text-align:left;">', paste(rhs_parts, collapse = " "), '</td>',
                     '</tr>')
            }, character(1))
          }
          row_htmls_packed_plain   <- build_packed_rows(term_html)

          tbl_html <- paste0(
            '<div class="fairy-h-table-scroll">',
            # display:inline-table (not the default 'table', which
            # stretches to fill its containing block's full width
            # regardless of how narrow the actual content is, spreading
            # the leftover space evenly across columns — exactly the
            # huge blank gaps reported) makes the table size to its own
            # content instead, like an inline-block. Also what makes
            # window.fitHTablesToWidth's scrollWidth measurement
            # meaningful at all — with the old stretch-to-fill behavior
            # scrollWidth was always ~= the wrapper's own width by
            # construction, so it never found anything to shrink.
            '<table class="fairy-h-aligned-plain-table" style="display:inline-table;border-collapse:collapse;font-size:0.85em;margin-top:6px;white-space:nowrap;">',
            paste(row_htmls_aligned_plain, collapse = ""),
            '</table>',
            '<table class="fairy-h-packed-plain-table" style="display:none;border-collapse:collapse;font-size:0.85em;margin-top:6px;white-space:nowrap;">',
            paste(row_htmls_packed_plain, collapse = ""),
            '</table>',
            '</table></div>')
          count_badge <- paste0(
            '<div class="fairy-h-count-badge fairy-tooltip" data-tooltip="Excludes the automatic 0-1 bounds">',
            n_equal, ' eq · ', n_inequal_real, ' ineq</div>'
          )
          # many probabilities: one reserved column per probability makes the aligned table very wide and mostly empty
          # (an unpacked items model easily has 15 or more), so such a card is shown compactly (see the CSS .fairy-auto-pack-flag)
          # (the automatic switch to the compact layout for models with many probabilities is off: the Layout buttons decide)
          pack_flag <- ''
          equation_all <- paste0(
            count_badge,
            '<div class="model-card-title">', card_title_html(current_name), '</div>', pack_flag, tbl_html)

          # Plain-LaTeX align* block for this model, reusing the same
          # math_of()/row_data/trivial_vec already computed above for the
          # HTML cards — real \leq/\text{...} macros (valid LaTeX either
          # way), just without the <table>/<span> markup that's only
          # meaningful to a browser/MathJax, which is what made the old
          # "LaTeX file" download fail to compile (see d_latex's own
          # comment). Trivial 0-1 bound rows are skipped here too, same
          # as the count badge already excludes them.
          # All rows are kept here, with a flag for the trivial 0-1 bounds: the download decides at the
          # moment of the click which of them to write (show / gray / hide), following the toggle on the screen
          latex_parts <- lapply(seq_along(row_data), function(ri) {
            d <- row_data[[ri]]
            lhs_set <- setdiff(d$nz_all, d$move_idx)
            lhs_terms <- c(
              if (d$lhs_const > 0) num2str_lin(as.numeric(d$lhs_const)) else NULL,
              vapply(seq_along(lhs_set), function(k) math_of(d$coeffs[lhs_set[k]], lhs_set[k], lead = d$lhs_const <= 0 && k == 1), character(1))
            )
            if (length(lhs_terms) == 0) lhs_terms <- "0"
            rhs_terms <- c(
              if (d$rhs_const > 0) num2str_lin(as.numeric(d$rhs_const)) else NULL,
              vapply(seq_along(d$move_idx), function(k) math_of(abs(d$coeffs[d$move_idx[k]]), d$move_idx[k], lead = d$rhs_const <= 0 && k == 1), character(1))
            )
            if (length(rhs_terms) == 0) rhs_terms <- "0"
            list(lhs = paste(lhs_terms, collapse = ""), op = if (d$is_eq) "=" else "\\leq", rhs = paste(rhs_terms, collapse = ""))
          })
          latex_show <- vapply(latex_parts, function(p) paste0(p$lhs, " &", p$op, " ", p$rhs, " \\\\"), character(1))
          latex_gray <- vapply(latex_parts, function(p) paste0("\\textcolor{gray}{", p$lhs, "} &\\textcolor{gray}{", p$op, " ", p$rhs, "} \\\\"), character(1))

          equation_all_total_latex <- c(equation_all_total_latex, list(list(
            title = paste0("\\subsection*{", gsub("_", "\\\\_", current_name), "}\n"),
            show = latex_show, gray = latex_gray, trivial = trivial_vec
          )))
        } else {
          count_badge <- paste0(
            '<div class="fairy-h-count-badge fairy-tooltip" data-tooltip="Excludes the automatic 0-1 bounds">',
            n_equal, ' eq · ', n_inequal_real, ' ineq</div>'
          )
          equation_all <- paste0(
            count_badge,
            '<div class="model-card-title">', card_title_html(current_name), '</div>',
            '<p style="color:#888;font-size:0.9em;">H-representation: ',
            n_equal, ' equalities, ', n_inequal,
            ' inequalities (too many to display).</p>'
          )
        }

        equation_all_total <- c(equation_all_total, equation_all)
      }

      output$h <- renderUI({
        # Cards flow left-to-right and wrap, centered as a group — plain
        # stacked block divs just left-aligned under the narrow icon
        # column, leaving the rest of the wide tab mostly empty.
        div(
          class = "fairy-h-cards-wrap",
          withMathJax(
            lapply(seq_along(equation_all_total), function(i) {
              div(class = "model-card", helpText(HTML(equation_all_total[i])))
            })
          ),
          if (length(disjoint_pairs) > 0) {
            div(
              class = "model-card",
              div(class = "model-card-title", "Empty intersections"),
              helpText(HTML(paste0(
                "The following model pairs do not overlap (their intersection is empty): ",
                paste0("<b>", disjoint_pairs, "</b>", collapse = ", "), "."
              )))
            )
          }
        )
      })

      equation_all_total_reactive$value <- equation_all_total
      equation_all_total_latex_reactive$value <- equation_all_total_latex

      # the tables of the V-representation need the vertices: built right here, or - when they are computed in separate
      # processes - as soon as all of them are there
      render_v_tail <- function() {
        ####* Tables V-representation ####

        show_table <- names(v_reactive)

        all_displayable <- unique(c(names_models_reactive$value, intersection_names, mixture_names, items_names))
        # Same Input-tab row-order fix as all_display_names above (see its
        # own comment) — row_order was already computed there, in this
        # same server execution, so it's reused here rather than
        # recomputed.
        all_displayable <- c(intersect(row_order, all_displayable), setdiff(all_displayable, row_order))
        show_table <- show_table[show_table %in% all_displayable]
        show_table <- all_displayable[all_displayable %in% show_table]

        updatePickerInput(session,
          inputId = "go_example",
          choices = show_table,
          # Otherwise this starts with nothing selected and the Edge-Cases
          # plot is just blank until the user manually picks a model —
          # default to the first one so something renders immediately.
          selected = if (length(show_table) > 0) show_table[1] else character(0)
        )

        if (length(show_table) > 0) {
          showTab(inputId = "tabs", target = "V-representation")

          counter_table <- 1
          v_table_list <- list()

          for (loop_table in show_table) {

            v_table <- data.frame(v_reactive[[loop_table]])

            if (length(v_table) > 0) {
              v_table <- v_table[, 3:ncol(v_table), drop = FALSE]
              v_table <- cbind(loop_table, v_table)

              rownames(v_table) <-
                paste("V_", 1:nrow(v_table), sep = "")

              h_cn_lt <- colnames(isolate(h_reactive[[loop_table]]))
              v_p_names_lt <- if (!is.null(h_cn_lt) && length(h_cn_lt) > 2) h_cn_lt[-(1:2)] else names_p_multi[-(1:2)]
              colnames(v_table) <- c("model_name", v_p_names_lt)

              v_table_list[[counter_table]] <- v_table
            }
            counter_table <- counter_table + 1
          }

          output$v_representation_table <- renderUI({
            # Same flow-left-to-right-and-wrap layout as the H-representation
            # cards (see fairy-h-cards-wrap), rather than one full-width
            # stack — most V-rep tables are narrow enough that stacking them
            # left a lot of empty space to their right.
            div(
              class = "fairy-h-cards-wrap",
              lapply(as.list(seq_len(length(v_table_list))), function(i) {
                id <- paste0("v_representation_table", i)
                model_nm <- tryCatch(as.character(v_table_list[[i]][1, 1]), error = function(e) "")
                # A NULL/empty entry in v_table_list (e.g. a slot never
                # populated for a skipped model) makes [1, 1] come back as
                # character(0) without throwing, which crashed the if() below
                # (a zero-length condition is a runtime error, not FALSE).
                if (length(model_nm) == 0) model_nm <- ""
                div(
                  class = "model-card",
                  if (nzchar(model_nm)) div(class = "model-card-title", model_nm),
                  uiOutput(paste0("v_meta_", i)),
                  DT::dataTableOutput(id)
                )
              })
            )
          })

          # every model's vertices as comparable keys (for "mark vertices that other models share")
          derived_names_now <- derived_row_names()
          vkey_tab <- lapply(v_table_list, function(t) {
            if (is.null(t) || nrow(t) == 0) return(NULL)
            m <- matrix(q2d(unlist(t[, 2:ncol(t)])), nrow = nrow(t))
            nm_t <- as.character(t[1, 1])
            list(name = nm_t, derived = nm_t %in% derived_names_now, inter = nm_t %in% derived_names_now && is.null(get0(nm_t, envir = mix_components, inherits = FALSE)), keys = apply(m, 1, function(r) paste(round(r, 6), collapse = ",")))
          })

          # the models a vertex list is compared with: the ordinary models; a mixture is not compared with its own components
          # (its vertices are theirs by construction, the "from" tag says that), an intersection with all ordinary models
          comp_for <- function(my) {
            srcs <- if (isTRUE(vkey_tab[[my]]$derived) && !isTRUE(vkey_tab[[my]]$inter)) get0(vkey_tab[[my]]$name, envir = mix_components, inherits = FALSE) else NULL
            Filter(function(o) o != my && !is.null(vkey_tab[[o]]) && !isTRUE(vkey_tab[[o]]$derived) && !(vkey_tab[[o]]$name %in% srcs), seq_along(vkey_tab))
          }

          for (loop_table in seq_len(length(v_table_list))) {
            if (is.null(v_table_list[[loop_table]]) == F) {
              local({
                id <- paste0("v_representation_table", loop_table)
                pl_t <- v_table_list[[loop_table]]
                colnames_pl_t <- colnames(pl_t)
                num_v <- matrix(q2d(unlist(pl_t[, 2:ncol(pl_t)])), nrow = nrow(pl_t))
                my_i <- loop_table
                pl_t <- cbind(pl_t[, 1], matrix(as.character(fractions(q2d(unlist(pl_t[, 2:ncol(pl_t)])))), ncol = ncol(pl_t) - 1))
                colnames(pl_t) <- colnames_pl_t
                colnames(pl_t)[1] <- "Model Name"
                # DT column headers are raw text, not run through MathJax like
                # the H-representation table's HTML output is — wrap each
                # parameter name in \(...\) and rely on the drawCallback below
                # to retypeset after DT (re)draws, or these show as literal
                # LaTeX source ("{p_{1}}^{(1)}") instead of rendering.
                colnames(pl_t)[-1] <- paste0("\\(", tex_name(colnames_pl_t[-1]), "\\)")
                # line under the title: size of the model; with the sharing marks on, how many vertices are shared with
                # another model and how many are unique to this one
                output[[paste0("v_meta_", my_i)]] <- renderUI({
                  txt <- sprintf("%d probabilities \u00b7 %d vertices", ncol(num_v), nrow(num_v))
                  if ((isTRUE(input$v_shared) || isTRUE(input$v_unique)) && !is.null(vkey_tab[[my_i]])) {
                    comp <- comp_for(my_i)
                    if (length(comp) > 0) {
                      uniq <- !(vkey_tab[[my_i]]$keys %in% unlist(lapply(comp, function(o) vkey_tab[[o]]$keys)))
                      txt <- paste0(txt, sprintf(" (%d shared, %d unique)", sum(!uniq), sum(uniq)))
                      # a mixture is not compared with its own components (its vertices are theirs): say so, the reader should not have to know it
                      if (isTRUE(vkey_tab[[my_i]]$derived) && !isTRUE(vkey_tab[[my_i]]$inter)) {
                        srcs <- get0(vkey_tab[[my_i]]$name, envir = mix_components, inherits = FALSE)
                        if (length(srcs) > 0) txt <- paste0(txt, " (compared with the other models, not with its own components ", paste(vapply(srcs, short_model_name, character(1)), collapse = ", "), ")")
                      }
                    }
                  }
                  div(class = "fairy-v-meta", txt)
                })
                output[[id]] <- DT::renderDataTable({
                  # Reads input$v_rep_words live, inside the render expression
                  # (not baked in once at Go-time) — same trap as the earlier
                  # "Model insights" checkbox: a value computed once outside a
                  # render*()/reactive() block doesn't retrigger when the
                  # checkbox changes afterward, only when Go runs again.
                  display_t <- pl_t
                  if (isTRUE(input$v_rep_words)) {
                    # Cast 0/1 vertex coordinates as words ("none"/"all"),
                    # same convention as Tables 1-2 in the paper: "a randomly
                    # drawn person cringes with probability one precisely
                    # when everybody in that (sub)population cringes," and
                    # probability zero precisely when nobody does. Fractional
                    # coordinates (e.g. 2/3) are left as fractions, matching
                    # Table 2, which uses the same mixed convention.
                    display_t[, -1][display_t[, -1] == "0"] <- "none"
                    display_t[, -1][display_t[, -1] == "1"] <- "all"
                  }
                  # Show N entries / Search only earn their place with more than one page of vertices
                  many_rows <- nrow(display_t) > 10
                  # first column numbers the vertices (the model name is the card's title);
                  # optional tag: this vertex is shared with another plotted model
                  v_lab <- paste0("V", seq_len(nrow(display_t)))
                  uniq_flags <- rep(FALSE, nrow(display_t)); n_other <- 0
                  if ((isTRUE(input$v_shared) || isTRUE(input$v_unique)) && !is.null(vkey_tab[[my_i]])) {
                    mine <- vkey_tab[[my_i]]$keys
                    # compared with the other ordinary models only (intersections and mixtures share vertices with their sources by construction)
                    comp <- comp_for(my_i)
                    n_other <- length(comp)
                    if (n_other > 0) uniq_flags <- !(mine %in% unlist(lapply(comp, function(o) vkey_tab[[o]]$keys)))
                    if (isTRUE(input$v_shared)) v_lab <- vapply(seq_along(v_lab), function(j) {
                      others <- unlist(lapply(comp, function(o) if (mine[j] %in% vkey_tab[[o]]$keys) vkey_tab[[o]]$name))
                      if (!length(others)) return(v_lab[j])
                      lab <- if (length(others) == 1) paste("also in", short_model_name(others)) else paste("shared by", length(others) + 1L)
                      paste0(v_lab[j], " <span class='fairy-v-shared' title='", htmltools::htmlEscape(paste("also in:", paste(others, collapse = " | ")), attribute = TRUE), "'>", htmltools::htmlEscape(lab), "</span>")
                    }, character(1))
                  }
                  # a mixture: say which of its models each vertex comes from (the vertices of a mixture are vertices of its models)
                  mix_srcs <- if (!is.null(vkey_tab[[my_i]]) && isTRUE(vkey_tab[[my_i]]$derived)) get0(vkey_tab[[my_i]]$name, envir = mix_components, inherits = FALSE) else NULL
                  if (isTRUE(input$v_shared) && length(mix_srcs) > 0) {
                    by_name <- Filter(Negate(is.null), vkey_tab); names(by_name) <- vapply(by_name, function(x) x$name, character(1))
                    mine <- vkey_tab[[my_i]]$keys
                    v_lab <- vapply(seq_along(v_lab), function(j) {
                      from <- Filter(function(nm) !is.null(by_name[[nm]]) && mine[j] %in% by_name[[nm]]$keys, mix_srcs)
                      if (!length(from)) return(v_lab[j])
                      paste0(v_lab[j], " <span class='fairy-v-shared' title='", htmltools::htmlEscape(paste("from:", paste(from, collapse = " | ")), attribute = TRUE), "'>",
                             htmltools::htmlEscape(paste("from", paste(vapply(from, short_model_name, character(1)), collapse = ", "))), "</span>")
                    }, character(1))
                  }
                  display_t[, 1] <- v_lab
                  # optional: only the vertices that no other plotted model has
                  if (isTRUE(input$v_unique) && n_other > 0) {
                    display_t <- display_t[uniq_flags, , drop = FALSE]
                    uniq_flags <- uniq_flags[uniq_flags]
                    many_rows <- nrow(display_t) > 10
                  }
                  colnames(display_t)[1] <- "Vertex"
                  DT::datatable(display_t, escape = FALSE, options = list(
                    scrollX = TRUE,
                    rowCallback = DT::JS(sprintf("function(row, data, index) { var u = %s; if (u[index]) $(row).addClass('fairy-v-unique'); }", jsonlite::toJSON(as.logical(uniq_flags & isTRUE(input$v_shared))))),
                    dom = if (many_rows) "lfrtip" else "t",
                    paging = many_rows,
                    # the number of entries chosen once stays when the table is drawn again (words, compare, unique ...)
                    initComplete = DT::JS("function(settings) { var n = window.fairyVLen; if (n && settings._iDisplayLength !== n) this.api().page.len(n).draw(false); }"),
                    drawCallback = DT::JS(
                      "function() { if (window.MathJax && MathJax.Hub) {",
                      "setTimeout(function() { MathJax.Hub.Queue(['Typeset', MathJax.Hub]); }, 30); } }"
                    )
                  ))
                }, server = FALSE)   # client-side paging: Show N entries must not need a round trip to the R process
              })
            }
          }

          function_plot(v_table_list, length(v_table_list))
        }
      }
      if (isTRUE(v_async)) {
        v_state$after <- function(cancelled = character(0), skipped = character(0)) {
          note <- v_pending_note
          if (length(cancelled) > 0) note <- paste0("<b>Cancelled:</b> the V-representation of ", paste(htmltools::htmlEscape(cancelled), collapse = ", "), " was not computed.<br>", note)
          if (length(skipped) > 0) note <- paste0("<b>Skipped:</b> the V-representation of ", paste(htmltools::htmlEscape(skipped), collapse = ", "), " was not computed.<br>", note)
          fairy_run_end(note)
          tryCatch(render_v_tail(), error = function(e) fairy_report_error(e, "go"))
        }
      } else {
        render_v_tail()
      }
    } else {
      fairy_notify("Please type in all model specifications", type = "error")
    }
  }, "go_v_h")

  #### Parsimony ####

  # The volumes are estimated in separate R processes (volesti), so the window stays alive: it shows what is being computed
  # and can be cancelled. The Go handler below runs twice with the same code: first it only collects the jobs and starts them
  # (plan mode), when all are done it runs again and takes the volumes from parsim_state$results.
  parsim_state <- reactiveValues(go_seen = 0, results = NULL, resume = 0, exact = NULL, exact_done = FALSE)
  pv <- reactiveValues(active = FALSE, dir = NULL, keys = character(0), queue = character(0), procs = list(),
                       parallel = FALSE, start = NULL, status = "", elapsed = 0, prev_snap = NULL, total = 0)
  pv_kill_all <- function() {
    for (p in isolate(pv$procs)) try(p$kill_tree(), silent = TRUE)
    pv$procs <- list()
  }
  parsim_start_jobs <- function(jobs) {
    pv_kill_all()
    d <- tempfile("pvrun_"); dir.create(d)
    writeLines(c("suppressMessages(library(volesti))", "a <- commandArgs(TRUE)", "x <- readRDS(a[1])",
                 "setClass(\"model_s4\", representation(A = \"matrix\", b = \"numeric\", type = \"character\"))",
                 "P <- new(\"model_s4\", A = x$A, b = x$b, type = \"Hpolytope\")",
                 "v <- tryCatch(volume(P, settings = x$settings), error = function(e) NA_real_)",
                 "saveRDS(v, a[2])"), file.path(d, "job.R"))
    keys <- names(jobs)
    for (i in seq_along(keys)) saveRDS(jobs[[keys[i]]], file.path(d, paste0("in", i, ".rds")))
    pv$dir <- d; pv$keys <- keys; pv$queue <- keys; pv$procs <- list(); pv$start <- Sys.time(); pv$elapsed <- 0
    pv$total <- length(keys); pv$status <- "starting ..."
    pv$parallel <- isTRUE(isolate(input$use_parallel))
    parsim_state$results <- NULL
    pv$active <- TRUE
    for (k in keys) fairy_run_cell(sub("\\|[^|]*$", "", k), c(CB = "Cooling Bodies", CG = "Cooling Gaussian", SoB = "Sequence of Balls")[[sub("^.*\\|", "", k)]], "wait")
    session$sendCustomMessage("fairy_run_cancelable", list(on = TRUE, input = "pv_cancel", label = "Cancel"))
  }
  observe({
    if (!isTRUE(pv$active)) return()
    invalidateLater(400)
    d <- isolate(pv$dir); keys <- isolate(pv$keys); procs <- isolate(pv$procs); queue <- isolate(pv$queue)
    res <- isolate(parsim_state$results); if (is.null(res)) res <- list()
    for (k in names(procs)) {
      if (!procs[[k]]$is_alive()) {
        idx <- match(k, keys)
        v <- tryCatch(readRDS(file.path(d, paste0("out", idx, ".rds"))), error = function(e) NA_real_)
        res[[k]] <- if (is.numeric(v) && length(v) == 1) v else NA_real_
        procs[[k]] <- NULL
        fairy_run_cell(sub("\\|[^|]*$", "", k), c(CB = "Cooling Bodies", CG = "Cooling Gaussian", SoB = "Sequence of Balls")[[sub("^.*\\|", "", k)]], "done")
      }
    }
    max_run <- if (isolate(pv$parallel)) length(keys) else 1L
    while (length(queue) > 0 && length(procs) < max_run) {
      k <- queue[1]; queue <- queue[-1]
      idx <- match(k, keys)
      p <- tryCatch(processx::process$new(file.path(R.home("bin"), "Rscript"),
                      c(file.path(d, "job.R"), file.path(d, paste0("in", idx, ".rds")), file.path(d, paste0("out", idx, ".rds"))),
                      cleanup_tree = TRUE), error = function(e) NULL)
      if (is.null(p)) { res[[k]] <- NA_real_; fairy_run_cell(sub("\\|[^|]*$", "", k), c(CB = "Cooling Bodies", CG = "Cooling Gaussian", SoB = "Sequence of Balls")[[sub("^.*\\|", "", k)]], "fail") } else {
        procs[[k]] <- p
        fairy_run_cell(sub("\\|[^|]*$", "", k), c(CB = "Cooling Bodies", CG = "Cooling Gaussian", SoB = "Sequence of Balls")[[sub("^.*\\|", "", k)]], "run")
      }
    }
    pv$procs <- procs; pv$queue <- queue
    pv$elapsed <- as.numeric(difftime(Sys.time(), isolate(pv$start), units = "secs"))
    parsim_state$results <- res
    if (length(queue) == 0 && length(procs) == 0) {
      pv$active <- FALSE
      session$sendCustomMessage("fairy_run_cancelable", list(on = FALSE))
      parsim_state$resume <- isolate(parsim_state$resume) + 1   # runs the Go handler again, now with the volumes
    }
  })
  observeEvent(input$pv_cancel, {
    if (!isTRUE(isolate(pv$active))) return()
    pv_kill_all()
    pv$queue <- character(0); pv$active <- FALSE
    parsim_state$results <- NULL
    if (!is.null(isolate(pv$prev_snap))) last_parsimony_snapshot(isolate(pv$prev_snap))
    fairy_run_hide()
    showNotification("The volume computation was cancelled; the earlier results (if any) are unchanged.", type = "message", duration = 6)
  })
  session$onSessionEnded(function() { for (p in isolate(pv$procs)) try(p$kill_tree(), silent = TRUE) })

  # Exact volume from the vertices (convex hull), in separate R processes like the estimates: the window shows what is being
  # computed, "skip" stops it and the algorithm takes over, and EXACT_VOLUME_LIMIT is the longest it may take in total.
  # Result per model: a number, NaN = stopped (time limit or skipped), NA = no exact volume exists / can be computed.
  ex <- reactiveValues(active = FALSE, dir = NULL, names = character(0), procs = list(), res = NULL, start = NULL,
                       elapsed = 0, skip = FALSE, prev_snap = NULL, hkeys = NULL, queue = character(0), parallel = FALSE, skipped_run = character(0))
  exact_kill_all <- function() {
    for (p in isolate(ex$procs)) try(p$kill_tree(), silent = TRUE)
    ex$procs <- list()
  }
  # results of the exact calculation by H-representation: a number or NA (no exact volume exists) is kept, and so is a calculation
  # that ran into the time limit (it is not tried again for the same model, unless the time limit is switched off)
  exact_cache <- new.env()
  # models for which the exact volume was skipped by hand: optionally not tried again (the checkbox appears once there are some)
  exact_skipped <- reactiveVal(character(0))
  # what the app remembers: shown above the results, with a link to forget it (same wording and place as in the analysis window)
  output$ex_skipped_note <- renderUI({
    sk <- exact_skipped()
    if (length(sk) == 0 || identical(input$EX, FALSE)) return(NULL)
    tags$div(class = "fairy-skipnote",
      icon("circle-info"), tags$span(" Skipped earlier: ", tags$b(paste(sk, collapse = ", ")),
      " (no exact volume, the algorithm is used)."), actionLink("ex_forget", "Retry"))
  })
  observeEvent(input$ex_forget, {
    exact_skipped(character(0))
    shinyjs::runjs("var g = document.getElementById('go'); if (g) g.click();")   # and calculate them now
  })
  ex_spawn <- function(d, u, i) {
    saveRDS(isolate(h_reactive[[u[i]]]), file.path(d, paste0("h", i, ".rds")))
    tryCatch(processx::process$new(file.path(R.home("bin"), "Rscript"),
      c(file.path(d, "job.R"), file.path(d, paste0("h", i, ".rds")), file.path(d, paste0("v", i, ".rds"))), cleanup_tree = TRUE),
      error = function(e) NULL)
  }
  exact_start_jobs <- function(nms) {
    exact_kill_all()
    u <- unique(nms)
    res <- stats::setNames(rep(NA_real_, length(u)), u)
    hkeys <- stats::setNames(vapply(u, function(nm) rlang::hash(isolate(h_reactive[[nm]])), character(1)), u)
    d <- tempfile("exact_"); dir.create(d)
    writeLines(c("suppressMessages(library(rcdd))", "a <- commandArgs(TRUE)", "h <- readRDS(a[1])",
      "res <- tryCatch({",
      "  if (any(q2d(h)[, 1] > 0)) 0 else {",
      "    hh <- matrix(as.character(h), ncol = ncol(h)); attr(hh, \"representation\") <- \"H\"",
      "    vn <- q2d(scdd(hh)$output)",
      "    if (any(vn[, 2] == 0)) NA_real_ else {",
      "      pts <- vn[vn[, 2] == 1, -(1:2), drop = FALSE]",
      "      if (nrow(pts) <= ncol(pts)) 0 else if (qr(sweep(pts, 2, pts[1, ]), tol = 1e-9)$rank < ncol(pts)) 0 else if (ncol(pts) == 1) diff(range(pts)) else as.numeric(geometry::convhulln(pts, options = \"FA\")$vol)",
      "    }",
      "  }",
      "}, error = function(e) NA_real_)",
      "saveRDS(res, a[2])"), file.path(d, "job.R"))
    procs <- list()
    cached_state <- stats::setNames(rep(NA_character_, length(u)), u)
    todo <- integer(0)
    if (requireNamespace("geometry", quietly = TRUE)) for (i in seq_along(u)) {
      h <- isolate(h_reactive[[u[i]]])
      if (is.null(h)) next
      if (u[i] %in% isolate(exact_skipped())) {
        res[[u[i]]] <- NaN; cached_state[[u[i]]] <- "skipped"; next
      }
      ch <- get0(hkeys[[i]], envir = exact_cache, inherits = FALSE)
      if (!is.null(ch) && (ch$kind != "timeout" || !isTRUE(isolate(ex_nolimit())))) {
        res[[u[i]]] <- ch$value
        cached_state[[u[i]]] <- ch$kind
        next
      }
      todo <- c(todo, i)
    }
    # like the other windows: one model after the other, all at once only with the parallel option
    par <- isTRUE(isolate(input$use_parallel))
    first <- if (par) todo else utils::head(todo, 1)
    for (i in first) { pr <- ex_spawn(d, u, i); if (!is.null(pr)) procs[[as.character(i)]] <- pr }
    queue <- as.character(setdiff(todo, first))
    ex$queue <- queue; ex$parallel <- par
    ex$skipped_run <- character(0); ex_grace(NULL)
    ex$dir <- d; ex$names <- u; ex$procs <- procs; ex$res <- res; ex$start <- Sys.time(); ex$elapsed <- 0; ex$skip <- FALSE; ex$hkeys <- hkeys
    ex$prev_snap <- isolate(pv$prev_snap)
    ex$active <- TRUE
    session$sendCustomMessage("fairy_run_cancelable", list(on = TRUE, input = "ex_skip", label = "Skip all"))
    for (i in seq_along(u)) fairy_run_cell(u[i], "Exact volume", if (as.character(i) %in% names(procs)) "run" else if (as.character(i) %in% queue) "wait" else
      switch(if (is.na(cached_state[[u[i]]])) "none" else cached_state[[u[i]]], ok = "cached", timeout = "stop", skipped = "skip", "na"))
    session$sendCustomMessage("fairy_run_limit", list(seconds = if (isTRUE(isolate(ex_nolimit()))) 0 else EXACT_VOLUME_LIMIT, nolimit = isTRUE(isolate(ex_nolimit()))))
  }
  observe({
    if (!isTRUE(ex$active)) return()
    invalidateLater(400)
    d <- isolate(ex$dir); procs <- isolate(ex$procs); res <- isolate(ex$res); u <- isolate(ex$names)
    el <- as.numeric(difftime(Sys.time(), isolate(ex$start), units = "secs"))
    for (k in names(procs)) {
      if (!procs[[k]]$is_alive()) {
        v <- tryCatch(readRDS(file.path(d, paste0("v", k, ".rds"))), error = function(e) NA_real_)
        res[[u[as.integer(k)]]] <- if (is.numeric(v) && length(v) == 1) v else NA_real_
        fairy_run_cell(u[as.integer(k)], "Exact volume", if (is.finite(res[[u[as.integer(k)]]])) "done" else "na")
        hk <- isolate(ex$hkeys)[[u[as.integer(k)]]]
        if (!is.null(hk)) assign(hk, list(kind = if (is.finite(res[[u[as.integer(k)]]])) "ok" else "na", value = res[[u[as.integer(k)]]]), envir = exact_cache)
        procs[[k]] <- NULL
      }
    }
    q <- isolate(ex$queue)
    limit_hit <- !isTRUE(isolate(ex_nolimit())) && el > EXACT_VOLUME_LIMIT
    # the next model of the queue starts when nothing runs any more
    if (length(q) > 0 && length(procs) == 0 && !limit_hit && !isTRUE(isolate(ex$skip))) {
      i <- as.integer(q[1]); q <- q[-1]
      pr <- ex_spawn(d, u, i)
      if (!is.null(pr)) { procs[[as.character(i)]] <- pr; fairy_run_cell(u[i], "Exact volume", "run") } else fairy_run_cell(u[i], "Exact volume", "na")
    }
    if ((length(procs) > 0 || length(q) > 0) && (limit_hit || isTRUE(isolate(ex$skip)))) {
      if (isTRUE(isolate(ex$skip))) exact_skipped(union(isolate(exact_skipped()), u[as.integer(c(names(procs), q))]))
      for (k in q) { res[[u[as.integer(k)]]] <- NaN; fairy_run_cell(u[as.integer(k)], "Exact volume", if (isTRUE(isolate(ex$skip))) "skip" else "stop") }
      q <- character(0)
      for (k in names(procs)) {
        try(procs[[k]]$kill_tree(), silent = TRUE); res[[u[as.integer(k)]]] <- NaN
        fairy_run_cell(u[as.integer(k)], "Exact volume", "stop")
        # only the time limit is remembered; a skip was a choice of this moment
        hk <- isolate(ex$hkeys)[[u[as.integer(k)]]]
        if (!is.null(hk) && !isTRUE(isolate(ex$skip))) assign(hk, list(kind = "timeout", value = NaN), envir = exact_cache)
      }
      procs <- list()
    }
    ex$procs <- procs; ex$res <- res; ex$elapsed <- el; ex$queue <- q
    # after a skip the run goes straight on with the algorithm (no waiting time here: Undo skip works while other models still run, "Try exact again" afterwards)
    if (length(procs) == 0 && length(q) == 0) {
      ex$active <- FALSE
      session$sendCustomMessage("fairy_run_cancelable", list(on = FALSE))
      session$sendCustomMessage("fairy_run_limit", list(seconds = 0))
      unlink(d, recursive = TRUE)
      parsim_state$exact <- res
      parsim_state$exact_done <- TRUE
      parsim_state$resume <- isolate(parsim_state$resume) + 1   # runs the Go handler again, now with the exact volumes
    }
  })
  observeEvent(input$ex_skip, {
    if (!is.null(isolate(ex_grace()))) { ex_grace(Sys.time() - 1); return() }
    if (isTRUE(isolate(ex$active))) ex$skip <- TRUE
  })
  # the same Skip current model as in the other windows: the model that is running now is stopped, the next one starts
  observeEvent(input$ex_skip_model, {
    if (!isTRUE(isolate(ex$active))) return()
    m <- input$ex_skip_model; u <- isolate(ex$names); procs <- isolate(ex$procs); res <- isolate(ex$res); q <- isolate(ex$queue)
    k <- names(procs)[vapply(names(procs), function(k) identical(u[as.integer(k)], m), logical(1))]
    iq <- match(as.character(match(m, u)), q)
    if (length(k) == 0 && is.na(iq)) return()
    if (length(k) > 0) { try(procs[[k[1]]]$kill_tree(), silent = TRUE); procs[[k[1]]] <- NULL }
    if (!is.na(iq)) q <- q[-iq]
    res[[m]] <- NaN
    fairy_run_cell(m, "Exact volume", "skip")
    exact_skipped(union(isolate(exact_skipped()), m))
    ex$skipped_run <- union(isolate(ex$skipped_run), m)
    ex$procs <- procs; ex$res <- res; ex$queue <- q
  })
  # the skip is taken back: the model waits for its turn again
  observeEvent(input$ex_retry_all, {
    exact_skipped(setdiff(isolate(exact_skipped()), as.character(input$ex_retry_all)))
    fairy_run_hide()
    shinyjs::runjs("var g = document.getElementById('go'); if (g) g.click();")
  })
  observeEvent(input$ex_unskip_model, {
    if (!isTRUE(isolate(ex$active))) {
      # the run is over: forget the skip and calculate again (the other models come from the cache)
      exact_skipped(setdiff(isolate(exact_skipped()), input$ex_unskip_model))
      fairy_run_hide()
      shinyjs::runjs("var g = document.getElementById('go'); if (g) g.click();")   # a new run, as if Go was pressed
      return()
    }
    m <- input$ex_unskip_model; u <- isolate(ex$names); i <- match(m, u)
    if (is.na(i) || !(m %in% isolate(exact_skipped()))) return()
    exact_skipped(setdiff(isolate(exact_skipped()), m))
    res <- isolate(ex$res); res[[m]] <- NA_real_
    ex$res <- res; ex$queue <- c(isolate(ex$queue), as.character(i))
    ex$skipped_run <- setdiff(isolate(ex$skipped_run), m); ex_grace(NULL); session$sendCustomMessage("fairy_run_cancel_label", list(text = ""))
    session$sendCustomMessage("fairy_run_phase", list(text = "Calculating the volumes"))
    fairy_run_cell(m, "Exact volume", "wait")
  })
  # fairy dust (five quick clicks on the title or the time of the run window): no time limit for the exact calculation
  ex_nolimit <- reactiveVal(FALSE)
  observeEvent(input$ex_unlock, {
    ex_nolimit(!isTRUE(ex_nolimit()))
    if (isTRUE(isolate(ex$active))) session$sendCustomMessage("fairy_run_limit", list(seconds = if (ex_nolimit()) 0 else EXACT_VOLUME_LIMIT, nolimit = ex_nolimit()))
    showNotification(if (ex_nolimit()) "\u2728 Fairy dust: no time limit for the exact volume (five quick clicks on the title switch it off again)." else paste0("The time limit is back (", EXACT_VOLUME_LIMIT_TXT, ")."),
                     type = "message", duration = 6)
  })
  session$onSessionEnded(function() { for (p in isolate(ex$procs)) try(p$kill_tree(), silent = TRUE) })

  observe_guarded(list(input$go, parsim_state$resume), {
    # without a press of Go there is nothing to compute (the event also fires once when the page is loaded)
    if (is.null(isolate(input$go)) || isolate(input$go) == 0) return(invisible())
    # a new press of Go starts from scratch (plan mode); the second run (resume) takes the finished volumes
    go_now <- isolate(input$go)
    if (!identical(go_now, isolate(parsim_state$go_seen))) {
      parsim_state$go_seen <- go_now
      # the columns in the order the algorithms are worked on (the same as the jobs are made below)
      algo_names_all <- c(CB = "Cooling Bodies", SoB = "Sequence of Balls", CG = "Cooling Gaussian")
      sel_b <- c(CB = isTRUE(isolate(input$CB)), SoB = isTRUE(isolate(input$SoB)), CG = isTRUE(isolate(input$CG)))
      if (!isTRUE(isolate(input$ALG))) sel_b[] <- FALSE   # the backup algorithm gets its column only if it is needed
      run_cols(c(if (!identical(isolate(input$EX), FALSE)) "Exact volume", unname(algo_names_all[names(sel_b)[sel_b]])))
      fairy_run_begin("Calculating the volumes", isolate(run_cols()), skippable = TRUE)
      parsim_state$exact <- NULL; parsim_state$exact_done <- FALSE
      parsim_state$results <- NULL
      pv$prev_snap <- isolate(last_parsimony_snapshot())
    }
    plan_mode <- is.null(isolate(parsim_state$results))
    vol_jobs <- list()
    vol_results <- isolate(parsim_state$results)
    vol_call <- function(key, model_s4, settings) {
      if (skip_estimate(sub("\\|[^|]*$", "", key))) return(NA_real_)
      if (plan_mode) {
        vol_jobs[[key]] <<- list(A = model_s4@A, b = model_s4@b, settings = settings)
        return(NA_real_)
      }
      r <- vol_results[[key]]
      if (is.null(r)) NA_real_ else r
    }
    last_parsimony_snapshot(make_parsimony_snapshot())
    input_volume <- isolate(input_volume_reactive)

    {
      setClass(
        "model_s4",
        representation(
          A = "matrix", b = "numeric",
          type = "character"
        )
      )

      # Volumes are computed ONLY for what the user actually specified on
      # the Input page: base models plus their explicit intersections and
      # mixtures (and replication/multi-item models) — never any
      # auto-detected pairwise intersection. An earlier version of this
      # tab used to also pre-compute every pairwise overlap between base
      # models for a comparison table; that table is gone, and silently
      # adding e.g. "[m1 ∩ m2]" rows the user never asked to see was
      # confusing, not useful — see comp_int_reactive's own comment.
      names_h_rep <- c(
        names_models_reactive$value,
        isolate(intersections_reactive$names),
        isolate(mixtures_reactive$names),
        isolate(items_reactive$names)
      )
      names_h_rep <- order_by_page(names_h_rep[!is.na(names_h_rep) & nchar(names_h_rep) > 0])

      # the exact volume first: a model that has one needs no estimate (the algorithms only run for the others)
      exact_on <- !identical(isolate(input$EX), FALSE)
      alg_on <- isTRUE(isolate(input$ALG))
      # which algorithms run: the selected ones when Algorithms is on, otherwise (a backup for models without an exact volume) Cooling Bodies
      sel_algo <- c(CB = isTRUE(isolate(input$CB)), SoB = isTRUE(isolate(input$SoB)), CG = isTRUE(isolate(input$CG)))
      if (!alg_on || !any(sel_algo)) sel_algo <- c(CB = TRUE, SoB = FALSE, CG = FALSE)
      if (any(vapply(unlist(names_h_rep), function(nm) is.null(isolate(h_reactive[[nm]])), logical(1)))) {
        fairy_run_hide()
        fairy_notify("The H-representations are not there yet", "Click Go on the Input tab first, then compute the parsimony.", type = "warning")
        return(invisible())
      }
      if (exact_on && !isTRUE(isolate(parsim_state$exact_done))) {
        exact_start_jobs(as.character(names_h_rep))   # the handler runs again when they are done
        return(invisible())
      }
      ex_pre <- if (exact_on) isolate(parsim_state$exact) else NULL
      has_exact <- function(nm) !is.null(ex_pre) && isTRUE(is.finite(unname(ex_pre[nm])))
      skip_estimate <- function(nm) has_exact(nm) && !alg_on   # an exact volume makes the estimate unnecessary, unless Algorithms is switched on

      n_rep <- 1
      parsim_rep <- numeric()


      for (loop_repeat_parsimony in 1:n_rep) {
        parsim <- numeric()
        act_dim <- numeric()

        for (loop_parsimony in seq_along(names_h_rep)) {
          act_pars <- (isolate(h_reactive[[names_h_rep[loop_parsimony]]]))
          act_pars <- matrix(as.character(act_pars), ncol = ncol(act_pars))


          not_full_dim <- ifelse(sum(q2d(act_pars)[, 1]) > 0, 1, 0)


          if (not_full_dim == 0) {
            left_pars <- q2d((act_pars[, 3:ncol(act_pars), drop = FALSE]))
            right_pars <- q2d((act_pars[, 2]))

            model_s4 <- new("model_s4",
              A = -left_pars,
              b = right_pars,
              type = "Hpolytope"
            )


            ####* CB ####

            if (sel_algo[["CB"]]) {
              #####* settings strings ####


              settings_string_CB <- rep(NA, 6)

              settings_string_CB[1] <- ifelse(input_volume$value[1] == "default", "",
                paste("'error' =", input_volume$value[1], sep = "")
              )


              rand_w <- ifelse(input_volume$value[2] == "default", "default", input_volume_reactive$value[2])
              rand_w <- ifelse(rand_w == "Coordinate Directions Hit-and-Run", "CDHR", rand_w)
              rand_w <- ifelse(rand_w == "Random Directions Hit-and-Run", "RDHR", rand_w)
              rand_w <- ifelse(rand_w == "Ball Walk", "BaW", rand_w)
              rand_w <- ifelse(rand_w == "Billiard Walk", "BiW", rand_w)


              settings_string_CB[2] <- ifelse(rand_w == "default", "",
                paste("'random_walk' = '", rand_w, "'", sep = "")
              )

              settings_string_CB[3] <- ifelse(input_volume$value[3] == "default", "",
                paste("'walk_length' =", input_volume$value[3], sep = "")
              )

              settings_string_CB[4] <- ifelse(input_volume$value[4] == "default", "",
                paste("'win_len' =", input_volume$value[4], sep = "")
              )


              settings_string_CB[5] <- ifelse(input_volume$value[5] == "default", "",
                paste("'hpoly' =", input_volume$value[5], sep = "")
              )

              settings_string_CB[6] <- ifelse(input_volume$value[6] == "none", "",
                paste("'seed' =", input_volume$value[6], sep = "")
              )

              settings_string_CB <- settings_string_CB[settings_string_CB != ""]

              settings_string_CB <- paste(settings_string_CB, collapse = ",")

              if (settings_string_CB[1] != "") {
                settings_string_final_CB <- paste("list('algorithm' = 'CB',", settings_string_CB, ")")
              } else {
                settings_string_final_CB <- "list('algorithm' = 'CB')"
              }

              #####* calc volume ####

              act_vol_CB <- vol_call(paste(names_h_rep[loop_parsimony], "CB", sep = "|"), model_s4, tryCatch(eval(parse(text = settings_string_final_CB)), error = function(e) NULL))
            } else {
              act_vol_CB <- NA
            }


            ####* SoB ####

            if (sel_algo[["SoB"]]) {
              #####* settings strings ####


              settings_string_SoB <- rep(NA, 4)

              settings_string_SoB[1] <- ifelse(input_volume$value[7] == "default", "",
                paste("'error' =", input_volume$value[7], sep = "")
              )


              rand_w <- ifelse(input_volume$value[8] == "default", "default", input_volume_reactive$value[8])
              rand_w <- ifelse(rand_w == "Coordinate Directions Hit-and-Run", "CDHR", rand_w)
              rand_w <- ifelse(rand_w == "Random Directions Hit-and-Run", "RDHR", rand_w)
              rand_w <- ifelse(rand_w == "Ball Walk", "BaW", rand_w)
              rand_w <- ifelse(rand_w == "Billiard Walk", "BiW", rand_w)


              settings_string_SoB[2] <- ifelse(rand_w == "default", "",
                paste("'random_walk' = '", rand_w, "'", sep = "")
              )

              settings_string_SoB[3] <- ifelse(input_volume$value[9] == "default", "",
                paste("'walk_length' =", input_volume$value[9], sep = "")
              )


              settings_string_SoB[4] <- ifelse(input_volume$value[10] == "none", "",
                paste("'seed' =", input_volume$value[10], sep = "")
              )

              settings_string_SoB <- settings_string_SoB[settings_string_SoB != ""]

              settings_string_SoB <- paste(settings_string_SoB, collapse = ",")

              if (settings_string_SoB[1] != "") {
                settings_string_final_SoB <- paste("list('algorithm' = 'SOB',", settings_string_SoB, ")")
              } else {
                settings_string_final_SoB <- "list('algorithm' = 'SOB')"
              }


              #####* calc volume ####

              act_vol_SoB <- vol_call(paste(names_h_rep[loop_parsimony], "SoB", sep = "|"), model_s4, tryCatch(eval(parse(text = settings_string_final_SoB)), error = function(e) NULL))
            } else {
              act_vol_SoB <- NA
            }

            ####* CG ####

            if (sel_algo[["CG"]]) {
              #####* settings strings ####


              settings_string_CG <- rep(NA, 5)

              settings_string_CG[1] <- ifelse(input_volume$value[11] == "default", "",
                paste("'error' =", input_volume$value[11], sep = "")
              )


              rand_w <- ifelse(input_volume$value[12] == "default", "default", input_volume_reactive$value[12])
              rand_w <- ifelse(rand_w == "Coordinate Directions Hit-and-Run", "CDHR", rand_w)
              rand_w <- ifelse(rand_w == "Random Directions Hit-and-Run", "RDHR", rand_w)
              rand_w <- ifelse(rand_w == "Ball Walk", "BaW", rand_w)
              rand_w <- ifelse(rand_w == "Billiard Walk", "BiW", rand_w)


              settings_string_CG[2] <- ifelse(rand_w == "default", "",
                paste("'random_walk' = '", rand_w, "'", sep = "")
              )

              settings_string_CG[3] <- ifelse(input_volume$value[13] == "default", "",
                paste("'walk_length' =", input_volume$value[13], sep = "")
              )

              settings_string_CG[4] <- ifelse(input_volume$value[14] == "default", "",
                paste("'win_len' =", input_volume$value[14], sep = "")
              )


              settings_string_CG[5] <- ifelse(input_volume$value[15] == "none", "",
                paste("'seed' =", input_volume$value[15], sep = "")
              )

              settings_string_CG <- settings_string_CG[settings_string_CG != ""]

              settings_string_CG <- paste(settings_string_CG, collapse = ",")

              if (settings_string_CG[1] != "") {
                settings_string_final_CG <- paste("list('algorithm' = 'CG',", settings_string_CG, ")")
              } else {
                settings_string_final_CG <- "list('algorithm' = 'CG')"
              }

              #####* calc volume ####

              act_vol_CG <- vol_call(paste(names_h_rep[loop_parsimony], "CG", sep = "|"), model_s4, tryCatch(eval(parse(text = settings_string_final_CG)), error = function(e) NULL))
            } else {
              act_vol_CG <- NA
            }


            n_dims <- ncol(act_pars) - 2
            act_dim <- c(act_dim, paste0("Full-dimensional (", n_dims, "D)"))
          } else {
            if (sel_algo[["CB"]]) {
              act_vol_CB <- 0
            } else {
              act_vol_CB <- NA
            }


            if (sel_algo[["SoB"]]) {
              act_vol_SoB <- 0
            } else {
              act_vol_SoB <- NA
            }


            if (sel_algo[["CG"]]) {
              act_vol_CG <- 0
            } else {
              act_vol_CG <- NA
            }

            # n_dims here is the same "how many parameter columns does
            # this model have" count as the Full-dimensional branch
            # above — it's the AMBIENT space the model is embedded in,
            # not the polytope's own actual dimension (which is exactly
            # what "not full-dimensional" means: a genuine equality
            # constraint — e.g. a repeated-items "Identical" type —
            # collapses the polytope onto a lower-dimensional subspace
            # within it, giving it zero volume there). "(6D)" alone reads
            # as directly contradicting "Not full-dimensional" right
            # next to it (reported directly: "not full-dimensional but
            # 6D?") — "in 6D space" instead makes clear that's the
            # space the (lower-dimensional) model lives IN, not its own
            # dimension.
            n_dims <- ncol(act_pars) - 2
            act_dim <- c(act_dim, paste0("Not full-dimensional (in ", n_dims, "D space)"))
          }

          parsim <- c(parsim, c(act_vol_CB, act_vol_SoB, act_vol_CG))
        }

        # plan mode: the volumes are computed in separate processes; this handler runs again when they are done
        if (plan_mode) {
          if (length(vol_jobs) > 0) {
            parsim_start_jobs(vol_jobs)
            return(invisible())
          }
          vol_results <- list(); plan_mode <- FALSE   # nothing to compute (e.g. only lower-dimensional models)
        }


        # Explicit levels = names_h_rep's own order (the order the user
        # actually entered/created these models in, on the Input page) —
        # as.factor() on its own sorts levels alphabetically, which is
        # what silently reordered every downstream table/plot away from
        # input order.
        parsim <- data.frame(
          "Model" = rep(factor(unlist(names_h_rep), levels = unique(unlist(names_h_rep))), each = 3),
          "Algorithm" = as.factor(rep(
            c("Cooling Bodies", "Sequence of Balls", "Cooling Gaussian"), length(names_h_rep)
          )),
          "Volume" = parsim,
          "Dimensionality" = rep(act_dim, each = 3)
        )


        selected_algos <- c(
          if (sel_algo[["CB"]]) "Cooling Bodies",
          if (sel_algo[["SoB"]]) "Sequence of Balls",
          if (sel_algo[["CG"]]) "Cooling Gaussian"
        )
        parsim <- parsim[parsim$Algorithm %in% selected_algos, ]
        # a model with an exact volume gets one row without an estimate (no algorithm was run for it)
        ex_row <- vapply(as.character(parsim$Model), skip_estimate, logical(1))
        algo_chr <- as.character(parsim$Algorithm); algo_chr[ex_row] <- "Exact"
        parsim$Volume[ex_row] <- NA_real_
        parsim$Algorithm <- factor(algo_chr, levels = c(levels(parsim$Algorithm), "Exact"))
        parsim <- parsim[!duplicated(paste(parsim$Model, parsim$Algorithm)), ]

        parsim_rep <- rbind(parsim_rep, parsim)
      }


      parsim_raw <- data.frame(parsim_rep[order(parsim_rep$Model, parsim_rep$Algorithm), ])

      # Cache mean volume across all selected algorithms per model for Model Properties table
      for (nm in unique(as.character(parsim_raw$Model))) {
        vol_rows <- parsim_raw[parsim_raw$Model == nm, "Volume"]
        vol_vals <- vol_rows[!is.na(vol_rows)]
        if (length(vol_vals) > 0)
          h_pars_reactive[[nm]] <- mean(vol_vals)
      }
      if (length(names_models_reactive$value) >= 2)
        showTab(inputId = "tabs", target = "Model Properties")

      parsim <- parsim_rep %>%
        group_by(Model, Algorithm, Dimensionality) %>%
        summarize(
          SD = sd(Volume), Volume = mean(Volume),
          Max_BF = 1 / Volume
        )


      parsim_wide <- parsim %>%
        pivot_wider(
          names_from = c("Algorithm"),
          values_from = c(Volume, SD, Max_BF)
        )

      parsim_wide_table <- (parsim_wide %>% select(-contains("SD")))

      parsim_wide_table_reactive$value <- parsim_wide_table

      # Build display table: one row per model × algorithm
      parsim_display <- as.data.frame(parsim[order(parsim$Model, parsim$Algorithm), ])
      exact_vol <- if (exact_on && !is.null(ex_pre)) unname(ex_pre[as.character(parsim_display$Model)]) else rep(NA_real_, nrow(parsim_display))
      # Plain decimal rounds tiny volumes to "0.0000", and as.character()'s
      # default scientific notation ("5e-04") is inconsistent with the rest
      # of the app's number formatting — show a fixed "< m.mm x 10^-n" form
      # instead so small volumes stay legible without a raw R exponent.
      vol_str <- function(x) {
        rounded <- round(x, 4)
        # as.character() on a small-but-nonzero rounded value (e.g. 0.0005)
        # STILL falls back to R's own scientific notation ("5e-04") — must
        # force fixed notation explicitly, not just branch on rounded==0.
        if (rounded != 0) return(format(rounded, scientific = FALSE, trim = TRUE))
        if (x <= 0) return("0")
        exp  <- floor(log10(x))
        mant <- x / 10^exp
        sprintf("%.2f &times; 10<sup>%d</sup>", mant, exp)
      }
      # Same idea as vol_str above, mirrored for Max BF (= 1/volume, so a
      # tiny volume means a huge BF here) — a plain round() left values
      # like 8336282.75 as a long, hard-to-scan decimal; same "m.mm x
      # 10^n" scientific form once it's large enough to matter.
      # No "<"/">" here: vol_str's own "< X" doesn't mean "the true
      # volume is below X" (a real bound) — X there is computed AS
      # x/10^exp, i.e. it already IS the actual volume estimate, just
      # written in scientific notation because plain 4-decimal rounding
      # would otherwise show a misleading "0.0000". Since Max BF is
      # simply 1 divided by that same already-precise number, it's a
      # plain value here too, not a bound in either direction — an
      # earlier version of this added a ">" prefix on that (incorrect)
      # bound assumption; reverted after being questioned on it.
      bf_str <- function(x) {
        if (is.na(x)) return("—")
        # Max_BF = 1/Volume, so an exactly-zero (not merely tiny) Volume
        # — e.g. a full-dimensional model whose Monte Carlo estimate
        # landed on 0 without tripping the separate "Not full-dimensional"
        # branch above — gives Inf here. floor(log10(Inf)) is itself Inf,
        # and sprintf("%d", Inf) errors ("invalid format '%d' ... for
        # numeric objects") since Inf has no integer representation —
        # exactly the crash this guards against.
        if (!is.finite(x)) return("∞")
        if (abs(x) < 1000) return(as.character(round(x, 2)))
        exp  <- floor(log10(abs(x)))
        mant <- x / 10^exp
        sprintf("%.2f &times; 10<sup>%d</sup>", mant, exp)
      }
      # One row per model and method: "Exact" (calculated) and the algorithms (estimated), one Volume column for all
      mdl_all <- gsub("^\\[(.*)\\]$", "\\1", as.character(parsim_display$Model))
      first_of_model <- !duplicated(as.character(parsim_display$Model))
      is_exact_row <- as.character(parsim_display$Algorithm) == "Exact"
      long_df <- rbind(
        if (exact_on) data.frame(Model = mdl_all[first_of_model], Algorithm = "Exact",
                                 Dimensionality = as.character(parsim_display$Dimensionality)[first_of_model],
                                 Volume = exact_vol[first_of_model], stringsAsFactors = FALSE),
        data.frame(Model = mdl_all[!is_exact_row], Algorithm = as.character(parsim_display$Algorithm)[!is_exact_row],
                   Dimensionality = as.character(parsim_display$Dimensionality)[!is_exact_row],
                   Volume = as.numeric(parsim_display$Volume)[!is_exact_row], stringsAsFactors = FALSE))
      long_df <- long_df[order(match(long_df$Model, unique(mdl_all)), long_df$Algorithm != "Exact"), , drop = FALSE]
      long_nfd <- startsWith(long_df$Dimensionality, "Not full-dimensional")
      # a model that is not full-dimensional has volume 0 whatever the method says
      long_df$Volume[long_nfd] <- 0
      # a fraction for an exact value (1/6 instead of 0.1667) when it reproduces the number to 12 digits and its denominator is small;
      # only for the Exact rows (a sampled estimate would pretend to be more precise than it is)
      rat_approx <- function(x, maxden = 10000, tol = 1e-12) {
        if (!is.finite(x) || x <= 0 || x >= 1e6) return(NA_character_)
        y <- x; h0 <- 0; h1 <- 1; k0 <- 1; k1 <- 0
        for (it in 1:40) {
          a <- floor(y); h <- a * h1 + h0; k <- a * k1 + k0
          if (k > maxden) break
          h0 <- h1; h1 <- h; k0 <- k1; k1 <- k
          if (abs(x - h1 / k1) <= tol * x) {
            if (k1 == 1) return(NA_character_)
            return(paste0(format(h1, scientific = FALSE, trim = TRUE), "/", format(k1, scientific = FALSE, trim = TRUE)))
          }
          if (y - a < 1e-15) break
          y <- 1 / (y - a)
        }
        NA_character_
      }
      with_frac <- function(txt, v, is_exact) {
        fr <- if (is_exact) rat_approx(v) else NA_character_
        if (is.na(fr)) txt else paste0(fr, " (", txt, ")")
      }
      is_ex_long <- long_df$Algorithm == "Exact"
      dim_short <- function(x) sub("^Not full-dimensional \\(in (\\d+)D space\\)$", "Not full-dim. (in \\1D)", sub("^Full-dimensional \\((\\d+D)\\)$", "\\1", x))
      simple_tbl <- data.frame(
        Model          = long_df$Model,
        Algorithm      = long_df$Algorithm,
        Dimensionality = dim_short(long_df$Dimensionality),
        Volume         = vapply(seq_len(nrow(long_df)), function(i) {
          v <- long_df$Volume[i]
          if (is.nan(v)) return(paste0("n/a (stopped after ", EXACT_VOLUME_LIMIT_TXT, " or skipped)"))
          if (is.na(v)) return("\u2014")
          if (v == 0) return("0")
          with_frac(vol_str(v), v, is_ex_long[i])
        }, character(1)),
        `Max BF`       = vapply(seq_len(nrow(long_df)), function(i) {
          v <- long_df$Volume[i]
          if (is.na(v)) return("\u2014")
          if (v == 0) return("\u221e")
          with_frac(bf_str(1 / v), 1 / v, is_ex_long[i])
        }, character(1)),
        check.names    = FALSE
      )
      # Sort: base models first, intersections (containing ∩) below
      is_intersection <- grepl("∩", simple_tbl$Model)
      simple_tbl <- rbind(simple_tbl[!is_intersection, ], simple_tbl[is_intersection, ])

      # Whether an ACTUAL comparison table is being shown at all — mirrors
      # the exact "need >= 2 models" gate output$comparison_table_ui uses.
      # A model merely existing/being computed is NOT enough — with only
      # one model defined, that view shows a placeholder instead of a
      # table, so the parsimony detail table is the only place this
      # information exists and must default open. (Since the comparison
      # table is now a single unified table across base/replication/item
      # models — see all_comparison_model_names() — this is just its
      # length, not three separate per-type thresholds.)
      any_comparison_shown <- length(all_comparison_model_names()) >= 2
      parsim_needs_open$value <- !any_comparison_shown

      # Assign a color per unique model
      model_order  <- unique(simple_tbl$Model)
      palette_pool <- c("#e8edf5", "#e8f5eb", "#f5ebe8", "#f5f5e8", "#ede8f5", "#f5e8f0", "#e8f5f5", "#f5f0e8", "#eef5e8", "#f0e8f5")
      model_colors <- setNames(
        rep_len(palette_pool, length(model_order)),
        model_order
      )
      simple_tbl$.grp <- simple_tbl$Model

      output$parsim_table <- DT::renderDataTable({
        DT::datatable(simple_tbl,
          rownames = FALSE,
          escape = c(1, 2, 3, ncol(simple_tbl)),   # the number columns carry a real superscript (10<sup>-8</sup>)
          options = list(
            scrollX   = FALSE,
            # autoWidth measures the table's CONTAINER at the exact
            # moment DataTables initializes — on the very first
            # Compute, that can happen before this panel has settled
            # into its final layout width, locking columns to a too-
            # narrow snapshot that a later re-init (Recalculate)
            # "fixes" only because the container is already correctly
            # sized by then. Leaving it off lets the table's own
            # width:100% (below) size it via normal CSS instead of
            # DataTables' own pixel-snapshotted column widths, so
            # there's nothing to get stuck on a stale measurement.
            autoWidth = FALSE,
            pageLength = 12,
            lengthMenu = c(6, 12, 18, 24, 48, 96),
            dom = if (nrow(simple_tbl) > 6) "ltp" else "t",
            # a short explanation when the mouse is over a column header
            headerCallback = DT::JS(paste0("function(thead) { var t = { 'Dimensionality': 'Number of dimensions of the model (3D: three free probabilities). Not full-dim.: the model is flat in some direction because of an equality, so its volume is 0.', 'Algorithm': 'Exact: calculated from the corner points of the model, not sampled, does not change between runs. The other rows: estimated by random sampling with that algorithm; they change from run to run, by an amount that depends on the model. By default only shown for models without an exact volume.', 'Volume': 'The share of the parameter space that fits the model. n/a: the exact calculation was stopped (time limit of ", EXACT_VOLUME_LIMIT_TXT, " or skipped); then the algorithm estimates the volume.', 'Max BF': 'Largest Bayes factor the model can reach against the unconstrained model: 1 / volume of that row.'}; $(thead).find('th').each(function() { var k = $(this).text().trim(); if (t[k]) this.title = t[k]; }); }")),
            columnDefs = list(
              list(className = "dt-left", targets = 0),
              list(visible = FALSE, targets = ncol(simple_tbl) - 1)
            )
          ),
          width = "100%"
        ) %>%
          DT::formatStyle(
            columns = ".grp",
            target  = "row",
            backgroundColor = DT::styleEqual(names(model_colors), unname(model_colors))
          )
      }, server = FALSE)   # client-side paging, see the V-representation tables

      # One (grouped) bar per model x algorithm — same numbers as the
      # "Volume" column of the table below, just visual, so both a big
      # volume gap between models AND a disagreement between algorithms
      # on the same model are legible at a glance instead of read off a
      # column of numbers. "Not full-dimensional" reads as a genuine 0
      # volume here, same convention as the table's Volume column.
      bar_df <- data.frame(
        Model     = gsub("^\\[(.*)\\]$", "\\1", as.character(parsim_display$Model)),
        Algorithm = as.character(parsim_display$Algorithm),
        Volume    = ifelse(startsWith(parsim_display$Dimensionality, "Not full-dimensional"), 0, parsim_display$Volume)
      )
      bar_df <- bar_df[!is.na(bar_df$Volume), ]
      # the exact volume as one more bar per model (where there is one), next to the estimates of the algorithms
      ex_all <- data.frame(Model = gsub("^\\[(.*)\\]$", "\\1", as.character(parsim_display$Model)), Volume = exact_vol)
      ex_all <- ex_all[is.finite(ex_all$Volume) & !duplicated(ex_all$Model), , drop = FALSE]
      if (nrow(ex_all) > 0) {
        ex_df <- data.frame(Model = ex_all$Model, Algorithm = "Exact", Volume = ex_all$Volume)
        bar_df <- rbind(bar_df, ex_df)
      }
      n_algos_used <- length(unique(bar_df$Algorithm))
      parsim_bar_data(bar_df)

      # Shared between the compact overview chart and its "expand" modal
      # view — same data/colors/ordering, only the font/margin sizing
      # scales up for the larger one so it doesn't look like the same
      # cramped chart just stretched.
      build_parsimony_plot <- function(large = FALSE) {
        if (nrow(bar_df) == 0) return(NULL)
        # Keep models in the same top-to-bottom order as the table above
        # rather than plotly's default (alphabetical/appearance) order.
        # long model names are wrapped, otherwise they squeeze the plot into a narrow strip
        wrap_lab <- function(x) vapply(x, function(z) paste(strwrap(z, 26), collapse = "<br>"), character(1), USE.NAMES = FALSE)
        bar_df$Model <- factor(wrap_lab(bar_df$Model), levels = rev(unique(wrap_lab(bar_df$Model))))
        algo_colors <- c("Cooling Bodies" = "#7a4fc4", "Cooling Gaussian" = "#f0ad4e", "Sequence of Balls" = "#5cb85c", "Exact" = "#8b93a7")
        fsize <- if (large) 15 else 11
        # very small volumes are invisible on a 0-1 axis: then the axis is logarithmic (models with volume 0 have no bar)
        pos_vol <- bar_df$Volume[is.finite(bar_df$Volume) & bar_df$Volume > 0]
        use_log <- length(pos_vol) > 0 && min(pos_vol) < 0.01
        p <- plot_ly(
          bar_df,
          x = ~Volume, y = ~Model, color = ~Algorithm, type = "bar", orientation = "h",
          colors = algo_colors,
          marker = list(line = list(width = 0)),
          hovertemplate = "%{fullData.name}: %{x:.3g}<extra></extra>"
        ) %>%
          layout(
            showlegend = TRUE,
            barmode = "group",
            bargap = 0.35, bargroupgap = 0.15,
            # one label per model row, wherever the mouse is on that row (not only at the end of a bar), listing the
            # volume of every algorithm; a white box, so it is not mistaken for part of the bar
            hovermode = "y unified",
            hoverlabel = list(bgcolor = "white", bordercolor = "rgba(120,120,120,0.5)", font = list(color = "#333", size = fsize)),
            font = list(size = fsize, color = "#555"),
            paper_bgcolor = "rgba(0,0,0,0)", plot_bgcolor = "rgba(0,0,0,0)",
            xaxis = list(
              title = list(text = if (use_log) "Volume (log scale)" else "Volume", standoff = if (large) 14 else 8),
              type = if (use_log) "log" else "linear",
              # on a log axis only the powers of ten get a mark and a label (otherwise the large view adds 2 and 5 between them)
              dtick = if (use_log) 1 else NULL,
              exponentformat = "power", showexponent = "all",
              range = if (use_log) c(log10(min(pos_vol) / 3), 0.05) else c(0, 1),
              gridcolor = "rgba(120,120,120,0.15)", zeroline = FALSE,
              showline = TRUE, linecolor = "rgba(120,120,120,0.35)"
            ),
            yaxis = list(title = "", showgrid = FALSE, ticks = "", automargin = TRUE),
            # Placed ABOVE the plot area (y > 1, paper coordinates) rather
            # than below it — a bottom-anchored legend kept landing on top
            # of the x-axis title regardless of how far down it was pushed,
            # since plotly draws the axis title relative to the actual
            # tick labels, not a fixed offset a legend's y can reliably
            # clear. Above the bars there's nothing else to collide with.
            legend = if (n_algos_used >= 1) list(orientation = "h", x = 0, xanchor = "left", y = 1.02, yanchor = "bottom", font = list(size = fsize - 1)) else list(visible = FALSE, showlegend = FALSE),
            # room above the plot for the legend, also when it wraps to one entry per line in a narrow chart
            margin = if (large) list(l = 10, r = 30, t = if (n_algos_used >= 1) 30 + 22 * n_algos_used else 20, b = 50, pad = 6)
                     else list(l = 10, r = 20, t = if (n_algos_used >= 1) 20 + 20 * n_algos_used else 10, b = 34, pad = 4)
          ) %>%
          # the only button is the download, as a vector graphic (SVG)
          config(displayModeBar = if (large) TRUE else "hover", displaylogo = FALSE,
                 modeBarButtons = list(list("toImage")),
                 toImageButtonOptions = list(format = "svg", filename = "volume_by_model"))
        p
      }

      output$parsimony_bar_plot <- renderPlotly(build_parsimony_plot(large = FALSE))
      output$parsimony_bar_plot_large <- renderPlotly(build_parsimony_plot(large = TRUE))
      # Its home container renders with style="display:none" (see
      # output$parsimony_plot_ui) until expanded — Shiny suspends an
      # output's computation by default while its container isn't
      # visible, which would leave this stale/blank the first time it's
      # actually shown. Always compute it instead.
      outputOptions(output, "parsimony_bar_plot_large", suspendWhenHidden = FALSE)

      # numeric version of the table for the CSV download (volume and Max BF unformatted, 0 / Inf for models that are not full-dimensional)
      csv_tbl <- data.frame(
        Model          = long_df$Model,
        Algorithm      = long_df$Algorithm,
        Dimensionality = long_df$Dimensionality,
        Volume         = ifelse(is.nan(long_df$Volume), NA_real_, long_df$Volume),
        Max_BF         = ifelse(is.finite(long_df$Volume) & long_df$Volume > 0, 1 / long_df$Volume, ifelse(!is.na(long_df$Volume) & long_df$Volume == 0, Inf, NA_real_)),
        stringsAsFactors = FALSE
      )
      parsim_csv_data(csv_tbl[order(grepl("∩", csv_tbl$Model)), , drop = FALSE])

      parsim_has_results(TRUE)
      fairy_run_end("")

    }

    #### Parsimony output ####

    output$parsimony_results_header_ui <- renderUI({
      div(style = "margin-bottom:10px;",
        h5("Parsimony results", style = "margin:0 0 6px 0;"),
        HTML(paste0("<details style='font-size:13px; color:#555; line-height:1.55;'><summary style='cursor:pointer; color:var(--fairy-primary);'>What do the columns mean?</summary>
          <div><b>Volume</b> &ndash; the share of the parameter space that fits the model. Each model has one row per method (column Algorithm).</div>
          <div><b>Exact</b> &ndash; calculated, not sampled, from the corner points of the model's region. The result does not change between runs; numerical rounding only affects digits far beyond those shown (e.g. the 10th significant digit, even for extremely small volumes). <b>By default, no algorithm is run for a model when an exact volume can be calculated</b> (switch Algorithms on to run them anyway). n/a: the calculation was stopped (time limit of ", EXACT_VOLUME_LIMIT_TXT, " or skipped); then the algorithm estimates the volume.</div>
          <div><b>Cooling Bodies, Cooling Gaussian, Sequence of Balls</b> &ndash; the same share, estimated by random sampling. It differs from run to run, and how much depends on the model (typically more with many dimensions or thin shapes). For more precise values lower the error in the algorithm settings (slower).</div>
          <div><b>Max BF</b> &ndash; the largest Bayes factor the model can reach against the unconstrained model: 1 / the volume of that row. Smaller volume = more restrictive model = larger Max BF.</div>
          <div><b>Software</b> &ndash; these volumes are not calculated by this app itself but by R packages. <i>Exact</i>: <a href='https://cran.r-project.org/package=rcdd' target='_blank' rel='noopener'>rcdd</a> finds the corner points (it uses the library cddlib), <a href='https://cran.r-project.org/package=geometry' target='_blank' rel='noopener'>geometry</a> (Qhull) calculates the volume of the shape they span. <i>Algorithms</i>: <a href='https://cran.r-project.org/package=volesti' target='_blank' rel='noopener'>volesti</a>. How to cite them: in R, <code>citation(\"rcdd\")</code>, <code>citation(\"geometry\")</code>, <code>citation(\"volesti\")</code>.</div>
        </details>"))
      )
    })

    output$parsimony_plot_ui <- renderUI({
      # A compact overview, not a full-size chart: fixed small per-row
      # height (a few more px per model when several algorithms are
      # grouped side by side within each row) instead of stretching to
      # fill the page, capped so a long model list still scrolls its
      # table rather than the plot growing without bound.
      n_models <- length(model_order)
      n_algos  <- max(1, n_algos_used)
      # Extra fixed room at the top for the legend row (see the matching
      # top margin in output$parsimony_bar_plot) when more than one
      # algorithm is shown.
      legend_h <- 20 + 20 * n_algos
      plot_h <- min(400, max(140, 55 + legend_h + n_models * (20 + n_algos * 14)))
      tagList(
        div(
          class = "model-card",
          style = "margin-bottom:20px; max-width:560px; padding:14px 18px;",
          div(style = "display:flex; align-items:center; justify-content:space-between; margin-bottom:8px;",
            h5("Volume by model", style = "margin:0; font-size:13px;"),
            # Plain button, not a Shiny actionButton — expanding this is
            # purely a client-side DOM move now (see openParsimonyPlot-
            # Full()/closeParsimonyPlotFull() in the tags$script below),
            # reusing the same #fairy-card-overlay every other card's
            # click-to-expand already uses, instead of a bounded
            # Bootstrap modalDialog with its own margins/max-width that
            # never actually reached full-screen.
            div(style = "display:flex; align-items:center; gap:8px;",
              downloadButton("download_parsimony_pdf", "PDF", class = "btn-sm"),
              tags$button(
                id = "expand_parsimony_plot_btn", type = "button",
                class = "fairy-plot-expand-btn fairy-tooltip",
                `data-tooltip` = "Expand",
                icon("expand")
              )
            )
          ),
          plotlyOutput("parsimony_bar_plot", height = paste0(plot_h, "px"))
        ),
        # The full-screen version — same data, bigger fonts/margins (see
        # build_parsimony_plot(large=TRUE)) — lives here always, just
        # hidden, so openParsimonyPlotFull() can move the REAL node (not
        # a clone) into the overlay: a cloned live Plotly widget doesn't
        # actually resize/respond, since Plotly's own internal state is
        # tied to the specific DOM node it was drawn into.
        div(
          id = "parsimony_plot_large_home", style = "display:none;",
          div(class = "model-card-title", style = "margin-bottom:12px;", "Volume by model"),
          plotlyOutput("parsimony_bar_plot_large", height = "calc(100vh - 160px)")
        )
      )
    })

    output$parsimony_spinner_table <- renderUI({
      # This tab's whole purpose is this per-algorithm results table, so it
      # is always shown directly — no collapsed <details> to click through.
      div(style = "width:100%;",
        div(style = "display:flex; align-items:center; justify-content:space-between; margin-bottom:8px;",
          h5("Detailed results per model and method", style = "margin:0;"),
          downloadButton("download_parsimony_csv", "CSV", class = "btn-sm")),
        DT::dataTableOutput("parsim_table", width = "100%")
      )
    })

  })

  #####* Download H-representation QTEST ####

  # QTEST's H-representation file format is a pure inequality system
  # (A*p <= b) -- it has no notion of "=" at all. A model with
  # equalities used to just be refused a QTEST file outright ("Use
  # V-representation instead"). This eliminates each equality by
  # Gaussian substitution -- solving it for one parameter in terms of
  # the others, substituting that into every remaining row (other
  # equalities and all inequalities), and dropping that parameter's
  # column -- so what's left is a smaller pure-inequality system QTEST
  # can actually read. One parameter is eliminated per INDEPENDENT
  # equality; a redundant one (already implied, reduces to 0=0 once
  # prior eliminations are applied) is silently dropped, and a genuinely
  # contradictory one (0=nonzero) marks the model infeasible instead of
  # emitting a bogus file.
  #
  # Returns a list:
  #   ineq          - the reduced inequality-only matrix (numeric,
  #                    [type, b, coefs...] rcdd-style rows, type always 0)
  #   remaining_idx - original column index (1-based, into the model's
  #                    own p1..pn) each column of `ineq` corresponds to
  #   eliminated    - named list (key = original index, as a string) of
  #                    each eliminated parameter's formula, fully
  #                    resolved in terms of the FINAL surviving
  #                    parameters only (list(const=, idx=, coefs=))
  #   infeasible    - TRUE if the equalities are contradictory
  eliminate_h_equalities <- function(h_mat) {
    h_num <- q2d(h_mat)
    n_p   <- ncol(h_num) - 2L
    is_eq <- h_num[, 1] == 1

    eq_pool   <- h_num[is_eq, , drop = FALSE]
    ineq_rows <- h_num[!is_eq, , drop = FALSE]

    remaining_idx <- seq_len(n_p)
    elim_raw <- list()
    elim_order <- character()
    infeasible <- FALSE

    # Drops column `pivot_pos` (a position WITHIN the current, possibly
    # already-shrunk, column set) from every row of M, after first
    # subtracting whatever multiple of `eq_row` zeroes that column out.
    # Column 1 (the row's own type flag, 0=inequality/1=equality) is
    # deliberately left OUT of that subtraction and copied straight from
    # M itself — it isn't part of the linear system at all, just a tag,
    # and subtracting eq_row's own type value (always 1) through it
    # corrupted every substituted inequality row into looking like an
    # equality (or worse) instead of staying 0. Confirmed directly: a
    # hand-built 1-equality/3-inequality test case came back with type
    # values of -1 and 1 on rows that were, and needed to stay, plain
    # inequalities.
    reduce_matrix <- function(M, pivot_pos, a_piv, eq_row) {
      if (nrow(M) == 0) return(M[, -(2L + pivot_pos), drop = FALSE])
      out <- matrix(0, nrow = nrow(M), ncol = ncol(M) - 1L)
      for (r in seq_len(nrow(M))) {
        k <- M[r, 2L + pivot_pos]
        new_row <- if (abs(k) < 1e-12) M[r, ] else M[r, ] - (k / a_piv) * eq_row
        new_row[1] <- M[r, 1]
        out[r, ] <- new_row[-(2L + pivot_pos)]
      }
      out
    }

    while (nrow(eq_pool) > 0 && length(remaining_idx) > 0) {
      row <- eq_pool[1, ]
      eq_pool <- eq_pool[-1, , drop = FALSE]

      coefs <- row[3L:(2L + length(remaining_idx))]
      pivot_pos <- which(abs(coefs) > 1e-9)[1]
      if (is.na(pivot_pos)) {
        # Nothing left standing that this equality still constrains --
        # either it's implied by eliminations already applied (0 = 0,
        # drop it) or it contradicts them (0 = nonzero, infeasible).
        if (abs(row[2]) > 1e-9) { infeasible <- TRUE; break }
        next
      }

      pivot_orig <- remaining_idx[pivot_pos]
      a_piv <- coefs[pivot_pos]
      other_pos <- setdiff(seq_along(remaining_idx), pivot_pos)

      elim_raw[[as.character(pivot_orig)]] <- list(
        const = -row[2] / a_piv,
        idx   = remaining_idx[other_pos],
        coefs = if (length(other_pos) > 0) -coefs[other_pos] / a_piv else numeric(0)
      )
      elim_order <- c(elim_order, as.character(pivot_orig))

      eq_pool   <- reduce_matrix(eq_pool,   pivot_pos, a_piv, row)
      ineq_rows <- reduce_matrix(ineq_rows, pivot_pos, a_piv, row)
      remaining_idx <- remaining_idx[-pivot_pos]
    }

    # Each formula above is only in terms of whatever was still standing
    # AT THE TIME its own equality was processed -- which can include a
    # parameter eliminated LATER (never one eliminated earlier, since
    # that one had already been dropped from the pool). Resolving fully
    # down to just the FINAL survivors is therefore one clean backward
    # pass over elim_order, last-processed first: the last one is
    # already survivor-only, and substituting each already-resolved
    # formula into the ones before it (in reverse) can never re-
    # introduce a dependency this pass hasn't reached yet.
    resolved <- list()
    for (ki in rev(seq_along(elim_order))) {
      key <- elim_order[ki]
      e <- elim_raw[[key]]
      const <- e$const
      new_idx <- numeric(0); new_coefs <- numeric(0)
      for (ii in seq_along(e$idx)) {
        dep_key <- as.character(e$idx[ii])
        if (dep_key %in% names(resolved)) {
          dep <- resolved[[dep_key]]
          const <- const + e$coefs[ii] * dep$const
          new_idx   <- c(new_idx,   dep$idx)
          new_coefs <- c(new_coefs, e$coefs[ii] * dep$coefs)
        } else {
          new_idx   <- c(new_idx,   e$idx[ii])
          new_coefs <- c(new_coefs, e$coefs[ii])
        }
      }
      if (length(new_idx) > 0) {
        u <- unique(new_idx)
        agg <- vapply(u, function(ui) sum(new_coefs[new_idx == ui]), numeric(1))
        new_idx <- u; new_coefs <- agg
      }
      resolved[[key]] <- list(const = const, idx = new_idx, coefs = new_coefs)
    }

    list(
      ineq = ineq_rows, remaining_idx = remaining_idx,
      eliminated = resolved, infeasible = infeasible
    )
  }

  # Shared by both the plain (no-equalities) and equality-eliminated
  # paths below -- same fraction/common-denominator formatting either
  # way, just fed a different (already numeric, already reduced-to-the-
  # right-columns) inequality matrix, so there's exactly one place that
  # knows the actual QTEST text layout.
  # R script that ships inside the multinomineq downloads: it reads the files that are next to it and runs the analysis
  # example data files next to the script: one row per probability, to be overwritten with the own frequencies. Models with a
  # different number of probabilities (e.g. unpacked items models) need their own file, so there is one file per number of
  # probabilities: data_choices.csv if all models have the same number, data_choices_<k>_probabilities.csv otherwise.
  # groups: list named by group ("k:<number>" for models that share their probabilities, "m:<model>" for an unpacked model of its
  # own), each with k, labels (column names), stem (file name part). Returns the file names.
  # (decreasing example frequencies: equal ones can stop the sampler)
  write_multinomineq_data <- function(groups, user = list(), share = list()) {
    # an unpacked model that uses the numbers of the models with the same number of probabilities gets no file of its own
    # (share[[key]]: TRUE = the models with the same number of probabilities, or the key of the group whose numbers it uses)
    src_of <- function(key) {
      v <- share[[key]]
      if (is.character(v) && length(v) == 1) v else if (isTRUE(v) && !is.null(groups[[key]])) paste0("k:", groups[[key]]$k) else NULL
    }
    drop <- vapply(names(groups), function(key) {
      if (!startsWith(key, "m:")) return(FALSE)
      s0 <- src_of(key)
      !is.null(s0) && startsWith(s0, "k:") && !is.null(groups[[s0]])
    }, logical(1))
    all_groups <- groups
    groups <- groups[!drop]
    base_ks <- unique(vapply(groups[grepl("^k:", names(groups))], function(g) as.integer(g$k), integer(1)))
    out <- character(0)
    for (key in names(groups)) {
      g <- groups[[key]]
      f <- if (startsWith(key, "m:")) paste0("data_model_", g$stem, ".csv")
           else if (length(base_ks) == 1) "data_choices.csv" else paste0("data_choices_", g$k, "_probabilities.csv")
      ex <- round(25 * seq(0.8, 0.2, length.out = g$k))
      # the numbers belong to the probability (its name), so they stay with it when the order is changed
      u <- user[[key]]
      # an unpacked model that uses the numbers of another unpacked model: the numbers of that model, probability by probability
      src <- if (startsWith(key, "m:")) src_of(key) else NULL
      for (hop in 1:4) { if (!is.null(src) && startsWith(src, "m:") && !is.null(src_of(src))) src <- src_of(src) else break }
      if (!is.null(src) && !is.null(all_groups[[src]]) && all_groups[[src]]$k == g$k) {
        sg <- all_groups[[src]]; su <- user[[src]]
        # the same probabilities in a different order (each unpacked model has its own order): the numbers follow the probability,
        # otherwise they follow the position
        pos <- if (setequal(sg$labels, g$labels)) match(g$labels, sg$labels) else seq_len(g$k)
        nn <- vapply(seq_len(g$k), function(i) { v <- su[[sg$labels[pos[i]]]]; if (is.null(v)) 25L else as.integer(v$n) }, integer(1))
        ff <- vapply(seq_len(g$k), function(i) { v <- su[[sg$labels[pos[i]]]]; if (is.null(v)) as.integer(ex[pos[i]]) else as.integer(v$f) }, integer(1))
      } else {
        nn <- vapply(seq_len(g$k), function(i) { v <- u[[g$labels[i]]]; if (is.null(v)) 25L else as.integer(v$n) }, integer(1))
        ff <- vapply(seq_len(g$k), function(i) { v <- u[[g$labels[i]]]; if (is.null(v)) as.integer(ex[i]) else as.integer(v$f) }, integer(1))
      }
      utils::write.csv(data.frame(probability = g$labels, n = nn, frequency = ff), f, row.names = FALSE, quote = FALSE)
      out <- c(out, f)
    }
    out
  }
  # Exact equalities between two probabilities (p_i = p_j) can be used by multinomineq through its map argument: the equal
  # probabilities become ONE free parameter. h_num: numeric H-representation [type, b, coefficients]. Returns NULL if there is
  # no such equality, else list(map = group of every probability, groups = first member of every group, keep = rows to keep).
  mn_reduce_equalities <- function(h_num) {
    n_p <- ncol(h_num) - 2L
    parent <- seq_len(n_p)
    find <- function(i) { while (parent[i] != i) i <- parent[i]; i }
    simple <- rep(FALSE, nrow(h_num))
    for (r in which(h_num[, 1] == 1)) {
      cf <- h_num[r, -(1:2)]
      nz <- which(abs(cf) > 1e-12)
      if (length(nz) == 2 && abs(h_num[r, 2]) < 1e-12 && abs(cf[nz[1]] + cf[nz[2]]) < 1e-12) {
        simple[r] <- TRUE
        a <- find(nz[1]); b <- find(nz[2])
        if (a != b) parent[max(a, b)] <- min(a, b)
      }
    }
    if (!any(simple) || all(simple)) return(NULL)
    root <- vapply(seq_len(n_p), find, integer(1))
    groups <- sort(unique(root))
    list(map = match(root, groups), groups = groups, keep = !simple)
  }
  # Does an H-representation (character rcdd matrix, after the equalities p_i = p_j are merged) have volume? NULL = yes,
  # otherwise the reason as text: an exact equality is left, or some inequalities hold with equality everywhere.
  mn_volume_zero <- function(A) {
    num <- q2d(A)
    labs <- colnames(A)[-(1:2)]
    eqs <- which(num[, 1] == 1)
    if (length(eqs) > 0) {
      txt <- vapply(eqs, function(r) {
        cf <- num[r, -(1:2)]; nz <- which(abs(cf) > 1e-12)
        lhs <- paste(vapply(nz, function(j) paste0(if (abs(cf[j] - 1) < 1e-12) "" else format(cf[j], digits = 4), labs[j]), character(1)), collapse = " + ")
        paste0(lhs, " = ", format(-num[r, 2], digits = 4))
      }, character(1))
      return(paste0("it contains the exact equality ", paste(txt, collapse = "; "), " (other than p = p)"))
    }
    hh <- A; attr(hh, "representation") <- "H"
    lin <- tryCatch(rcdd::linearity(hh), error = function(e) integer(0))
    if (length(lin) > 0) return("some of its inequalities hold with equality everywhere, so it is flat in some direction")
    NULL
  }
  multinomineq_script <- function(first_model, n_p) {
    paste(c(
      '#### Analysis with the multinomineq package ####',
      '# Put this script in one folder with the files of this download:',
      '#   A_<model>.csv, b_<model>.csv   H-representation',
      '#   map_<model>.csv                only with equal probabilities',
      '#   V_<model>.csv                  V-representation (not used; see the commented lines in analyse())',
      '#   data_choices*.csv              your data (see below)',
      '# Then run the whole script. It analyses EVERY model in the',
      '# folder and writes results.csv (Bayes factors),',
      '# posterior.csv (estimates of the probabilities) and',
      '# results.html (the main results as a web page).',
      '# Package: https://www.dwheck.de/software/multinomineq/',
      '#',
      '# Equalities: multinomineq needs a model with positive volume.',
      '# Exact equalities between two probabilities (p1 = p2) are',
      '# handled: the files have fewer columns, and map_<model>.csv',
      '# says which probabilities are equal. Other exact equalities',
      '# (p1 = 0.3, p1 = p2 + p3) give volume zero: set them to',
      '# "Approximate" in the app before you download.',
      '#',
      '# Your data: open the data file(s) next to this script and',
      '# replace the example numbers by your own (or enter them in the',
      '# app first: Data button next to the download).',
      '#   data_choices.csv: for the models with the same probabilities',
      '#   (if they differ in number: data_choices_<k>_probabilities.csv)',
      '#   data_model_<name>.csv: only for that model (unpacked items',
      '#   models: their probabilities mean something of their own)',
      '#   The script takes, for each model, the first file that exists.',
      '#   One row per probability, in the order of the columns of A / V.',
      '#   n          number of observations for this probability',
      '#   frequency  how often the outcome the probability stands for',
      '#              was observed, out of n (e.g. how often the option',
      '#              with choice probability p1 was chosen)',
      '',
      '#### Settings ####',
      'final <- FALSE   # TRUE: more samples for the final numbers',
      '                 # (takes longer, smaller standard error)',
      'plots <- FALSE   # TRUE: one plot of the posterior per model',
      '# Advanced: the prior. Beta(1, 1) = uniform on every probability',
      '# (default of multinomineq).',
      'prior <- c(1, 1)',
      '# (for even more samples set M_post and M_bf to larger numbers)',
      'M_post <- if (final) 20000 else 5000     # posterior samples',
      'M_bf <- if (final) 100000 else 10000     # Bayes factor samples',
      '# Advanced: draws discarded at the start (burn-in); these are the',
      '# defaults of multinomineq. The seed makes a run repeatable.',
      'burnin_post <- 10   # posterior',
      'burnin_bf <- 5      # Bayes factors (per step)',
      '',
      '#### Packages (installed if missing) ####',
      'for (p in c("multinomineq", "rcdd", "coda")) {',
      '  if (!requireNamespace(p, quietly = TRUE)) install.packages(p)',
      '}',
      'library("rcdd")',
      'library("multinomineq")',
      'library("coda")',
      'seed <- 1234   # makes a run repeatable; every model gets its own random numbers',
      'fairy_app_url <- ""   # link that opens the app with this input (filled in by the app; used in results.pdf)',
      '',
      '# In RStudio: work in the folder of this script',
      'try({',
      '  if (requireNamespace("rstudioapi", quietly = TRUE) &&',
      '      rstudioapi::isAvailable()) {',
      '    here <- dirname(rstudioapi::getSourceEditorContext()$path)',
      '    if (nzchar(here) && here != ".") setwd(here)',
      '  }',
      '}, silent = TRUE)',
      '',
      '#### Helper functions ####',
      '# numbers or fractions such as 1/2',
      'read_q <- function(x) {',
      '  if (is.numeric(unlist(x))) {',
      '    matrix(unlist(x), ncol = ncol(x))',
      '  } else {',
      '    matrix(q2d(unlist(x)), ncol = ncol(x))',
      '  }',
      '}',
      '# one row: all Bayes factors of bf_binom with error and interval',
      'bf_row <- function(model, rep, bf, note = "") {',
      '  out <- data.frame(model = model, representation = rep)',
      '  for (r in c("bf_0u", "bf_u0", "bf_00\'")) {',
      '    nm <- sub("\'", "", r)',
      '    out[[nm]] <- bf[r, "bf"]',
      '    out[[paste0(nm, "_se")]] <- bf[r, "se"]',
      '    out[[paste0(nm, "_ci5")]] <- bf[r, "ci.5%"]',
      '    out[[paste0(nm, "_ci95")]] <- bf[r, "ci.95%"]',
      '  }',
      '  if (!nzchar(note) && any(c(out$bf_0u, out$bf_00) == 0,',
      '                           na.rm = TRUE))',
      '    note <- paste("The estimate is 0: the data speak strongly",',
      '                  "against the model (no sample fell inside it), so",',
      '                  "the true value is very small but not 0. More",',
      '                  "samples may give a number.")',
      '  if (!nzchar(note) && is.finite(out$bf_0u) && !is.finite(out$bf_00))',
      '    note <- paste("multinomineq gives no Bayes factor against the",',
      '                  "complement (everything the model forbids) for a",',
      '                  "model with equalities. The Bayes factor against",',
      '                  "the unconstrained model is not affected.")',
      '  out$note <- note',
      '  out',
      '}',
      'empty_bf <- matrix(NA_real_, 3, 4, dimnames = list(',
      '  c("bf_0u", "bf_u0", "bf_00\'"), c("bf", "se", "ci.5%", "ci.95%")))',
      '',
      '# plain explanations for models that cannot be computed',
      'no_result <- paste("No result: the model has volume, but not even",',
      '  "the stepwise method found a point inside it (very thin?).",',
      '  "Try final <- TRUE; if it still fails, check the files.")',
      'friendly <- function(msg) {',
      '  if (grepl("Truncation|min<max|boundar", msg))',
      '    return(paste("The sampler could not start. The model probably",',
      '      "has volume zero or is extremely thin; check the equalities",',
      '      "in the app and download the files again.",',
      '      "Technical message:", msg))',
      '  if (grepl("data file|needs one row|cannot be larger", msg))',
      '    return(msg)',
      '  paste("Unexpected problem:", msg, "- check that all files of",',
      '        "the download are in this folder.")',
      '}',
      '# labels like p_{1}^{(2)} as plotmath for the plot titles',
      'to_plotmath <- function(x) {',
      '  gsub("_[{]([^}]*)[}]", "[\\\\1]", x)   # ^{...} is plotmath already',
      '}',
      'plot_title <- function(label, what) {',
      '  e <- tryCatch(parse(text = to_plotmath(label))[[1]],',
      '                error = function(err) label)',
      '  bquote(.(e) ~ .(what))',
      '}',
      '# diagnostics of the posterior sample: ESS, Geweke z and an svg plot',
      'n_svg <- 0',
      'diag_rows <- function(model, rep, post, labels) {',
      '  m <- as.matrix(post); k <- ncol(m)',
      '  if (length(labels) != k) labels <- colnames(m)',
      '  ess <- tryCatch(as.numeric(coda::effectiveSize(post)),',
      '                  error = function(e) rep(NA_real_, k))',
      '  gz <- tryCatch(as.numeric(coda::geweke.diag(post)$z),',
      '                 error = function(e) rep(NA_real_, k))',
      '  f <- tempfile(fileext = ".svg")',
      '  svg_txt <- tryCatch({',
      '    svg(f, width = 8, height = 1.5 * k + 0.4)',
      '    op <- par(mfrow = c(k, 2), mar = c(2.2, 3, 1.4, 1),',
      '              mgp = c(1.6, 0.5, 0))',
      '    for (i in seq_len(k)) {',
      '      keep <- unique(round(seq(1, nrow(m), length.out = 1000)))',
      '      plot(keep, m[keep, i], type = "l", col = "#593196",',
      '           xlab = "", ylab = "",',
      '           main = plot_title(labels[i], "trace"))',
      '      plot(density(m[, i]), xlab = "", ylab = "", lwd = 2,',
      '           col = "#593196",',
      '           main = plot_title(labels[i], "density"))',
      '    }',
      '    par(op); dev.off()',
      '    x <- paste(readLines(f, warn = FALSE), collapse = " ")',
      '    n_svg <<- n_svg + 1',
      '    x <- sub("^<[?]xml[^>]*>", "", x)',
      '    # the curves follow the accent colour of the page (purple by day, blue at night)',
      '    x <- gsub(\'stroke="rgb[(]34[.]9[0-9]*%, *19[.]2[0-9]*%, *58[.]8[0-9]*%[)]"\',',
      '              \'stroke="#593196" style="stroke:var(--prim,#593196)"\', x)',
      '    x <- gsub("glyph-", paste0("g", n_svg, "glyph-"), x, fixed = TRUE)',
      '    gsub("clip", paste0("c", n_svg, "clip"), x, fixed = TRUE)',
      '  }, error = function(e) NULL)',
      '  unlink(f)',
      '  list(model = model, rep = rep, labels = labels, ess = ess,',
      '       n_draws = nrow(m), geweke = gz, svg = svg_txt,',
      '       draws = m[unique(round(seq(1, nrow(m), length.out = min(nrow(m), 2000)))), , drop = FALSE])',
      '}',
      '# posterior of every probability: mean, SD, 95% interval',
      'post_rows <- function(model, rep, post, labels) {',
      '  m <- as.matrix(post)',
      '  if (length(labels) != ncol(m)) labels <- colnames(m)',
      '  data.frame(model = model, representation = rep,',
      '    probability = labels, mean = colMeans(m),',
      '    sd = apply(m, 2, sd),',
      '    ci2.5 = apply(m, 2, quantile, 0.025),',
      '    ci97.5 = apply(m, 2, quantile, 0.975), row.names = NULL)',
      '}',
      '',
      '# long model names are shortened where space is tight',
      'short_name <- function(x, n = 28) {',
      '  ifelse(nchar(x) > n, paste0(substr(x, 1, n - 3), "..."), x)',
      '}',
      '',
      '# progress messages (the app shows them while the analysis runs)',
      'cur <- new.env()',
      'status <- function(txt) {',
      '  cat(sprintf("[%d/%d] %s: %s\\n", cur$i, cur$n,',
      '              short_name(cur$model, 40), txt))',
      '  flush.console()',
      '}',
      '',
      '#### Analysis of one model ####',
      'analyse <- function(model_name) {',
      '  file_A <- paste0("A_", model_name, ".csv")',
      '  file_V <- paste0("V_", model_name, ".csv")',
      '  A <- b <- V <- NULL',
      '  if (file.exists(file_A)) {',
      '    A_raw <- read.csv(file_A, check.names = FALSE,',
      '                      stringsAsFactors = FALSE)',
      '    A <- read_q(A_raw); colnames(A) <- colnames(A_raw)',
      '    b <- unlist(read.csv(paste0("b_", model_name, ".csv"),',
      '                  header = FALSE, stringsAsFactors = FALSE))',
      '    if (!is.numeric(b)) b <- q2d(b)',
      '  }',
      '  # Analysis from the V-representation (vertices) is possible but switched off: the app always analyses the',
      '  # H-representation (A and b). To use it, remove the # here and in the line with one("V", V = V) below, and',
      '  # put the file V_<model>.csv (one vertex per row) next to the A_ and b_ files.',
      '  # if (file.exists(file_V)) {',
      '  #   V_raw <- read.csv(file_V, check.names = FALSE,',
      '  #                     stringsAsFactors = FALSE)',
      '  #   V <- read_q(V_raw); colnames(V) <- colnames(V_raw)',
      '  # }',
      '  # does the model have volume? (the app checked the files)',
      '  info <- if (file.exists("model_info.csv")) {',
      '    read.csv("model_info.csv", stringsAsFactors = FALSE)',
      '  } else NULL',
      '  zero <- !is.null(info) && any(info$model == model_name &',
      '                                 info$volume == "zero")',
      '  if (zero) {',
      '    why <- info$reason[info$model == model_name][1]',
      '    return(list(bf = bf_row(model_name, if (!is.null(A)) "H" else "V",',
      '      empty_bf, paste0("This model has volume zero: ", why, ".",',
      '      " multinomineq needs a model with volume. In the app set",',
      '      " such equalities to Approximate and download again.")),',
      '      posterior = NULL, diag = NULL))',
      '  }',
      '  # equal probabilities: map says which parameter each belongs to',
      '  file_map <- paste0("map_", model_name, ".csv")',
      '  n_free <- if (!is.null(A)) ncol(A) else ncol(V)',
      '  map <- if (file.exists(file_map)) {',
      '    read.csv(file_map, header = FALSE)[[1]]',
      '  } else seq_len(n_free)',
      '  n_p <- length(map)',
      '',
      '  # your data for this number of probabilities',
      '  data_file <- c(paste0("data_model_", model_name, ".csv"),',
      '                 paste0("data_choices_", n_p, "_probabilities.csv"),',
      '                 "data_choices.csv")',
      '  data_file <- data_file[file.exists(data_file)][1]',
      '  if (is.na(data_file))',
      '    stop("No data file found for model ", model_name, ": expected",',
      '         " data_choices.csv or data_model_", model_name,',
      '         ".csv next to this script.")',
      '  dat <- read.csv(data_file, stringsAsFactors = FALSE)',
      '  n <- dat$n',
      '  choices <- dat$frequency',
      '  if (length(choices) != n_p)',
      '    stop(data_file, " needs one row for each of the ", n_p,',
      '         " probabilities of this model.")',
      '  if (any(choices > n))',
      '    stop("In ", data_file, ": frequency cannot be larger than n.")',
      '',
      '  # posterior: equal probabilities share one parameter, so add up',
      '  # their counts (sampling_binom with map needs a start value)',
      '  k_use <- as.vector(tapply(choices, map, sum))',
      '  n_use <- as.vector(tapply(n, map, sum))',
      '  rows <- list(); post <- list(); dg <- list(); note <- ""',
      '  one <- function(rep, ...) {',
      '    status(paste0("drawing the posterior (", rep, ")"))',
      '    p <- tryCatch(sampling_binom(k = k_use, n = n_use, ...,',
      '      prior = prior, M = M_post, burnin = burnin_post,',
      '      progress = FALSE),',
      '      error = function(e) NULL)',
      '    if (is.null(p)) {',
      '      note <<- paste("No posterior could be drawn: the sampler",',
      '        "could not start (the data are far from the model, or",',
      '        "the model has no volume).")',
      '    } else {',
      '      labs <- colnames(if (rep == "V") V else A)',
      '      post[[rep]] <<- post_rows(model_name, rep, p, labs)',
      '      dg[[rep]] <<- diag_rows(model_name, rep, p, labs)',
      '      if (plots) plot(p)',
      '    }',
      '    status(paste0("estimating the Bayes factors (", rep, ")"))',
      '    # with map the equalities belong to the model; the',
      '    # unconstrained model has all probabilities free',
      '    bf <- bf_binom(k = choices, n = n, ..., map = map,',
      '                   prior = prior, M = M_bf, burnin = burnin_bf,',
      '                   progress = FALSE)',
      '    # very small models: no sample falls inside. Then use the',
      '    # stepwise method of the package (one constraint at a time)',
      '    first <- bf["bf_0u", "bf"]',
      '    # (only for a very thin model; with data far from the model the',
      '    # stepwise method can run for a very long time)',
      '    if (!is.finite(first)) {',
      '      status("very small model: stepwise estimate")',
      '      bf2 <- tryCatch(bf_binom(k = choices, n = n, ..., map = map,',
      '        prior = prior, M = M_bf, cmin = 100, burnin = burnin_bf,',
      '        progress = FALSE),',
      '        error = function(e) NULL)',
      '      if (!is.null(bf2) && is.finite(bf2["bf_0u", "bf"])) {',
      '        bf <- bf2',
      '        note <<- paste("The model has a very small volume:",',
      '                       "computed stepwise (less precise, see se).",',
      '                       "For a more precise value use more samples (in the",',
      '                       "app: Run window, Number of samples; in the",',
      '                       "script: M_bf).")',
      '      }',
      '    }',
      '    rows[[rep]] <<- bf_row(model_name, rep, bf,',
      '      if (is.finite(bf["bf_0u", "bf"])) note else no_result)',
      '  }',
      '  # if (!is.null(V)) one("V", V = V)   # analysis from the vertices, see above',
      '  if (!is.null(A)) one("H", A = A, b = b)',
      '  list(bf = do.call(rbind, rows), posterior = do.call(rbind, post),',
      '       diag = unname(dg))',
      '}',
      '',
      '#### Run all models ####',
      '# (to analyse from V_<model>.csv files as well, use [AbV] instead of [Ab] in both places)',
      'models <- unique(sub("^[Ab]_(.*)\\\\.csv$", "\\\\1",',
      '                     list.files(pattern = "^[Ab]_.*\\\\.csv$")))',
      'cat("Working directory:", getwd(), "\\n")',
      'if (length(models) == 0)',
      '  stop("No A_*.csv files found in ", getwd(), ". Put this",',
      '       " script in the folder with the downloaded files (RStudio:",',
      '       " Session > Set Working Directory > To Source File Location).")',
      '# the order of the Input page (model_order.txt of the download), else',
      '# the alphabetical order of the files',
      'if (file.exists("model_order.txt")) {',
      '  ord <- readLines("model_order.txt")',
      '  models <- c(intersect(ord, models), setdiff(models, ord))',
      '}',
      'cat("Models found:", paste(models, collapse = ", "), "\\n")',
      '# Optional arguments (the app uses them to run every model in its own',
      '# process; without arguments the script analyses all models):',
      '#   only=<model>   analyse this model and save res_<model>.rds',
      '#   report         build the tables and results.html from the res_*.rds',
      'args <- commandArgs(TRUE)',
      'only <- sub("^only=", "", args[grepl("^only=", args)])',
      'run_one <- function(i) {',
      '  m <- models[i]',
      '  set.seed(seed + i)',
      '  cur$i <- i; cur$n <- length(models); cur$model <- m',
      '  status("starting")',
      '  res <- tryCatch(analyse(m), error = function(e) {',
      '    list(bf = bf_row(m, NA, empty_bf, friendly(conditionMessage(e))),',
      '         posterior = NULL, diag = NULL)',
      '  })',
      '  cat("\\n==== Model", m, "====\\n")',
      '  print(res$bf[, c("representation", "bf_0u", "bf_0u_se",',
      '                   "bf_u0", "bf_00", "note")], row.names = FALSE)',
      '  if (!is.null(res$posterior))',
      '    print(res$posterior[, -1], row.names = FALSE)',
      '  res',
      '}',
      'skipped <- character(0)',
      'if (length(only) == 1) {',
      '  saveRDS(run_one(match(only, models)), paste0("res_", only, ".rds"))',
      '  quit(save = "no")',
      '}',
      'if ("report" %in% args) {',
      '  have <- models[file.exists(paste0("res_", models, ".rds"))]',
      '  skipped <- setdiff(models, have)',
      '  if (file.exists("skipped.txt")) skipped <- union(skipped, readLines("skipped.txt"))',
      '  runs <- lapply(have, function(m) readRDS(paste0("res_", m, ".rds")))',
      '} else {',
      '  # every model is shown as soon as it is done',
      '  runs <- lapply(seq_along(models), run_one)',
      '}',
      'results <- do.call(rbind, lapply(runs, `[[`, "bf"))',
      'posterior <- do.call(rbind, lapply(runs, `[[`, "posterior"))',
      'diags <- unlist(lapply(runs, `[[`, "diag"), recursive = FALSE)',
      'cat("\\n==== All models ====\\n")',
      'print(results[, c("model", "representation", "bf_0u",',
      '                  "bf_0u_se", "bf_00", "note")], row.names = FALSE)',
      'write.csv(results, "results.csv", row.names = FALSE)',
      'if (!is.null(posterior))',
      '  write.csv(posterior, "posterior.csv", row.names = FALSE)',
      '#### Overview as a web page (results.html) ####',
      'esc <- function(x) {',
      '  x <- gsub("&", "&amp;", x, fixed = TRUE)',
      '  x <- gsub("<", "&lt;", x, fixed = TRUE)',
      '  gsub(">", "&gt;", x, fixed = TRUE)',
      '}',
      '# numbers: scientific for very small ones (below 0.01)',
      'num <- function(x, d = 3) {',
      '  small <- is.finite(x) & x != 0 & abs(x) < 0.01',
      '  txt <- trimws(formatC(x, digits = d, format = "g"))',
      '  txt[small] <- sprintf(paste0("%.", d - 1, "e"), x[small])',
      '  ifelse(is.finite(x), txt, "-")',
      '}',
      '# one table; cls = colour class per cell, raw = columns with html',
      'html_table <- function(df, cls = NULL, raw = character()) {',
      '  df[] <- lapply(df, as.character)',
      '  head <- paste0("<th>", esc(names(df)), "</th>", collapse = "")',
      '  body <- vapply(seq_len(nrow(df)), function(i) {',
      '    cells <- vapply(seq_along(df), function(j) {',
      '      cl <- if (is.null(cls)) "" else cls[i, j]',
      '      txt <- if (names(df)[j] %in% raw) df[i, j] else esc(df[i, j])',
      '      if (nzchar(cl)) paste0("<td class=c><span class=", cl, ">",',
      '                             txt, "</span></td>")',
      '      else paste0("<td>", txt, "</td>")',
      '    }, "")',
      '    paste0("<tr>", paste(cells, collapse = ""), "</tr>")',
      '  }, "")',
      '  c("<div class=tw><table>", paste0("<tr>", head, "</tr>"), body, "</table></div>")',
      '}',
      '# labels like p_{1}^{(2)} as html: stacked index and exponent',
      'lab_html <- function(x) {',
      '  x <- esc(x)',
      '  x <- gsub("_[{]([^}]*)[}][\\\\^][{]([^}]*)[}]",',
      '            "<span class=ss><sup>\\\\2</sup><sub>\\\\1</sub></span>", x)',
      '  x <- gsub("_[{]([^}]*)[}]", "<sub>\\\\1</sub>", x)',
      '  gsub("[\\\\^][{]([^}]*)[}]", "<sup>\\\\1</sup>", x)',
      '}',
      '# an estimate of exactly 0 means: no sample fell inside the model',
      'with_se <- function(bf, se) {',
      '  ifelse(is.finite(bf),',
      '         ifelse(bf == 0, paste0("< ", num(se, 2)),',
      '                paste0(num(bf), " (se ", num(se, 2), ")")), "-")',
      '}',
      '# colour of a Bayes factor: green for the model, red against it;',
      '# the categories of Jeffreys (1961) as given by Lee & Wagenmakers',
      '# (2013): 1-3 anecdotal, 3-10 moderate, 10-30 strong,',
      '# 30-100 very strong, above 100 extreme (and the inverse)',
      'bf_class <- function(x) {',
      '  cl <- as.character(cut(x, c(-Inf, 1/100, 1/30, 1/10, 1/3, 1, 3,',
      '                              10, 30, 100, Inf),',
      '                         labels = paste0("b", 1:10)))',
      '  ifelse(is.finite(x), cl, "")',
      '}',
      '# the column of the representation is only shown if V was analysed as well (the app itself always uses H)',
      'show_rep <- any(results$representation != "H", na.rm = TRUE)',
      'drop_rep_cols <- function(d, i) if (show_rep) d else d[, -i, drop = FALSE]',
      'key <- data.frame(',
      '  Model = results$model,',
      '  Representation = results$representation,',
      '  "Bayes factor, model vs. unconstrained" =',
      '    with_se(results$bf_0u, results$bf_0u_se),',
      '  "Bayes factor, model vs. complement" =',
      '    with_se(results$bf_00, results$bf_00_se),',
      '  Note = ifelse(nzchar(results$note), "see below", ""),',
      '  check.names = FALSE)',
      'key_cls <- data.frame(',
      '  "", "", bf_class(results$bf_0u), bf_class(results$bf_00),',
      '  ifelse(nzchar(results$note), "warn", ""))',
      'if (!is.null(posterior)) {',
      '  lo <- posterior$ci2.5; hi <- posterior$ci97.5',
      '  bar <- paste0("<div class=track><div class=range style=left:",',
      '    sprintf("%.1f", 100 * lo), "%;width:",',
      '    sprintf("%.1f", 100 * (hi - lo)),',
      '    "%></div><div class=dot style=left:",',
      '    sprintf("%.1f", 100 * posterior$mean), "%></div></div>")',
      '  post <- data.frame(',
      '    Representation = posterior$representation,',
      '    Probability = lab_html(posterior$probability),',
      '    Mean = num(posterior$mean),',
      '    SD = num(posterior$sd),',
      '    "95% interval" = paste0("[", num(lo), ", ", num(hi), "]"),',
      '    "0 to 1" = bar, check.names = FALSE)',
      '}',
      '# traffic light: ok / warn / bad (rules of thumb)',
      'level <- function(x, warn, bad, above = TRUE) {',
      '  v <- if (above) x else -x',
      '  w <- if (above) warn else -warn',
      '  b <- if (above) bad else -bad',
      '  ifelse(!is.finite(x), "", ifelse(v >= w, "ok",',
      '         ifelse(v >= b, "warn", "bad")))',
      '}',
      'diag_html <- function(d) {',
      '  e_cl <- level(d$ess, 1000, 400)               # ESS: >= 1000 ok',
      '  g_cl <- level(abs(d$geweke), 2, 3, above = FALSE)  # |z| <= 2 ok',
      '  tab <- data.frame(',
      '    Probability = lab_html(d$labels),',
      '    "Effective sample size (of all draws)" =',
      '      ifelse(is.finite(d$ess), paste0(format(round(d$ess), big.mark = ",", trim = TRUE),',
      '             " of ", format(d$n_draws, big.mark = ",", trim = TRUE)), "-"),',
      '    "Geweke z" = num(d$geweke, 2),',
      '    check.names = FALSE)',
      '  cls <- data.frame("", e_cl, g_cl)',
      '  n_bad <- sum(c(e_cl, g_cl) == "bad")',
      '  n_warn <- sum(c(e_cl, g_cl) == "warn")',
      '  verdict <- if (n_bad > 0) {',
      '    c("problem", "Check: some values are clearly outside the usual range.",',
      '      "Use more samples (in the app: Data, Analysis settings; in the",',
      '      "script: M_post) and run again.")',
      '  } else if (n_warn > 0) {',
      '    c("problem", "Mostly fine: some values are borderline.",',
      '      "With many probabilities a few borderline Geweke values are",',
      '      "normal.")',
      '  } else c("ok", "All checks fine.")',
      '  c(if (show_rep) paste0("<h4>Representation ", d$rep, "</h4>"),',
      '    paste0("<p class=", verdict[1], "><b>", verdict[2], "</b> ",',
      '           paste(verdict[-(1:2)], collapse = " "), "</p>"),',
      '    html_table(tab, cls, raw = "Probability"),',
      '    if (is.null(d$svg)) "<p class=small>No plot (svg missing).</p>"',
      '    else c("<div class=plots>", d$svg, "</div>"))',
      '}',
      '# the page of one model: Bayes factors, posterior, diagnostics',
      'model_page <- function(m) {',
      '  r <- results$model == m',
      '  nt <- unique(results$note[results$model == m])',
      '  nt <- nt[nzchar(nt)]',
      '  out <- c(paste0("<h2>", esc(m), "</h2>"),',
      '           if (length(nt) > 0) paste0("<p class=problem><b>Note:</b> ",',
      '                                      esc(nt), "</p>"),',
      '           "<h3>Bayes factors</h3>",',
      '           "<p class=small>Note: empty when all went well, otherwise",',
      '           "the reason why a value is missing or unreliable.</p>",',
      '           html_table(drop_rep_cols(key[r, -c(1, 5), drop = FALSE], 1),',
      '                      drop_rep_cols(key_cls[r, -c(1, 5), drop = FALSE], 1)))',
      '  ps <- if (is.null(posterior)) logical(0) else posterior$model == m',
      '  if (any(ps)) {',
      '    out <- c(out, "<h3>Probabilities (posterior)</h3>",',
      '      "<p class=small>The dot is the mean, the bar the 95% interval.",',
      '      "</p>", html_table(post[ps, if (show_rep) names(post) else setdiff(names(post), "Representation"), drop = FALSE],',
      '                         raw = c("Probability", "0 to 1")))',
      '  }',
      '  dg <- Filter(function(d) d$model == m, diags)',
      '  if (length(dg) > 0) {',
      '    out <- c(out, "<h3>Diagnostics of the posterior sample</h3>",',
      '      "<p class=small>Is the sample of the posterior reliable?",',
      '      "Green = fine, amber = borderline, red = check.",',
      '      "<b>Effective sample size</b>: how many independent draws the",',
      '      "sample is worth; 1000 or more is good. <b>Geweke z</b>:",',
      '      "start and end of the chain should agree, between -2 and 2",',
      '      "is fine. More below under &quot;How to read this&quot;.</p>",',
      '      "<details><summary>How to read this</summary>",',
      '      "<p class=small><b>Trace plot</b> (left): the values over the",',
      '      "draws. Good: a fuzzy band around a fixed level. Bad: a trend,",',
      '      "long flat stretches or jumps.</p>",',
      '      "<p class=small><b>Effective sample size</b> (ESS): the draws",',
      '      "depend on each other; the ESS says how many independent draws",',
      '      "they are worth (of all draws of the chain, shown behind it). Rule of thumb: 1000 or more is good, 400",',
      '      "to 1000 is borderline, below 400 means that means and",',
      '      "intervals are imprecise.</p>",',
      '      "<p class=small><b>Geweke z</b>: compares the mean of the",',
      '      "beginning of the chain with the end. Between -2 and 2 is",',
      '      "fine, up to 3 is borderline, beyond that the chain probably",',
      '      "still drifts. By chance about one in twenty values is",',
      '      "outside -2 to 2, so single borderline values are no alarm.",',
      '      "</p></details>",',
      '      unlist(lapply(dg, diag_html)))',
      '  }',
      '  out',
      '}',
      'mods <- unique(results$model)',
      'n_tab <- length(mods) + 1',
      'tabs <- seq_len(n_tab)',
      'css <- c(',
      '  ":root{--bg:#fff;--fg:#1f2430;--mut:#667085;--line:#e2e6ee;",',
      '  "--head:#f4f6fa;--prim:#593196}",',
      '  "@media(prefers-color-scheme:dark){:root{--bg:#161b27;",',
      '  "--fg:#e6e9f0;--mut:#9aa3b5;--line:#2d3347;--head:#1c2230;",',
      '  "--prim:#6089f8}}",',
      '  "body{background:var(--bg);color:var(--fg);margin:0;",',
      '  "font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,",',
      '  "Ubuntu,Helvetica Neue,Arial,sans-serif;line-height:1.5}",',
      '  "header{padding:1.2em 2em .4em}",',
      '  "header h1{margin:0;font-size:1.25em;font-weight:650}",',
      '  "header p{margin:.3em 0 0;color:var(--mut);font-size:.9em}",',
      '  "html,body{max-width:100%;overflow-x:hidden}",',
      '  "p,summary,td,th,h2,h3,h4,label{overflow-wrap:anywhere}",',
      '  "main{max-width:66em;margin:0 auto;padding:.5em 2em 3em}",',
      '  "h2{margin:1.2em 0 .2em;font-size:1.3em}",',
      '  "h3{margin:1.6em 0 .2em;font-size:1.05em}",',
      '  "h4{margin:1.2em 0 .2em;font-size:.95em;color:var(--mut)}",',
