      '        tx(0.80, y, if (is.na(ess[j])) "-" else round(ess[j]), cex = 0.65, font = 2, col = light(ess[j], 1000, 400))',
      '        tx(0.88, y, if (is.na(gz[j])) "-" else sprintf("%.2f", gz[j]), cex = 0.65, font = 2, col = light(gz[j], 2, 3, FALSE))',
      '        segments(0.06, y - 0.0165, 0.94, y - 0.0165, col = rule)',
      '        y <- y - 0.033',
      '      }',
      '      y <- y - 0.012',
      '      if (!is.null(d1) && !is.null(d1$draws)) {',
      '        ensure(0.12)',
      '        tx(0.06, y, paste0("Trace and density plots", if (show_rep) paste0(", ", r, " representation") else ""), cex = 0.9, font = 2); y <- y - 0.025',
      '        y <- para(y, "Trace (left): the values over the draws; good is a fuzzy band around a fixed level, bad is a trend, long flat stretches or jumps. Density (right): the posterior distribution of the probability.", cex = 0.55)',
      '        dr <- d1$draws; labs <- d1$labels',
      '        for (j in seq_len(ncol(dr))) {',
      '          if (y - 0.075 < 0.06) y <- new_page(cont)',
      '          lab <- if (length(labs) == ncol(dr)) labs[j] else colnames(dr)[j]',
      '          for (side in 1:2) {',
      '            par(fig = if (side == 1) c(0.06, 0.50, y - 0.072, y) else c(0.52, 0.94, y - 0.072, y),',
      '                mar = c(1.3, 2.2, 1.3, 0.4), mgp = c(1.1, 0.35, 0), cex = 0.6, new = TRUE)',
      '            if (side == 1) plot(seq_len(nrow(dr)), dr[, j], type = "l", col = prim, xlab = "", ylab = "", main = plot_title(lab, "trace"), cex.main = 0.85, tcl = -0.2)',
      '            else plot(density(dr[, j]), xlab = "", ylab = "", lwd = 2, col = prim, main = plot_title(lab, "density"), cex.main = 0.85, tcl = -0.2)',
      '          }',
      '          canvas(TRUE)',
      '          y <- y - 0.078',
      '        }',
      '      }',
      '      y <- y - 0.02',
      '    }',
      '  }',
      '  dev.off()',
      '  if (!is.null(link_rect)) pdf_add_link("results.pdf", link_rect, fairy_app_url, page = 1)',
      '}, error = function(e) { try(dev.off(), silent = TRUE); cat("results.pdf could not be written:", conditionMessage(e), "\\n") })',
      'if (interactive()) browseURL("results.html")',
      'cat("\\nDone:", sum(is.finite(results$bf_0u)), "of", nrow(results),',
      '    "analyses gave a result; tables saved in",',
      '    getwd(), "(results.csv, posterior.csv, results.html, results.pdf)\\n")',
      '',
      '# Reading results.csv (one row per model and representation):',
      '#   bf_0u   model against the unconstrained model (all',
      '#           probabilities free; equalities are part of the',
      '#           model). Above 1 favours the model.',
      '#   bf_u0   the same the other way round (1 / bf_0u)',
      '#   bf_00   model against its complement',
      '#           (everything the model forbids)',
      '#   *_se    Monte-Carlo error of the Bayes factor; if it is large,',
      '#           set final <- TRUE. V and H agree up to this error.',
      '#   *_ci5, *_ci95   90% interval of the estimate',
      '# Reading posterior.csv: estimate of every probability given the',
      '# data and the model: mean, SD and 95% interval (ci2.5, ci97.5).',
      '#',
      '#   note    empty if all went well; otherwise why the model could',
      '#           not be analysed (e.g. exact equalities: volume zero,',
      '#           use "Approximate" in the app)',
      '# For very thin models (narrow approximate equalities) the',
      '# estimates are less precise.',
      '# More commands: https://www.dwheck.de/vignettes/multinomineq_intro.html'
    ), collapse = "\n")
  }

  # file name from a model name: every run of odd characters becomes one underscore ("m1 [2 items · joint]" -> "m1_2_items_joint")
  safe_file_name <- function(x) {
    x <- gsub("[^A-Za-z0-9_.-]+", "_", x)
    x <- gsub("_{2,}", "_", x)
    x <- gsub("^_+|_+$", "", x)
    ifelse(nzchar(x), x, "model")
  }
  format_qtest_ineq_file <- function(ineq_mat, n_p) {
    act_v_left  <- -ineq_mat[, 3L:(2L + n_p), drop = FALSE]
    act_v_right <- ineq_mat[, 2]

    act_v_left  <- fractions(act_v_left)
    act_v_right <- fractions(act_v_right)

    nom_left    <- str_extract_part(act_v_left,  "/", before = TRUE)
    denom_left  <- str_extract_part(act_v_left,  "/", before = FALSE)
    nom_right   <- str_extract_part(act_v_right, "/", before = TRUE)
    denom_right <- str_extract_part(act_v_right, "/", before = FALSE)

    pos_ratios_left  <- str_detect(act_v_left,  "/")
    pos_ratios_right <- str_detect(act_v_right, "/")

    nom_left[!pos_ratios_left]   <- c(act_v_left)[!pos_ratios_left]
    denom_left  <- ifelse(is.na(denom_left),  "1", denom_left)
    nom_right[!pos_ratios_right] <- c(act_v_right)[!pos_ratios_right]
    denom_right <- ifelse(is.na(denom_right), "1", denom_right)

    nom_left    <- as.numeric(nom_left);   denom_left  <- as.numeric(denom_left)
    nom_right   <- as.numeric(nom_right);  denom_right <- as.numeric(denom_right)

    prod_denom_all <- prod(unique(c(denom_left[denom_left != 0], denom_right[denom_right != 0])))

    act_v_left  <- format(act_v_left  * prod_denom_all, scientific = FALSE)
    act_v_right <- format(act_v_right * prod_denom_all, scientific = FALSE)

    header_v <- c(nrow(ineq_mat), n_p)
    paste(
      paste(as.character(header_v), collapse = " "), "\n\n",
      paste(apply(act_v_left, 1, paste, collapse = " "), collapse = "\n"), "\n\n",
      paste(act_v_right, collapse = "\n"),
      sep = ""
    )
  }

  # Human-readable companion note for a QTEST file that went through
  # eliminate_h_equalities -- QTEST's own format has no room for
  # comments, so this ships as a SEPARATE file in the same tar rather
  # than inline, explaining which reduced column is which original
  # parameter and how each eliminated one is recovered from the
  # survivors (e.g. to reconstruct a full result vector afterward).
  format_qtest_substitution_note <- function(elim, orig_names) {
    lines <- c(
      "This model included equalities. QTEST's H-representation format",
      "has no way to express \"=\", so one parameter was eliminated per",
      "independent equality (solved for and substituted out) instead --",
      "the accompanying .txt file is the resulting pure-inequality",
      "system in the parameters listed below as \"kept\".",
      ""
    )
    kept_names <- orig_names[elim$remaining_idx]
    lines <- c(lines, "Kept parameters (in the order they appear in the QTEST file):")
    lines <- c(lines, paste0("  ", seq_along(kept_names), ": ", kept_names))
    lines <- c(lines, "")
    if (length(elim$eliminated) > 0) {
      lines <- c(lines, "Eliminated parameters (recover after solving the reduced system):")
      for (key in names(elim$eliminated)) {
        e <- elim$eliminated[[key]]
        orig_idx <- as.integer(key)
        terms <- character(0)
        ordered <- order(match(e$idx, elim$remaining_idx))
        for (ii in ordered) {
          c_i <- e$coefs[ii]
          if (abs(c_i) < 1e-9) next
          nm <- orig_names[e$idx[ii]]
          sign <- if (c_i >= 0) "+" else "-"
          coef_txt <- if (abs(abs(c_i) - 1) < 1e-9) "" else paste0(format(round(abs(c_i), 6)), "*")
          terms <- c(terms, paste(sign, paste0(coef_txt, nm)))
        }
        const_txt <- format(round(e$const, 6))
        formula <- paste(c(const_txt, terms), collapse = " ")
        lines <- c(lines, paste0("  ", orig_names[orig_idx], " = ", formula))
      }
    }
    paste(lines, collapse = "\n")
  }

  # Data for the multinomineq script: typed in the app, written into data_choices*.csv of the download.
  # Stored per probability (by its name), so the numbers stay with the probability when the order is changed.
  mn_user_data <- reactiveVal(list())
  # settings of the analysis chosen in the data window (number of samples, burn-in, prior, seed): they are written into the
  # script of every download and used when the analysis runs here, so a downloaded script replicates the app
  mn_settings <- reactiveVal(list())
  mn_sample_presets <- list(std = c(mb = 10000, mp = 5000), more = c(mb = 100000, mp = 20000), max = c(mb = 1000000, mp = 100000))
  observeEvent(input$mn_samples, {
    pr <- mn_sample_presets[[if (is.null(input$mn_samples)) "" else input$mn_samples]]
    if (!is.null(pr)) {
      updateNumericInput(session, "mn_m_bf", value = pr[["mb"]])
      updateNumericInput(session, "mn_m_post", value = pr[["mp"]])
    }
  }, ignoreInit = TRUE)
  observeEvent(list(input$mn_m_bf, input$mn_m_post), {
    mb <- input$mn_m_bf; mp <- input$mn_m_post
    if (is.null(mb) || is.null(mp) || is.na(mb) || is.na(mp)) return()
    hit <- names(Filter(function(pr) pr[["mb"]] == mb && pr[["mp"]] == mp, mn_sample_presets))
    want <- if (length(hit) > 0) hit[1] else "custom"
    if (!identical(input$mn_samples, want)) updateSelectInput(session, "mn_samples", selected = want)
  }, ignoreInit = TRUE)
  mn_settings_collect <- function(quiet = FALSE) {
    notify <- function(...) if (!quiet) showNotification(...)
    num <- function(x, d) if (is.null(x) || length(x) != 1 || is.na(x)) d else as.numeric(x)
    st <- list(samples = if (is.null(input$mn_samples)) "std" else input$mn_samples,
               mb = num(input$mn_m_bf, 10000), mp = num(input$mn_m_post, 5000),
               bp = num(input$mn_burnin_post, 10), bb = num(input$mn_burnin_bf, 5),
               pa = num(input$mn_prior_a, 1), pb = num(input$mn_prior_b, 1), seed = num(input$mn_seed, 1234))
    if (st$mb < 100 || st$mp < 100 || st$mb != round(st$mb) || st$mp != round(st$mp)) {
      notify("The numbers of samples must be whole numbers, 100 or more.", type = "error"); return(FALSE)
    }
    if (st$mb > 1000000 || st$mp > 100000) {
      notify("That is a large number of samples: it can take a very long time and uses a lot of the shared server. For this, download the files and run analysis_multinomineq.R on your own computer.", type = "warning", duration = 10)
    }
    if (st$bp < 0 || st$bb < 0 || st$bp != round(st$bp) || st$bb != round(st$bb)) {
      notify("Burn-in must be a whole number, 0 or more.", type = "error"); return(FALSE)
    }
    if (st$pa <= 0 || st$pb <= 0) {
      notify("The prior numbers a and b must be positive.", type = "error"); return(FALSE)
    }
    mn_settings(st)
    TRUE
  }
  # the settings are kept as soon as they are valid, so the downloads use them even if Run is not started
  observeEvent(list(input$mn_m_bf, input$mn_m_post, input$mn_burnin_post, input$mn_burnin_bf, input$mn_prior_a, input$mn_prior_b, input$mn_seed, input$mn_samples),
               { mn_settings_collect(quiet = TRUE) }, ignoreInit = TRUE)
  # the settings in the lines of the script (the lines of the default script are replaced)
  mn_apply_settings <- function(txt) {
    st <- isolate(mn_settings())
    g <- function(nm, d) if (is.null(st[[nm]])) d else st[[nm]]
    fmt <- function(x) format(x, scientific = FALSE, trim = TRUE)
    mb <- g("mb", 10000); mp <- g("mp", 5000)
    ln <- strsplit(txt, "\n", fixed = TRUE)[[1]]
    # "final" only says that more than the default number of samples is used (the notes of the results refer to it)
    if (mb > 10000 || mp > 5000) ln <- sub("^final <- FALSE.*", "final <- TRUE", ln)
    ln <- sub("^M_post <- .*", paste0("M_post <- ", fmt(mp)), ln)
    ln <- sub("^M_bf <- .*", paste0("M_bf <- ", fmt(mb)), ln)
    ln <- sub("^burnin_post <- [0-9.]+", paste0("burnin_post <- ", fmt(g("bp", 10))), ln)
    ln <- sub("^burnin_bf <- [0-9.]+", paste0("burnin_bf <- ", fmt(g("bb", 5))), ln)
    ln <- sub("^prior <- c\\(1, 1\\)", paste0("prior <- c(", fmt(g("pa", 1)), ", ", fmt(g("pb", 1)), ")"), ln)
    ln <- sub("^seed <- 1234", paste0("seed <- ", fmt(round(g("seed", 1234)))), ln)
    url <- tryCatch(isolate(app_share_url()), error = function(e) NULL)
    if (!is.null(url) && nzchar(url)) ln <- sub("^fairy_app_url <- \"\"", paste0("fairy_app_url <- ", encodeString(url, quote = "\""), "   # opens the app with this input"), ln)
    paste(ln, collapse = "\n")
  }
  mn_share <- reactiveVal(list())   # unpacked model (key m:<name>) -> TRUE: uses the numbers of the models with the same number of probabilities
  # one group per set of probabilities that mean the same thing: the base models (and intersections, mixtures) with the same number
  # of probabilities share one; every unpacked items model has its own, because its probabilities mean something of their own
  mn_np_labels <- function() {
    items_nms <- isolate(items_reactive$names)
    nms <- c(isolate(names_models_reactive$value), isolate(intersections_reactive$names),
             isolate(mixtures_reactive$names), items_nms)
    nms <- unique(nms[!is.na(nms) & nzchar(nms)])
    out <- list()
    for (nm in nms) {
      h <- isolate(h_reactive[[nm]])
      if (is.null(h)) next
      cols <- colnames(h)[-(1:2)]
      pm <- isolate(qtest_perm$map[[nm]])
      ok <- !is.null(pm) && length(pm) == length(cols) && setequal(pm, seq_along(cols))
      if (ok) cols <- cols[pm]
      unpacked <- nm %in% items_nms
      key <- if (unpacked) paste0("m:", nm) else paste0("k:", length(cols))
      if (is.null(out[[key]])) {
        desc <- NULL
        if (unpacked) {
          lg <- items_model_legend(nm)
          if (!is.null(lg) && length(lg) == length(cols)) desc <- if (ok) lg[pm] else lg
        }
        out[[key]] <- list(key = key, k = length(cols), labels = cols, desc = desc,
                           title = if (unpacked) nm else paste0(length(cols), " probabilities"), models = character(0))
      }
      if (!unpacked) out[[key]]$models <- c(out[[key]]$models, nm)
    }
    # base groups first (by size), then the unpacked models
    if (length(out) == 0) return(list())
    ord <- order(!startsWith(names(out), "k:"), vapply(out, function(g) g$k, numeric(1)))
    unname(out[ord])
  }
  # numbers typed in the window -> stored per probability; returns FALSE if something is not valid
  mn_collect <- function(groups, strict = TRUE) {
    cur <- isolate(mn_user_data())
    sh <- isolate(mn_share())
    for (gi in seq_along(groups)) {
      g <- groups[[gi]]
      if (startsWith(g$key, "m:") && !is.null(input[[paste0("mn_share_", gi)]])) {
        sv <- input[[paste0("mn_share_", gi)]]
        sh[[g$key]] <- if (identical(sv, "own") || identical(sv, FALSE)) FALSE else if (startsWith(as.character(sv), "k:")) TRUE else as.character(sv)
      }
      nn <- vapply(seq_len(g$k), function(i) as.numeric(input[[paste0("mn_n_", gi, "_", i)]] %||% NA), numeric(1))
      ff <- vapply(seq_len(g$k), function(i) as.numeric(input[[paste0("mn_f_", gi, "_", i)]] %||% NA), numeric(1))
      bad <- anyNA(nn) || anyNA(ff) || any(nn < 1) || any(ff < 0) || any(ff > nn) || any(nn != round(nn)) || any(ff != round(ff))
      if (bad) {
        if (strict) return(FALSE)
        next
      }
      u <- cur[[g$key]]; if (is.null(u)) u <- list()
      for (i in seq_len(g$k)) u[[g$labels[i]]] <- list(n = as.integer(nn[i]), f = as.integer(ff[i]))
      cur[[g$key]] <- u
    }
    mn_user_data(cur)
    mn_share(sh)
    TRUE
  }
  # a label like p_{1}^{(2)} with a real subscript and superscript (stacked), instead of the raw code
  # the list a probability of an unpacked model belongs to (as set in the unpack window), with the colour of that list there; only when
  # there are at least two lists
  mn_list_info <- function(desc) {
    if (is.null(desc) || length(desc) == 0) return(NULL)
    lst <- vapply(desc, function(d) {
      m <- regmatches(d, regexec("<span class='text-muted'>\\(([^<)]*)\\)</span>", d))[[1]]
      if (length(m) == 2 && !grepl("^not repeated$", m[2])) m[2] else NA_character_
    }, character(1))
    nm <- unique(lst[!is.na(lst)])
    if (length(nm) < 2) return(NULL)
    pal <- c("#3a6df0", "#e07b00", "#2a9d6f", "#b04fd0", "#c2385a", "#7a7f8c")
    idx <- vapply(nm, function(x) if (grepl("^list [A-Z]$", x)) utf8ToInt(substr(x, 6, 6)) - 64L else NA_integer_, integer(1))
    idx[is.na(idx)] <- 26L + seq_len(sum(is.na(idx)))
    col <- stats::setNames(pal[((idx - 1L) %% length(pal)) + 1L], nm)
    list(name = lst, col = col[lst])
  }
  mn_lab_html <- function(x) {
    x <- htmltools::htmlEscape(x)
    st <- "display:block; font-size:.7em; line-height:1.15;"
    x <- gsub("_[{]([^}]*)[}][\\^][{]([^}]*)[}]",
              paste0("<span style='display:inline-block; vertical-align:middle; line-height:1;'><sup style='", st, "'>\\2</sup><sub style='", st, "'>\\1</sub></span>"), x)
    x <- gsub("_[{]([^}]*)[}]", "<sub>\\1</sub>", x)
    gsub("[\\^][{]([^}]*)[}]", "<sup>\\1</sup>", x)
  }
  # the models that can be analysed from the current tab: display name -> file name part
  mn_model_choices <- function() {
    nms <- c(isolate(names_models_reactive$value), isolate(intersections_reactive$names),
             isolate(mixtures_reactive$names), isolate(items_reactive$names))
    nms <- unique(nms[!is.na(nms) & nzchar(nms)])   # an unpacked model is in the model list and in the items list: once
    nms <- nms[vapply(nms, function(nm) !is.null(isolate(h_reactive[[nm]])), logical(1))]
    stats::setNames(safe_file_name(str_replace_all(nms, fixed(" AND "), "_AND_")), nms)
  }
  mn_nall_ids <- character(0)
  show_mn_data <- function() {
    groups <- mn_np_labels()
    if (length(groups) == 0) {
      showNotification("No H-representation yet: click Go first.", type = "warning"); return()
    }
    cur <- isolate(mn_user_data())
    one_group <- function(gi) {
      g <- groups[[gi]]
      ex <- round(25 * seq(0.8, 0.2, length.out = g$k))
      u <- cur[[g$key]]
      # an unpacked model can use the numbers of the models with the same number of probabilities instead of its own
      srcs <- if (startsWith(g$key, "m:")) Filter(function(x) x$k == g$k && !identical(x$key, g$key), groups) else list()
      can_share <- length(srcs) > 0
      li <- mn_list_info(g$desc)
      tbl <- tags$table(class = "mn-tbl",
          tags$thead(tags$tr(tags$th("Observed for"), tags$th("n"), tags$th("Frequency"))),
          tags$tbody(lapply(seq_len(g$k), function(i) {
            v <- u[[g$labels[i]]]
            tags$tr(
              tags$td(style = "font-size:14px; padding-right:22px;", HTML(mn_lab_html(g$labels[i])),
                if (!is.null(li) && !is.na(li$name[i])) tags$span(class = "mn-list", style = paste0("--lc:", li$col[[i]], ";"), li$name[i])),
              tags$td(numericInput(paste0("mn_n_", gi, "_", i), NULL, value = if (!is.null(v)) v$n else 25, min = 1, step = 1, width = "96px")),
              tags$td(numericInput(paste0("mn_f_", gi, "_", i), NULL, value = if (!is.null(v)) v$f else ex[i], min = 0, step = 1, width = "96px")))
          })))
      # one n for every probability of the table in one step (the single n fields stay editable)
      nall <- tags$div(class = "mn-nall", tags$label(`for` = paste0("mn_nall_", gi), "Same n for every row (optional)"),
                       numericInput(paste0("mn_nall_", gi), NULL, value = NA, min = 1, step = 1, width = "88px"))
      tbl <- tags$div(
        tbl, nall)
      # which numbers does this group use: its own, or those of the models with the same number of probabilities / of another unpacked model
      src_choices <- c("These numbers (typed below)" = "own", stats::setNames(
        vapply(srcs, function(x) x$key, character(1)),
        vapply(srcs, function(x) if (startsWith(x$key, "k:")) paste0("The same as the models with ", x$k, " probabilities (", paste(x$models, collapse = ", "), ")")
                                  else paste0("The same as ", x$title), character(1))))
      cur_sh <- isolate(mn_share())[[g$key]]
      sel_share <- if (is.character(cur_sh)) cur_sh else if (isTRUE(cur_sh)) paste0("k:", g$k) else "own"
      if (!(sel_share %in% src_choices)) sel_share <- "own"
      # the groups that use the numbers of this one
      users <- unlist(lapply(groups, function(x) {
        sv <- isolate(mn_share())[[x$key]]
        tgt <- if (is.character(sv)) sv else if (isTRUE(sv)) paste0("k:", x$k) else NULL
        if (!is.null(tgt) && identical(tgt, g$key) && !identical(x$key, g$key)) x$title else NULL
      }))
      tags$div(
        if (length(g$models)) tags$div(style = "margin:2px 0 4px 0;", tags$span(class = "mn-for", paste0("For: ", paste(g$models, collapse = ", ")))),
        tags$div(class = "mn-usedby", `data-key` = g$key, style = paste0("margin:2px 0 6px 0;", if (length(users)) "" else " display:none;"),
          tags$span(class = "mn-for", paste0("Also used by: ", paste(users, collapse = ", ")))),
        # two ways (own numbers / the numbers of the one other model): both are shown, a drop-down only from three on
        if (can_share) (if (length(src_choices) <= 2) radioButtons(paste0("mn_share_", gi), "Numbers", width = "100%", selected = sel_share, choices = src_choices)
                        else selectInput(paste0("mn_share_", gi), "Numbers", width = "100%", selected = sel_share, choices = src_choices)),
        if (can_share) conditionalPanel(sprintf("input.mn_share_%d == 'own'", gi), tbl) else tbl)
    }
    for (gi in seq_along(groups)) local({
      gi_ <- gi; id <- paste0("mn_nall_", gi_)
      if (id %in% mn_nall_ids) return()
      mn_nall_ids <<- c(mn_nall_ids, id)
      observeEvent(input[[id]], {
        v <- input[[id]]
        k <- isolate(mn_np_labels())[[gi_]]$k
        if (is.null(v) || is.na(v) || v < 1 || is.null(k)) return()
        for (i in seq_len(k)) updateNumericInput(session, paste0("mn_n_", gi_, "_", i), value = v)
      }, ignoreInit = TRUE)
    })
    body <- if (length(groups) == 1) one_group(1) else
      do.call(tabsetPanel, c(list(id = "mn_data_tabs", type = "tabs"),
        lapply(seq_along(groups), function(gi) tabPanel(groups[[gi]]$title, one_group(gi)))))
    has_unpacked <- length(isolate(items_reactive$names)) > 0
    # the order of the probabilities only matters for unpacked item models: the button is there only while their tab is open
    order_button <- NULL
    if (has_unpacked) {
      btn <- actionButton("mn_data_to_order", "Order of the probabilities",
                          title = "An unpacked model has many probabilities (one per item). Here you choose which of them is called p1, p2, ... in this table and in the downloads.")
      order_button <- if (length(groups) == 1) {
        if (startsWith(groups[[1]]$key, "m:")) btn else NULL
      } else {
        tags$div(style = "display:inline-block;",
                 conditionalPanel("input.mn_data_tabs && input.mn_data_tabs.indexOf('probabilities') < 0", btn))
      }
    }
    showModal(modalDialog(
      title = "Your data for the multinomineq analysis", size = "m", easyClose = TRUE, class = "fairy-form-modal",
      tags$style(HTML(paste(
        ".mn-foot .btn { margin: 0 !important; }",
        ".mn-data-modal .form-group { margin-bottom: 0; }",
        ".mn-data-modal .mn-tbl { border-collapse: separate; border-spacing: 0; margin: 6px 0 0 0; }",
        ".mn-data-modal .mn-tbl th { font-size: 11px; font-weight: 600; color: var(--fairy-text-muted, #667085); text-transform: uppercase; letter-spacing: .05em; padding: 0 12px 6px 0; border: 0; }",
        ".mn-data-modal .mn-tbl td { padding: 5px 12px 5px 0; border: 0; border-top: 1px solid var(--fairy-border, #e5e7eb); vertical-align: middle; }",
        ".mn-data-modal .mn-tbl input.form-control { height: 32px; padding: 4px 8px; }",
        ".mn-data-modal .mn-nall { display: flex; align-items: center; gap: 10px; margin-top: 8px; font-size: 13px; color: var(--fairy-text-muted, #667085); }",
        ".mn-data-modal .mn-nall label { margin: 0; font-weight: 500; }",
        ".mn-data-modal .mn-nall input.form-control { height: 30px; padding: 3px 8px; }",
        ".mn-data-modal .mn-for { display: inline-block; font-size: 12px; font-weight: 600; padding: 2px 10px; border-radius: 999px; color: var(--fairy-primary); background: color-mix(in srgb, var(--fairy-primary) 10%, transparent); }",
        ".mn-data-modal .mn-list { display: inline-block; margin-left: 10px; font-size: 11px; font-weight: 600; padding: 1px 9px; border-radius: 999px; border: 1.5px solid var(--lc); color: var(--lc); vertical-align: middle; }",
        ".mn-data-modal .mn-lead { font-size: 13px; color: var(--fairy-text-muted, #667085); margin: 0 0 10px 0; }",
        ".mn-data-modal hr { margin: 14px 0 12px 0; }",
        ".mn-data-modal input.mn-bad { border-color: #c9353b !important; background: rgba(201,53,59,.08) !important; }",
        ".mn-data-modal .mn-warn { color: #b42318; font-size: 13px; margin-top: 8px; }",
        ".mn-data-modal label.control-label { font-size: 13px; font-weight: 600; margin-bottom: 4px; }",
        sep = " "))),
      tags$div(class = "mn-data-modal",
      tags$p(class = "mn-lead", tags$b("n"), " = number of observations, ", tags$b("frequency"), " = how often the outcome happened (out of n)."),
      if (has_unpacked) tags$p(class = "fairy-eq-tol-help", "Each unpacked model has its own tab: its probabilities can rest on different observations. To use the same numbers as another model (same number of probabilities), choose it under Numbers in the tab."),
      tags$div(style = "max-height:max(46vh, calc(100vh - 380px)); overflow-y:auto;", body),
      tags$div(id = "mn_data_warn", class = "mn-warn"),
      tags$script(HTML(paste0("
        (function() {
          // which groups use the numbers of which: the line 'Also used by' of every tab follows the choices
          var titles = ", as.character(jsonlite::toJSON(stats::setNames(lapply(groups, function(x) x$title), vapply(groups, function(x) x$key, character(1))), auto_unbox = TRUE)), ",
              own = ", as.character(jsonlite::toJSON(stats::setNames(as.list(vapply(groups, function(x) x$key, character(1))), paste0('mn_share_', seq_along(groups))), auto_unbox = TRUE)), ";
          function refresh() {
            var used = {};
            [].forEach.call(document.querySelectorAll('select[id^=mn_share_], div[id^=mn_share_]'), function(sel) {
              var v = sel.value;
              if (sel.tagName === 'DIV') { var r = sel.querySelector('input:checked'); v = r ? r.value : null; }
              var k = own[sel.id];
              if (v && v !== 'own' && k) { (used[v] = used[v] || []).push(titles[k]); }
            });
            [].forEach.call(document.querySelectorAll('.mn-usedby'), function(d) {
              var l = used[d.getAttribute('data-key')] || [];
              d.style.display = l.length ? '' : 'none';
              var sp = d.querySelector('.mn-for'); if (sp) sp.textContent = 'Also used by: ' + l.join(', ');
            });
          }
          if (window.jQuery) jQuery(document).on('change', 'select[id^=mn_share_], div[id^=mn_share_] input', function() { setTimeout(refresh, 50); });
          setTimeout(refresh, 300);
        })();
      "))),
      tags$script(HTML("
        (function() {
          var root = document.querySelector('.mn-data-modal'), warn = document.getElementById('mn_data_warn');
          if (!root || !warn) return;
          function check() {
            if (!document.body.contains(root)) { clearInterval(iv); return; }
            var msgs = [];
            [].forEach.call(root.querySelectorAll('input[id^=mn_f_]'), function(f) {
              var n = document.getElementById(f.id.replace('mn_f_', 'mn_n_'));
              var fv = parseFloat(f.value), nv = n ? parseFloat(n.value) : NaN;
              var bad = (!isNaN(fv) && !isNaN(nv) && fv > nv) || (!isNaN(fv) && fv < 0);
              var badN = !isNaN(nv) && nv < 1;
              f.classList.toggle('mn-bad', bad); if (n) n.classList.toggle('mn-bad', badN);
              if ((bad || badN) && f.offsetParent !== null) {
                var tr = f.closest('tr'), lab = tr && tr.cells[0] ? tr.cells[0].innerText.replace(/\\s+/g, '') : '';
                msgs.push(bad ? (lab + ': frequency (' + f.value + ') cannot be larger than n (' + (n ? n.value : '') + ')') : (lab + ': n must be at least 1'));
              }
            });
            warn.textContent = msgs.join('; ');
          }
          var iv = setInterval(check, 300);
          root.addEventListener('input', check); root.addEventListener('change', check);
          check();
        })();
      "))),
      footer = tags$div(class = "mn-foot", style = "display:flex; flex-wrap:wrap; gap:8px; justify-content:space-between; align-items:center; width:100%;",
        tags$div(style = "display:flex; gap:8px;",
          order_button,
          actionButton("mn_data_reset", "Reset to example numbers", icon = icon("rotate-left"), class = "btn-default",
                       title = "Your numbers become the example numbers again. The models and the settings stay as they are.")),
        tags$div(style = "display:flex; gap:8px;",
          modalButton("Cancel"), actionButton("mn_data_save", "Save", class = "btn-primary", title = "Keeps your numbers for the next download and for Run")))))
  }

  # The window of the Run button: only the analysis (the numbers and settings come from Data)
  output$mn_skipped_note <- renderUI({
    sk <- mn_skipped_mem()
    if (length(sk) == 0) return(NULL)
    ch <- mn_model_choices()
    nm <- names(ch)[match(sk, unname(ch))]
    nm <- ifelse(is.na(nm), sk, nm)
    tags$div(class = "fairy-skipnote",
      icon("circle-info"), tags$span(" Skipped earlier: ", tags$b(paste(nm, collapse = ", ")),
      " (not analysed)."), actionLink("mn_forget", "Retry all"))
  })
  observeEvent(input$mn_forget, { mn_skipped_mem(character(0)) })
  show_mn_run <- function() {
    groups <- mn_np_labels()
    if (length(groups) == 0) {
      showNotification("No H-representation yet: click Go first.", type = "warning"); return()
    }
    st <- isolate(mn_settings())
    mb <- if (is.null(st$mb)) 10000 else st$mb; mp <- if (is.null(st$mp)) 5000 else st$mp
    own <- length(isolate(mn_user_data())) > 0
    showModal(modalDialog(
      title = "Run the multinomineq analysis here", size = "m", easyClose = TRUE, class = "fairy-form-modal",
      tags$style(HTML(".mn-foot .btn { margin: 0 !important; } .mn-lead { font-size: 13px; color: var(--fairy-text-muted, #667085); margin: 0 0 10px 0; } .modal-body hr { margin: 14px 0 12px 0; } .modal-body label.control-label { font-size: 13px; font-weight: 600; margin-bottom: 4px; }")),
      uiOutput("mn_skipped_note"),
      tags$p(class = "fairy-eq-tol-help",
        HTML(paste0("Runs <a href='https://www.dwheck.de/software/multinomineq/' target='_blank' rel='noopener'>multinomineq</a> on the numbers under <b>Data</b>",
          if (own) "" else " (examples until you save your own)", ". ")),
        actionLink("mn_run_to_data", "Change the data")),
      if (length(mn_model_choices()) > 1)
        checkboxGroupInput("mn_models", "Models to analyse",
                           choices = mn_model_choices(), selected = unname(mn_model_choices()), inline = TRUE, width = "100%"),
      selectInput("mn_samples", "Samples (Bayes factors / posterior)", width = "100%", selected = (function(x) if (is.null(x)) "std" else x)(isolate(mn_settings())$samples), choices = c(
        "Standard: 10,000 / 5,000 samples" = "std",
        "More: 100,000 / 20,000 (slower)" = "more",
        "Even more: 1,000,000 / 100,000 (very slow)" = "max",
        "Custom (see Advanced)" = "custom")),
      tags$details(style = "margin:4px 0 8px 0;",
        tags$summary(style = "cursor:pointer; color:var(--fairy-primary); font-size:13px;", "Advanced: burn-in, prior, seed"),
        tags$div(style = "display:flex; flex-wrap:wrap; gap:12px; margin-top:6px;",
          numericInput("mn_m_bf", "Samples, Bayes factors", value = (function(x) if (is.null(x)) 10000 else x)(isolate(mn_settings())$mb), min = 100, step = 1000, width = "190px"),
          numericInput("mn_m_post", "Samples, posterior", value = (function(x) if (is.null(x)) 5000 else x)(isolate(mn_settings())$mp), min = 100, step = 1000, width = "170px"),
          numericInput("mn_burnin_post", "Burn-in, posterior", value = (function(x) if (is.null(x)) 10 else x)(isolate(mn_settings())$bp), min = 0, step = 10, width = "150px"),
          numericInput("mn_burnin_bf", "Burn-in, Bayes factors", value = (function(x) if (is.null(x)) 5 else x)(isolate(mn_settings())$bb), min = 0, step = 5, width = "170px"),
          numericInput("mn_prior_a", "Prior, a (Beta)", value = (function(x) if (is.null(x)) 1 else x)(isolate(mn_settings())$pa), min = 0.001, step = 0.5, width = "130px"),
          numericInput("mn_prior_b", "Prior, b (Beta)", value = (function(x) if (is.null(x)) 1 else x)(isolate(mn_settings())$pb), min = 0.001, step = 0.5, width = "130px"),
          numericInput("mn_seed", "Random seed", value = (function(x) if (is.null(x)) 1234 else x)(isolate(mn_settings())$seed), step = 1, width = "130px")),
        tags$p(style = "font-size:12px; color:#667085; margin:4px 0 0 0;",
          "Samples: the number of draws for the Bayes factors and for the posterior; the choice above sets them to a ready-made pair, and a number of your own switches the choice to Custom. More samples give a smaller Monte-Carlo error but take longer (the package default is 10,000 and 5,000). ",
          "Burn-in: draws discarded at the start of each run (the package default is 10 for the posterior and 5 per step for the Bayes factors). ",
          "Prior: Beta(a, b) on every probability; Beta(1, 1) is uniform. ",
          "The seed makes a run repeatable.")),
      tags$div(class = "fairy-mn-note",
        icon("triangle-exclamation"),
        tags$span(tags$b("Shared server:"), " keep it small. For larger analyses use ", tags$b("Download"), " under MULTINOMINEQ (left) and run ", tags$code("analysis_multinomineq.R"), " yourself.")),
      footer = tags$div(class = "mn-foot", style = "display:flex; gap:8px; justify-content:flex-end; width:100%;",
        modalButton("Cancel"),
        actionButton("mn_run", "Run analysis here", class = "btn-primary", title = "Runs on our shared server (best for small analyses). For larger ones, run the script from the download on your own computer."))))
  }
  for (btn_id in c("mn_run_open")) local({
    id <- btn_id
    observeEvent(input[[id]], {
      if (isTRUE(input[[id]] > 0)) { show_mn_run() }
    }, ignoreInit = TRUE)
  })
  observeEvent(input$mn_run_to_data, { show_mn_data() })
  for (btn_id in c("mn_data_open")) local({
    id <- btn_id
    observeEvent(input[[id]], {
      if (isTRUE(input[[id]] > 0)) { show_mn_data() }
    }, ignoreInit = TRUE)
  })
  # the numbers are set back to the examples in the open window (no new window: the tab stays as it is)
  observeEvent(input$mn_data_reset, {
    mn_user_data(list())
    groups <- isolate(mn_np_labels())
    for (gi in seq_along(groups)) {
      k <- groups[[gi]]$k
      ex <- round(25 * seq(0.8, 0.2, length.out = k))
      for (i in seq_len(k)) {
        updateNumericInput(session, paste0("mn_n_", gi, "_", i), value = 25)
        updateNumericInput(session, paste0("mn_f_", gi, "_", i), value = ex[i])
      }
      updateNumericInput(session, paste0("mn_nall_", gi), value = NA)
    }
  })
  observeEvent(input$mn_data_save, {
    if (!mn_collect(mn_np_labels(), strict = TRUE)) {
      showNotification("n and frequency must be whole numbers, n at least 1, and frequency between 0 and n.", type = "error"); return()
    }
    removeModal()
    showNotification("Saved. The next multinomineq download (the download buttons next to Data) and Run use your numbers.", type = "message", duration = 7)
  })
  # data and order belong together for unpacked models: switch between the two windows without losing what was typed
  observeEvent(input$mn_data_to_order, {
    mn_collect(mn_np_labels(), strict = FALSE)
    show_qtest_order(back = TRUE)
  })
  observeEvent(input$qtest_order_back_data, { show_mn_data() })

  # Run the analysis in the app: the same files and the same script as in the download, run in a separate R process
  mn_result <- reactiveValues(dir = NULL, time = NULL)
  observeEvent(input$mn_run, {
    if (!mn_settings_collect()) return()
    groups <- mn_np_labels()
    if (length(groups) == 0) { showNotification("No H-representation yet: click Go first.", type = "warning"); return() }
    choices_mn <- mn_model_choices()
    sel <- if (length(choices_mn) > 1) input$mn_models else unname(choices_mn)
    if (length(sel) == 0) { showNotification("Choose at least one model to analyse.", type = "warning"); return() }
    if (length(sel) > 10) {
      showNotification("That is a larger analysis and it may take a while. Next time you can also download the files and run analysis_multinomineq.R on your own computer.", type = "message", duration = 10)
    }
    removeModal()
    d <- tempfile("mn_run_"); dir.create(d)
    prep <- tryCatch({
      mn_h_content(file.path(d, "in.tar"), quiet = TRUE)
      utils::untar(file.path(d, "in.tar"), exdir = d)
      # only the chosen models: the script analyses every model it finds in the folder
      for (st in setdiff(unname(choices_mn), sel))
        unlink(file.path(d, paste0(c("A_", "b_", "V_", "map_"), st, ".csv")))
      ord <- tryCatch(readLines(file.path(d, "model_order.txt")), error = function(e) character(0))
      sel <- c(intersect(ord, sel), setdiff(sel, ord))   # the order of the Input page
      TRUE
    }, error = function(e) FALSE)
    if (!isTRUE(prep)) {
      showNotification("The analysis could not be started. Download the files and run the script in R.", type = "error", duration = NULL)
      return()
    }
    # every model runs in its own R process (one after the other), so a single model can be skipped; at the end the page with the results
    # is built from what is finished (the same script, started with only=<model> and with report)
    short_row <- function(x) if (nchar(x) > 40) paste0(substr(x, 1, 37), "...") else x
    mn_proc$dir <- d; mn_proc$stems <- sel; mn_proc$row_of <- stats::setNames(vapply(sel, short_row, character(1)), sel)
    # models that were skipped by hand in an earlier run stay skipped (Undo skip in the window takes it back)
    rem <- intersect(sel, isolate(mn_skipped_mem()))
    mn_proc$queue <- setdiff(sel, rem); mn_proc$procs <- list(); mn_proc$phase <- "models"; mn_proc$report_p <- NULL
    mn_proc$skipped <- rem; mn_proc$failed <- character(0); mn_proc$last <- list()
    mn_grace(NULL)
    mn_proc$start <- Sys.time(); mn_proc$elapsed <- 0; mn_proc$limit <- if (isTRUE(mn_nolimit())) Inf else 900
    mn_proc$parallel <- isTRUE(isolate(input$use_parallel))
    mn_proc$active <- TRUE
    # the same run window as everywhere else: one row per model, a column for each step, a skip button per row
    run_cols(c("Posterior", "Bayes factors"))
    fairy_run_begin("Running the analysis", c("Posterior", "Bayes factors"), skippable = TRUE)
    for (m in mn_proc$row_of) { fairy_run_cell(m, "Posterior", "wait"); fairy_run_cell(m, "Bayes factors", "wait") }
    for (m in rem) { fairy_run_cell(mn_proc$row_of[[m]], "Posterior", "skip"); fairy_run_cell(mn_proc$row_of[[m]], "Bayes factors", "skip") }
    session$sendCustomMessage("fairy_run_cancelable", list(on = TRUE, input = "mn_cancel", label = "Skip all"))
    session$sendCustomMessage("fairy_run_limit", list(seconds = if (is.finite(mn_proc$limit)) mn_proc$limit else 0, nolimit = !is.finite(mn_proc$limit), label = "analysis"))
  })
  mn_skipped_mem <- reactiveVal(character(0))
  mn_proc <- reactiveValues(active = FALSE, dir = NULL, start = NULL, elapsed = 0, limit = 900, stems = character(0), row_of = NULL,
                            queue = character(0), procs = list(), phase = "models", report_p = NULL, skipped = character(0),
                            failed = character(0), last = list(), parallel = FALSE)
  mn_rscript <- function(d, args, out) {
    tryCatch(processx::process$new(file.path(R.home("bin"), "Rscript"), c("analysis_multinomineq.R", args), wd = d,
                                   stdout = file.path(d, out), stderr = "2>&1", cleanup_tree = TRUE), error = function(e) NULL)
  }
  mn_end_ui <- function() {
    session$sendCustomMessage("fairy_run_cancelable", list(on = FALSE))
    session$sendCustomMessage("fairy_run_limit", list(seconds = 0))
  }
  mn_kill_all <- function() {
    for (p in isolate(mn_proc$procs)) try(p$kill_tree(), silent = TRUE)
    rp <- isolate(mn_proc$report_p); if (!is.null(rp)) try(rp$kill_tree(), silent = TRUE)
    mn_proc$procs <- list(); mn_proc$report_p <- NULL; mn_proc$queue <- character(0)
  }
  # the window state of one model from the progress lines of its process
  mn_model_cells <- function(m, out) {
    row <- isolate(mn_proc$row_of)[[m]]
    st <- grep("^\\[[0-9]+/[0-9]+\\] ", out, value = TRUE)
    if (length(st) == 0) return(invisible())
    step <- sub("^\\[[0-9]+/[0-9]+\\] [^:]*: ", "", tail(st, 1))
    key <- paste(m, step)
    if (identical(isolate(mn_proc$last)[[m]], key)) return(invisible())   # nothing new
    mn_proc$last[[m]] <- key
    if (grepl("posterior", step, ignore.case = TRUE)) {
      fairy_run_cell(row, "Posterior", "run")
    } else {
      fairy_run_cell(row, "Posterior", "done")
      # a very small model: no sample fell inside it, the package then works one constraint at a time
      fairy_run_cell(row, "Bayes factors", if (grepl("stepwise", step, fixed = TRUE)) "step" else "run")
    }
  }
  observe({
    if (!isTRUE(mn_proc$active)) return()
    invalidateLater(500)
    d <- isolate(mn_proc$dir)
    el <- as.numeric(difftime(Sys.time(), isolate(mn_proc$start), units = "secs"))
    mn_proc$elapsed <- el
    row_of <- isolate(mn_proc$row_of)
    if (identical(isolate(mn_proc$phase), "models")) {
      procs <- isolate(mn_proc$procs); queue <- isolate(mn_proc$queue)
      for (m in names(procs)) {
        out <- tryCatch(readLines(file.path(d, paste0("out_", m, ".txt")), warn = FALSE), error = function(e) character(0))
        if (procs[[m]]$is_alive()) { mn_model_cells(m, out); next }
        if (file.exists(file.path(d, paste0("res_", m, ".rds")))) {
          fairy_run_cell(row_of[[m]], "Posterior", "done"); fairy_run_cell(row_of[[m]], "Bayes factors", "done")
        } else {
          fairy_run_cell(row_of[[m]], "Posterior", "fail"); fairy_run_cell(row_of[[m]], "Bayes factors", "fail")
          mn_proc$failed <- c(isolate(mn_proc$failed), paste0(m, ": ", paste(tail(out, 2), collapse = " ")))
        }
        procs[[m]] <- NULL
      }
      max_run <- if (isTRUE(isolate(mn_proc$parallel))) length(isolate(mn_proc$stems)) else 1L
      while (length(queue) > 0 && length(procs) < max_run) {
        m <- queue[1]; queue <- queue[-1]
        pr <- mn_rscript(d, paste0("only=", m), paste0("out_", m, ".txt"))
        if (is.null(pr)) {
          fairy_run_cell(row_of[[m]], "Posterior", "fail"); fairy_run_cell(row_of[[m]], "Bayes factors", "fail")
          mn_proc$failed <- c(isolate(mn_proc$failed), paste0(m, ": could not be started"))
        } else {
          procs[[m]] <- pr
          fairy_run_cell(row_of[[m]], "Posterior", "run")
        }
      }
      mn_proc$procs <- procs; mn_proc$queue <- queue
      if (el > isolate(mn_proc$limit)) {
        # the time is over: what is still running or waiting is stopped, the finished models are reported
        for (m in c(names(procs), queue)) {
          if (!is.null(procs[[m]])) try(procs[[m]]$kill_tree(), silent = TRUE)
          fairy_run_cell(row_of[[m]], "Posterior", "stop"); fairy_run_cell(row_of[[m]], "Bayes factors", "stop")
          mn_proc$skipped <- c(isolate(mn_proc$skipped), m)
        }
        mn_proc$procs <- list(); mn_proc$queue <- character(0)
        procs <- list(); queue <- character(0)
      }
      if (length(procs) == 0 && length(queue) == 0 ) {
        mn_end_ui()
        have <- file.exists(file.path(d, paste0("res_", isolate(mn_proc$stems), ".rds")))
        if (!any(have)) {
          mn_proc$active <- FALSE
          fe <- isolate(mn_proc$failed)
          fairy_run_end(paste0("<b>No model was analysed.</b> ", if (length(fe)) htmltools::htmlEscape(paste(fe, collapse = " | ")) else "All models were skipped or stopped."))
          return()
        }
        writeLines(isolate(mn_proc$skipped), file.path(d, "skipped.txt"))
        mn_proc$phase <- "report"
        session$sendCustomMessage("fairy_run_phase", list(text = "Building the results page"))
        mn_proc$report_p <- mn_rscript(d, "report", "out_report.txt")
        if (is.null(isolate(mn_proc$report_p))) {
          mn_proc$active <- FALSE
          fairy_run_end("<b>The results page could not be built.</b> Download the files and run the script in R.")
        }
      }
    } else {
      rp <- isolate(mn_proc$report_p)
      if (!is.null(rp) && !rp$is_alive()) {
        mn_proc$active <- FALSE; mn_proc$report_p <- NULL
        if (file.exists(file.path(d, "results.html"))) {
          mn_result$dir <- d
          mn_result$time <- Sys.time()
          session$sendCustomMessage("fairy_run_phase", list(text = "Opening the results"))
          show_mn_results()   # the run window closes by itself once the results are shown (mn_results_shown)
          fe <- isolate(mn_proc$failed)
          if (length(fe)) showNotification(paste("Not every model could be analysed:", paste(fe, collapse = " | ")), type = "warning", duration = 12)
        } else {
          out <- tryCatch(readLines(file.path(d, "out_report.txt"), warn = FALSE), error = function(e) character(0))
          fairy_run_end(paste0("<b>The results page could not be built:</b> ", htmltools::htmlEscape(paste(tail(out, 3), collapse = " "))))
        }
      }
    }
  })
  # a single model is skipped: its process is stopped (or it is taken out of the queue), the others go on
  observeEvent(input$mn_skip_model, {
    if (!isTRUE(isolate(mn_proc$active)) || !identical(isolate(mn_proc$phase), "models")) return()
    row_of <- isolate(mn_proc$row_of); stem <- names(row_of)[unname(row_of) == input$mn_skip_model]
    procs <- isolate(mn_proc$procs); queue <- isolate(mn_proc$queue)
    for (m in intersect(stem, c(names(procs), queue))) {
      if (!is.null(procs[[m]])) { try(procs[[m]]$kill_tree(), silent = TRUE); procs[[m]] <- NULL; mn_proc$procs <- procs }
      queue <- setdiff(queue, m); mn_proc$queue <- queue
      mn_proc$skipped <- unique(c(isolate(mn_proc$skipped), m)); mn_skipped_mem(union(isolate(mn_skipped_mem()), m))
      fairy_run_cell(row_of[[m]], "Posterior", "skip"); fairy_run_cell(row_of[[m]], "Bayes factors", "skip")
    }
  })
  # the skip is taken back: the model waits for its turn again
  observeEvent(input$mn_unskip_model, {
    if (!isTRUE(isolate(mn_proc$active)) || !identical(isolate(mn_proc$phase), "models")) return()
    row_of <- isolate(mn_proc$row_of); stem <- names(row_of)[unname(row_of) == input$mn_unskip_model]
    for (m in intersect(stem, isolate(mn_proc$skipped))) {
      mn_proc$skipped <- setdiff(isolate(mn_proc$skipped), m)
      mn_skipped_mem(setdiff(isolate(mn_skipped_mem()), m))
      mn_proc$queue <- c(isolate(mn_proc$queue), m)
      fairy_run_cell(row_of[[m]], "Posterior", "wait"); fairy_run_cell(row_of[[m]], "Bayes factors", "wait")
      mn_grace(NULL); session$sendCustomMessage("fairy_run_phase", list(text = "Running the analysis")); session$sendCustomMessage("fairy_run_cancel_label", list(text = ""))
    }
  })
  # fairy dust (five quick clicks on the window title, see the script above): no time limit for the analysis here
  mn_nolimit <- reactiveVal(FALSE)
  observeEvent(input$mn_unlock, {
    mn_nolimit(!isTRUE(mn_nolimit()))
    if (isTRUE(isolate(mn_proc$active))) {
      mn_proc$limit <- if (mn_nolimit()) Inf else 900
      session$sendCustomMessage("fairy_run_limit", list(seconds = if (mn_nolimit()) 0 else 900, nolimit = mn_nolimit(), label = "analysis"))
    }
    showNotification(if (mn_nolimit()) "✨ Fairy dust: no time limit for the analysis (five quick clicks on the title switch it off again)." else "The time limit is back (15 minutes).",
                     type = "message", duration = 6)
  })
  observeEvent(input$mn_cancel, {
    if (!is.null(isolate(mn_grace()))) { mn_grace(Sys.time() - 1); return() }
    if (!isTRUE(isolate(mn_proc$active))) return()
    mn_kill_all()
    mn_proc$active <- FALSE
    mn_end_ui()
    fairy_run_hide()
    showNotification("The analysis was cancelled.", type = "message", duration = 5)
  })
  session$onSessionEnded(function() { mn_kill_all() })
  # the last results stay available: a "Results" button next to "Data" opens them again
  observeEvent(input$mn_results_shown, fairy_run_hide(), ignoreInit = TRUE)
  show_mn_results <- function() {
    d <- isolate(mn_result$dir)
    if (is.null(d) || !file.exists(file.path(d, "results.html"))) {
      showNotification("No results yet: run the analysis first.", type = "warning"); return()
    }
    page <- paste(readLines(file.path(d, "results.html"), warn = FALSE, encoding = "UTF-8"), collapse = "\n")
    showModal(modalDialog(
      title = "Results of the multinomineq analysis", size = "l", easyClose = TRUE, class = "fairy-form-modal",
      tags$p(class = "fairy-eq-tol-help", HTML("Computed with <a href='https://www.dwheck.de/software/multinomineq/' target='_blank' rel='noopener'>multinomineq</a> (Heck &amp; Davis-Stober, 2019) on our shared server. For larger or repeated analyses, download the results and run "),
        tags$code("analysis_multinomineq.R"), " yourself."),
      # the page is put into the window itself (in a shadow root, so its styles stay apart from the app's): no frame to scroll in
      tags$textarea(id = "mn_results_src", style = "display:none;", page),
      tags$div(id = "mn_results_host"),
      tags$script(HTML("
        (function() {
          var src = document.getElementById('mn_results_src');
          var host = document.getElementById('mn_results_host');
          function shown() { if (window.Shiny) Shiny.setInputValue('mn_results_shown', Date.now(), { priority: 'event' }); }
          if (!src || !host) { shown(); return; }
          try {
          var doc = new DOMParser().parseFromString(src.value, 'text/html');
          var css = [].map.call(doc.querySelectorAll('style'), function(s) { return s.textContent; }).join('\\n');
          css = css.replace(/html,body\\{/g, '.page{').replace(/(^|[}\\s])body\\{/g, '$1.page{').replace(/:root/g, ':host');
          var root = host.shadowRoot || host.attachShadow({ mode: 'open' });
          root.innerHTML = '<style>:host{display:block;} ' + css + '</style><div class=\"page\">' + doc.body.innerHTML + '</div>';
          // the colours follow the mode of the app (light or dark), not the setting of the operating system
          var dark = document.body.classList.contains('dark-mode');
          var ds = document.createElement('style');
          ds.textContent = dark ? ':host{--bg:#161b27;--fg:#e6e9f0;--mut:#9aa3b5;--line:#2d3347;--head:#1c2230;--prim:#6089f8}'
                                : ':host{--bg:#fff;--fg:#1f2430;--mut:#667085;--line:#e2e6ee;--head:#f4f6fa;--prim:#593196}';
          // the page sits inside the window: no second title (the window has one), the same left edge as the text above, calmer sizes
          ds.textContent += ' header{padding:0 0 .4em !important;border:0 !important} header h1{display:none} main{max-width:none !important;padding:.2em 0 1.2em !important}'
            + ' h2{font-size:1.1em !important;margin:1.1em 0 .25em !important} h3{font-size:1em !important} .scale{gap:4px !important} .scale > *{padding:5px 4px !important;font-size:.82em !important}'
            + ' .legend span{font-size:.85em !important} th:nth-child(n+2),td:nth-child(n+2){text-align:center !important}';
          root.appendChild(ds);
          var nt = document.getElementById('mn_results_newtab');
          if (nt) nt.addEventListener('click', function() {
            var b = new Blob([src.value], { type: 'text/html' });
            window.open(URL.createObjectURL(b), '_blank');
          });
          } finally { setTimeout(shown, 50); }
        })();
      ")),
      footer = tagList(actionButton("mn_results_again", "Analyse again", icon = icon("rotate-right"), class = "btn-primary",
                                    title = "Opens the Run window: change the models, the settings or the numbers and run again; the new results replace these"),
                       tags$div(class = "btn-group dropup", style = "margin-left:6px;",
                         tags$button(type = "button", class = "btn btn-default dropdown-toggle", `data-toggle` = "dropdown", style = "display:inline-flex; align-items:center; gap:8px;", icon("download"), tags$span("Download"), tags$span(class = "caret", style = "margin:0;")),
                         tags$ul(class = "dropdown-menu dropdown-menu-right",
                           if (file.exists(file.path(d, "results.pdf"))) tags$li(downloadLink("mn_results_pdf", "PDF report")),
                           tags$li(downloadLink("mn_results_dl", "Everything (.tar): PDF, web page, tables, files and the R script")))),
                       modalButton("Close"))))
  }
  for (btn_id in c("mn_results_open")) local({
    id <- btn_id
    observeEvent(input[[id]], { if (isTRUE(input[[id]] > 0)) show_mn_results() }, ignoreInit = TRUE)
  })
  for (suffix in c("")) local({
    sf <- suffix
    output[[paste0("mn_results_btn_ui", sf)]] <- renderUI({
      if (is.null(mn_result$dir)) return(NULL)
      tags$span(class = "fairy-tooltip", `data-tooltip` = "Open the results of the last multinomineq analysis again",
        actionButton(paste0("mn_results_open", sf), NULL, icon = icon("chart-column"), class = "fairy-toolbar-iconbtn fairy-order-btn"))
    })
  })
  observeEvent(input$mn_results_again, { removeModal(); show_mn_run() })
  output$mn_results_pdf <- downloadHandler(
    filename = function() paste0("multinomineq_results_", Sys.Date(), ".pdf"),
    content = function(file) {
      d <- isolate(mn_result$dir)
      req(!is.null(d), file.exists(file.path(d, "results.pdf")))
      file.copy(file.path(d, "results.pdf"), file, overwrite = TRUE)
    }
  )
  outputOptions(output, "mn_results_pdf", suspendWhenHidden = FALSE)
  output$mn_results_dl <- downloadHandler(
    filename = function() paste0("multinomineq_results_", Sys.Date(), ".tar"),
    content = function(file) {
      d <- isolate(mn_result$dir)
      req(!is.null(d))
      old <- setwd(d); on.exit(setwd(old), add = TRUE)
      # the results and the files they came from (A, b, V, map, data, script), so the analysis can be repeated in R
      tar(file, setdiff(list.files(d), "in.tar"))
    }
